export default [{"id":"0001","name_zh":"3/4仰卧起坐","target":"腹部","media_id":"2gPfomN","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"0002","name_zh":"45度侧屈","target":"腹部","media_id":"Hy9D21L","instructions_zh":"双脚分开与肩同宽站立，双臂在身体两侧笔直向下伸展。 保持背部挺直，核心肌群参与，慢慢将躯干向一侧弯曲，将手向膝盖方向放低。 在底部停顿片刻，然后慢慢回到起始位置。 在另一侧重复。 继续交替进行所需的重复次数。"},{"id":"0003","name_zh":"空中蹬车","target":"腹部","media_id":"1ZFqTDN","instructions_zh":"平躺，双手放在脑后。 将双腿抬离地面，并以 90 度角弯曲膝盖。 将右肘靠近左膝盖，同时伸直右腿。 返回起始位置，在另一侧重复该动作，将左肘拉向右膝盖，同时伸直左腿。 继续交替进行蹬踏动作，达到所需的重复次数。"},{"id":"1512","name_zh":"四足支撑拉伸","target":"股四头肌","media_id":"qBcKorM","instructions_zh":"从四肢着地开始，双手直接放在肩膀下方，膝盖直接放在臀部下方。 将一条腿向后伸直，保持膝盖弯曲和脚弯曲。 慢慢地将臀部降低到地面，感觉股四头肌的伸展。 保持这个姿势20-30秒。 换腿并在另一侧重复拉伸。"},{"id":"0006","name_zh":"交替触脚跟","target":"腹部","media_id":"qaZVsGk","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双臂伸直至两侧，与地面平行。 收紧腹肌，将肩膀抬离地面，并将右手伸向右脚跟。 返回起始位置并在左侧重复，将左手伸向左脚跟。 继续交替进行所需的重复次数。"},{"id":"0007","name_zh":"交替侧拉","target":"背阔肌","media_id":"4IKbhHV","instructions_zh":"坐在缆绳机上，背部挺直，双脚平放在地面上。 正手握住手柄，握距略宽于肩宽。 稍微向后倾斜，将手柄拉向胸部，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"1368","name_zh":"踝关节环绕","target":"小腿","media_id":"uL9CsKm","instructions_zh":"坐在地上，双腿在身前伸展。 将一条腿抬离地面，并以圆周运动旋转脚踝。 在一个方向上转所需的圈数，然后切换到另一个方向。 换另一条腿重复上述步骤。"},{"id":"3293","name_zh":"弓箭手引体向上","target":"背阔肌","media_id":"72BC5Za","instructions_zh":"首先，用正手握法悬挂在引体向上杆上，握距略宽于肩宽。 启动你的核心并将肩胛骨向下拉和向后拉。 当你站起来时，弯曲一只手臂并将肘部移向身体一侧，同时保持另一只手臂伸直。 继续拉，直到下巴位于杠铃上方并且弯曲的手臂完全弯曲。 有控制地放低自己，伸直弯曲的手臂并在另一侧重复该动作。 每次重复时交替进行。"},{"id":"3294","name_zh":"弓箭手俯卧撑","target":"胸","media_id":"A9qxk2F","instructions_zh":"从俯卧撑位置开始，双手分开略宽于肩宽。 将一只手臂伸直至一侧，与地面平行。 弯曲肘部降低身体，保持背部挺直，核心参与。 推回到起始位置。 在另一侧重复上述步骤，将另一只手臂伸出到一侧。 继续交替进行所需的重复次数。"},{"id":"2355","name_zh":"悬吊屈膝举腿","target":"腹部","media_id":"uWpxD4v","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，膝盖弯曲成 90 度角。 收紧核心并将膝盖抬向胸部，尽可能靠近肘部。 慢慢地将双腿放回起始位置。 重复所需的重复次数。"},{"id":"2333","name_zh":"悬吊直腿举腿","target":"腹部","media_id":"PXTIwgu","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，双腿伸直向下。 启动你的核心并将双腿抬起到你面前，直到它们与地面平行。 在顶部保持片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"3214","name_zh":"双臂打开画圆触脚尖（男）","target":"臀部","media_id":"RtyAsy1","instructions_zh":"双脚分开与肩同宽站立，双臂向两侧伸展。 保持双腿伸直，腰部向前弯曲，右手向下伸向脚趾。 当你向下伸展时，同时将左腿在身后伸直，保持平衡。 返回起始位置，重复该动作，左手伸向脚趾，右腿在身后抬起。 继续交替进行所需的重复次数。"},{"id":"3204","name_zh":"双臂过头全幅度仰卧起坐（男）","target":"腹部","media_id":"NAkmgdx","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将手臂伸过头顶，保持伸直。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲直到躯干直立。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"0009","name_zh":"辅助胸肌臂屈伸（跪姿）","target":"胸","media_id":"PAgTVaK","instructions_zh":"将机器调整到您想要的高度，并将膝盖固定在垫子上。 手掌朝下，抓住手柄，双臂完全伸展。 弯曲肘部降低身体，直到上臂与地板平行。 暂停片刻，然后将自己推回到起始位置。 重复所需的重复次数。"},{"id":"0011","name_zh":"辅助悬垂举腿","target":"腹部","media_id":"03lzqwk","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。 调动你的核心肌肉，将膝盖抬向胸部，弯曲臀部和膝盖。 在动作的最高点暂停片刻，挤压腹肌。 慢慢地将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0010","name_zh":"辅助悬垂屈膝举腿（抗阻下放）","target":"腹部","media_id":"8K0w2yA","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。 收紧核心并将膝盖抬向胸部，保持双腿并拢。 一旦你的膝盖与胸部齐平，爆发性地将你的双腿向地面扔去，将它们完全伸展。 让双腿向后摆动并重复该动作达到所需的重复次数。"},{"id":"1708","name_zh":"辅助仰卧小腿拉伸","target":"小腿","media_id":"GxDwDX0","instructions_zh":"仰卧，双腿伸展。 弯曲一侧膝盖，将脚平放在地上。 用手或毛巾轻轻地将脚趾拉向身体，感受小腿的拉伸。 保持拉伸 20-30 秒。 松开拉伸并在另一条腿上重复。"},{"id":"1709","name_zh":"辅助仰卧臀部拉伸","target":"臀部","media_id":"yn0LjwL","instructions_zh":"仰卧，双腿伸展。 弯曲右膝盖，将右脚踝放在左大腿上，就在膝盖上方。 用双手抓住左大腿，轻轻地将其拉向胸部。 保持拉伸 20-30 秒。 松开并在另一侧重复。"},{"id":"1710","name_zh":"辅助仰卧臀肌和梨状肌拉伸","target":"臀部","media_id":"RQNVT10","instructions_zh":"仰卧，双腿伸展。 弯曲右膝盖，将右脚踝放在左大腿上，就在膝盖上方。 用双手抓住左大腿，轻轻地将其拉向胸部。 保持拉伸 20-30 秒。 松开拉伸并在另一侧重复。"},{"id":"0012","name_zh":"辅助仰卧举腿（侧向抗阻下放）","target":"腹部","media_id":"UGhRD1A","instructions_zh":"平躺，双腿伸展，双臂放在身体两侧。 将双手放在臀部下方以获得支撑。 收紧腹肌，将双腿抬离地面，保持伸直。 双腿并拢的同时，将它们降低到一侧，直到离地几英寸。 暂停片刻，然后抬起双腿回到起始位置。 到另一侧重复该动作。 继续交替进行所需的重复次数。"},{"id":"0013","name_zh":"辅助仰卧举腿（抗阻下放）","target":"腹部","media_id":"VX5YKR5","instructions_zh":"平躺，双腿伸展，双臂放在身体两侧。 将双手放在臀部下方以获得支撑。 启动你的核心并将双腿抬离地面，保持伸直。 抬起双腿，直到它们垂直于地面。 将双腿放低回到起始位置。 同时，将双腿向地面放下，保持伸直。 将双腿抬回到起始位置。 重复所需的重复次数。"},{"id":"0014","name_zh":"辅助动态俄罗斯转体","target":"腹部","media_id":"r7cT9YD","instructions_zh":"坐在地上，膝盖弯曲，双脚平放在地板上。 双手将健身球放在胸前。 稍微向后倾斜，收紧腹肌并保持背部挺直。 慢慢地将你的躯干向右扭转，将健身球移向身体的右侧。 暂停片刻，然后将躯干向左扭转，将健身球移向身体左侧。 继续交替进行所需的重复次数。"},{"id":"0015","name_zh":"辅助窄距对握引体向上","target":"背阔肌","media_id":"vrhHa6D","instructions_zh":"将机器调整到您想要的重量和高度。 将双手紧紧握在双杠上，手掌相对。 悬挂在杠上，双臂完全伸展，双脚离开地面。 收紧背部肌肉，将身体拉向杠铃，保持肘部靠近身体。 继续拉，直到下巴高于杠铃。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"0016","name_zh":"辅助俯卧腘绳肌拉伸","target":"大腿后侧","media_id":"VedGSby","instructions_zh":"脸朝下躺在垫子或长凳上，双腿完全伸展。 找一个伙伴或使用阻力带来固定脚踝。 收紧腿筋，将双腿抬向臀肌，保持膝盖伸直。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"1713","name_zh":"辅助俯卧股四头肌拉伸","target":"股四头肌","media_id":"YUYAMEj","instructions_zh":"脸朝下躺在地上，双腿伸直。 弯曲左膝，用左手向后抓住左脚或脚踝。 轻轻地将左脚拉向臀肌，感受左股四头肌的拉伸。 保持拉伸 20-30 秒，然后放松。 右腿重复上述动作。"},{"id":"1714","name_zh":"辅助俯卧股直肌拉伸","target":"腹部","media_id":"2Ryn564","instructions_zh":"脸朝下躺在地上，双腿伸直。 弯曲右膝，用右手向后伸抓住右脚或脚踝。 轻轻地将右脚或脚踝拉向臀部，感受右大腿前部的拉伸。 保持拉伸 20-30 秒。 松开并在另一侧重复。"},{"id":"0017","name_zh":"辅助引体向上","target":"背阔肌","media_id":"kiJ4Z2K","instructions_zh":"将机器调整至您所需的体重和高度设置。 正手握住手柄，握距略宽于肩宽。 双臂完全伸展，双脚离开地面。 收紧背部肌肉，将身体拉向手柄，保持肘部靠近身体。 继续拉，直到下巴位于手柄上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"1716","name_zh":"辅助坐姿胸大肌拉伸（健身球）","target":"胸","media_id":"RoV1Rfa","instructions_zh":"坐在稳定球上，双脚平放在地面上，背部挺直。 双手握住稳定球，并将双臂伸直至身前。 慢慢地将稳定球降低到胸部，感受胸肌的拉伸。 保持伸展几秒钟，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"1712","name_zh":"辅助侧卧内收肌拉伸","target":"内收肌","media_id":"hC6oYY5","instructions_zh":"侧躺，双腿伸直并叠放在一起。 稍微弯曲下面的腿以保持稳定。 将上脚放在稳定的表面上，例如长凳或台阶上。 保持上腿伸直，慢慢将其降低到地面，感觉大腿内侧有拉伸感。 保持拉伸 20-30 秒。 返回起始位置并在另一侧重复。"},{"id":"1758","name_zh":"辅助仰卧起坐","target":"腹部","media_id":"aumB2IV","instructions_zh":"坐在长凳边缘或让某人按住你的脚。 平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"1431","name_zh":"辅助站立反手引体向上","target":"背阔肌","media_id":"7OeHptV","instructions_zh":"将机器调整至您所需的辅助级别。 站在脚踏板上，正手握住手柄，握距略宽于肩宽。 保持挺胸、肩膀向后，收紧核心肌群，并稍微弯曲膝盖。 弯曲肘部并将肘部向身体两侧压低，将身体向上拉。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"1432","name_zh":"辅助站立引体向上","target":"背阔肌","media_id":"f4xtKBj","instructions_zh":"将机器调整至您所需的体重和高度设置。 面向机器站立，双脚分开与肩同宽。 正手握住手柄，握距略宽于肩宽。 启动你的背阔肌和二头肌，并将自己拉向手柄。 在顶部暂停片刻，挤压背部肌肉。 慢慢地将自己放回到起始位置。 重复所需的重复次数。"},{"id":"0018","name_zh":"辅助站立臂屈伸（毛巾）","target":"肱三头肌","media_id":"7HcfMBP","instructions_zh":"双脚分开与肩同宽站立，双手握住毛巾放在脑后。 保持肘部靠近耳朵，上臂保持静止。 慢慢向上伸展前臂，在顶部挤压三头肌。 暂停片刻，然后慢慢将毛巾放回起始位置。 重复所需的重复次数。"},{"id":"0019","name_zh":"辅助肱三头肌臂屈伸（跪姿）","target":"肱三头肌","media_id":"J60bN17","instructions_zh":"将机器调整到您想要的重量和高度。 跪在面向机器的垫子上，双手握住手柄。 弯曲肘部降低身体，保持背部挺直并靠近机器。 在底部暂停片刻，然后将自己推回到起始位置。 重复所需的重复次数。"},{"id":"2364","name_zh":"辅助宽距胸肌臂屈伸（跪姿）","target":"胸","media_id":"PnZJIrk","instructions_zh":"将机器调整到您想要的高度，并将膝盖固定在垫子上。 宽握手柄并保持肘部稍微弯曲。 弯曲肘部降低身体，直到上臂与地板平行。 伸展双臂，将自己推回到起始位置。 重复所需的重复次数。"},{"id":"3220","name_zh":"分腿跳（男）","target":"有氧","media_id":"f9lVSSI","instructions_zh":"双脚分开与肩同宽站立。 弯曲膝盖并将身体降低至蹲姿。 爆发性向上跳跃，伸展双腿和手臂。 在空中时，将双腿分开，并将双臂向两侧伸出。 双脚分开与肩同宽，轻轻落地，弯曲膝盖以吸收冲击力。 重复所需的重复次数。"},{"id":"3672","name_zh":"前后迈步","target":"有氧","media_id":"fNGumX0","instructions_zh":"双脚分开与肩同宽站立。 右脚向前迈出一步，弯曲膝盖，将身体降低到弓步位置。 用右脚蹬地，然后回到起始位置。 用左脚重复该动作，每一步交替双腿。 继续来回走动，保持稳定的步伐。 重复所需的持续时间或重复次数。"},{"id":"1314","name_zh":"健身球俯卧挺身","target":"脊柱","media_id":"qLpO4vV","instructions_zh":"将稳定球放在地面上，面朝下躺在上面，臀部放在球上，双脚靠在墙壁或其他稳定的表面上。 将双手放在脑后或交叉在胸前。 启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"3297","name_zh":"后水平","target":"上背部","media_id":"GaSzzuh","instructions_zh":"首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。 启动你的核心并将肩胛骨向下拉和向后拉。 弯曲膝盖并将其向胸部靠拢。 慢慢抬起双腿，保持伸直，直到身体与地面平行。 保持这个姿势几秒钟，然后慢慢地将双腿放回起始位置。 重复所需的重复次数。"},{"id":"1405","name_zh":"背部胸肌拉伸","target":"背阔肌","media_id":"chfnQnM","instructions_zh":"站直，双脚分开与肩同宽。 将双臂伸直在身前，与地面平行。 双臂交叉在身体前方，右臂放在左臂上方。 手指交叉，手掌旋转远离身体。 慢慢抬起手臂并远离身体，感觉背部和胸部有拉伸感。 保持拉伸 15-30 秒，然后放松。 在另一侧重复。"},{"id":"1473","name_zh":"向后跳","target":"股四头肌","media_id":"SaDOwk7","instructions_zh":"双脚分开与肩同宽站立。 稍微弯曲膝盖，向后跳跃，用双脚蹬地。 脚掌轻轻着地，弯曲膝盖以吸收冲击力。 重复所需的重复次数。"},{"id":"0020","name_zh":"平衡板","target":"股四头肌","media_id":"xAySMB0","instructions_zh":"将平衡板放在平坦的表面上。 用一只脚踩在平衡板上，确保其居中。 慢慢地将体重转移到平衡板上的脚上，保持核心肌群参与。 在保持该姿势所需的时间内保持平衡和稳定。 用另一只脚重复该练习。"},{"id":"0968","name_zh":"弹力带交替弯举","target":"肱二头肌","media_id":"3omWx6P","instructions_zh":"双脚分开与肩同宽站立，反手握住弹力带，手掌朝上。 保持肘部靠近身体两侧，慢慢地将一只手臂向肩膀弯曲，在顶部挤压二头肌。 将手臂放回起始位置，然后用另一只手臂重复此动作。 继续交替手臂进行所需的重复次数。"},{"id":"0969","name_zh":"弹力带交替V字起","target":"腹部","media_id":"ztAa1RK","instructions_zh":"平躺，双腿伸直，手臂伸过头顶，握住弹力带。 收紧腹肌，同时将双腿和上半身抬离地面，将双手伸向脚趾。 当你降低双腿和上半身时，交换双腿的位置，将一条腿交叉在另一条腿上。 重复该动作，每次重复时交替变换双腿的位置。 继续进行所需的重复次数。"},{"id":"0970","name_zh":"弹力带辅助引体向上","target":"背阔肌","media_id":"r1XNRYB","instructions_zh":"将弹力带固定在上拉杆或坚固的锚点上。 踏上弹力带，手掌背向自己，握住杠铃，双手之间的距离略宽于肩宽。 双臂完全伸展，保持核心收紧，肩膀向下并向后倾斜。 将肩胛骨挤压在一起并将肘部向下推向臀部，将身体向上拉向杠铃杆。 继续拉，直到下巴高于杠铃，然后慢慢降低回到起始位置。 重复所需的重复次数。"},{"id":"0971","name_zh":"弹力带辅助健腹轮前推","target":"腹部","media_id":"zhF9lW4","instructions_zh":"跪在地板上，双手握住弹力带的手柄，手掌朝下。 将弹力带放在您面前的地面上，双手分开与肩同宽。 启动你的核心并缓慢地向前滚动轮子，在保持控制的同时尽可能地伸展你的身体。 在最远点暂停片刻，然后慢慢地将轮子向膝盖方向滚动，回到起始位置。 重复所需的重复次数。"},{"id":"1254","name_zh":"弹力带卧推","target":"胸","media_id":"khlHMqs","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 正手握住带子手柄，间距略宽于肩宽。 充分伸展双臂，将弹力带推离胸部。 慢慢将弹力带放回到胸部，保持肘部呈 90 度角。 重复所需的重复次数。"},{"id":"0980","name_zh":"弹力带俯身髋伸展","target":"臀部","media_id":"wSScovH","instructions_zh":"将带子固定在脚踝高度的坚固锚点上。 背对锚点站立，双脚与肩同宽。 向后退一步，在弹力带上产生张力，保持膝盖稍微弯曲。 铰接臀部并向前倾斜，保持脊柱中立。 将右腿向后伸直，在顶部挤压臀部。 将右腿放回原位，然后换左腿重复此动作。 继续交替双腿达到所需的重复次数。"},{"id":"0972","name_zh":"弹力带自行车卷腹","target":"腹部","media_id":"tZkGYZ9","instructions_zh":"平躺，双手放在脑后，膝盖弯曲。 将脚抬离地面，将右膝盖靠近胸部，同时扭转躯干，将左肘靠近右膝盖。 伸直右腿，同时将左膝靠近胸部，并扭转躯干，使右肘靠近左膝。 继续交替扭转运动，就像踩自行车一样，同时在整个运动过程中保持核心参与。 重复所需的重复次数。"},{"id":"0974","name_zh":"弹力带窄握下拉","target":"背阔肌","media_id":"DptumMx","instructions_zh":"将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。 面向锚点站立，用反手抓住弹力带，双手与肩同宽。 后退一步，在弹力带上产生张力，双脚分开与臀部同宽。 当你将弹力带向下拉向胸部时，收紧你的核心并保持背部挺直，将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢松开弹力带回到起始位置。 重复所需的重复次数。"},{"id":"0975","name_zh":"弹力带窄距俯卧撑","target":"肱三头肌","media_id":"ufaxB52","instructions_zh":"将一条带子绕在你的上臂上，就在肘部上方。 采取俯卧撑姿势，双手直接放在肩膀下方，身体从头到脚跟呈一条直线。 弯曲肘部，将胸部降低到地面，保持肘部靠近身体两侧。 推动手掌以伸展手臂并返回到起始位置。 重复所需的重复次数。"},{"id":"0976","name_zh":"弹力带集中弯举","target":"肱二头肌","media_id":"kmVVAfu","instructions_zh":"坐在长凳或椅子上，双腿分开，双脚平放在地上。 用手握住带子的一端，用脚踩在另一端上，同时将脚放在同一侧。 稍微向前倾，将肘部放在大腿内侧，膝盖上方。 手掌朝上，慢慢地将手向肩膀弯曲，保持上臂静止。 在顶部暂停片刻，然后慢慢将手放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"3117","name_zh":"弹力带固定靠背窄握下拉","target":"背阔肌","media_id":"4LoWllp","instructions_zh":"将弹力带固定在您上方的固定点上，例如上拉杆或坚固的横梁。 坐在面向乐队的长凳或椅子上，双脚平放在地上，膝盖弯曲。 紧紧握住弹力带，手掌朝向您。 保持背部挺直并启动核心肌群。 将弹力带向下拉向胸部，将肩胛骨挤压在一起。 在动作的底部暂停片刻，感受背阔肌的收缩。 慢慢地将弹力带释放回起始位置，在整个运动过程中保持控制。 重复所需的重复次数。"},{"id":"3116","name_zh":"弹力带固定靠背反握下拉","target":"背阔肌","media_id":"ZH68exZ","instructions_zh":"将带子固定在头顶上方坚固的锚点上。 面向锚点站立，双脚分开与肩同宽。 反手握住弹力带，双手间距略宽于肩宽。 后退一步，在弹力带上产生张力，保持手臂完全伸展。 启动你的核心并将肩胛骨挤压在一起。 将弹力带向下拉向胸部，用肘部引导。 在动作的底部暂停片刻，感受背阔肌的收缩。 慢慢释放带子的张力并返回到起始位置。 重复所需的重复次数。"},{"id":"0977","name_zh":"弹力带前平举","target":"肩","media_id":"sTg7iys","instructions_zh":"双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝下。 保持双臂伸直，将弹力带举到身前，直到双臂与地面平行。 在顶部暂停片刻，然后慢慢将弹力带放回起始位置。 重复所需的重复次数。"},{"id":"0978","name_zh":"弹力带前平举","target":"肩","media_id":"TFA88iB","instructions_zh":"双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝下。 保持手臂伸直，慢慢向前举起，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"1408","name_zh":"弹力带臀部上提","target":"臀部","media_id":"E4R8Hz1","instructions_zh":"仰卧，膝盖弯曲，双脚平放在地上。 将阻力带放在膝盖上方。 调动你的臀肌和核心肌肉。 将脚后跟压入地面，将臀部抬离地板，在顶部挤压臀部。 在顶部暂停片刻，然后慢慢将臀部放回起始位置。 重复所需的重复次数。"},{"id":"0979","name_zh":"弹力带水平帕洛夫推","target":"腹部","media_id":"9pa4H5m","instructions_zh":"将带子固定在腰部高度的坚固锚点上。 垂直于锚点站立，双脚分开与肩同宽。 用双手抓住带子手柄并远离锚点以在带子中产生张力。 将双手放在胸前，保持肘部弯曲并靠近身体。 调动你的核心并保持稳定的姿势。 将手臂伸直至前方，将弹力带推离身体。 保持伸展姿势几秒钟，专注于保持核心紧张。 慢慢地将双手放回胸前，抵抗弹力带的拉力。 重复所需的重复次数。"},{"id":"0981","name_zh":"弹力带折刀式仰卧起坐","target":"腹部","media_id":"KCBKjma","instructions_zh":"平躺，双腿伸直，手臂伸过头顶，握住弹力带。 收紧腹肌，同时抬起双腿和上半身，将双手移向脚部。 在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。 重复所需的重复次数。"},{"id":"0983","name_zh":"弹力带跪姿单臂下拉","target":"背阔肌","media_id":"pmnrOp0","instructions_zh":"将带子固定在头顶上方坚固的锚点上。 跪下，用一只手握住弹力带，手掌朝下。 将手臂完全伸过头顶，保持肘部稍微弯曲。 调动你的背阔肌，将弹力带拉向你的一侧，使你的肘部靠近你的胸腔。 在底部停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0985","name_zh":"弹力带跪姿转体卷腹","target":"腹部","media_id":"225x2Vd","instructions_zh":"将带子固定在腰部高度的坚固锚点上。 面向远离锚点的方向跪下，用双手握住弹力带，保持肘部弯曲并靠近身体两侧。 收紧腹肌，慢慢地将躯干扭向一侧，将双手移向另一侧的臀部。 暂停片刻，然后慢慢回到起始位置。 在另一侧重复。 继续交替进行所需的重复次数。"},{"id":"0984","name_zh":"弹力带仰卧髋内旋","target":"臀部","media_id":"vIICElP","instructions_zh":"仰卧，双腿伸直，将阻力带绕在脚上。 弯曲膝盖并将其靠近胸部，双脚并拢。 慢慢向外旋转膝盖，使膝盖彼此远离，同时保持双脚并拢。 旋转结束时暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"1002","name_zh":"弹力带仰卧直腿抬高","target":"腹部","media_id":"bbLR7fB","instructions_zh":"平躺，双腿伸直，双脚并拢。 将带子放在脚弓周围，并用手握住带子的末端。 收紧腹肌，将双腿抬离地面，直到它们垂直于地板。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0986","name_zh":"弹力带单臂过头肱二头肌弯举","target":"肱二头肌","media_id":"UNAB8ak","instructions_zh":"双脚分开与肩同宽站立，将弹力带的一端放在脚下。 握住弹力带的另一端，手臂完全伸过头顶，手掌朝前。 保持上臂静止，将前臂向肩膀弯曲，挤压二头肌。 在顶部停顿片刻，然后慢慢将前臂放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0987","name_zh":"弹力带单臂单腿分腿蹲","target":"股四头肌","media_id":"arsYEd3","instructions_zh":"双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。 向前伸出一条腿，将脚尖放在长凳上或身后的一步上。 用一只手握住支撑物以保持平衡。 弯曲站立的腿，将身体降低到蹲姿，保持膝盖与脚趾在一条直线上。 推动脚后跟返回到起始位置。 重复所需的重复次数，然后换腿。"},{"id":"0988","name_zh":"弹力带单臂站立低位划船","target":"上背部","media_id":"km0sQC0","instructions_zh":"将带子固定在腰部高度的稳定锚点上。 面向锚点站立，双脚分开与肩同宽。 用一只手握住弹力带，手掌朝内，然后后退以在弹力带中产生张力。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将带子拉向腰部，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢松开弹力带回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0989","name_zh":"弹力带单臂转体推胸","target":"胸","media_id":"c16nYGA","instructions_zh":"将带子固定在胸部高度的坚固锚点上。 站立，一侧面向锚点，用一只手抓住带子。 远离锚点以在带子中产生张力。 将双脚分开与肩同宽，并稍微弯曲膝盖。 将握住弹力带的手穿过身体，朝向对侧的肩膀。 在保持弹力带张力的同时，将手向前推离身体，伸展手臂。 慢慢回到起始位置并重复所需的重复次数。 换边并用另一只手重复练习。"},{"id":"0990","name_zh":"弹力带单臂转体坐姿划船","target":"上背部","media_id":"DKBwJrL","instructions_zh":"坐在长凳或椅子上，双脚平放在地上，背部挺直。 用一只手握住弹力带，并将手臂完全伸到身前。 保持背部挺直，弯曲肘部并将肩胛骨挤压在一起，将弹力带拉向身体。 同时，将躯干向拉动手臂的一侧扭转。 在顶部暂停片刻，然后慢慢释放弹力带的张力并返回到起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0991","name_zh":"弹力带拉穿","target":"臀部","media_id":"VtTbiP3","instructions_zh":"将阻力带连接到地面上坚固的锚点上。 背对锚点站立，双脚与肩同宽。 向前迈一步，在弹力带中产生张力，保持膝盖稍微弯曲。 铰接臀部并将臀部向后推，保持膝盖轻微弯曲。 降低躯干直到与地面平行，感觉腿筋被拉伸。 向前推动臀部并挤压臀部以返回起始位置。 重复所需的重复次数。"},{"id":"0992","name_zh":"弹力带推举仰卧起坐","target":"腹部","media_id":"zFzbBfL","instructions_zh":"将带子牢固地固定在稳定的锚点上。 平躺，膝盖弯曲，双脚平放在地上。 用双手握住弹力带，并将双臂伸向天花板。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"0993","name_zh":"弹力带反向飞鸟","target":"肩","media_id":"sTfvVsG","instructions_zh":"将带子固定在胸部高度的固定物体上。 双脚分开与肩同宽站立，双手握住弹力带放在身前。 保持手臂伸直并将其向两侧抬起，直到与地面平行。 在动作的最高点将肩胛骨挤压在一起。 慢慢地将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0994","name_zh":"弹力带反握腕弯举","target":"前臂","media_id":"Ezpnw9d","instructions_zh":"坐在长凳或椅子上，双脚平放在地面上。 正手握住弹力带，手掌朝下，然后将其缠绕在手指上。 将前臂放在大腿上，手腕悬在边缘上。 慢慢向上弯曲手腕，挤压前臂。 在顶部暂停片刻，然后慢慢将手腕放回起始位置。 重复所需的重复次数。"},{"id":"0996","name_zh":"弹力带坐姿髋内旋","target":"臀部","media_id":"9gbyYKk","instructions_zh":"坐在椅子或长凳上，背部挺直，双脚平放在地面上。 在大腿周围、膝盖上方放置一条阻力带。 保持膝盖弯曲 90 度，双脚分开与肩同宽。 收紧臀肌，慢慢向外旋转膝盖，克服弹力带的阻力。 动作结束时暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"1011","name_zh":"弹力带坐姿转体","target":"腹部","media_id":"S1JXDAG","instructions_zh":"坐在地上，双腿向前伸展，背部挺直。 将带子绕在腰上，并用双手握住两端。 收紧腹肌，慢慢将躯干扭向一侧，保持背部挺直，双脚着地。 扭转结束时暂停片刻，然后慢慢回到起始位置。 重复扭转到另一侧。 继续交替进行所需的重复次数。"},{"id":"0997","name_zh":"弹力带肩推举","target":"肩","media_id":"peAeMR3","instructions_zh":"双脚分开与肩同宽站立，将弹力带放在脚下。 手掌朝前握住弹力带，将双手举至肩高，肘部弯曲。 将弹力带压过头顶，充分伸展双臂。 在顶部暂停片刻，然后慢慢将阻力带降低至肩部高度。 重复所需的重复次数。"},{"id":"1018","name_zh":"弹力带耸肩","target":"斜方肌","media_id":"trmte8s","instructions_zh":"双脚分开与肩同宽站立，将弹力带放在脚下，用手握住两端。 保持手臂伸直并放松，让弹力带悬挂在大腿前面。 向上耸肩，尽可能高地举起弹力带，以启动斜方肌。 保持收缩一会儿，然后慢慢将肩膀放回起始位置。 重复所需的重复次数。"},{"id":"0998","name_zh":"弹力带侧向臂屈伸","target":"肱三头肌","media_id":"obe5LMq","instructions_zh":"双脚分开与肩同宽站立，双手握住弹力带，掌心朝下。 将手臂伸直至两侧，保持与地面平行。 慢慢弯曲肘部，将双手放在肩膀上，保持上臂不动。 暂停片刻，然后慢慢将手臂伸回起始位置。 重复所需的重复次数。"},{"id":"0999","name_zh":"弹力带单腿提踵","target":"小腿","media_id":"9JprnPh","instructions_zh":"双脚分开站立，与臀部同宽，将弹力带绕在左脚掌上。 如果需要，请抓住一个稳定的物体以保持平衡。 慢慢地将左脚跟抬离地面，将身体重量转移到脚掌上。 在顶部暂停片刻，然后慢慢将左脚跟放回起始位置。 重复所需的重复次数，然后换右腿。"},{"id":"1000","name_zh":"弹力带单腿反向提踵","target":"小腿","media_id":"QsSQWbf","instructions_zh":"双脚分开站立，与臀部同宽，将弹力带放在脚掌周围。 抓住稳定的物体以保持平衡。 慢慢地将脚跟抬离地面，将身体重量转移到脚掌上。 在顶部暂停片刻，然后慢慢将脚跟放回起始位置。 重复所需的重复次数，然后换另一条腿。"},{"id":"1001","name_zh":"弹力带单腿分腿蹲","target":"股四头肌","media_id":"y8bYM8w","instructions_zh":"双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。 右脚向前迈一大步，左脚向后退一小步。 弯曲膝盖并降低身体，直到右大腿与地面平行，保持左膝盖略高于地面。 推动右脚跟回到起始位置。 在另一侧重复。"},{"id":"1004","name_zh":"弹力带深蹲","target":"臀部","media_id":"TUZLh71","instructions_zh":"双脚分开站立，与肩同宽，弹力带放在膝盖上方。 保持挺胸、核心收紧，将臀部向后推，弯曲膝盖，形成下蹲姿势。 确保膝盖位于脚趾上方，并且重量位于脚后跟。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1003","name_zh":"弹力带深蹲划船","target":"臀部","media_id":"w1NOByi","instructions_zh":"将带子固定在腰部高度的坚固锚点上。 面向锚点站立，双脚分开与肩同宽。 双手握住弹力带手柄，手掌相对，双臂向前伸展。 弯曲膝盖并蹲下，保持背部挺直，挺胸。 从蹲姿开始，将弹力带手柄拉向身体，将肩胛骨挤压在一起。 在最高点停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数。"},{"id":"1005","name_zh":"弹力带站姿卷腹","target":"腹部","media_id":"Kzg30R7","instructions_zh":"将带子固定在腰部高度的坚固锚点上。 背对锚点站立，双脚与肩同宽。 用双手握住弹力带并将其举至胸前，保持肘部弯曲并靠近身体。 收紧腹肌，慢慢向前挺胸，使胸部靠近膝盖。 在卷腹的最高点暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"1022","name_zh":"弹力带站姿后束划船","target":"肩","media_id":"tc5dYrf","instructions_zh":"双脚分开与肩同宽站立，将弹力带放在脚下。 双手握住弹力带手柄，手掌相对，双臂向前伸展。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将弹力带拉向胸部，将肩胛骨挤压在一起。 在最高点停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数。"},{"id":"1007","name_zh":"弹力带站姿转体卷腹","target":"腹部","media_id":"euq4pwp","instructions_zh":"双脚分开与肩同宽站立，将弹力带绕在上背部，穿过胸前。 用手握住带子的末端，保持肘部弯曲并靠近身体两侧。 收紧腹肌并将躯干向一侧扭转，将肘部移向另一侧的膝盖。 暂停片刻，然后回到起始位置。 在另一侧重复。 继续交替进行所需的重复次数。"},{"id":"1008","name_zh":"弹力带上台阶","target":"臀部","media_id":"d5bTEPV","instructions_zh":"将一条带子绕在大腿上，就在膝盖上方。 面向台阶或平台站立，双脚分开与臀部同宽。 用右脚踩上平台，用脚后跟推动。 将左腿伸到身后，保持伸直。 将左脚放回地面。 重复左脚踩上平台的动作。 继续交替双腿达到所需的重复次数。"},{"id":"1009","name_zh":"弹力带直腿硬拉","target":"臀部","media_id":"kuMiR2T","instructions_zh":"双脚分开站立，与肩同宽，将弹力带绕在脚踝上。 用双手将弹力带放在大腿前面，手掌朝向身体。 保持背部挺直，核心收紧，铰接臀部，慢慢将上半身降低到地面。 当你降低时，将臀部向后推，并让膝盖稍微弯曲。 将弹力带降低至地面，感受腿筋的拉伸。 在底部暂停片刻，然后启动臀肌和腿筋，将上半身抬回到起始位置。 重复所需的重复次数。"},{"id":"1023","name_zh":"弹力带直背直腿硬拉","target":"臀部","media_id":"lHeUULr","instructions_zh":"双脚分开与肩同宽站立，将弹力带绕在大腿上。 用双手将弹力带放在大腿前面，手掌朝向身体。 保持背部挺直，膝盖稍微弯曲，铰接臀部并将弹力带降低到地面。 当你降低弹力带时，感受腿筋的拉伸。 启动臀肌和腿筋，将身体抬回到起始位置。 重复所需的重复次数。"},{"id":"1010","name_zh":"弹力带直腿硬拉","target":"脊柱","media_id":"KUaoUV8","instructions_zh":"双脚分开与肩同宽站立，将弹力带绕在脚上。 双手握住弹力带，手掌朝向身体，手臂伸直。 收紧核心并保持膝盖轻微弯曲。 慢慢地以臀部为中心向前转动，保持背部挺直，挺胸。 将弹力带降低至地面，同时保持双腿伸直。 在底部暂停片刻，然后挤压臀肌和腿筋，回到起始位置。 重复所需的重复次数。"},{"id":"1012","name_zh":"弹力带转体推举","target":"肩","media_id":"u4bAmKp","instructions_zh":"双脚分开与肩同宽站立，将弹力带放在脚下。 将弹力带手柄保持在与肩同高的位置，手掌朝前。 启动你的核心并将弹力带压过头顶，充分伸展你的手臂。 当你按压时，将你的躯干扭转到一侧，保持臀部稳定。 在顶部暂停片刻，然后回到起始位置。 在另一侧重复按压和扭转。 继续交替进行所需的重复次数。"},{"id":"1369","name_zh":"弹力带双腿提踵（弹力带在双腿下）v.2","target":"小腿","media_id":"jl6uxZV","instructions_zh":"双脚分开与肩同宽站立，并将阻力带放在双脚下方。 用手握住带子的末端以保持稳定。 用小腿将脚跟抬离地面，尽可能高。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1013","name_zh":"弹力带反握下拉","target":"背阔肌","media_id":"k6tUeqS","instructions_zh":"将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。 面向锚点站立，双脚分开与肩同宽。 反手握住弹力带，双手间距略宽于肩宽。 将手臂完全伸过头顶，保持肘部稍微弯曲。 收紧背阔肌，将弹力带向下拉向胸部，将肩胛骨挤压在一起。 在动作底部停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数。"},{"id":"1014","name_zh":"弹力带V字卷腹","target":"腹部","media_id":"H6ETwO9","instructions_zh":"平躺，双腿伸直，手臂伸过头顶，握住弹力带。 收紧腹肌，同时将双腿和上半身抬离地面，双手伸向脚趾。 在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。 重复所需的重复次数。"},{"id":"1015","name_zh":"弹力带垂直帕罗夫推","target":"腹部","media_id":"G7PXMlT","instructions_zh":"双脚分开与肩同宽站立，将弹力带缠绕在胸部高度的坚固物体上。 用双手握住弹力带并远离锚点，在弹力带中产生张力。 使自己垂直于锚点，一侧面向弹力带。 将双臂伸直在身前，保持双手与胸同高。 收紧核心肌群，将弹力带压离胸部，充分伸展手臂。 保持该姿势几秒钟，然后慢慢将弹力带拉回到胸部。 重复所需的重复次数，然后换边。"},{"id":"1016","name_zh":"弹力带腕弯举","target":"前臂","media_id":"vUTfFHw","instructions_zh":"坐在长凳或椅子上，双脚平放在地面上。 双手握住弹力带，手掌朝上，前臂放在大腿上。 慢慢向上弯曲手腕，挤压前臂。 在顶部暂停片刻，然后慢慢将手腕放回起始位置。 重复所需的重复次数。"},{"id":"1017","name_zh":"弹力带Y字上举","target":"肩","media_id":"aHDy5O5","instructions_zh":"双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝内。 保持双臂伸直，将其向上举至两侧，与身体形成“Y”形。 在动作的最高点将肩胛骨挤压在一起。 慢慢地将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0023","name_zh":"杠铃交替弯举","target":"肱二头肌","media_id":"Yza7XrQ","instructions_zh":"站直，双脚分开与肩同宽，每只手握住一个杠铃，手掌朝前。 保持上臂静止，在弯举哑铃时呼气，同时收缩二头肌。 继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢开始将杠铃放回起始位置。 重复所需的重复次数，交替手臂。"},{"id":"0024","name_zh":"杠铃平凳前蹲","target":"股四头肌","media_id":"Y7YcmIJ","instructions_zh":"首先站立，双脚分开与肩同宽，将杠铃放在上胸部，锁骨下方。 正手握住杠铃，保持肘部向上，上臂与地面平行。 弯曲膝盖和臀部，将身体降低到蹲姿，保持背部挺直，挺胸。 在深蹲底部暂停片刻，然后用脚后跟恢复到起始位置。 重复所需的重复次数。"},{"id":"0025","name_zh":"杠铃平板卧推","target":"胸","media_id":"EIeI8Vf","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 正手握住杠铃，握距略宽于肩宽。 将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。 将杠铃慢慢降低到胸部，保持肘部内收。 当杠铃触及胸部时暂停片刻。 伸展双臂，将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"0026","name_zh":"杠铃平板凳深蹲","target":"股四头肌","media_id":"W9pFVv1","instructions_zh":"将杠铃放在深蹲架上，与胸部同高。 背对架子站立，双脚与肩同宽。 弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。 正手握住杠铃，握距略宽于肩宽。 将杠铃从架子上提起并向后退一步，确保双脚仍与肩同宽。 降低身体蹲下，保持膝盖与脚趾在一条线上。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1316","name_zh":"杠铃屈臂上拉","target":"背阔肌","media_id":"cA9FuWG","instructions_zh":"平躺在长凳上，头放在一端，双脚放在地板上。 握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。 将杠铃放在脑后，同时保持手臂稍微弯曲。 暂停片刻，然后将杠铃举回起始位置。 重复所需的重复次数。"},{"id":"0027","name_zh":"杠铃俯身划船","target":"上背部","media_id":"eZyBC3j","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 臀部向前弯曲，同时保持背部挺直、挺胸。 正手握住杠铃，双手间距略宽于肩宽。 通过收缩肩胛骨并挤压背部肌肉，将杠铃拉向下胸部。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"2407","name_zh":"杠铃弯举（使用弯举板）","target":"肱二头肌","media_id":"aee2Fcj","instructions_zh":"站直，双脚分开与肩同宽，反手握住杠铃，手掌朝上。 将上臂靠在手臂冲击波上，保持肘部靠近躯干。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0028","name_zh":"杠铃高翻推举","target":"股四头肌","media_id":"SGY8Zui","instructions_zh":"双脚分开与肩同宽站立，杠铃放在你面前的地板上。 弯曲膝盖并以臀部为铰链降低并用正手握住杠铃，双手分开略宽于肩宽。 通过脚后跟发力，伸展臀部和膝盖，将杠铃抬离地板，使其靠近身体。 当杠铃到达大腿时，爆发性伸展臀部，耸肩，并将杠铃拉向胸部。 当杠铃到达胸部高度时，迅速将其降至肩部水平，肘部向前，手掌朝上。 从接球位置开始，伸展双臂并将杠铃笔直向上推，将杠铃压过头顶。 将杠铃放回起始位置，然后重复所需的重复次数。"},{"id":"0029","name_zh":"杠铃抓举握前蹲","target":"臀部","media_id":"qi996YS","instructions_zh":"首先，双脚分开与肩同宽，将杠铃放在上胸部，肘部向前。 弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。 下降时保持挺胸、背部挺直，确保膝盖不超过脚趾。 继续降低，直到大腿与地面平行，或者尽可能低。 在底部停顿片刻，然后用脚跟推动站起来，伸展臀部和膝盖。 重复所需的重复次数。"},{"id":"0030","name_zh":"杠铃窄距平板卧推","target":"肱三头肌","media_id":"J6Dx1Mu","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 紧紧握住杠铃，握距略窄于肩宽。 松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。 当杠铃触及胸部时暂停片刻。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0031","name_zh":"杠铃弯举","target":"肱二头肌","media_id":"25GPyDY","instructions_zh":"站直，双脚分开与肩同宽，反手握住杠铃，手掌朝前。 保持肘部靠近躯干，在弯举哑铃时呼气，同时收缩二头肌。 继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢开始将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0032","name_zh":"杠铃硬拉","target":"臀部","media_id":"ila4NZS","instructions_zh":"双脚分开与肩同宽站立，杠铃放在你面前的地面上。 弯曲膝盖并以臀部为铰链，降低躯干，正手握住杠铃，双手分开略宽于肩宽。 当你通过脚后跟将杠铃抬离地面时，保持背部挺直，胸部抬起，伸展臀部和膝盖。 当你站直时，挤压你的臀部并保持你的核心参与。 弯曲臀部和膝盖，将杠铃放回地面，保持背部挺直。 重复所需的重复次数。"},{"id":"0033","name_zh":"杠铃下斜卧推","target":"胸","media_id":"GrO65fd","instructions_zh":"躺在倾斜的长凳上，双脚固定，头部低于臀部。 正手握住杠铃，握距略宽于肩宽。 松开杠铃，慢慢将其降低到胸部，保持肘部内收。 在底部停顿片刻，然后将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"0034","name_zh":"杠铃下斜屈臂上拉","target":"背阔肌","media_id":"hMEptv0","instructions_zh":"躺在倾斜的长凳上，头部低于臀部，双脚固定。 旋前握住杠铃（手掌背向您），并将手臂伸直至胸部上方。 有控制地将杠铃降低到头后，保持手臂稍微弯曲。 暂停片刻，然后收缩背阔肌，将杠铃抬回到起始位置。 重复所需的重复次数。"},{"id":"0035","name_zh":"杠铃下斜窄距颅骨推","target":"肱三头肌","media_id":"LMGXZn8","instructions_zh":"躺在下斜长凳上，头低于脚，紧紧握住杠铃。 弯曲肘部，将杠铃向前额降低，保持上臂静止。 暂停片刻，然后伸展双臂将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"1255","name_zh":"杠铃下斜上拉","target":"胸","media_id":"9sgNE2O","instructions_zh":"躺在倾斜的长凳上，头部低于臀部，双脚固定。 旋前握住杠铃（手掌背向自己），双手之间的距离略宽于肩宽。 将手臂伸至胸部上方，保持肘部轻微弯曲。 以弧线动作将杠铃降低到头后，感受胸部和肩膀的伸展。 暂停片刻，然后反向动作将杠铃恢复到起始位置。 重复所需的重复次数。"},{"id":"0036","name_zh":"杠铃下斜宽距卧推","target":"胸","media_id":"hl8DUh8","instructions_zh":"躺在倾斜的长凳上，双脚固定，头部低于臀部。 宽握距抓住杠铃，握距略宽于肩宽。 将杠铃降低到胸部，保持肘部向两侧伸出。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0037","name_zh":"杠铃下斜宽距上拉","target":"背阔肌","media_id":"Hj4FOCd","instructions_zh":"躺在倾斜的长凳上，头部低于臀部，双脚固定。 宽握距握住杠铃，并将双臂伸直至胸部上方。 有控制地将杠铃降低到头后，保持手臂伸直。 暂停片刻，然后将杠铃举回起始位置。 重复所需的重复次数。"},{"id":"0038","name_zh":"杠铃拖拽弯举","target":"肱二头肌","media_id":"IENzBdA","instructions_zh":"双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。 让杠铃悬挂在大腿前面，与手臂保持一定距离。 保持上臂静止，通过收缩二头肌将杠铃向上卷曲至胸部。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"1370","name_zh":"杠铃地板提踵","target":"小腿","media_id":"2IHEa2T","instructions_zh":"将杠铃放在您面前的地板上。 站立，脚掌放在杠铃边缘，脚跟悬垂。 如果需要，请抓住一个稳定的物体以保持平衡。 尽可能高地抬高脚后跟，用小腿来抬起身体。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0039","name_zh":"杠铃前蹲","target":"臀部","media_id":"IeTIEqg","instructions_zh":"首先站立，双脚分开与肩同宽，脚趾稍微向外。 将杠铃放在胸前，双手与肩同宽，肘部向前。 当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。 降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0041","name_zh":"杠铃前平举","target":"肩","media_id":"b2Uoz54","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃于大腿前方。 保持手臂伸直，向前向上举起杠铃，直至达到肩部水平。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0040","name_zh":"杠铃前平举及上拉","target":"胸","media_id":"33AzZeV","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃，手掌朝下。 保持双臂伸直，将杠铃举至身前，直至达到肩膀高度。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 接下来，将杠铃放低到头后，保持手臂伸直。 在底部停顿片刻，然后将杠铃举回起始位置。 重复所需的重复次数。"},{"id":"0042","name_zh":"杠铃前蹲","target":"臀部","media_id":"zG0zs85","instructions_zh":"首先站立，双脚分开与肩同宽，脚趾稍微向外。 将杠铃放在肩膀前面，将其放在锁骨和肩膀上。 当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。 降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0043","name_zh":"杠铃全蹲","target":"臀部","media_id":"qXTaZnJ","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微向外。 将杠铃放在上背部，将其放在斜方肌或三角肌后束上。 当你开始降低身体时，启动你的核心并保持胸部挺直。 弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。 放低身体，直到大腿与地面平行或稍低于地面。 保持膝盖与脚趾对齐，并将重量放在脚后跟上。 通过脚后跟站起来，伸展臀部和膝盖。 重复所需的重复次数。"},{"id":"1461","name_zh":"杠铃全蹲（背面视角）","target":"臀部","media_id":"DhMl549","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微向外。 将杠铃放在上背部，将其放在斜方肌或三角肌后束上。 当你开始降低身体时，启动你的核心并保持胸部挺直。 弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。 降低身体，直到大腿与地面平行或稍低于地面。 保持膝盖与脚趾对齐，并将重量放在脚后跟上。 通过脚后跟站起来，伸展臀部和膝盖。 重复所需的重复次数。"},{"id":"1462","name_zh":"杠铃全蹲（侧面视角）","target":"臀部","media_id":"iYzB0Cz","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微向外。 将杠铃放在上背部，将其放在斜方肌或三角肌后束上。 当你开始降低身体时，启动你的核心并保持胸部挺直。 弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。 降低身体，直到大腿与地面平行或稍低于地面。 保持膝盖与脚趾对齐，并将重量放在脚后跟上。 通过脚后跟站起来，伸展臀部和膝盖。 重复所需的重复次数。"},{"id":"1545","name_zh":"杠铃泽奇全蹲","target":"臀部","media_id":"vR1vold","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微外翻。 将杠铃放在肘部的弯曲处，双手握住杠铃以保持稳定。 当你将臀部向后降低到蹲姿时，启动你的核心并保持胸部抬起。 保持膝盖与脚趾对齐，并将重量放在脚后跟上。 降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。 通过脚跟发力站起来，在动作的最高点挤压臀部。 重复所需的重复次数。"},{"id":"1409","name_zh":"杠铃臀桥","target":"臀部","media_id":"qKBpF7I","instructions_zh":"首先平躺在地上，膝盖弯曲，双脚平放在地板上。 将杠铃放在臀部上，用双手牢牢握住它。 锻炼臀部和核心肌肉，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。 在顶部暂停片刻，挤压臀部。 慢慢地将臀部放回起始位置。 重复所需的重复次数。"},{"id":"3562","name_zh":"杠铃臀桥（双腿置于平凳）（男）","target":"臀部","media_id":"qg2PGl6","instructions_zh":"首先坐在长凳边缘，上背部靠在长凳上，双脚平放在地面上，与臀部同宽。 将杠铃放在臀部上，用双手牢牢握住它。 锻炼臀肌和核心肌肉，然后用脚后跟将臀部抬离长凳，形成从膝盖到肩膀的一条直线。 在顶部暂停片刻，挤压臀部。 慢慢地将臀部放回起始位置。 重复所需的重复次数。"},{"id":"0044","name_zh":"杠铃早安式","target":"大腿后侧","media_id":"XlZ4lAC","instructions_zh":"首先站立，双脚分开与肩同宽，将杠铃放在上背部。 保持背部挺直，核心肌群参与，臀部向前转动，将臀部向后推，就好像你试图用臀部触碰身后的墙壁一样。 降低躯干直到与地面平行，感觉腿筋被拉伸。 暂停片刻，然后通过挤压臀部并将臀部向前推回到起始位置。 重复所需的重复次数。"},{"id":"0045","name_zh":"杠铃断头台卧推","target":"胸","media_id":"GXoaSgn","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 正手握住杠铃，握距略宽于肩宽。 慢慢地将杠铃降低到颈部，保持肘部朝外。 当杠铃位于颈部上方时，暂停片刻。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0046","name_zh":"杠铃哈克深蹲","target":"臀部","media_id":"5VCj6iH","instructions_zh":"首先站立，双脚分开与肩同宽，脚趾稍微向外。 将杠铃放在腿后面，将其放在大腿上部。 弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。 继续降低，直到大腿与地面平行，或者尽可能低。 暂停片刻，然后用力推动脚后跟，回到起始位置。 重复所需的重复次数。"},{"id":"1436","name_zh":"杠铃高杠深蹲","target":"臀部","media_id":"Gnfo4FM","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微向外。 将杠铃放在上背部，放在斜方肌上。 当你开始蹲下时，启动你的核心并保持胸部挺直，将臀部向后推并弯曲膝盖。 放低身体，直到大腿与地面平行，或者尽可能低到您能舒服的高度。 通过脚后跟站起来，伸展臀部和膝盖。 重复所需的重复次数。"},{"id":"0047","name_zh":"杠铃上斜卧推","target":"胸","media_id":"3TZduzM","instructions_zh":"设置一个 45 度角的上斜凳。 躺在长凳上，双脚平放在地上。 正手握住杠铃，握距略宽于肩宽。 松开杠铃并将其缓慢降低至胸部，保持肘部呈 45 度角。 在底部停顿片刻，然后将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"1719","name_zh":"杠铃上斜窄距卧推","target":"肱三头肌","media_id":"gx7s7uF","instructions_zh":"设置一个 45 度角的上斜凳。 躺在长凳上，双脚平放在地上。 紧紧握住杠铃，握距略窄于肩宽。 松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。 当杠铃触及胸部时暂停片刻。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0048","name_zh":"杠铃上斜反握卧推","target":"肱三头肌","media_id":"641mIfk","instructions_zh":"设置一个 45 度角的上斜凳。 仰卧在长凳上，反握抓住杠铃，双手距离略宽于肩宽。 松开杠铃并将其向上胸部降低，保持肘部内收。 在底部停顿片刻，然后将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"0049","name_zh":"杠铃上斜划船","target":"上背部","media_id":"dmgMp3n","instructions_zh":"设置一个 45 度角的上斜凳。 脸朝下躺在长凳上，胸部靠在垫子上，双脚平放在地上。 正手握住杠铃，握距略宽于肩宽。 保持背部挺直，核心肌群参与。 将杠铃拉向胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0050","name_zh":"杠铃上斜肩上举","target":"前锯肌","media_id":"xi0yckC","instructions_zh":"设置一个 45 度角的上斜凳。 坐在长凳上，背部靠在垫子上，双脚平放在地面上。 正手握住杠铃，杠铃间距略宽于肩宽。 将杠铃举至肩膀高度，保持肘部稍微弯曲。 慢慢地将杠铃举过头顶，充分伸展双臂。 在顶部停顿片刻，然后慢慢将杠铃放回肩部高度。 重复所需的重复次数。"},{"id":"0051","name_zh":"杠铃杰斐逊深蹲","target":"臀部","media_id":"pkSoCW9","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微外翻。 正手握住杠铃，将其放在身体前部、腰部下方。 左脚向前迈出，右脚向后迈出，双脚分开与肩同宽。 弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。 脚后跟用力，站回起始位置。 重复该动作，每次重复时交替使用前脚和后脚。"},{"id":"0052","name_zh":"杠铃JM卧推","target":"肱三头肌","media_id":"ZsiqXYa","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 正手握住杠铃，握距略宽于肩宽。 将杠铃降低到胸部，保持肘部靠近身体。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0053","name_zh":"杠铃跳跃深蹲","target":"臀部","media_id":"1gFNTZV","instructions_zh":"首先，双脚分开与肩同宽站立，将杠铃放在上背部。 弯曲膝盖并将臀部向后推，将身体降低至蹲姿。 一旦到达深蹲底部，就从地面跳起向上爆发。 跳跃时，伸展臀部、膝盖和脚踝，推动脚趾。 轻轻地回到蹲姿，然后立即重复该动作达到所需的重复次数。"},{"id":"1410","name_zh":"杠铃侧弓步","target":"臀部","media_id":"py1HSzx","instructions_zh":"双脚分开与肩同宽站立，将杠铃放在上背部。 右脚向一侧迈出一大步，保持左脚踩地。 弯曲右膝，将身体降低到弓步位置，保持左腿伸直。 用右脚推出并返回到起始位置。 在另一侧重复，用左脚迈步。"},{"id":"1435","name_zh":"杠铃低杠深蹲","target":"臀部","media_id":"bTpEUcm","instructions_zh":"双脚分开与肩同宽站立，杠铃放在上背部。 保持挺胸，核心收紧，弯曲膝盖并向后推臀部，慢慢降低身体。 继续降低，直到大腿与地面平行或略低于地面。 暂停片刻，然后用力推动脚后跟，回到起始位置。 重复所需的重复次数。"},{"id":"0054","name_zh":"杠铃弓步蹲","target":"臀部","media_id":"t8iSghb","instructions_zh":"首先，双脚分开与肩同宽，将杠铃放在上背部。 右脚向前迈出一步，保持躯干直立。 弯曲右膝降低身体，直到大腿与地面平行。 推动右脚跟回到起始位置。 用左腿重复上述动作，交替腿进行所需的重复次数。"},{"id":"1720","name_zh":"杠铃仰卧颈后臂屈伸","target":"肱三头肌","media_id":"yg8Totb","instructions_zh":"平躺在长凳上，双脚平放在地上，头放在长凳的末端。 正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。 保持上臂静止，弯曲肘部，慢慢将杠铃降低到脑后。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"0055","name_zh":"杠铃仰卧窄距卧推","target":"肱三头肌","media_id":"EcaV7aL","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 紧紧握住杠铃，双手与肩同宽，手掌朝向脚部。 将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。 慢慢地将杠铃降低到胸部，保持肘部靠近身体。 当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。 重复所需的重复次数。"},{"id":"0056","name_zh":"杠铃仰卧窄距臂屈伸","target":"肱三头肌","media_id":"HJ63mSO","instructions_zh":"平躺在长凳上，双脚平放在地上，头放在长凳的末端。 紧握杠铃，双手与肩同宽，掌心向上。 充分伸展双臂，将杠铃举至胸部上方。 保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。 在底部停顿片刻，然后将手臂伸展回起始位置。 重复所需的重复次数。"},{"id":"0057","name_zh":"杠铃仰卧臂屈伸","target":"肱三头肌","media_id":"EMpUwRI","instructions_zh":"平躺在长凳上，双脚平放在地上，头放在长凳的末端。 正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。 保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"0058","name_zh":"杠铃仰卧提拉(髋部)","target":"臀部","media_id":"SNFfUff","instructions_zh":"仰卧在长凳上，双脚平放在地上，膝盖弯曲。 正手握住杠铃并将其放在臀部上。 收紧臀部，将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。 在顶部暂停片刻，然后慢慢将臀部放回起始位置。 重复所需的重复次数。"},{"id":"0059","name_zh":"杠铃仰卧牧师凳弯举","target":"肱二头肌","media_id":"SYJ4Bkt","instructions_zh":"坐在牧师长凳上，胸部靠在垫子上，手臂伸出边缘，反手握住杠铃。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0061","name_zh":"杠铃仰卧臂屈伸","target":"肱三头肌","media_id":"iZop9xO","instructions_zh":"平躺在长凳上，双脚平放在地上，头放在长凳的末端。 正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。 保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。 在底部停顿片刻，然后将手臂伸回起始位置。 重复所需的重复次数。"},{"id":"0060","name_zh":"杠铃仰卧臂屈伸(碎颅者)","target":"肱三头肌","media_id":"h8LFzo9","instructions_zh":"平躺在长凳上，双脚平放在地上，头放在长凳的末端。 正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。 保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。 当杠铃位于前额上方时暂停片刻，然后将手臂向后伸展至起始位置。 重复所需的重复次数。"},{"id":"0063","name_zh":"杠铃窄距深蹲","target":"臀部","media_id":"elhhVgj","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微向外。 将杠铃放在上背部，将其放在斜方肌或三角肌后束上。 收紧核心并保持挺胸，同时弯曲膝盖并向后推臀部，慢慢降低身体。 继续降低，直到大腿与地面平行或略低于地面。 暂停片刻，然后用力推动脚后跟，回到起始位置。 重复所需的重复次数。"},{"id":"0064","name_zh":"杠铃单臂俯身划船","target":"上背部","media_id":"Jsgsc27","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲，用一只手正握握住杠铃。 臀部向前弯曲，保持背部挺直，头部处于中立位置。 将杠铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。 以受控的方式将杠铃降低回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0065","name_zh":"杠铃单臂地板卧推","target":"肱三头肌","media_id":"vtusOWT","instructions_zh":"仰卧在地板上，膝盖弯曲，双脚平放在地面上。 用一只手握住杠铃，掌心朝上，将手臂伸直至胸部上方。 慢慢地将杠铃降低到胸部，保持肘部靠近身体。 在底部停顿片刻，然后将杠铃推回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0066","name_zh":"杠铃单臂侧硬拉","target":"臀部","media_id":"2DxtqHL","instructions_zh":"双脚分开与肩同宽站立，一只手握住杠铃，正握。 保持背部挺直，核心肌群参与。 臀部弯曲，将杠铃向腿外侧放低，保持手臂伸直，挺胸。 尽可能降低杠铃，同时保持良好的姿势。 暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0067","name_zh":"杠铃单臂抓举","target":"肩","media_id":"xHKN2s8","instructions_zh":"双脚分开与肩同宽站立，脚趾稍微向外。 正手握住杠铃，双手分开略宽于肩宽。 弯曲膝盖，降低臀部至下蹲位置，保持背部挺直，挺胸。 爆发性伸展臀部、膝盖和脚踝，将杠铃向上推。 当杠铃到达胸部水平时，用手臂将其向上拉，使其靠近身体。 将肘部旋转到杠铃下方，并将手臂完全伸过头顶，锁定肘部。 以受控的方式将杠铃降低回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0068","name_zh":"杠铃单腿深蹲","target":"股四头肌","media_id":"uKyN64F","instructions_zh":"双脚分开与肩同宽站立，将杠铃放在上背部。 将一只脚抬离地面并向前伸展，保持与地面平行。 弯曲站立的腿，放低身体，就像坐回椅子上一样，保持挺胸、背部挺直。 降低身体直到大腿与地面平行，然后通过脚后跟推回到起始位置。 重复所需的重复次数，然后换腿并重复。"},{"id":"0069","name_zh":"杠铃过头深蹲","target":"股四头肌","media_id":"gfk9kD4","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微外翻。 宽握距握住杠铃，将其置于头顶，双臂完全伸展。 收紧核心肌群，将身体放低至蹲姿，保持胸部向上，膝盖位于脚趾上方。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1411","name_zh":"杠铃正手腕弯举(俯身凳上)","target":"前臂","media_id":"yzYH9pI","instructions_zh":"坐在长凳上，双脚平放在地上，前臂放在大腿上，手掌朝下。 正手握住杠铃，双手与肩同宽。 弯曲手腕，将杠铃降低到地面，保持前臂静止。 在底部停顿片刻，然后通过伸展手腕慢慢将杠铃举起。 重复所需的重复次数。"},{"id":"1412","name_zh":"杠铃反手腕弯举(俯身凳上)","target":"前臂","media_id":"SJAA2IQ","instructions_zh":"坐在长凳上，双脚平放在地面上，反手握住杠铃，手掌朝上。 将前臂放在长凳上，让手腕悬在长凳边缘。 保持前臂静止，呼气并尽可能向上弯曲手腕。 保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"3017","name_zh":"杠铃潘德雷划船","target":"上背部","media_id":"r0z6xzQ","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 臀部向前弯曲，保持背部挺直，挺胸。 正手握住杠铃，握距略宽于肩宽。 将杠铃拉向上腹部，将肩胛骨挤压在一起。 将杠铃降低回到起始位置。 重复所需的重复次数。"},{"id":"1751","name_zh":"杠铃架上卧推","target":"肱三头肌","media_id":"bndCa3Q","instructions_zh":"将杠铃放在与胸部同高的力量架上。 面向杠铃站立，将自己置于杠铃下方，双脚分开与肩同宽。 正手握住杠铃，握距略宽于肩宽。 将杠铃从架子上提起，并将其保持在胸部正上方，双臂完全伸展。 将杠铃向胸部方向降低，保持肘部靠近身体。 当杠铃触及胸部时暂停片刻。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0070","name_zh":"杠铃牧师凳弯举","target":"肱二头肌","media_id":"qOgPVf6","instructions_zh":"坐在牧师凳上，上臂放在垫子上，胸部靠在支撑物上。 反手握住杠铃，握距略宽于肩宽。 保持上臂静止，呼气并将杠铃向上弯向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气并慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0071","name_zh":"杠铃推举仰卧起坐","target":"腹部","media_id":"wnEscH8","instructions_zh":"平躺在垫子上，膝盖弯曲，双脚平放在地上。 正手握住杠铃，将其放在胸前。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"0072","name_zh":"杠铃俯卧上斜弯举","target":"肱二头肌","media_id":"WLvTAv5","instructions_zh":"设置一个 45 度角的上斜凳。 脸朝下躺在长凳上，胸部和腹部靠在长凳上。 反手握住杠铃，距离与肩同宽。 充分伸展双臂，让杠铃垂向地板。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0073","name_zh":"杠铃仰卧臂上拉","target":"背阔肌","media_id":"i6LWjok","instructions_zh":"平躺在长凳上，头放在一端，双脚放在地板上。 握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。 保持手臂伸直，以受控的方式将杠铃降低到头后，直到感觉到背阔肌被拉伸。 暂停片刻，然后将杠铃举回起始位置。 重复所需的重复次数。"},{"id":"0022","name_zh":"杠铃臂上拉接推举","target":"背阔肌","media_id":"znLogoF","instructions_zh":"平躺在长凳上，头朝一端，双脚着地。 旋前握住杠铃（手掌背向您），并将手臂伸直至胸部上方。 保持手臂伸直，以弧形动作将杠铃降低到脑后，直到感觉到背阔肌有拉伸感。 暂停片刻，然后反转动作，将杠铃推回到胸部上方的起始位置。 重复所需的重复次数。"},{"id":"0074","name_zh":"杠铃架拉","target":"臀部","media_id":"za9Ni4z","instructions_zh":"将杠铃放在膝盖高度的架子上。 双脚分开与肩同宽站立，脚趾稍微向外。 弯曲臀部和膝盖，降低身体高度，正手握住杠铃，双手与肩同宽。 通过伸展臀部和膝盖、向后拉肩膀并在顶部挤压臀部来收紧核心并举起杠铃。 弯曲臀部和膝盖，将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0075","name_zh":"杠铃后束飞鸟","target":"肩","media_id":"Ln9iTbU","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃，手掌朝下。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将杠铃向两侧举起，保持手臂伸直，直到它们与地面平行。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0076","name_zh":"杠铃后束划船","target":"肩","media_id":"S9zHIvU","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 正手握住杠铃，双手分开略宽于肩宽。 臀部向前弯曲，保持背部挺直，挺胸。 将杠铃拉向胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0078","name_zh":"杠铃后弓步","target":"臀部","media_id":"VaP75jl","instructions_zh":"首先，双脚分开与肩同宽，将杠铃放在上背部。 右脚向后退一步，用脚掌着地。 弯曲双膝降低身体，直到左大腿与地面平行。 推动左脚跟返回到起始位置。 换另一条腿重复上述步骤。"},{"id":"0077","name_zh":"杠铃后弓步 v.2","target":"臀部","media_id":"62Nw60O","instructions_zh":"双脚分开与肩同宽站立，将杠铃放在上背部。 右脚向后退一步，用脚掌着地。 弯曲双膝降低身体，直到左大腿与地面平行。 推动左脚跟返回到起始位置。 换另一条腿重复上述步骤。"},{"id":"0079","name_zh":"杠铃反式腕弯举 v.2","target":"前臂","media_id":"qDnGfDb","instructions_zh":"坐在长凳上，双脚平放在地上，膝盖弯曲。 正手握住杠铃，手掌朝下，双手与肩同宽。 将前臂放在大腿上，让手腕悬在边缘。 保持前臂静止，呼气并尽可能向上弯曲手腕。 保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"2187","name_zh":"杠铃反手窄距卧推","target":"肱三头肌","media_id":"YqJw82s","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 反握抓住杠铃，双手与肩同宽。 将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。 慢慢地将杠铃向胸部降低，保持肘部靠近身体。 当杠铃位于胸部正上方时，暂停片刻。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0080","name_zh":"杠铃反手弯举","target":"肱二头肌","media_id":"xNrS20v","instructions_zh":"站直，双脚分开与肩同宽，正手握住杠铃，手掌朝下。 保持上臂静止，向上弯举杠铃时呼气，收缩二头肌。 继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢将杠铃放回起始位置，保持上臂静止。 重复所需的重复次数。"},{"id":"0118","name_zh":"杠铃反握俯身划船","target":"上背部","media_id":"SzX3uzM","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 正手握住杠铃，手掌朝下，双手分开略宽于肩宽。 臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。 将杠铃拉向下胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"1256","name_zh":"杠铃反握下斜卧推","target":"胸","media_id":"DotAgEF","instructions_zh":"躺在倾斜的长凳上，双脚固定，头部低于臀部。 反握抓住杠铃，握距略宽于肩宽。 松开杠铃，慢慢将其降低到胸部，保持肘部内收。 在底部停顿片刻，然后将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"1257","name_zh":"杠铃反握上斜卧推","target":"胸","media_id":"DU7I633","instructions_zh":"设置一个 45 度角的上斜凳。 躺在长凳上，双脚平放在地上。 反握抓住杠铃，双手分开略宽于肩宽。 松开杠铃，慢慢将其降低到胸部，保持肘部内收。 当杠铃触及胸部时暂停片刻。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"1317","name_zh":"杠铃反握上斜划船","target":"上背部","media_id":"8d8qJQI","instructions_zh":"设置一个 45 度角的上斜凳。 坐在长凳上，面向靠背，胸部靠在靠背上。 反握（手掌朝下）抓住杠铃，双手距离略宽于肩宽。 保持背部挺直，核心参与。 将杠铃拉向上腹部，将肩胛骨挤压在一起。 在动作的最高点停顿片刻。 慢慢地将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"1721","name_zh":"杠铃反握碎颅者","target":"肱三头肌","media_id":"yRLPCLu","instructions_zh":"平躺在长凳上，双脚平放在地上，头放在长凳的末端。 反握握住杠铃，手掌朝向脸部，双手与肩同宽。 将手臂伸直越过胸部，保持肘部内收和手腕伸直。 弯曲肘部，慢慢将杠铃降低到前额，保持上臂静止。 在底部停顿片刻，然后将手臂伸回起始位置。 重复所需的重复次数。"},{"id":"0081","name_zh":"杠铃反手牧师凳弯举","target":"肱二头肌","media_id":"4LIG9xr","instructions_zh":"坐在牧师凳上，胸部靠在垫子上，手臂伸直向下，正手握住杠铃。 保持上臂静止，呼气并向上弯曲杠铃，同时收缩二头肌。 继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0082","name_zh":"杠铃反手腕弯举","target":"前臂","media_id":"LsZkfU6","instructions_zh":"坐在长凳上，双脚平放在地上，正手握住杠铃，手掌朝下。 将前臂放在大腿上，让手腕悬在边缘。 慢慢向上弯曲手腕，将杠铃拉向身体。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0084","name_zh":"杠铃滚轮","target":"腹部","media_id":"7M66AVi","instructions_zh":"跪在地板上，双手握住杠铃，距离与肩同宽。 向前滚动杠铃，伸展手臂并保持核心收紧。 继续向前滚动，直到身体完全伸展并且手臂举过头顶。 暂停片刻，然后慢慢将杠铃向膝盖方向滚动，保持控制。 重复所需的重复次数。"},{"id":"0083","name_zh":"杠铃凳上滚轮","target":"腹部","media_id":"Gxg9lDc","instructions_zh":"首先跪在地板上，将杠铃放在你面前的长凳上。 正手握住杠铃，握距略宽于肩宽。 保持核心收紧，背部挺直，慢慢向前滚动杠铃，将手臂伸到身前。 继续向前滚动杠铃，直到身体完全伸展并且手臂举过头顶。 在完全伸展的位置暂停片刻，然后慢慢地将杠铃向身体方向滚动，回到起始位置。 重复所需的重复次数。"},{"id":"0085","name_zh":"杠铃罗马尼亚硬拉","target":"臀部","media_id":"wQ2c4XD","instructions_zh":"站立，双脚分开与肩同宽，脚趾指向前方。 正手握住杠铃，双手分开略宽于肩宽。 弯曲臀部，保持背部挺直，膝盖稍微弯曲。 将杠铃向地面降低，使其靠近身体。 当你降低杠铃时，感受腿筋的拉伸。 一旦感觉到腿筋拉伸，就将臀部向前推并站直。 在动作的最高点挤压臀部。 将杠铃放回起始位置，然后重复所需的重复次数。"},{"id":"0086","name_zh":"杠铃坐姿颈后推举","target":"肩","media_id":"ngPpyRS","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 正手握住杠铃，杠铃间距略宽于肩宽。 将杠铃从架子上提起，然后将其降至与肩同高，位于头后。 向上推杠铃，直到手臂完全伸展。 将杠铃降低回到起始位置。 重复所需的重复次数。"},{"id":"0087","name_zh":"杠铃坐姿布拉德福德推举","target":"肩","media_id":"0dCyly0","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 正手握住杠铃，杠铃间距略宽于肩宽。 将杠铃举至肩膀高度，保持肘部稍微弯曲并指向前方。 将杠铃推过头顶，充分伸展双臂。 将杠铃降低回肩部高度，然后重复所需的重复次数。"},{"id":"0088","name_zh":"杠铃坐姿提踵","target":"小腿","media_id":"ktsFQAZ","instructions_zh":"坐在长凳上，双脚平放在地板上，杠铃放在大腿上。 将脚掌放在升高的平台上，例如木块或台阶。 将杠铃放在大腿上，并用手牢牢握住它。 保持背部挺直，核心收紧，伸展脚踝，将脚后跟抬离地面。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1371","name_zh":"杠铃坐姿提踵","target":"小腿","media_id":"ipvgBnC","instructions_zh":"坐在长凳上，双脚平放在地板上，杠铃放在大腿上。 将脚掌放在升高的平台上，例如木块或台阶。 尽可能降低脚后跟，感受小腿的拉伸。 尽可能高地抬高脚后跟，收缩小腿。 重复所需的重复次数。"},{"id":"1718","name_zh":"杠铃坐姿窄距颈后臂屈伸","target":"肱三头肌","media_id":"4CBIBOM","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 紧紧抓住颈后的杠铃，手掌朝前。 保持肘部靠近头部，慢慢将杠铃放低至脑后。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"0089","name_zh":"杠铃坐姿窄距集中弯举","target":"肱二头肌","media_id":"1V1gj1u","instructions_zh":"坐在长凳上，双脚平放在地板上，反手握住杠铃，双手与肩同宽。 将你的上臂靠在大腿内侧，就在膝盖上方，让杠铃垂在你面前。 保持上臂静止，呼气并将杠铃向上卷曲至肩膀，收缩二头肌。 保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0090","name_zh":"杠铃坐姿早安式","target":"臀部","media_id":"d960PgE","instructions_zh":"坐在长凳上，双脚平放在地上，上背部放一个杠铃。 保持背部挺直，挺胸。 慢慢地向前转动臀部，将躯干降低到地面。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0091","name_zh":"杠铃坐姿推举","target":"肩","media_id":"kTbSH9h","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 正手握住杠铃，杠铃间距略宽于肩宽。 将杠铃从架子上提起，并将其置于与肩同高的位置，肘部弯曲，手掌朝前。 充分伸展双臂，将杠铃压过头顶。 在顶部停顿片刻，然后慢慢将杠铃放回肩部水平。 重复所需的重复次数。"},{"id":"0092","name_zh":"杠铃坐姿过顶臂屈伸","target":"肱三头肌","media_id":"5uFK1xr","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 正手握住杠铃，双手与肩同宽，并将其举过头顶。 弯曲肘部，将杠铃降低到脑后，保持上臂靠近头部。 暂停片刻，然后伸展双臂将杠铃举回起始位置。 重复所需的重复次数。"},{"id":"0094","name_zh":"杠铃坐姿转体","target":"腹部","media_id":"dFSNDOA","instructions_zh":"坐在平坦的长凳上，双脚平放在地上，膝盖弯曲。 双手握住杠铃于胸前，保持肘部稍微弯曲。 启动你的核心，慢慢地将你的躯干扭转到一侧，保持背部挺直。 扭转结束时暂停片刻，然后慢慢旋转回到起始位置。 重复扭转到另一侧。 继续交替进行所需的重复次数。"},{"id":"0095","name_zh":"杠铃耸肩","target":"斜方肌","media_id":"dG7tG5y","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃。 在整个练习过程中保持手臂伸直和背部挺直。 将肩膀尽可能高地抬向耳朵，挤压斜方肌顶部。 保持一会儿，然后慢慢将肩膀放回起始位置。 重复所需的重复次数。"},{"id":"0096","name_zh":"杠铃侧屈（v.2）","target":"腹部","media_id":"i4JkUaL","instructions_zh":"双脚分开与肩同宽站立，双手握住杠铃，掌心朝下。 在整个练习过程中保持背部挺直并保持核心参与。 慢慢地将你的躯干弯曲到右侧，将杠铃向右膝方向降低。 暂停片刻，然后回到起始位置。 在左侧重复该动作。 继续交替进行所需的重复次数。"},{"id":"0098","name_zh":"杠铃侧分腿蹲","target":"股四头肌","media_id":"W31mMjd","instructions_zh":"站立，双脚分开比肩宽，脚趾稍微向外。 将杠铃放在上背部，将其放在斜方肌上。 当你将身体降低到蹲姿时，收紧你的核心并保持胸部向上，弯曲膝盖和臀部。 当你下降时，将膝盖向两侧推出，并将体重保持在脚后跟上。 降低直到大腿与地面平行，然后通过脚后跟推回到起始位置。 重复所需的重复次数。"},{"id":"0097","name_zh":"杠铃侧分腿蹲（v.2）","target":"股四头肌","media_id":"HUEqZ1y","instructions_zh":"站立，双脚分开比肩宽，脚趾稍微向外。 将杠铃放在上背部，将其放在肩膀上。 右脚向一侧迈出一大步，保持左脚踩地。 弯曲右膝，将身体放低至蹲姿，保持挺胸、背部挺直。 推动右脚跟回到起始位置。 在另一侧重复，左脚迈出。 继续交替进行所需的重复次数。"},{"id":"1756","name_zh":"杠铃单腿硬拉","target":"臀部","media_id":"gEyURal","instructions_zh":"站立，双脚分开与臀部同宽，正手握住杠铃在大腿前面。 将重心转移到左脚上，并将右脚稍微抬离地面。 臀部向前转动，保持背部挺直，右腿向后伸展以保持平衡。 将杠铃向地面降低，使其靠近身体，左腿稍微弯曲。 在底部暂停片刻，然后启动臀肌和腿筋，将躯干抬回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0099","name_zh":"杠铃单腿分腿蹲","target":"股四头肌","media_id":"gGNQmVt","instructions_zh":"双脚分开与肩同宽站立，将杠铃放在上背部。 单腿向前迈出一大步，保持躯干直立。 弯曲前膝盖和臀部，降低身体，同时保持后腿伸直。 继续降低，直到大腿前侧与地面平行。 暂停片刻，然后推动前脚跟回到起始位置。 重复所需的重复次数，然后换腿。"},{"id":"2799","name_zh":"杠铃坐姿交替抬腿","target":"腹部","media_id":"G7xoEzr","instructions_zh":"坐在长凳上，背部挺直，将杠铃放在大腿上。 保持双腿伸直，将一条腿尽可能高地抬起，同时将另一条腿放在地上。 将抬起的腿放回原位，然后换另一条腿重复上述步骤。 继续交替双腿达到所需的重复次数。"},{"id":"2800","name_zh":"杠铃坐姿交替抬腿（女）","target":"腹部","media_id":"BCs0G2F","instructions_zh":"坐在长凳上，背部挺直，将杠铃放在大腿上。 将双手放在长凳两侧以获得支撑。 保持双腿伸直，将一条腿尽可能抬高，同时保持与地面平行。 将腿放回原位，然后换另一条腿重复此动作。 继续交替双腿达到所需的重复次数。"},{"id":"0100","name_zh":"杠铃滑雪式","target":"肩","media_id":"4Leypho","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃于大腿前方。 稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。 同时将杠铃举向肩膀，同时稍微离开地面。 当您到达动作的最高点时，快速反转动作并将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0101","name_zh":"杠铃速度深蹲","target":"臀部","media_id":"euI1BwR","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微向外。 将杠铃放在上背部，将其放在斜方肌或三角肌后束上。 收紧核心肌群，保持挺胸，同时向后和向下降低臀部，就像坐在椅子上一样。 降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。 通过脚跟发力站起来，在顶部挤压臀部。 重复所需的重复次数。"},{"id":"2810","name_zh":"杠铃分腿蹲（v.2）","target":"股四头肌","media_id":"HBYyX94","instructions_zh":"首先，双脚分开与肩同宽站立，将杠铃放在上背部。 右脚向前迈出一大步，保持躯干直立。 弯曲膝盖和臀部，降低身体，直到右大腿与地面平行。 暂停片刻，然后推动右脚跟回到起始位置。 左腿向前重复此动作，达到所需的重复次数。"},{"id":"0102","name_zh":"杠铃跪姿深蹲","target":"股四头肌","media_id":"oR7O9LW","instructions_zh":"首先跪在地上，膝盖分开与臀部同宽，脚趾向前。 将杠铃放在肩膀上，正手握住杠铃，双手分开的距离略大于肩宽。 收紧核心并保持胸部抬起，同时弯曲膝盖慢慢降低身体，保持背部挺直。 继续降低，直到大腿与地面平行，或者尽可能低。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"2798","name_zh":"杠铃深蹲跳接后弓步","target":"股四头肌","media_id":"RYcV1kH","instructions_zh":"首先，双脚分开与肩同宽站立，将杠铃放在上背部。 弯曲膝盖并将臀部向后推，将身体降低至蹲姿。 向上爆炸，尽可能高地跳离地面。 双脚轻轻落地，然后立即单腿向后退一步，形成反向弓步。 降低身体，直到大腿前侧与地面平行，保持背部挺直。 推动前脚跟以返回到起始位置。 在另一条腿上重复跳跃和弓步序列。 继续交替双腿达到所需的重复次数。"},{"id":"0103","name_zh":"杠铃站姿滚轮","target":"腹部","media_id":"xnInPfE","instructions_zh":"站直，双脚分开与肩同宽，双手握住杠铃于大腿前方。 启动你的核心肌群，慢慢地将杠铃向地面滚动，保持背部挺直，手臂伸展。 继续向前滚动杠铃，直到身体完全伸展，双手位于头顶正上方。 暂停片刻，然后慢慢地将杠铃向大腿方向滚动，保持控制并保持核心参与。 重复所需的重复次数。"},{"id":"0104","name_zh":"杠铃站姿反握腕弯举","target":"前臂","media_id":"2qTvJAZ","instructions_zh":"站直，双脚分开与肩同宽，正手握住杠铃。 将杠铃放在手背上，手掌朝下，手指指向身体。 保持上臂静止，呼气并尽可能向上弯曲手腕。 保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0105","name_zh":"杠铃站姿布拉德福德推举","target":"肩","media_id":"dCPESfR","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃于肩前。 将杠铃推过头顶，充分伸展双臂。 将杠铃降低回到起始位置。 重复所需的重复次数。"},{"id":"1372","name_zh":"杠铃站姿提踵","target":"小腿","media_id":"8ozhUIZ","instructions_zh":"双脚分开与肩同宽站立，将杠铃放在上背部。 仅用脚趾将脚后跟抬离地面，尽可能高。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0106","name_zh":"杠铃站姿窄距弯举","target":"肱二头肌","media_id":"4dUn2iv","instructions_zh":"站直，双脚分开与肩同宽，反手握住杠铃，双手并拢。 在整个运动过程中，保持肘部靠近躯干，上臂保持静止。 弯举哑铃时呼气，同时收缩二头肌。继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢开始将杠铃拉回到起始位置。 重复所需的重复次数。"},{"id":"1456","name_zh":"杠铃站姿窄距推举","target":"肩","media_id":"wdRZISl","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃，双手距离略小于肩宽。 将杠铃举至肩膀高度，保持肘部靠近身体。 将杠铃推过头顶，充分伸展双臂。 将杠铃降低回肩部高度。 重复所需的重复次数。"},{"id":"2414","name_zh":"杠铃站姿集中弯举","target":"肱二头肌","media_id":"vsMcDi9","instructions_zh":"双脚分开与肩同宽站立，一手握住杠铃，掌心朝上。 将另一只手放在大腿上以获得支撑。 保持上臂静止，呼气并将重量向上弯向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气并慢慢将重量放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0107","name_zh":"杠铃站姿前平举过头","target":"肩","media_id":"S8mo30S","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃于大腿前方。 保持背部挺直并启动核心肌群。 慢慢地将杠铃举到你面前，保持手臂伸直，手掌朝下。 继续举起杠铃，直到杠铃略高于肩部水平。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0108","name_zh":"杠铃站姿单腿提踵","target":"小腿","media_id":"rGwhJ5o","instructions_zh":"双脚分开与肩同宽站立，将杠铃放在上背部。 用小腿将脚跟抬离地面，尽可能高。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0109","name_zh":"杠铃站姿过顶臂屈伸","target":"肱三头肌","media_id":"dZl9Q27","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃。 将杠铃举过头顶，充分伸展双臂。 保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。 暂停片刻，然后伸展双臂将杠铃举回起始位置。 重复所需的重复次数。"},{"id":"0110","name_zh":"杠铃站姿反握弯举","target":"肱二头肌","media_id":"LWuA3aZ","instructions_zh":"站直，双脚分开与肩同宽，反手握住杠铃，手掌朝上。 保持肘部靠近躯干，上臂保持静止。 呼气并弯举杠铃，同时收缩二头肌，使杠铃尽可能靠近肩膀。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0111","name_zh":"杠铃站姿摇摆提踵","target":"小腿","media_id":"6HiHHe0","instructions_zh":"双脚分开与肩同宽站立，将杠铃放在上背部。 将脚跟抬离地面，尽可能高，用脚掌保持平衡。 慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0112","name_zh":"杠铃站姿转体","target":"腹部","media_id":"yQe5HpE","instructions_zh":"双脚分开与肩同宽站立，双手握住杠铃于胸前，掌心朝下。 在整个练习过程中启动你的核心并保持背部挺直。 慢慢地将躯干向右扭转，以脚和臀部为轴，同时保持下半身稳定。 扭转结束时暂停片刻，然后慢慢回到起始位置。 向左侧重复扭转。 继续交替扭转所需的重复次数。"},{"id":"1629","name_zh":"杠铃站姿宽握弯举","target":"肱二头肌","media_id":"faHKVkK","instructions_zh":"双脚分开与肩同宽站立，反握握住杠铃，双手分开比肩宽。 保持背部挺直，肘部靠近躯干。 呼气并将杠铃向上弯向肩膀，保持上臂静止。 在顶部暂停片刻，挤压你的二头肌。 吸气，慢慢将杠铃放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"1457","name_zh":"杠铃站姿宽握推举","target":"肩","media_id":"Kyd9Rz5","instructions_zh":"双脚分开与肩同宽站立，正手握杠铃，握距略宽于肩。 将杠铃举至肩膀高度，保持肘部稍微位于杠铃前方。 将杠铃推过头顶，充分伸展双臂。 将杠铃降低回肩部高度，然后重复所需的重复次数。"},{"id":"0113","name_zh":"杠铃站姿宽握弯举","target":"肱二头肌","media_id":"NdIb5Z1","instructions_zh":"站直，双脚分开与肩同宽，正手握住杠铃，双手分开比肩宽。 让杠铃悬挂在大腿前面，与手掌保持一臂距离，手掌背向身体。 保持上臂静止，呼气并通过收缩二头肌向上弯曲杠铃。 继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0114","name_zh":"杠铃上步","target":"臀部","media_id":"Kxquu2E","instructions_zh":"站在长凳或台阶前，将杠铃放在上背部。 将一只脚放在长凳或台阶上，确保整个脚与表面接触。 穿过你的脚后跟，走上长凳或台阶，充分伸展你的臀部和膝盖。 在顶部短暂停顿，然后放低自己回到起始位置。 用另一条腿重复上述步骤。 继续交替双腿达到所需的重复次数。"},{"id":"0115","name_zh":"杠铃直腿早安式","target":"臀部","media_id":"JrOHAZc","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 将杠铃放在上背部，将其放在斜方肌上。 保持背部挺直，臀部向前转动，将臀部向后推。 降低躯干直到与地面平行，感觉腿筋被拉伸。 启动臀肌和腿筋以返回起始位置。 重复所需的重复次数。"},{"id":"0116","name_zh":"杠铃直腿硬拉","target":"大腿后侧","media_id":"hrVQWvE","instructions_zh":"站立，双脚分开与肩同宽，脚趾指向前方。 正手握住杠铃，双手分开略宽于肩宽。 弯曲臀部，将杠铃放低至地面，保持背部挺直，膝盖稍微弯曲。 降低杠铃，直到感觉到腿筋拉伸。 启动腿筋和臀肌，将杠铃举回起始位置。 重复所需的重复次数。"},{"id":"0117","name_zh":"杠铃相扑硬拉","target":"臀部","media_id":"KgI0tqW","instructions_zh":"站立，双脚分开比肩宽，脚趾朝外。 将杠铃放在您面前的地面上，位于双脚之间的中心。 弯曲膝盖，降低臀部，保持背部挺直，挺胸，用正手握法抓住杠铃。 启动你的核心并通过你的脚后跟发力，将杠铃抬离地面，同时伸展你的臀部和膝盖。 当你举起时，保持胸部挺直，背部挺直，向前推动臀部以充分锻炼臀部。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置，在整个动作过程中保持控制。 重复所需的重复次数。"},{"id":"3305","name_zh":"杠铃火箭推","target":"肩","media_id":"f7Y9eDZ","instructions_zh":"首先，双脚分开与肩同宽站立，正手握住杠铃，与肩同高。 弯曲膝盖并将臀部向后推，降低至蹲姿。 当你到达深蹲底部时，爆发性地通过脚后跟站起来，同时将杠铃压过头顶。 当你回到深蹲位置时，将杠铃降低到肩膀高度。 重复所需的重复次数。"},{"id":"0120","name_zh":"杠铃直立划船","target":"肩","media_id":"UDlhcO8","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。 让杠铃悬挂在大腿前面，双臂完全伸展。 保持背部挺直，核心收紧，呼气，将杠铃笔直向上举向下巴，用肘部引导。 在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0119","name_zh":"杠铃直立划船 v. 2","target":"肩","media_id":"83HoW9X","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。 让杠铃悬挂在大腿前面，双臂完全伸展。 保持背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。 在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0121","name_zh":"杠铃直立划船 v. 3","target":"肩","media_id":"fI18Rbc","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。 让杠铃悬挂在大腿前面，双臂完全伸展。 保持核心收紧，背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。 在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0122","name_zh":"杠铃宽握卧推","target":"胸","media_id":"JsKq9so","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 宽握距抓住杠铃，握距略宽于肩宽。 将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。 慢慢地将杠铃向胸部降低，保持肘部稍微张开。 当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。 重复所需的重复次数。"},{"id":"1258","name_zh":"杠铃宽握反握卧推","target":"胸","media_id":"945zpRg","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 反握宽握杠铃，握距略宽于肩宽。 将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。 将杠铃慢慢降低到胸部，保持肘部内收，手腕伸直。 当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。 重复所需的重复次数。"},{"id":"0124","name_zh":"杠铃宽距深蹲","target":"股四头肌","media_id":"s7HX1BY","instructions_zh":"站立，双脚分开比肩宽，脚趾稍微向外。 将杠铃放在上背部，将其放在斜方肌或三角肌后束上。 当你下蹲时，收紧你的核心并保持胸部挺直，将臀部向后推并弯曲膝盖。 降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0123","name_zh":"杠铃宽握直立划船","target":"肩","media_id":"RgJDRR1","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃，双手分开比肩宽。 让杠铃悬挂在大腿前面，双臂完全伸展。 保持背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。 在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0126","name_zh":"杠铃腕弯举","target":"前臂","media_id":"82LxxkW","instructions_zh":"坐在长凳上，双脚平放在地面上，前臂放在大腿上，反握杠铃。 让杠铃向下滚动到指尖，保持手腕伸直。 弯曲手腕，慢慢地将杠铃向上卷向前臂。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0125","name_zh":"杠铃腕弯举 v. 2","target":"前臂","media_id":"6kSxYnw","instructions_zh":"坐在长凳上，双脚平放在地上，膝盖弯曲。 反手握住杠铃，手掌朝上，双手与肩同宽。 将前臂放在大腿上，让手腕悬在边缘。 慢慢向上弯曲手腕，将杠铃拉向前臂。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0127","name_zh":"杠铃泽奇深蹲","target":"臀部","media_id":"LSTChY9","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微外翻。 将杠铃放在肘部的弯曲处，双手握住杠铃以保持稳定。 当你将臀部向后降低到蹲姿时，启动你的核心并保持胸部抬起。 保持膝盖与脚趾对齐，并将重量放在脚后跟上。 在深蹲底部暂停片刻，然后用脚后跟恢复到起始位置。 重复所需的重复次数。"},{"id":"3212","name_zh":"基本触脚尖（男）","target":"臀部","media_id":"BbfB8Gb","instructions_zh":"双脚分开与肩同宽站立，双臂放在身体两侧。 腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。 双手向下伸向脚趾，尽可能保持双腿伸直。 在底部停顿片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0128","name_zh":"战绳","target":"肩","media_id":"RJa4tCo","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 双手握住绳子的一端，手掌相对。 将手臂举至肩膀高度，保持肘部稍微弯曲。 快速抬起和放下每只手臂，开始用绳索产生交替的波浪。 继续所需的持续时间或重复次数。"},{"id":"3360","name_zh":"熊爬","target":"有氧","media_id":"0Yz8WdV","instructions_zh":"从四肢着地开始，双手直接放在肩膀下方，膝盖直接放在臀部下方。 将膝盖稍微抬离地面，保持背部平坦并收紧核心。 同时向前移动右手和左脚，然后是左手和右脚。 继续向前爬行，手脚交替动作。 在整个练习过程中保持稳定的节奏并保持核心紧张。 继续所需的距离或时间。"},{"id":"1259","name_zh":"头后胸肌拉伸","target":"胸","media_id":"QoHIhPl","instructions_zh":"站直，双脚分开与肩同宽。 将手指交叉放在脑后，肘部朝外。 慢慢地将肩胛骨挤压在一起，并将胸部向前推。 保持拉伸 15-30 秒。 松开拉伸并根据需要重复。"},{"id":"0129","name_zh":"凳上臂屈伸（屈膝）","target":"肱三头肌","media_id":"RrLske5","instructions_zh":"坐在长凳或椅子的边缘，双手抓住臀部旁边的边缘。 将臀部从长凳上滑下来，在身前伸直双腿，脚后跟保持在地面上。 弯曲肘部，将身体放低至地面，保持背部靠近长凳。 在底部暂停片刻，然后将自己推回到起始位置。 重复所需的重复次数。"},{"id":"1399","name_zh":"地面凳上臂屈伸","target":"肱三头肌","media_id":"9RT8oQW","instructions_zh":"坐在长凳或椅子的边缘，双手抓住边缘，手指指向前方。 将臀部滑离长凳，用手支撑体重。 弯曲肘部降低身体，直到上臂与地板平行。 伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"0130","name_zh":"凳上臀桥","target":"臀部","media_id":"u27Kcdz","instructions_zh":"坐在长凳上，背部靠在长凳上，双脚平放在地上。 将双手放在长凳上以获得支撑。 收紧臀肌和腿筋，然后将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。 在顶部暂停片刻，然后慢慢将臀部放回起始位置。 重复所需的重复次数。"},{"id":"3019","name_zh":"长椅引体向上","target":"背阔肌","media_id":"mExgrF9","instructions_zh":"将自己置于与胸部同高的横杆或坚固的水平表面下方。 正手握住杠铃或杠铃表面，握距略宽于肩宽。 双臂完全伸展，身体伸直。 将肩胛骨挤压在一起并弯曲肘部，将胸部拉向杠铃或地面。 继续拉，直到下巴位于杆或表面上方。 有控制地降低自己回到起始位置。 重复所需的重复次数。"},{"id":"3639","name_zh":"屈膝仰卧转体（男）","target":"臀部","media_id":"6sYyrRX","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将手臂向两侧伸展，与身体垂直。 保持膝盖并拢，慢慢地将它们降低到一侧，旨在用膝盖接触地面。 暂停片刻，然后启动核心并慢慢将膝盖抬回到起始位置。 到另一侧重复该动作。 继续交替进行所需的重复次数。"},{"id":"1770","name_zh":"腿靠式集中弯举","target":"肱二头肌","media_id":"sJFIDIp","instructions_zh":"坐在长凳上，双腿分开，双脚平放在地上。 一只手握住哑铃，将肘部放在大腿内侧，膝盖上方。 手掌朝上，将哑铃向肩膀弯曲，同时保持上臂静止。 在动作的最高点挤压二头肌，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0139","name_zh":"窄握引体向上","target":"肱二头肌","media_id":"50BETrz","instructions_zh":"悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。 启动你的核心并将自己拉向杠铃，专注于使用二头肌来抬起你的身体。 在最高点暂停片刻，然后慢慢降低回到起始位置。 重复所需的重复次数。"},{"id":"0140","name_zh":"反握引体向上","target":"肱二头肌","media_id":"guT8YnS","instructions_zh":"悬挂在引体向上杆上，手掌背向自己，双手与肩同宽。 启动核心肌群，弯曲肘部将自己拉起，使胸部靠近杠铃。 在动作的最高点暂停，然后慢慢降低回到起始位置。 重复所需的重复次数。"},{"id":"0137","name_zh":"仰卧卷体","target":"肱三头肌","media_id":"U6G2gk9","instructions_zh":"首先将双手放在凸起的表面上，例如长凳或双杠上，手掌朝下，手指向前。 将双腿向前方伸展，脚跟保持在地面上，身体伸直。 弯曲肘部降低身体，使其靠近身体两侧，直到上臂与地面平行。 暂停片刻，然后用手掌伸直手臂，将身体抬回到起始位置。 重复所需的重复次数。"},{"id":"3543","name_zh":"自重下落跳深蹲","target":"臀部","media_id":"wfotm7S","instructions_zh":"双脚分开与肩同宽站立。 弯曲膝盖并将臀部向后推，将身体降低至蹲姿。 爆发性地跳起来，伸展臀部、膝盖和脚踝。 在半空中时，快速将双脚并拢。 脚掌轻轻着地，然后立即回到蹲姿。 重复所需的重复次数。"},{"id":"3544","name_zh":"自重上斜侧平板支撑","target":"腹部","media_id":"5VXmnV5","instructions_zh":"首先侧躺，双腿伸展并叠放在一起。 将前臂放在肩膀正下方的地面上，肘部弯曲成 90 度角。 启动你的核心并将臀部抬离地面，从头到脚形成一条直线。 保持此位置所需的时间。 将臀部放回到地面，然后在另一侧重复。"},{"id":"1771","name_zh":"自重跪姿颈后臂屈伸","target":"肱三头肌","media_id":"s0HKO2I","instructions_zh":"跪在地上，膝盖分开与臀部同宽。 将双手放在身前的地面上，与肩同宽，手指指向前方。 将双腿伸直在身后，用脚趾和双手保持平衡，从头到脚跟形成一条直线。 弯曲肘部，将上半身向地面降低，保持肘部靠近身体两侧。 在底部停顿片刻，然后双手用力伸直手臂，回到起始位置。 重复所需的重复次数。"},{"id":"1769","name_zh":"自重侧卧二头弯举","target":"肱二头肌","media_id":"gscGLOU","instructions_zh":"侧躺，双腿伸直，用手臂支撑头部。 将上臂靠在身体两侧，弯曲肘部，将前臂卷向肩膀。 在顶部暂停片刻，然后慢慢将前臂放回起始位置。 重复所需的重复次数。"},{"id":"3168","name_zh":"自重深蹲划船","target":"上背部","media_id":"3xK09Sk","instructions_zh":"双脚分开与肩同宽站立，伸直手臂抓住坚固的物体或悬挂训练器。 将身体降低至蹲姿，保持背部挺直，膝盖位于脚趾后面。 从蹲姿开始，将身体向上拉向物体或悬挂训练器，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"3167","name_zh":"自重深蹲划船（毛巾）","target":"上背部","media_id":"BReCuOn","instructions_zh":"双脚分开与肩同宽站立，手掌朝下，将毛巾放在身前。 弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。 当你下蹲时，同时将毛巾拉向胸部，将肩胛骨挤压在一起。 在深蹲底部停顿片刻，然后慢慢回到起始位置，同时伸展双臂。 重复所需的重复次数。"},{"id":"1373","name_zh":"自重站姿提踵","target":"小腿","media_id":"bJYHBIN","instructions_zh":"双脚分开与肩同宽站立，脚趾指向前方。 将手放在墙壁或稳定的表面上以保持平衡。 慢慢地将脚后跟抬离地面，将身体重量转移到脚掌上。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"3156","name_zh":"自重站姿窄握单臂划船","target":"上背部","media_id":"v2DfH14","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲，一只手握住哑铃，握姿中立。 臀部向前弯曲，保持背部挺直，核心肌群参与。 将哑铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"3158","name_zh":"自重站姿窄握划船","target":"上背部","media_id":"tig3PXb","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 腰部向前弯曲，保持背部挺直，核心肌群参与。 将双臂伸直在身前，紧紧抓住杆或手柄。 将杠铃或手柄拉向身体，将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢松开并回到起始位置。 重复所需的重复次数。"},{"id":"3162","name_zh":"自重站姿单臂划船","target":"上背部","media_id":"xbkPfaw","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲，一手握住哑铃。 臀部向前弯曲，保持背部挺直，核心肌群参与。 让哑铃垂直悬挂在您面前，手臂完全伸展。 将哑铃向上拉向胸部，保持肘部靠近身体。 在动作的最高点将肩胛骨挤压在一起。 将哑铃放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"3161","name_zh":"自重站姿单臂划船（毛巾）","target":"上背部","media_id":"O4oIqQD","instructions_zh":"双脚分开与肩同宽站立，膝盖微曲，单手握住毛巾。 臀部向前弯曲，保持背部挺直，核心肌群参与。 将毛巾拉向胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将毛巾放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"3166","name_zh":"自重站姿划船","target":"上背部","media_id":"wd4ds3s","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 正手握住杆或手柄，手掌朝下。 保持背部挺直，核心参与。 将杠铃或手柄拉向身体，将肩胛骨挤压在一起。 在动作的最高点停顿片刻。 慢慢释放并伸展双臂回到起始位置。 重复所需的重复次数。"},{"id":"3165","name_zh":"自重站姿划船（毛巾）","target":"上背部","media_id":"uTv34oq","instructions_zh":"双脚分开与肩同宽站立，双手握住毛巾放在身前。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将毛巾拉向胸部，将肩胛骨挤压在一起。 在最高点停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数。"},{"id":"0138","name_zh":"仰卧举臀","target":"腹部","media_id":"CI6baTY","instructions_zh":"平躺，双腿伸展，双臂放在身体两侧。 弯曲膝盖并将其靠近胸部，保持双脚离开地面。 收紧腹肌，将臀部抬离地面，将膝盖靠近头部。 在顶部暂停片刻，然后慢慢将臀部放回起始位置。 重复所需的重复次数。"},{"id":"1374","name_zh":"跳箱落地单腿稳定","target":"小腿","media_id":"iPm26QU","instructions_zh":"站在盒子或平台前，双脚分开与肩同宽。 弯曲膝盖，跳到盒子上，一只脚轻轻落地，另一只脚悬在盒子边缘。 将脚踩在盒子上，将自己稳定在盒子上，同时保持另一只脚离开地面。 保持这个姿势几秒钟，锻炼小腿肌肉以保持平衡。 将放在盒子上的脚慢慢放下，回到起始位置。 用另一条腿重复该练习。"},{"id":"2466","name_zh":"桥式登山（交叉）","target":"腹部","media_id":"9c6T1YX","instructions_zh":"从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。 启动你的核心并将右脚抬离地面，将右膝移向左肘。 将右脚放回到起始位置，然后将左脚朝向右肘重复该动作。 继续交替两侧，以受控的速度移动。 保持臀部水平，避免臀部抬得太高或下垂得太低。 在整个练习过程中保持稳定的呼吸模式。 重复所需的重复次数。"},{"id":"1160","name_zh":"波比跳","target":"有氧","media_id":"dK9394r","instructions_zh":"从站立位置开始，双脚分开与肩同宽。 弯曲膝盖并将双手放在身前的地板上，将身体降低至蹲姿。 将脚踢回到俯卧撑位置。 进行俯卧撑，保持身体呈一条直线。 将双脚跳回蹲姿。 爆发性地跳起，将双臂举过头顶。 轻轻落地并立即回到蹲姿，开始下一次重复。"},{"id":"0870","name_zh":"仰卧臀桥","target":"腹部","media_id":"qcNN2FN","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在身体两侧，掌心朝下。 收紧腹肌，将双腿抬离地面，将膝盖靠近胸部。 在动作的最高点，挤压腹肌并暂停片刻。 慢慢地将双腿放回起始位置。 重复所需的重复次数。"},{"id":"1494","name_zh":"蝴蝶式","target":"内收肌","media_id":"bWlZvXh","instructions_zh":"坐在地板上，双腿伸到身前。 弯曲膝盖，将脚底并拢，让膝盖向两侧倾斜。 用手抓住脚踝或脚。 坐直并拉长脊柱。 轻轻地将膝盖压向地板，感觉大腿内侧有拉伸感。 保持这个姿势几个呼吸。 要放松，请慢慢抬起膝盖并伸展双腿。"},{"id":"0148","name_zh":"绳索交替推肩","target":"肩","media_id":"KHPZL0b","instructions_zh":"双脚分开与肩同宽站立，并用正手握住绳索机的手柄。 将双手放在与肩同高的位置，手掌朝前。 保持核心参与并保持背部挺直。 向上并向前按下一个手柄，直到您的手臂完全伸展。 在最高点暂停片刻，然后慢慢将手柄放回起始位置。 用另一只手臂重复上述步骤。 双臂交替进行所需的重复次数。"},{"id":"0149","name_zh":"绳索交替臂屈伸","target":"肱三头肌","media_id":"Gchi5Tr","instructions_zh":"面对电缆机站立，双脚与肩同宽。 右手握住电缆手柄，抬起手臂，使上臂与地面平行，肘部弯曲成 90 度角。 保持上臂静止，前臂向后伸展，完全伸直手臂。 暂停片刻，然后慢慢回到起始位置。 用左臂重复此动作。 继续交替手臂进行所需的重复次数。"},{"id":"3235","name_zh":"绳索辅助反向腿弯举","target":"大腿后侧","media_id":"zHEpuuc","instructions_zh":"调整缆绳机，使脚踝附件处于最低设置。 面朝下躺在长凳上，双腿伸直，将脚踝固定装置固定在脚踝上。 握住长凳的把手以保持稳定。 保持上半身静止，呼气，弯曲膝盖，将双腿向臀肌方向卷起。 在动作的最高点暂停片刻，挤压你的腿筋。 吸气并慢慢降低双腿回到起始位置。 重复所需的重复次数。"},{"id":"0150","name_zh":"绳索直杆侧位下拉","target":"背阔肌","media_id":"eYnzaCm","instructions_zh":"将电缆滑轮调整至较高位置并安装直杆。 面向缆绳机坐着，双脚平放在地面上，膝盖稍微弯曲。 正手握住杠铃，握距略宽于肩宽。 稍微向后倾斜，挺胸，保持下背部轻微的拱形。 将杠铃向下拉向胸部，用肘部引导并将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢地将杠铃返回到起始位置。 重复所需的重复次数。"},{"id":"0151","name_zh":"绳索平板卧推","target":"胸","media_id":"7xI5MXA","instructions_zh":"将绳索机调整至胸部高度并安装手柄。 背对机器站立，双脚与肩同宽。 正手握住手柄并向前迈一步，以在电缆中产生张力。 将双脚牢牢放在地面上并启动核心。 弯曲肘部，将双手置于肩部水平，保持肘部呈 90 度角。 向前推动手柄，将双臂完全伸展到身前。 暂停片刻，然后慢慢扭转动作，将双手放回肩部水平。 重复所需的重复次数。"},{"id":"1630","name_zh":"绳索窄握弯举","target":"肱二头肌","media_id":"BCGQ6J5","instructions_zh":"将直杆连接到低滑轮电缆机上。 面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。 反手握住杠铃，双手与肩同宽。 在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。 呼气并将杠铃向上卷向肩膀，收缩二头肌。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气，慢慢将杠铃放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"1631","name_zh":"绳索集中弯举","target":"肱二头肌","media_id":"NvfE43H","instructions_zh":"坐在长凳或椅子上，双脚平放在地板上，膝盖稍微弯曲。 用手握住电缆手柄，并将肘部靠在大腿内侧。 保持上臂静止，呼气并将电缆手柄向肩膀卷曲，同时收缩二头肌。 在动作的最高点暂停片刻，然后吸气并慢慢将拉索手柄放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0152","name_zh":"绳索集中臂屈伸（膝上）","target":"肱三头肌","media_id":"Db7eEgw","instructions_zh":"坐在长凳或椅子上，膝盖弯曲，双脚平放在地上。 用右手握住电缆手柄，并将肘部放在右膝盖内侧。 充分伸展手臂，保持肘部静止并靠近膝盖。 在顶部停顿片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"0153","name_zh":"绳索交叉侧位下拉","target":"背阔肌","media_id":"OQ1otBN","instructions_zh":"将电缆手柄连接到电缆机器两侧与肩同高的位置。 站在机器中间，双脚分开与肩同宽。 正手握住手柄并后退以在电缆中产生张力。 从臀部开始稍微向前倾，保持背部挺直，挺胸。 将手柄向下拉并穿过身体，将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0154","name_zh":"绳索交叉反向飞鸟","target":"肩","media_id":"aqvSOQE","instructions_zh":"将 D 形手柄连接到每根低滑轮电缆上，并站在电缆交叉机的中间。 旋前抓住手柄（手掌朝下），向前迈出一步，双脚分开与肩同宽。 稍微弯曲膝盖，腰部前倾，保持背部挺直，腹部收紧。 双臂向两侧伸展，肘部稍微弯曲，呼气并将肩胛骨挤压在一起，同时以反向飞翔动作向后和向上拉动绳索。 在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0155","name_zh":"绳索交叉变式","target":"胸","media_id":"0CXGHya","instructions_zh":"将电缆滑轮调整至胸部高度。 站在电缆机的中央，一只脚在另一只脚前面。 手掌朝下抓住手柄，手臂向两侧伸展。 向前迈出一步，保持手臂稍微弯曲。 肘部稍微弯曲，双手并拢放在胸前。 暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0868","name_zh":"绳索弯举","target":"肱二头肌","media_id":"G08RZcQ","instructions_zh":"面对电缆机站立，双脚与肩同宽。 用手握住电缆附件，手掌朝上。 保持肘部靠近身体两侧，上臂保持静止。 呼气并将电缆附件卷向肩膀，收缩二头肌。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气并缓慢地将电缆附件放回起始位置。 重复所需的重复次数。"},{"id":"0157","name_zh":"绳索硬拉","target":"臀部","media_id":"eGDudUV","instructions_zh":"面对电缆机站立，双脚与肩同宽。 弯曲臀部和膝盖，降低躯干，直到背部与地面平行。 正手握住电缆手柄，保持手臂伸直，肩膀向后。 调动臀肌和腿筋来抬起拉索手柄，伸展臀部并站直。 在顶部暂停片刻，然后慢慢将缆索手柄放回起始位置。 重复所需的重复次数。"},{"id":"0158","name_zh":"绳索下斜飞鸟","target":"胸","media_id":"7saC5zz","instructions_zh":"将拉线机调整至下降位置。 背对机器站立，双脚与肩同宽。 握住手柄，手掌朝前，双臂在身前伸直。 保持肘部轻微弯曲，以受控的动作向两侧张开双臂。 在完全伸展位置停顿片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"1260","name_zh":"绳索下斜单臂推","target":"胸","media_id":"KHGNa16","instructions_zh":"将拉线机调整至下降位置。 背对机器站立，用一只手抓住手柄。 将背部靠在下斜长凳上，手臂伸直在身前。 弯曲肘部，将手柄向胸部方向降低，同时保持上臂静止。 在底部暂停片刻，然后将手柄推回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1261","name_zh":"绳索下斜推","target":"胸","media_id":"2Pya1cP","instructions_zh":"将拉线机调整至下降位置。 坐在面向缆绳机的下降长凳上。 正手握住手柄并将其置于胸部水平。 将双脚平放在地面上，并将背部牢牢靠在长凳上。 呼气并将手柄推离身体，充分伸展双臂。 动作结束时暂停片刻，挤压胸部肌肉。 吸气并慢慢地将手柄放回起始位置。 重复所需的重复次数。"},{"id":"0159","name_zh":"绳索下斜坐姿宽握划船","target":"上背部","media_id":"kesXOpB","instructions_zh":"坐在面向缆绳机的下斜长凳上，双脚牢固地放在脚踏板上。 用宽的正手握法抓住电缆附件，手掌朝下。 稍微向后倾斜，保持背部挺直，核心肌群参与。 将电缆拉向下胸部，将肩胛骨挤压在一起。 在收缩的峰值处暂停片刻，然后慢慢地将电缆释放回起始位置。 重复所需的重复次数。"},{"id":"1632","name_zh":"绳索拖拽弯举","target":"肱二头肌","media_id":"dXz8zjF","instructions_zh":"面向缆绳机站立，双脚与肩同宽。 用手握住电缆附件，手掌朝上，手臂完全伸展。 保持上臂静止，呼气并通过收缩二头肌将电缆附件卷曲至肩膀。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气并慢慢将电缆附件放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"0160","name_zh":"绳索地板坐姿宽握划船","target":"上背部","media_id":"veXwo0D","instructions_zh":"坐在地板上，双腿伸直，背部挺直。 将缆绳手柄连接到低滑轮上，并将缆绳机放在您身后。 正手宽握握住手柄，手掌朝下。 稍微向后倾斜，保持背部挺直，挺胸。 将手柄拉向腰部，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"0161","name_zh":"绳索前平举","target":"肩","media_id":"hvHhCv8","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 正手握住电缆手柄，手掌朝下，双臂在身前完全伸展。 保持手臂伸直，将电缆手柄抬高至肩部水平。 在顶部暂停片刻，然后慢慢将缆索手柄放回起始位置。 重复所需的重复次数。"},{"id":"0162","name_zh":"绳索前平举","target":"肩","media_id":"u2X71Np","instructions_zh":"双脚分开与肩同宽站立，并用正手握住电缆手柄。 保持背部挺直，核心肌群参与。 将电缆手柄举到您面前，保持手臂伸直，手掌朝下。 继续抬起，直到手臂与地板平行。 在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。 重复所需的重复次数。"},{"id":"0164","name_zh":"绳索前平举","target":"肩","media_id":"mTT3KLn","instructions_zh":"双脚分开与肩同宽站立，并用正手握住电缆手柄。 保持背部挺直，核心肌群参与。 将电缆手柄举到您面前，保持手臂伸直，手掌朝下。 继续抬起，直到手臂与地板平行。 在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。 重复所需的重复次数。"},{"id":"0165","name_zh":"绳索锤式弯举（用绳索）","target":"肱二头肌","media_id":"HPlPoQA","instructions_zh":"站直，双脚分开与肩同宽，膝盖稍微弯曲。 双手握住缆绳附件，手掌相对，手臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续提升缆绳附件，直到您的二头肌完全收缩并且绳索与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将缆绳附件降低回起始位置。 重复所需的重复次数。"},{"id":"1722","name_zh":"绳索高位过头三头臂屈伸","target":"肱三头肌","media_id":"1xHyxys","instructions_zh":"将绳子连接到高滑轮上，背对机器站立。 双手抓住绳子，并将双臂伸过头顶。 保持肘部靠近头部，上臂保持静止。 弯曲肘部，慢慢将绳子降低到头后。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"0167","name_zh":"绳索高位划船（跪姿）","target":"上背部","media_id":"ZSJNetl","instructions_zh":"将直杆连接到胸部高度的缆绳机上。 跪在缆绳机前，用正握方式抓住杠铃，双手与肩同宽。 坐在脚后跟上，保持背部挺直，核心肌群参与。 将杠铃拉向上腹部，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢松开杠铃回到起始位置。 重复所需的重复次数。"},{"id":"0168","name_zh":"绳索髋内收","target":"内收肌","media_id":"hBGWILP","instructions_zh":"将脚踝套戴到脚踝上，面向电缆机站立。 将自己放置在距离机器足够远的位置，以便电缆上有张力。 将手放在机器上以获得支撑。 保持腿伸直，慢慢将腿移向身体中线。 动作结束时暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0169","name_zh":"绳索上斜卧推","target":"胸","media_id":"Vh0GsK4","instructions_zh":"将长凳调整至 45 度倾斜。 将电缆手柄连接到高滑轮上。 坐在长凳上，面向电缆机，双脚平放在地面上。 正手握住手柄，并将其拉至肩部高度。 向前和向上推动手柄，直到手臂完全伸展。 暂停片刻，然后慢慢将手柄放回起始位置。 重复所需的重复次数。"},{"id":"1318","name_zh":"绳索上斜划船","target":"上背部","media_id":"yaMIo4D","instructions_zh":"以 45 度角设置一个上斜凳，并将绳索手柄连接到低滑轮上。 坐在长凳上，面向电缆机，双脚平放在地板上，膝盖稍微弯曲。 正手握住电缆手柄，并将双臂完全伸展到身前。 从臀部开始向前倾，同时保持背部挺直，核心肌群参与。 缩回肩胛骨并弯曲肘部，将电缆手柄拉向胸部。 在动作的最高点挤压背部肌肉，然后慢慢伸展手臂回到起始位置。 重复所需的重复次数。"},{"id":"0171","name_zh":"绳索上斜飞鸟","target":"胸","media_id":"tBWXbIT","instructions_zh":"将电缆机调整至较低位置并安装手柄。 坐在倾斜的长凳上，背部靠在垫子上，双脚平放在地板上。 正手握住手柄，并将双臂伸直至身前。 保持肘部轻微弯曲，以受控的动作向两侧张开双臂。 在完全伸展位置停顿片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0170","name_zh":"绳索上斜飞鸟（健身球）","target":"胸","media_id":"27NNGFr","instructions_zh":"以倾斜角度设置稳定球。 将电缆手柄连接到电缆机的高滑轮上。 背对机器坐在稳定球上，双脚牢牢踩在地面上。 正手握住电缆手柄，手掌朝前。 稍微向前倾，保持背部挺直，核心参与。 控制动作，将手臂向两侧伸出，保持肘部轻微弯曲。 继续这个动作，直到手臂与地面平行。 暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0172","name_zh":"绳索上斜下压","target":"背阔肌","media_id":"1PK5Uo3","instructions_zh":"将直杆连接到高滑轮电缆机上。 背对机器站立，双脚与肩同宽。 正手握住杠铃，双手距离略宽于肩宽。 稍微向前倾并保持背部挺直。 伸展肘部，将杠铃向下拉向大腿。 在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。 重复所需的重复次数。"},{"id":"0173","name_zh":"绳索上斜三头臂屈伸","target":"肱三头肌","media_id":"Hx1WC8I","instructions_zh":"将拉索机调整至低滑轮位置。 将直杆连接到电缆上。 背对机器站立，双脚与肩同宽。 正手握住杠铃，并将手臂伸直过头顶。 稍微向前倾，保持背部挺直，核心参与。 弯曲肘部，将杠铃放低到脑后，保持上臂靠近耳朵。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"0174","name_zh":"绳索柔道翻转","target":"腹部","media_id":"MvQPqVW","instructions_zh":"面对电缆机站立，双脚与肩同宽。 用双手握住电缆手柄，使其与胸部齐平，手掌朝下。 启动你的核心并将你的躯干向右旋转，将电缆拉过你的身体。 当你旋转时，转动后脚并让臀部自然旋转。 充分伸展双臂，将绳索手柄翻转到肩膀上来完成动作。 通过反向运动返回起始位置，将躯干旋转回中心。 在另一侧重复该动作。 继续交替进行所需的重复次数。"},{"id":"0860","name_zh":"绳索后摆臂屈伸","target":"肱三头肌","media_id":"HEJ6DIX","instructions_zh":"面向缆绳机站立，双脚与肩同宽。 用右手握住电缆手柄并后退以在电缆中产生张力。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 保持上臂靠近身体，肘部弯曲成 90 度角。 向后伸展前臂，完全伸直手臂。 暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0175","name_zh":"绳索跪姿卷腹","target":"腹部","media_id":"WW95auq","instructions_zh":"将绳索手柄连接到高滑轮上，然后面向远离机器的方向跪下。 双手握住绳柄，将其放在脑后，肘部向两侧伸出。 保持臀部不动，弯曲腰部并将躯干向大腿方向挤压。 在底部停顿片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"3697","name_zh":"绳索跪姿后束划船（用绳索）（男）","target":"肩","media_id":"G61cXLk","instructions_zh":"将绳索手柄连接到低电缆滑轮上，面向机器跪下。 以中立握法（手掌相对）抓住绳子，并将双臂完全伸展到身前。 保持背部挺直，核心收紧，通过收缩肩胛骨将绳子拉向身体。 在动作结束时将肩胛骨挤压在一起并保持短暂的停顿。 慢慢释放张力并回到起始位置。 重复所需的重复次数。"},{"id":"0176","name_zh":"绳索跪姿三头臂屈伸","target":"肱三头肌","media_id":"KWdF2JI","instructions_zh":"将绳索手柄连接到高滑轮上，面向绳索机跪下。 以中立握法（手掌相对）抓住绳子，并将双手放在头的两侧。 在整个练习过程中，保持肘部靠近头部，上臂保持静止。 通过收缩三头肌来伸展前臂，直到手臂完全伸展。 暂停片刻，然后弯曲肘部慢慢回到起始位置。 重复所需的重复次数。"},{"id":"2330","name_zh":"绳索全程背阔肌下拉","target":"背阔肌","media_id":"LEprlgG","instructions_zh":"坐在高位下拉机上，膝盖位于护垫下方。 正手握住电缆杆，握距略宽于肩宽。 稍微向后倾斜，挺胸，保持下背部轻微的拱形。 将杠铃向下拉至上胸部，将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。 重复所需的重复次数。"},{"id":"0177","name_zh":"绳索侧下拉（使用绳索附件）","target":"背阔肌","media_id":"CuaWCmC","instructions_zh":"将绳索附件连接到电缆机的高位置。 面向机器站立，双脚分开与肩同宽。 正手握住绳子，手掌相对。 保持背部挺直并稍微向后倾斜。 将绳子向下拉向身体两侧，将肩胛骨挤压在一起。 在动作的底部停顿片刻。 慢慢释放张力，让绳子回到起始位置。 重复所需的重复次数。"},{"id":"2616","name_zh":"绳索V形杆侧下拉","target":"背阔肌","media_id":"4c9BhzB","instructions_zh":"坐在电缆下拉机上，用正手抓住 V 形杆附件。 调整护膝，使大腿固定在其下方。 保持背部挺直并稍微向后倾斜。 将 V 形杆向下拉至上胸部，同时保持肘部靠近身体。 在动作底部挤压背部肌肉。 慢慢地将 v 形杆返回到起始位置，然后重复所需的重复次数。"},{"id":"0178","name_zh":"绳索侧平举","target":"肩","media_id":"goJ6ezq","instructions_zh":"双脚分开与肩同宽站立，并用正手握住电缆手柄。 保持双臂伸直，核心肌群参与。 将手臂向两侧举起，直到与地板平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0179","name_zh":"绳索低位飞鸟","target":"胸","media_id":"FVmZVhk","instructions_zh":"将手柄连接到缆绳机的低滑轮上，并选择合适的重量。 站在机器中间，双脚分开与肩同宽，膝盖稍微弯曲。 正手握住手柄，将手臂向两侧伸展，肘部保持轻微弯曲。 保持控制，以扫过的动作缓慢地将手臂向前伸，交叉在身体前面。 在运动的最高点暂停片刻，感受胸部肌肉的拉伸。 反转动作，慢慢将手臂恢复到起始位置，始终保持胸部肌肉紧张。 重复所需的重复次数。"},{"id":"0180","name_zh":"绳索低位坐姿划船","target":"上背部","media_id":"hvV79Si","instructions_zh":"坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。 正手握住手柄，手掌朝下。 保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。 将手柄拉向身体，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"1634","name_zh":"绳索仰卧二头弯举","target":"肱二头肌","media_id":"otqIxU4","instructions_zh":"将直杆连接到低滑轮电缆机上。 面朝上躺在平坦的长凳上，双脚平放在地上。 反手握住杠铃，双手与肩同宽。 充分伸展双臂，保持肘部靠近身体两侧。 保持上臂静止，呼气并将杠铃向上弯向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气，慢慢将杠铃放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"0182","name_zh":"绳索仰卧窄握弯举","target":"肱二头肌","media_id":"61GrD55","instructions_zh":"将直杆连接到低滑轮电缆机上。 面朝上躺在平坦的长凳上，双脚平放在地上。 反手握住杠铃，双手与肩同宽。 充分伸展双臂，保持肘部靠近身体两侧。 保持上臂静止，通过收缩二头肌将杠铃卷向胸部。 在顶部暂停片刻，挤压你的二头肌。 慢慢地将杠铃放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"0184","name_zh":"绳索仰卧臂屈伸上拉（使用绳索附件）","target":"背阔肌","media_id":"Q2Eu1Ax","instructions_zh":"将绳子连接到缆绳机上，并将滑轮设置在最高位置。 躺在长凳上，头朝向电缆机。 双手握住绳子，将双臂伸直至胸部上方。 保持双臂伸直，在保持控制的同时慢慢将绳子放到脑后。 在底部停顿片刻，然后慢慢将绳子拉回起始位置。 重复所需的重复次数。"},{"id":"0185","name_zh":"绳索仰卧飞鸟","target":"胸","media_id":"lJJ7Yq8","instructions_zh":"将手柄连接到电缆上，平放在长凳上，双脚平放在地面上。 手掌相对，握住手柄，双臂伸直至胸部上方。 保持肘部轻微弯曲，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。 暂停片刻，然后挤压胸部肌肉，使手臂回到起始位置。 重复所需的重复次数。"},{"id":"0186","name_zh":"绳索仰卧肱三头肌伸展版本2","target":"肱三头肌","media_id":"uxJcFUU","instructions_zh":"将绳索手柄连接到低滑轮电缆机器上。 面朝上躺在平坦的长凳上，头朝向电缆机。 双手抓住绳柄，掌心相对，将双臂伸直至胸前。 保持上臂静止，弯曲肘部，慢慢将绳索手柄放低至前额。 在底部停顿片刻，然后将手臂伸回起始位置。 重复所需的重复次数。"},{"id":"0188","name_zh":"绳索中位飞鸟","target":"胸","media_id":"xLYSdtg","instructions_zh":"将电缆连接到电缆机两侧胸部高度处。 站在机器的中央，一只脚稍微在另一只脚前面。 正手握住手柄，并将手臂向两侧伸展。 保持肘部轻微弯曲并保持轻微前倾。 收紧胸部肌肉，并以扫过的动作将手臂向前伸。 在中心停顿片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0189","name_zh":"绳索单臂俯身划船","target":"上背部","media_id":"EIsE3u8","instructions_zh":"面向缆绳机站立，双脚与肩同宽。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 用一只手抓住电缆手柄，手掌朝内，然后完全伸展手臂。 将电缆手柄拉向身体，保持肘部靠近身体一侧，直到手到达下胸部。 暂停片刻，然后慢慢将手臂伸回起始位置。 重复所需的重复次数，然后换边。"},{"id":"0190","name_zh":"绳索单臂弯举","target":"肱二头肌","media_id":"YTur5nR","instructions_zh":"面对电缆机站立，双脚与肩同宽。 反手握住电缆手柄，手掌朝上。 保持肘部靠近身体两侧，慢慢地将前臂向上卷向肩膀。 在顶部暂停片刻，然后慢慢将前臂放回起始位置。 重复所需的重复次数。"},{"id":"1262","name_zh":"绳索单臂下斜胸部飞鸟","target":"胸","media_id":"w4dLzSx","instructions_zh":"将 D 形手柄连接到低滑轮绳索机器上，并将长凳设置为下降角度。 躺在长凳上，头朝向机器，用右手抓住手柄。 将手臂伸直至胸部上方，保持肘部轻微弯曲。 控制动作，将手臂向一侧放低，直到手与肩膀在一条直线上。 暂停片刻，然后反转动作并将手臂恢复到起始位置。 重复所需的重复次数，然后切换到左臂并重复练习。"},{"id":"1263","name_zh":"绳索单臂健身球飞鸟","target":"胸","media_id":"hHy8tQG","instructions_zh":"坐在健身球上，双脚平放在地上，背部挺直。 一只手握住电缆手柄，并将手臂向一侧伸出，与地面平行。 保持肘部稍微弯曲，手掌朝前。 慢慢地将手臂放在身体上，挤压胸部肌肉。 动作结束时暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"1264","name_zh":"绳索单臂上斜健身球飞鸟","target":"胸","media_id":"P14Dz9D","instructions_zh":"坐在健身球上，双脚平放在地面上，背部靠在倾斜的长凳上。 一只手握住电缆手柄，手臂伸展，手掌朝内。 保持肘部轻微弯曲，慢慢地将手臂向一侧放低，直到手与肩膀在一条直线上。 暂停片刻，然后挤压胸部肌肉，使手臂回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1265","name_zh":"绳索单臂上斜推胸","target":"胸","media_id":"GKEH6jj","instructions_zh":"将拉索机调整至低滑轮位置。 坐在倾斜的长凳上，背对缆绳机。 用一只手抓住手柄并将其举至肩膀高度。 将双脚牢牢放在地面上并保持稳定的位置。 向前和向上按下手柄，充分伸展手臂。 在最高点暂停片刻，然后慢慢将手柄放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"1266","name_zh":"绳索单臂上斜健身球推胸","target":"胸","media_id":"6t00BsF","instructions_zh":"坐在健身球上，双脚平放在地上，背部靠在倾斜的长凳上。 一只手握住电缆手柄，将手臂呈 90 度角，肘部弯曲。 向前和向上按下电缆手柄，完全伸展手臂。 在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0191","name_zh":"绳索单臂侧俯身","target":"胸","media_id":"dB07vDu","instructions_zh":"双脚分开与肩同宽站立，面向缆绳机。 用一只手抓住手柄并向后退一步以在电缆上产生张力。 腰部向前弯曲，保持背部挺直，核心肌群参与。 将手臂向侧面伸展，与地面平行，肘部稍微弯曲。 慢慢地将手臂放回起始位置，在整个运动过程中保持控制。 重复所需的重复次数，然后换边。"},{"id":"0192","name_zh":"绳索单臂侧平举","target":"肩","media_id":"wEulIzp","instructions_zh":"双脚分开与肩同宽站立，面向绳索机。 用一只手握住电缆手柄，手掌朝下，站得离机器足够远，以便电缆上有张力。 保持手臂伸直，慢慢向一侧举起，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"1633","name_zh":"绳索单臂牧师凳弯举","target":"肱二头肌","media_id":"eHBlPsa","instructions_zh":"调整绳索机，使牧师弯举垫处于胸部高度。 面对电缆机站立，双脚与肩同宽。 用手握住电缆手柄，并将上臂靠在牧师弯举垫上。 保持背部挺直，核心肌群参与。 慢慢地将电缆手柄卷向肩膀，保持上臂靠在垫子上。 在动作的最高点暂停片刻，挤压你的二头肌。 慢慢地将电缆手柄放回起始位置。 重复所需的重复次数。 交换手臂并重复练习。"},{"id":"1267","name_zh":"绳索单臂健身球推举","target":"胸","media_id":"MKIelrR","instructions_zh":"坐在健身球上，双脚平放在地上，背部挺直。 一只手握住电缆手柄，将手臂置于胸部高度，肘部弯曲。 将另一只手放在臀部上以保持稳定。 向前按电缆手柄，完全伸展手臂。 暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"3563","name_zh":"绳索单臂下拉","target":"背阔肌","media_id":"U5INZY6","instructions_zh":"将单个手柄连接到高滑轮电缆机上。 面向机器站立，双脚分开与肩同宽。 正手握住手柄并完全伸展手臂。 保持背部挺直，核心肌群参与。 将手柄向一侧拉，同时保持肘部靠近身体。 在动作底部暂停片刻，挤压背阔肌。 慢慢松开手柄回到起始位置。 重复所需的重复次数。 换边并用另一只手臂重复练习。"},{"id":"1635","name_zh":"绳索单臂反向牧师凳弯举","target":"肱二头肌","media_id":"ZXnjcOQ","instructions_zh":"调整拉索机，使滑轮处于最低位置。 面对电缆机站立，双脚与肩同宽。 用反手抓住电缆手柄，并将上臂靠在牧师凳垫上。 在整个练习过程中保持背部挺直，核心肌群参与其中。 慢慢地将前臂向二头肌方向卷曲，保持上臂固定在垫子上。 在动作的最高点暂停片刻，挤压你的二头肌。 慢慢地将电缆手柄放回起始位置。 重复所需的重复次数。 交换手臂并重复练习。"},{"id":"0193","name_zh":"绳索单臂直背高位划船（跪姿）","target":"上背部","media_id":"WrYPP2g","instructions_zh":"将手柄连接到腰部高度的缆绳机上。 面向电缆机跪下，用一只手抓住手柄。 保持背部挺直，核心肌群参与。 将手柄拉向胸部，将肩胛骨挤压在一起。 在动作的最高点停顿片刻。 慢慢松开手柄回到起始位置。 重复所需的重复次数。 换边并用另一只手臂重复练习。"},{"id":"1723","name_zh":"绳索单臂肱三头肌下压","target":"肱三头肌","media_id":"qRZ5S1N","instructions_zh":"面向缆绳机站立，并在胸部高度处安装直杆附件。 正手握住杠铃，然后后退以在绳索上产生张力。 将双脚分开与肩同宽，并稍微弯曲膝盖。 在整个练习过程中保持背部挺直并保持核心参与。 首先，手臂完全伸展并垂直于地板。 保持上臂静止，呼气并将杠铃向下推，直到手臂完全伸展。 暂停片刻，然后吸气，慢慢回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1636","name_zh":"绳索过头弯举","target":"肱二头肌","media_id":"wDUqY2u","instructions_zh":"将直杆连接到高滑轮电缆机上。 面向机器站立，双脚分开与肩同宽。 反手握住杠铃，双手与肩同宽。 保持肘部靠近身体两侧，上臂保持静止。 呼气并将杠铃向下卷向前额，保持上臂静止。 在动作底部暂停片刻，挤压二头肌。 吸气，慢慢地将杠铃返回到起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"1637","name_zh":"绳索健身球过头弯举","target":"肱二头肌","media_id":"ioTf098","instructions_zh":"坐在健身球上，用反手握住电缆手柄。 将手臂完全伸过头顶，保持肘部靠近耳朵。 慢慢地将电缆朝前额卷曲，保持上臂静止。 在动作底部暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0194","name_zh":"绳索过头肱三头肌伸展（绳索附件）","target":"肱三头肌","media_id":"2IxROQ1","instructions_zh":"将绳索连接到高处的缆绳机上。 背对机器站立，双脚与肩同宽。 双手抓住绳子，掌心相对，将双手举过头顶。 保持上臂靠近头部，肘部向前。 弯曲肘部，慢慢将绳子降低到头后。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"1319","name_zh":"绳索手掌旋转划船","target":"上背部","media_id":"OmQ8w0p","instructions_zh":"将手柄连接到腰部高度的缆绳机上。 面向机器站立，双脚分开与肩同宽。 正手握住手柄，手掌朝下。 向后退一步，在绳索上产生张力，保持背部挺直，膝盖稍微弯曲。 将手柄拉向身体，同时将手掌旋转至向上。 在动作结束时将肩胛骨挤压在一起。 慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"0195","name_zh":"绳索牧师凳弯举","target":"肱二头肌","media_id":"P2lNrGL","instructions_zh":"调整绳索机，使牧师弯举垫处于胸部高度。 坐在牧师弯举凳上，将上臂放在垫子上，用反手抓住电缆附件。 保持背部挺直，肘部放在身体两侧。 慢慢地将电缆附件向肩膀方向卷曲，在动作的最高点挤压二头肌。 暂停片刻，然后慢慢将电缆附件放回起始位置。 重复所需的重复次数。"},{"id":"1268","name_zh":"绳索健身球推举","target":"胸","media_id":"vAwm6rK","instructions_zh":"坐在健身球上，双脚平放在地上，膝盖呈 90 度角。 将电缆手柄保持在胸部高度，手掌朝下，肘部弯曲。 收紧核心并向前按压缆索手柄，直到手臂完全伸展。 暂停片刻，然后慢慢释放张力，并将电缆手柄拉回起始位置。 重复所需的重复次数。"},{"id":"0196","name_zh":"绳索拉穿（使用绳索）","target":"臀部","media_id":"OM46QHm","instructions_zh":"背对缆绳机站立，双脚与肩同宽。 双手抓住绳索附件并向前迈一步，在绳索中产生张力。 弯曲臀部并降低上身直至与地面平行，保持背部挺直。 启动臀肌和腿筋，将身体拉回到起始位置。 重复所需的重复次数。"},{"id":"0198","name_zh":"绳索下拉","target":"背阔肌","media_id":"RVwzP10","instructions_zh":"调整拉索下拉机，使座椅处于舒适的高度并固定护膝。 坐在座位上，背部挺直，双脚平放在地面上。 正手握住电缆杆，握距略宽于肩宽。 稍微向后倾斜并启动你的核心。 将电缆杆向下拉向胸部，将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。 重复所需的重复次数。"},{"id":"0197","name_zh":"绳索高位下拉（背阔肌杆）","target":"背阔肌","media_id":"qdRxqCj","instructions_zh":"调整座椅高度，使大腿与地面平行，双脚平放在地板上。 正手握住背阔肌杠铃，握距略宽于肩宽。 坐下来，稍微向后倾斜，保持挺胸、背部挺直。 将杠铃向下拉向胸部，将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。 重复所需的重复次数。"},{"id":"1638","name_zh":"绳索下拉二头弯举","target":"肱二头肌","media_id":"QTXKWPh","instructions_zh":"在最高设置下将直杆连接到电缆机上。 面向机器站立，双脚分开与肩同宽。 反手握住杠铃，双手与肩同宽。 保持肘部靠近身体两侧，上臂保持静止。 呼气，慢慢将杠铃向大腿方向卷曲，保持手腕伸直。 在动作底部暂停片刻，挤压二头肌。 吸气，慢慢地将杠铃返回到起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"0201","name_zh":"绳索下压","target":"肱三头肌","media_id":"3ZflifB","instructions_zh":"将直杆连接到高滑轮电缆机上。 面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。 正手握住杠铃，双手与肩同宽。 保持肘部靠近身体两侧，上臂保持静止。 呼气并将杠铃向下推，直到肘部完全伸展。 暂停片刻，然后吸气，慢慢地将杠铃返回到起始位置。 重复所需的重复次数。"},{"id":"0199","name_zh":"绳索直臂下压（版本2）","target":"背阔肌","media_id":"PskORrA","instructions_zh":"将直杆连接到高滑轮电缆机上。 面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。 正手握住杠铃，保持手臂伸直，手掌朝下。 呼气时，收紧核心并保持背部挺直，并将杠铃向下推向大腿。 在底部暂停片刻，然后一边吸气，一边慢慢地将杠铃返回到起始位置。 重复所需的重复次数。"},{"id":"0200","name_zh":"绳索下压（绳索把手）","target":"肱三头肌","media_id":"dU605di","instructions_zh":"将绳索附件连接到缆绳机上的高滑轮上。 面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。 正手握住绳子，手掌相对。 在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。 呼气并伸展肘部将绳子向下推，直到手臂完全伸展。 暂停片刻，然后吸气，并让肘部弯曲，慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0202","name_zh":"绳索后束划船（马镫把手）","target":"肩","media_id":"yUdIGNs","instructions_zh":"将马镫手柄连接到低电缆滑轮上，面向机器站立。 左手抓住手柄，右脚后退一步，身体保持一个轻微的角度。 稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。 左臂伸展，手掌朝下，通过缩回肩胛骨将手柄拉向胸部。 在动作的最高点暂停片刻，挤压肩胛骨。 慢慢地将手柄释放回起始位置，然后重复所需的重复次数。 换边并用右臂重复练习。"},{"id":"0203","name_zh":"绳索后束划船（绳索把手）","target":"肩","media_id":"wqNPGCg","instructions_zh":"将绳索手柄连接到低滑轮电缆机器上。 面向机器站立，双脚分开与肩同宽。 正手握住绳索手柄，手掌相对。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 保持肘部稍微弯曲，将绳子拉向胸部，将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数。"},{"id":"0204","name_zh":"绳索后推","target":"肱三头肌","media_id":"c3QQLPi","instructions_zh":"将手柄连接到低滑轮电缆机器上，并背对机器站立。 正手握住手柄，并将双臂伸直至身前。 保持肘部不动，将手柄拉回身体，在动作结束时挤压三头肌。 慢慢地将手柄返回到起始位置，然后重复所需的重复次数。"},{"id":"0205","name_zh":"绳索后下拉","target":"背阔肌","media_id":"SpsOSXk","instructions_zh":"调整拉索机，使滑轮处于最高位置。 面向机器坐着，双脚平放在地面上，膝盖稍微弯曲。 正手握住电缆附件，双手之间的距离略大于肩宽。 稍微向后倾斜，保持背部挺直，挺胸。 将电缆附件向下拉向胸部，将肩胛骨挤压在一起。 在动作底部停顿片刻，然后慢慢松开绳索回到起始位置。 重复所需的重复次数。"},{"id":"0873","name_zh":"绳索反向卷腹","target":"腹部","media_id":"RqOtqD7","instructions_zh":"将电缆连接到低滑轮上，然后面朝上躺在垫子上。 用双手握住电缆，并将双臂伸向天花板。 弯曲膝盖并抬起双腿，使大腿靠近胸部。 在保持上半身稳定的同时，将骨盆向胸部弯曲，将臀部抬离垫子。 在顶部暂停片刻，然后慢慢将臀部放回起始位置。 重复所需的重复次数。"},{"id":"0206","name_zh":"绳索反握弯举","target":"肱二头肌","media_id":"eOG0r6v","instructions_zh":"将直杆连接到低滑轮电缆机上。 面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。 反手握住杠铃，双手与肩同宽。 在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。 呼气并将杠铃向上卷向肩膀，收缩二头肌。 在顶部暂停片刻，挤压你的二头肌。 吸气，慢慢将杠铃放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"2406","name_zh":"绳索反握三头肌下压（曲杆）（带臂带）","target":"肱三头肌","media_id":"ThKP69G","instructions_zh":"在最高设置下将直杆连接到电缆机上。 面对电缆机站立，双脚与肩同宽。 反手握住杠铃，手掌朝上，双手与肩同宽。 在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。 启动你的三头肌，慢慢地向下推杠铃，直到你的手臂完全伸展。 在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。 重复所需的重复次数。"},{"id":"1413","name_zh":"绳索反握单臂弯举","target":"肱二头肌","media_id":"gVlnLIJ","instructions_zh":"面向缆绳机站立，双脚与肩同宽。 反手握住电缆手柄，手掌朝下。 保持肘部靠近身体两侧，慢慢地将前臂向上卷向肩膀。 在顶部暂停片刻，然后慢慢将前臂放回起始位置。 重复所需的重复次数。"},{"id":"0209","name_zh":"绳索反握牧师凳弯举","target":"肱二头肌","media_id":"IwX5NqK","instructions_zh":"调整绳索机，使牧师弯举垫处于胸部高度。 坐在牧师弯举凳上，将上臂放在垫子上，手掌朝下，肘部完全伸展。 反手抓住电缆手柄，距离与肩同宽。 保持上臂静止，呼气并将手柄向肩膀卷曲，收缩二头肌。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气，慢慢将手柄放回起始位置，充分伸展肘部。 重复所需的重复次数。"},{"id":"0210","name_zh":"绳索反握腕弯举","target":"前臂","media_id":"eYmsEPR","instructions_zh":"将电缆连接到低滑轮上，然后坐在面向电缆机的长凳上。 正手握住电缆手柄，手掌朝下。 将前臂放在大腿上，手腕悬在边缘上。 保持前臂静止，呼气并尽可能向上弯曲手腕。 在顶部暂停片刻，然后吸气并慢慢将手腕放回起始位置。 重复所需的重复次数。"},{"id":"0207","name_zh":"绳索反握下压","target":"肱三头肌","media_id":"VjYliFZ","instructions_zh":"将直杆连接到高滑轮电缆机上。 面向机器站立，双脚分开与肩同宽。 反手握住杠铃，手掌朝上，双手与肩同宽。 在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。 使用三头肌，将杠铃向下推，直到手臂完全伸展并且三头肌收缩。 暂停片刻，然后慢慢地将杠铃返回到起始位置。 重复所需的重复次数。"},{"id":"0208","name_zh":"绳索反握直背坐姿高位划船","target":"上背部","media_id":"PNtsX17","instructions_zh":"坐在面向电缆机的座位上，双脚平放在地板上。 用手握住电缆附件，手掌朝上，双手与肩同宽。 保持背部挺直，并从臀部稍微向前倾斜。 通过缩回肩胛骨并挤压背部肌肉，将电缆拉向躯干。 在收缩的峰值处暂停片刻，然后慢慢地将电缆释放回起始位置。 重复所需的重复次数。"},{"id":"1320","name_zh":"绳索交叉坐姿划船","target":"上背部","media_id":"UFGF6gk","instructions_zh":"坐在划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。 正手握住缆绳，手掌相对。 稍微向后倾斜，保持背部挺直，核心肌群参与。 将缆绳拉向胸部，将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数。"},{"id":"1321","name_zh":"绳索高位坐姿划船","target":"上背部","media_id":"c8oybX6","instructions_zh":"坐在面向电缆机的高架座椅上。 正手握住缆绳手柄，手掌相对。 保持背部挺直并稍微向后倾斜，保持膝盖轻微弯曲。 通过缩回肩胛骨并挤压背部肌肉，将电缆拉向您的身体。 在完全收缩的位置暂停片刻。 慢慢释放压力并将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"1322","name_zh":"绳索上斜凳划船","target":"上背部","media_id":"MgKwAAo","instructions_zh":"以 45 度角设置上斜凳，并将绳索机连接到低滑轮上。 将绳索手柄连接到缆绳机上，然后坐在面向机器的倾斜长凳上。 正手抓住绳索把手，身体前倾，保持背部挺直。 充分伸展双臂，将绳子拉向上胸部，同时保持肘部靠近身体。 在动作结束时将肩胛骨挤压在一起。 慢慢释放张力并回到起始位置。 重复所需的重复次数。"},{"id":"1639","name_zh":"绳索锤式牧师凳弯举","target":"肱二头肌","media_id":"PcPe0P5","instructions_zh":"将绳索附件连接到低滑轮缆绳机上。 面向机器站立，双脚分开与肩同宽。 以中立握法（手掌相对）抓住绳子。 将上臂靠在牧师凳垫上，保持肘部稍微弯曲。 保持上臂静止，呼气并通过收缩二头肌将绳子卷向肩膀。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢将绳子放回起始位置。 重复所需的重复次数。"},{"id":"1724","name_zh":"绳索高位滑轮过顶三头肌伸展","target":"肱三头肌","media_id":"NN8nSNT","instructions_zh":"将绳子连接到高滑轮上并相应地调整重量。 背对滑轮机站立，双脚与肩同宽。 双手抓住绳子，掌心朝下，双手举过头顶。 保持上臂靠近头部并垂直于地板。 弯曲肘部，慢慢将绳子降低到头后。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"1725","name_zh":"绳索上斜三头肌伸展","target":"肱三头肌","media_id":"ZujAdR9","instructions_zh":"将绳子连接到高滑轮上，并将倾斜长凳调整到舒适的角度。 背对滑轮站立，双脚与肩同宽。 正手抓住绳子，并将双臂伸直过头顶。 在整个练习过程中，保持肘部靠近头部，上臂保持静止。 弯曲肘部，直到前臂接触二头肌，将绳子降低到头后。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"1726","name_zh":"绳索仰卧地板三头肌伸展","target":"肱三头肌","media_id":"U3ffHlY","instructions_zh":"将绳子连接到缆绳机上并将其设置到最低位置。 面朝上躺在地板上，头朝向电缆机。 双手握住绳子，掌心相对，双臂伸直向上伸向天花板。 保持上臂静止，慢慢地将绳子放低到前额，弯曲肘部。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"1640","name_zh":"绳索单臂锤式牧师凳弯举","target":"肱二头肌","media_id":"4hATdoB","instructions_zh":"将绳索手柄连接到低滑轮电缆机器上。 面向机器站立，双脚分开与肩同宽。 反手握住绳索手柄，手掌朝上。 将上臂靠在牧师凳垫上，保持肘部稍微弯曲。 在整个练习过程中保持背部挺直，核心肌群参与其中。 慢慢地将绳索手柄卷向肩膀，保持上臂静止。 在动作的最高点挤压二头肌，然后慢慢将绳柄放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1323","name_zh":"绳索坐姿划船","target":"上背部","media_id":"SJqRxOt","instructions_zh":"坐在划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。 正手握住缆绳，手掌相对。 保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。 将缆绳拉向身体，将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数。"},{"id":"0211","name_zh":"绳索俄罗斯转体（在稳定球上）","target":"腹部","media_id":"d9Xaxq6","instructions_zh":"坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。 双手握住电缆手柄，并将双臂伸直至前方。 稍微向后倾斜，同时保持背部挺直并且核心参与。 将躯干向右扭转，将电缆手柄拉向右臀部。 暂停片刻，然后将躯干向左扭转，将电缆手柄拉向左臀部。 继续交替扭转所需的重复次数。"},{"id":"2144","name_zh":"绳索坐姿胸推","target":"胸","media_id":"nIR4Rwl","instructions_zh":"将座椅高度和电缆手柄调整至舒适的位置。 坐在长凳上，背部挺直，双脚平放在地板上。 正手握住电缆手柄，与肩同高。 向前推动手柄并使其远离身体，充分伸展双臂。 暂停片刻，然后慢慢将手柄放回起始位置。 重复所需的重复次数。"},{"id":"0212","name_zh":"绳索坐姿卷腹","target":"腹部","media_id":"8xUv4J7","instructions_zh":"坐在缆绳机上，双脚平放在地面上，膝盖弯曲。 用双手握住电缆手柄并将其放在脑后。 收紧腹肌，慢慢向前弯曲上半身，使胸部靠近膝盖。 在顶部停顿片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"1641","name_zh":"绳索坐姿弯举","target":"肱二头肌","media_id":"8oYqOt9","instructions_zh":"坐在缆绳机上，双脚平放在地面上，背部挺直。 反手抓住电缆附件，手掌朝上，双臂完全伸展。 保持上臂静止，呼气并将电缆附件卷向肩膀，收缩二头肌。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气并慢慢将电缆附件放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"0213","name_zh":"绳索坐姿高位划船（V把）","target":"背阔肌","media_id":"pwt0pnM","instructions_zh":"坐在缆绳机上，双脚平放在地板上，膝盖稍微弯曲。 正手握住 V 形杆附件，手掌相对，双手与肩同宽。 保持背部挺直，并从臀部稍微向前倾斜。 通过收缩肩胛骨并挤压背部肌肉，将 V 形杆拉向躯干。 在收缩的顶峰停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数。"},{"id":"0214","name_zh":"绳索坐姿单臂交替划船","target":"上背部","media_id":"vpp9Ku2","instructions_zh":"坐在长凳上，面对缆绳机，双脚平放在地面上，膝盖稍微弯曲。 用一只手抓住手柄，并将手臂完全伸展到身前。 将手柄拉向身体，缩回肩胛骨并保持肘部靠近身体两侧。 在动作的最高点暂停片刻，挤压背部肌肉。 慢慢松开手柄回到起始位置。 用另一只手臂重复上述步骤。 双臂交替进行所需的重复次数。"},{"id":"1642","name_zh":"绳索坐姿单臂集中弯举","target":"肱二头肌","media_id":"rZ80Gbp","instructions_zh":"坐在长凳上，双脚平放在地板上，背部挺直。 用一只手握住电缆手柄，并将肘部放在大腿内侧、膝盖上方。 呼气时，保持上臂静止并将电缆手柄向肩膀卷曲。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气时慢慢将电缆手柄放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1643","name_zh":"绳索坐姿过顶弯举","target":"肱二头肌","media_id":"DpWMFP5","instructions_zh":"坐在长凳上，面向电缆机，双脚平放在地面上。 用手握住电缆附件，手掌朝上，双手与肩同宽。 保持上臂不动，肘部靠近身体两侧。 呼气并将电缆附件卷向肩膀，收缩二头肌。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气并慢慢将电缆附件放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"0215","name_zh":"绳索坐姿后束侧平举","target":"肩","media_id":"x825CZm","instructions_zh":"坐在长凳上，面向电缆机，双脚平放在地面上。 正手握住电缆手柄，并将双臂伸直至前方。 保持手臂伸直，慢慢向两侧举起，直到与地板平行。 在顶部停顿片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0861","name_zh":"坐姿绳索划船","target":"上背部","media_id":"fUBheHs","instructions_zh":"坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。 正手握住手柄，保持背部挺直，肩膀放松。 将手柄拉向身体，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"0216","name_zh":"坐姿绳索肩内旋","target":"肩","media_id":"YPoVrBi","instructions_zh":"坐在长凳或椅子上，面向电缆机，双脚平放在地面上。 握住电缆手柄，手臂在身前伸直，与地面平行。 保持肘部稍微弯曲，肩胛骨向后和向下拉。 慢慢向内旋转手臂，将电缆手柄拉向身体中心。 动作结束时暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"2399","name_zh":"坐姿绳索转体","target":"腹部","media_id":"UEjSrKI","instructions_zh":"坐在缆绳机上，双脚平放在地面上，膝盖稍微弯曲。 双手握住电缆手柄，并将双臂伸直至身前。 保持核心参与，慢慢地将躯干旋转到一侧，将电缆拉过身体。 在动作范围结束时暂停片刻，然后慢慢旋转回到起始位置。 在另一侧重复。 继续交替进行所需的重复次数。"},{"id":"0218","name_zh":"坐姿宽握绳索划船","target":"上背部","media_id":"qcY50ZD","instructions_zh":"坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。 正手宽握握住手柄，手掌朝下。 保持背部挺直，并从臀部稍微向前倾斜。 将手柄拉向下胸部，将肩胛骨挤压在一起。 在收缩高峰时暂停片刻。 慢慢松开手柄回到起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"0219","name_zh":"绳索肩推举","target":"肩","media_id":"PzQanLE","instructions_zh":"调整绳索机，使手柄位于肩部高度。 背对机器站立，双脚与肩同宽。 正手握住手柄，将其提升至肩部水平，肘部弯曲并指向外侧。 向上按压手柄，直到手臂完全伸过头顶。 在顶部暂停片刻，然后慢慢将手柄放回至肩部水平。 重复所需的重复次数。"},{"id":"0220","name_zh":"绳索耸肩","target":"斜方肌","media_id":"Eg98Ft9","instructions_zh":"面对电缆机站立，双脚与肩同宽。 正手握住电缆手柄，让手臂垂在身前。 保持手臂伸直，耸肩向耳朵方向向上。 保持收缩一会儿，然后慢慢将肩膀放回起始位置。 重复所需的重复次数。"},{"id":"0222","name_zh":"绳索体侧屈","target":"腹部","media_id":"wPypxFY","instructions_zh":"双脚分开与肩同宽站立，用一只手抓住电缆手柄。 保持背部挺直，核心肌群参与。 腰部慢慢向侧面弯曲，将电缆手柄向膝盖方向降低。 暂停片刻，然后回到起始位置。 在另一侧重复。 交替进行所需的重复次数。"},{"id":"0221","name_zh":"绳索侧屈卷腹（波速球）","target":"腹部","media_id":"qatbkEd","instructions_zh":"双脚分开与肩同宽站立，一只手握住电缆手柄。 将另一只手放在臀部上。 启动你的核心，慢慢向握住电缆的手侧弯，保持背部挺直。 在动作底部暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0223","name_zh":"绳索侧卷腹","target":"腹部","media_id":"q2ADGqV","instructions_zh":"将电缆手柄连接到低滑轮上并站在机器旁边。 用距离机器最远的手抓住手柄，并将另一只手放在臀部上。 双脚分开与肩同宽，膝盖稍微弯曲。 收紧腹肌，腰部向侧面弯曲，将肘部向下拉向臀部。 在底部停顿片刻，然后慢慢回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"1717","name_zh":"绳索深蹲划船（配绳索把手）","target":"背阔肌","media_id":"f7fnAIB","instructions_zh":"将绳子连接到腰部高度的缆绳机上。 面对电缆机站立，双脚与肩同宽。 弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。 正手握住绳子，双手与肩同宽。 收紧核心并将绳子拉向身体，将肩胛骨挤压在一起。 保持肘部靠近身体并继续拉，直到双手到达胸部。 在动作的最高点停顿片刻，然后慢慢松开绳子，并将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"1644","name_zh":"绳索深蹲弯举","target":"肱二头肌","media_id":"3XFdb1Z","instructions_zh":"将电缆手柄连接到电缆机器上的最低设置。 面向机器站立，双脚分开与肩同宽。 反手握住电缆手柄，手掌朝上，手臂完全伸展。 将身体降低至蹲姿，保持背部挺直，膝盖位于脚趾后面。 当你蹲下时，将电缆手柄卷向肩膀，保持肘部靠近身体两侧。 在弯举的顶部暂停片刻，挤压二头肌。 慢慢地将电缆手柄放回起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0224","name_zh":"站姿绳索反手腕弯举","target":"前臂","media_id":"VhX2JdE","instructions_zh":"面向缆绳机站立，双脚与肩同宽。 正手握住电缆手柄，手掌朝下。 保持手臂伸直，肘部靠近身体两侧。 慢慢向上弯曲手腕，将电缆手柄拉向身体。 在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。 重复所需的重复次数。"},{"id":"1375","name_zh":"站姿绳索提踵","target":"小腿","media_id":"yl2IYyy","instructions_zh":"面向缆绳机站立，双脚与肩同宽。 握住电缆机手柄或将电缆脚踝带固定在脚踝上。 尽可能高地伸展脚踝，将脚后跟抬离地面。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0225","name_zh":"站姿绳索交叉高位反向飞鸟","target":"肩","media_id":"P5p0j8B","instructions_zh":"将 D 形手柄安装到缆绳机两侧与肩同高的位置。 站在缆绳机的中间，双脚分开与肩同宽。 正手握住手柄，并将手臂向两侧伸展，手掌朝前。 在整个练习过程中保持肘部轻微弯曲并保持背部挺直。 当您将手柄拉向身体前方时，收紧肩部肌肉并将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0226","name_zh":"站姿绳索卷腹","target":"腹部","media_id":"jpgqxiS","instructions_zh":"将电缆手柄连接到高滑轮上，并背对机器站立。 双手握住手柄并将其放在脑后，保持肘部弯曲。 双脚分开与肩同宽站立，膝盖稍微弯曲。 保持腹肌收紧，呼气，将躯干压向膝盖，将肘部拉向大腿。 在动作底部暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0874","name_zh":"站姿绳索卷腹（配绳索把手）","target":"腹部","media_id":"XU3ePuv","instructions_zh":"将一根绳子连接到胸部高度的缆绳机上。 背对机器站立，双脚与肩同宽。 双手握住绳子并将其放在脑后，保持肘部弯曲。 收紧腹肌，慢慢向前挤压躯干，使肘部靠近膝盖。 在卷腹的最高点暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0227","name_zh":"站姿绳索飞鸟","target":"胸","media_id":"Pr9Rhf4","instructions_zh":"将手柄连接到胸部高度的电缆上。 双脚分开与肩同宽站立，背对缆绳机。 正手握住手柄，手掌朝前。 稍微向前一步以在缆绳中产生张力。 在整个练习过程中保持核心参与并保持背部挺直。 肘部稍微弯曲，慢慢地将双臂向前并拢在胸前。 在运动的最高点挤压胸部肌肉。 慢慢扭转动作，将手臂恢复到起始位置。 重复所需的重复次数。"},{"id":"0228","name_zh":"站姿绳索髋部伸展","target":"臀部","media_id":"Kpajagk","instructions_zh":"将电缆连接到低滑轮上，并背对机器站立。 将电缆绕在脚踝上，双脚分开与肩同宽站立。 在整个练习过程中保持核心参与并保持背部挺直。 慢慢地将腿向后伸直，在动作的最高点挤压臀部。 暂停片刻，然后回到起始位置。 重复所需的重复次数。 换边并用另一条腿重复。"},{"id":"0229","name_zh":"站姿绳索内弯举","target":"肱二头肌","media_id":"YwnI4ja","instructions_zh":"面向缆绳机站立，双脚与肩同宽。 反手握住电缆手柄，手掌朝上。 保持肘部靠近身体两侧，上臂保持静止。 呼气并将绳索手柄卷向肩膀，收缩二头肌。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气并缓慢地将电缆手柄放回起始位置。 重复所需的重复次数。"},{"id":"0230","name_zh":"站姿绳索提拉","target":"腹部","media_id":"qFpAkpP","instructions_zh":"面对电缆机站立，双脚与肩同宽。 双手握住电缆手柄并将其置于腰部高度。 在整个练习过程中启动核心并保持背部挺直。 保持手臂伸直，呼气并将电缆手柄向另一侧的肩膀向上提起，同时旋转躯干。 在顶部暂停片刻，然后吸气并慢慢将拉索手柄放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"0231","name_zh":"站姿单臂绳索肱三头肌伸展","target":"肱三头肌","media_id":"sYCcnon","instructions_zh":"双脚分开与肩同宽站立，面向绳索机。 用右手握住电缆手柄，掌心朝下，调整手臂位置，使其完全伸展并与地面平行。 保持肘部静止并靠近身体。 慢慢弯曲肘部，将电缆手柄向脑后降低。 在动作底部停顿片刻，然后将手臂伸回起始位置。 重复所需的重复次数，然后换边并用左臂进行练习。"},{"id":"1376","name_zh":"站姿单腿绳索提踵","target":"小腿","media_id":"fgc9Xdl","instructions_zh":"面向缆绳机站立，双脚与肩同宽。 抓住电缆机以获得支撑。 将一条腿抬离地面并用另一条腿保持平衡。 慢慢地将脚跟抬离地面，将身体抬起到脚趾上。 在顶部暂停片刻，然后慢慢将脚跟放回起始位置。 重复所需的重复次数，然后换腿。"},{"id":"0232","name_zh":"站姿绳索下拉（配绳索）","target":"肱二头肌","media_id":"CvPn9WV","instructions_zh":"将绳索连接到最高设置的缆绳机上。 面向机器站立，双脚分开与肩同宽。 正手握住绳子，手掌朝下。 在整个练习过程中保持背部挺直并保持核心参与。 将绳子向下拉向大腿，挤压二头肌。 在底部停顿片刻，然后慢慢地将绳子放回原位。 重复所需的重复次数。"},{"id":"0233","name_zh":"站姿绳索三角肌后束划船（配绳索）","target":"肩","media_id":"ZfyAGhK","instructions_zh":"面向缆绳机站立，双脚与肩同宽。 用双手握住电缆附件，手掌相对，然后后退以在电缆中产生张力。 保持背部挺直，核心肌群参与。 将电缆拉向您的身体，将肩胛骨挤压在一起。 在运动的最高点停顿片刻，然后慢慢松开绳索回到起始位置。 重复所需的重复次数。"},{"id":"1727","name_zh":"站姿反握单臂过头绳索肱三头肌伸展","target":"肱三头肌","media_id":"i11JWU7","instructions_zh":"背对缆绳机站立，双脚与肩同宽。 用手握住电缆手柄，并将手臂伸过头顶，保持肘部靠近头部。 保持上臂静止，弯曲肘部，慢慢将电缆手柄降低到脑后。 在底部停顿片刻，然后将手臂伸回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0234","name_zh":"站姿绳索划船（V把）","target":"上背部","media_id":"4f8RXP8","instructions_zh":"面对电缆机站立，双脚与肩同宽。 正手握住 V 形杆附件，手掌朝下。 保持背部挺直，核心肌群参与。 将 V 形杆拉向身体，将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数。"},{"id":"0235","name_zh":"站姿绳索肩外旋","target":"肩","media_id":"FWdVhcW","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 将手臂伸向前方，与地面平行，握住电缆手柄。 保持肘部稍微弯曲，肩胛骨向后拉。 慢慢地向外旋转手臂，远离身体，同时保持肘部处于同一位置。 动作结束时暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0236","name_zh":"站姿绳索转体划船（V把）","target":"上背部","media_id":"JOZhu2h","instructions_zh":"将 V 形杆附件连接到胸部高度的缆绳机上。 面对电缆机站立，双脚与肩同宽。 正手握住 V 形杆，手掌朝下。 后退一步以在电缆中产生张力。 在整个练习过程中保持背部挺直并保持核心参与。 缩回肩胛骨并弯曲肘部，将 V 形杆拉向躯干。 当你拉的时候，将你的躯干扭转到一侧，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，感受上背部的收缩。 慢慢释放紧张并回到起始位置，松开躯干。 重复该动作达到所需的重复次数，每次重复交替扭转方向。"},{"id":"1269","name_zh":"站姿直体绳索交叉","target":"胸","media_id":"UKWTJWR","instructions_zh":"站在缆绳机中间，双脚分开与肩同宽。 手掌朝下握住电缆手柄，手臂伸直至两侧。 保持双臂伸直，将双手放在身体前面，相互交叉。 暂停片刻，然后慢慢回到起始位置，保持双臂伸展。 重复所需的重复次数。"},{"id":"0238","name_zh":"直臂绳索下拉","target":"背阔肌","media_id":"x69MAlq","instructions_zh":"将直杆连接到缆绳机的高滑轮上。 面向机器站立，双脚分开与肩同宽。 正手握住杠铃，保持手臂伸直，手掌朝下。 收紧背阔肌并将杠铃向下拉向大腿，在整个运动过程中保持手臂伸直。 在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。 重复所需的重复次数。"},{"id":"0237","name_zh":"直臂绳索下拉（配绳索）","target":"背阔肌","media_id":"DT14T9T","instructions_zh":"将绳索连接到最高设置的缆绳机上。 面向机器站立，双脚分开与肩同宽。 双手抓住绳子，掌心朝下。 将手臂完全伸展到身前，保持肘部稍微弯曲。 收紧背阔肌，慢慢地将绳子向下拉向大腿，保持手臂伸直。 在底部停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数。"},{"id":"0239","name_zh":"直背坐姿绳索划船","target":"上背部","media_id":"Tq6gbK6","instructions_zh":"坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。 正手握住电缆手柄，手掌朝下。 保持背部挺直，并从臀部稍微向前倾斜。 将电缆手柄拉向身体，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"0240","name_zh":"仰卧绳索反向飞鸟","target":"肩","media_id":"PQcUlDi","instructions_zh":"将 D 形手柄连接到低滑轮缆绳机上，并面朝下躺在平凳上。 每只手握住 D 形手柄，手掌朝下，并将双臂伸直至前方。 保持手臂伸直，将它们向两侧举起，直到与地板平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"2464","name_zh":"绳索蒂博多皮划艇划船","target":"背阔肌","media_id":"ZgwWBoC","instructions_zh":"将电缆手柄连接到低滑轮上，面向机器坐着，双脚平放在地板上。 用右手抓住手柄，完全伸展手臂，保持肘部轻微弯曲。 从臀部开始向前倾斜，保持背部挺直并收紧腹肌。 缩回肩胛骨并弯曲肘部，将手柄拉向躯干，保持手臂靠近身体。 在动作的最高点挤压背部肌肉，然后慢慢回到起始位置。 重复所需的重复次数，然后换边并用左臂执行。"},{"id":"0241","name_zh":"绳索肱三头肌下压（V把）","target":"肱三头肌","media_id":"gAwDzB3","instructions_zh":"在最高设置下将 V 形杆附件连接到电缆机上。 面对电缆机站立，双脚与肩同宽。 正手握住 V 形杆，手掌朝下，双手与肩同宽。 在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。 收紧三头肌并呼气，同时向下推 V 形杆，直到手臂完全伸展。 在动作的底部暂停片刻，挤压你的三头肌。 吸气，同时缓慢地将 V 形杆返回到起始位置，保持控制。 重复所需的重复次数。"},{"id":"2405","name_zh":"绳索三头肌下压（V把）（带臂托板）","target":"肱三头肌","media_id":"OxJk1fg","instructions_zh":"在最高设置下将 V 形杆附件连接到电缆机上。 面对电缆机站立，双脚与肩同宽。 正手握住 V 形杆，手掌朝下，双手与肩同宽。 在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。 收紧三头肌并呼气，同时向下推 V 形杆，直到手臂完全伸展。 在动作的底部暂停片刻，挤压你的三头肌。 吸气，同时缓慢地将 V 形杆返回到起始位置，保持控制。 重复所需的重复次数。"},{"id":"0242","name_zh":"绳索屈膝反向卷腹","target":"腹部","media_id":"TXtXc84","instructions_zh":"将电缆连接到低滑轮上，然后面朝上躺在垫子上。 用双手握住电缆并将双臂伸直至胸部上方。 弯曲膝盖并抬起双腿，使膝盖靠近胸部。 同时，将骨盆向胸部弯曲，将臀部抬离地面。 在顶部暂停片刻，然后慢慢降低双腿和臀部回到起始位置。 重复所需的重复次数。"},{"id":"0243","name_zh":"绳索转体","target":"腹部","media_id":"aVs3BR3","instructions_zh":"双脚分开与肩同宽站立，面向绳索机。 双手握住电缆手柄于胸前，保持双臂略微弯曲。 启动你的核心并将你的躯干向右扭转，将电缆拉过你的身体。 动作结束时暂停片刻，感受腹肌和斜肌的收缩。 缓慢返回起始位置，抵抗绳索的拉力。 向左侧重复该动作。 继续交替进行所需的重复次数。"},{"id":"0862","name_zh":"绳索转体（上下）","target":"腹部","media_id":"fhZQPlV","instructions_zh":"双脚分开与肩同宽站立，面向绳索机。 双手握住电缆手柄于胸前，保持双臂略微弯曲。 启动你的核心并慢慢地将你的躯干旋转到一侧，保持你的臀部和腿部稳定。 旋转结束时暂停片刻，然后慢慢回到起始位置。 向另一侧重复旋转。 继续交替进行所需的重复次数。"},{"id":"0244","name_zh":"绳索旋转拉","target":"背阔肌","media_id":"zCgxPbV","instructions_zh":"将电缆手柄连接到低滑轮上并面向机器站立。 用左手抓住手柄，离开机器，完全伸展手臂。 双脚分开与肩同宽，膝盖稍微弯曲。 在整个练习过程中保持背部挺直，核心肌群参与其中。 将手柄拉向您的身体，同时将您的躯干向右旋转。 动作结束时挤压背部肌肉。 慢慢回到起始位置，保持绳索的张力。 重复所需的重复次数，然后换边并用右手执行。"},{"id":"1645","name_zh":"绳索双臂弯举（上斜凳）","target":"肱二头肌","media_id":"H9y3Dkr","instructions_zh":"坐在倾斜的长凳上，背部靠在垫子上，双脚平放在地面上。 反手握住电缆手柄，手掌朝上，手臂完全伸展。 保持上臂静止，呼气并将手柄向肩膀弯曲，同时收缩二头肌。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气，慢慢将手柄放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"1728","name_zh":"绳索双臂三头肌后伸","target":"肱三头肌","media_id":"vvNjDJS","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 双手握住电缆手柄，手掌朝内，手臂弯曲成 90 度角。 保持上臂静止，向后伸展前臂，直到手臂完全伸展。 暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0245","name_zh":"绳索反握下拉","target":"背阔肌","media_id":"xBYcQHj","instructions_zh":"调整缆绳机，使下拉杆位于您头部上方的高度。 坐在座椅上，用反手抓住下拉杆，双手分开的距离略大于肩宽。 保持背部挺直并稍微向后倾斜。 将杠铃向下拉向胸部，将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。 重复所需的重复次数。"},{"id":"1270","name_zh":"绳索上胸交叉","target":"胸","media_id":"j7XMAyn","instructions_zh":"将手柄连接到胸部高度的电缆上。 站在绳索机的中央，一只脚稍微在另一只脚前面。 手掌朝下抓住手柄，手臂向两侧伸展。 保持肘部轻微弯曲并启动核心肌群。 将电缆在胸前拉到一起，使它们相互交叉。 在运动的最高点挤压胸部肌肉。 慢慢地将电缆释放回起始位置。 重复所需的重复次数。"},{"id":"1324","name_zh":"绳索高位划船","target":"上背部","media_id":"PQStVXH","instructions_zh":"将直杆连接到胸部高度的缆绳机上。 面向机器站立，双脚分开与肩同宽。 正手握住杠铃，双手距离略宽于肩宽。 保持背部挺直，核心肌群参与。 将杠铃拉向上胸部，将肩胛骨挤压在一起。 在动作的最高点停顿片刻。 慢慢地将杠铃释放回起始位置。 重复所需的重复次数。"},{"id":"0246","name_zh":"绳索直立划船","target":"肩","media_id":"cALKspW","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲，并用正手握住电缆附件。 在整个练习过程中保持背部挺直，核心肌群参与其中。 用肘部引导，将电缆附件笔直向上拉向下巴。 在顶部暂停片刻，将肩胛骨挤压在一起。 缓慢地将电缆附件放回起始位置。 重复所需的重复次数。"},{"id":"1325","name_zh":"绳索宽握颈后高位下拉","target":"背阔肌","media_id":"CmEr4pM","instructions_zh":"调整缆绳机，使下拉杆位于您头部上方的高度。 坐在座椅上，用宽的正手握法抓住下拉杆。 稍微向后倾斜时，保持背部挺直，挺胸。 将杠铃向下拉至上胸部，将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。 重复所需的重复次数。"},{"id":"0247","name_zh":"绳索腕弯举","target":"前臂","media_id":"LrV4s90","instructions_zh":"将直杆连接到低滑轮电缆机上。 面向机器站立，双脚分开与肩同宽。 反手握住杠铃，手掌朝上，双手与肩同宽。 将前臂放在长凳或垫子上，手腕悬在边缘上。 保持前臂静止，呼气并尽可能向上弯曲手腕。 在顶部暂停片刻，然后吸气并慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"1407","name_zh":"推墙小腿拉伸","target":"小腿","media_id":"PzNxakt","instructions_zh":"面向墙壁站立，双脚分开与臀部同宽。 将双手靠在墙上，与肩同高。 一只脚向后退一步，脚跟保持在地面上，腿伸直。 稍微弯曲前膝盖并向前倾斜，感觉小腿有拉伸感。 保持拉伸 20-30 秒。 换腿并重复拉伸。"},{"id":"1377","name_zh":"扶墙小腿拉伸","target":"小腿","media_id":"m0tCHqc","instructions_zh":"面向墙壁站立，双脚分开与臀部同宽。 将双手靠在墙上，与肩同高。 右脚向后退一步，保持脚后跟着地，腿伸直。 弯曲左膝并向前倾斜，保持后腿伸直，脚后跟着地。 保持拉伸 20-30 秒。 换腿并重复拉伸。"},{"id":"1378","name_zh":"绳索辅助小腿拉伸","target":"小腿","media_id":"1LVFcEn","instructions_zh":"面向墙壁或坚固物体站立，双脚分开与臀部同宽。 双手握住绳子的两端，将绳子的中间放在右脚掌周围。 左脚向后退一步，脚跟保持在地面上，腿伸直。 身体前倾，保持背部挺直，轻轻拉动绳子以伸展小腿。 保持拉伸 20-30 秒，然后放松。 在另一条腿上重复。"},{"id":"0248","name_zh":"弯杠仰卧划船","target":"上背部","media_id":"R5swFnc","instructions_zh":"在地板上放一个杠铃，脸朝下躺在长凳上，胸部刚好离开边缘。 向下伸手，正手抓住杠铃，距离略宽于肩宽。 双腿伸直，双脚着地，伸展双臂，将杠铃提离地面。 将杠铃拉向胸部，将肩胛骨挤压在一起。 将杠铃放回起始位置，然后重复所需的重复次数。"},{"id":"2963","name_zh":"将军椅直腿举","target":"腹部","media_id":"weoDEpH","instructions_zh":"坐在船长椅上，背部靠在靠背上，前臂放在扶手垫上。 保持上半身稳定，背部挺直。 收紧腹肌并将双腿抬起到身前，保持伸直。 继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"1548","name_zh":"坐椅伸腿拉伸","target":"股四头肌","media_id":"xGgAGPm","instructions_zh":"坐在椅子边缘，背部挺直，双脚平放在地面上。 将一只腿伸直在身前，脚跟保持在地面上。 稍微向前倾，感受股四头肌的拉伸。 保持这个姿势20-30秒。 换腿并重复拉伸。"},{"id":"1271","name_zh":"胸部和肩前拉伸","target":"胸","media_id":"Uto7l43","instructions_zh":"站直，双脚分开与肩同宽。 将双臂伸直至前方，与肩同高。 双臂交叉在身体前方，右臂放在左臂上方。 手指交叉并将手掌压在一起。 轻轻地将肩胛骨挤压在一起，然后将双手向前推，感觉胸部和肩膀前部有拉伸感。 保持拉伸 20-30 秒，然后放松。 重复所需的重复次数。"},{"id":"0251","name_zh":"双杠臂屈伸","target":"胸","media_id":"9WTm7dq","instructions_zh":"将自己置于双杠上，双臂完全伸展，身体伸直。 弯曲肘部，降低身体，直到肩膀低于肘部。 伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"1430","name_zh":"双杠臂屈伸（引体双杠架上）","target":"胸","media_id":"XgWyAiA","instructions_zh":"将倾斜杆调整到您可以舒适地握住它们的高度。 站在杠铃之间，将双手放在每个杠铃上，距离略宽于肩宽。 跳起来并伸直双臂，将体重支撑在杠上。 弯曲膝盖并将脚踝交叉在身后。 弯曲肘部降低身体，保持胸部向上，肩膀向下。 继续降低，直到肩膀低于肘部或直到您感到胸部有拉伸感。 推动手掌并伸展肘部，将身体抬回到起始位置。 重复所需的重复次数。"},{"id":"2462","name_zh":"直杠臂屈伸","target":"胸","media_id":"LQFOrMn","instructions_zh":"手掌朝下，双臂完全伸展，抓住双杠。 弯曲膝盖并交叉脚踝。 弯曲手臂，降低身体，直到肩膀低于肘部。 伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"1272","name_zh":"健身球胸部拉伸","target":"胸","media_id":"ykA5tU7","instructions_zh":"坐在稳定球上，双脚平放在地面上，背部挺直。 双手握住健身球，并将双臂伸直至身前。 慢慢地将健身球移向胸部，感受胸部肌肉的拉伸。 保持伸展几秒钟，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"3216","name_zh":"拍胸俯卧撑（男）","target":"胸","media_id":"7E06s6d","instructions_zh":"从高平板支撑位置开始，双手分开略宽于肩宽，身体呈一条直线。 弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。 当你降低身体时，用右手拍打胸部。 将自己推回到起始位置。 重复这个动作，这次用左手敲击胸部。 继续交替进行所需的重复次数。"},{"id":"1326","name_zh":"反手引体向上","target":"背阔肌","media_id":"T2mxWqc","instructions_zh":"悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。 启动核心肌群，将身体拉向杠铃杆，以胸部为主导。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"0253","name_zh":"窄距对握引体向上","target":"上背部","media_id":"G70mEAJ","instructions_zh":"用狭窄的平行握距悬挂在引体向上杆上，手掌朝向您。 收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"0257","name_zh":"膝盖画圆拉伸","target":"小腿","media_id":"X7jbxra","instructions_zh":"双脚分开与肩同宽站立，双手放在臀部。 稍微弯曲膝盖，将脚跟抬离地面，用脚掌保持平衡。 保持膝盖弯曲，先顺时针旋转膝盖，然后逆时针旋转膝盖。 执行所需的重复运动次数。"},{"id":"1273","name_zh":"拍手俯卧撑","target":"胸","media_id":"wigSg76","instructions_zh":"从高平板支撑位置开始，双手分开略宽于肩宽。 弯曲肘部，将身体降低到地面，保持核心参与。 爆发性地推动手掌，将身体推离地面。 在半空中时，拍手，然后回到起始位置。 重复所需的重复次数。"},{"id":"0258","name_zh":"时钟俯卧撑","target":"胸","media_id":"CMAxnsG","instructions_zh":"从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。 弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。 当你下降时，将你的身体向左旋转，将你的左臂伸直到侧面。 向上推回到起始位置，同时将身体旋转到中心。 重复俯卧撑，这次将身体向右旋转，并将右臂向侧面伸出。 每次重复时继续交替进行。"},{"id":"1327","name_zh":"窄距反手引体向上","target":"背阔肌","media_id":"VnfUNW7","instructions_zh":"抓住引体向上杆，手掌朝向自己，双手与肩同宽。 悬挂在杠上，双臂完全伸展，双脚离开地面。 收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"0259","name_zh":"窄距俯卧撑","target":"肱三头肌","media_id":"x6KpKpq","instructions_zh":"从高位平板支撑开始，双手并拢，位于肩膀正下方。 收紧核心，将身体降低到地面，保持肘部靠近身体两侧。 推动手掌以伸展手臂并返回到起始位置。 重复所需的重复次数。"},{"id":"2398","name_zh":"窄距跪姿俯卧撑","target":"肱三头肌","media_id":"v3vLFW0","instructions_zh":"首先双手和膝盖着地，双手与肩同宽，膝盖与臀部同宽。 弯曲肘部，将上身压向地面，使其靠近身体两侧。 当你的胸部刚好高于地面时，暂停片刻。 推动手掌以伸直手臂并返回到起始位置。 重复所需的重复次数。"},{"id":"0260","name_zh":"蚕式卷腹","target":"腹部","media_id":"SLKj2pX","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"1468","name_zh":"蟹式转体触脚尖","target":"腹部","media_id":"xgsGFVM","instructions_zh":"首先坐在地上，膝盖弯曲，双脚平放在地板上。 将双手放在身后，手指指向脚部，并将臀部抬离地面。 将一条腿伸直到您面前，同时将另一只手伸向脚趾。 返回起始位置并在另一侧重复。 继续交替进行所需的重复次数。"},{"id":"0262","name_zh":"交叉卷腹","target":"腹部","media_id":"rbu5UUb","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，将上半身抬离地面，然后扭转，使右肘靠近左膝盖。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 在另一侧重复，将左肘靠近右膝盖。 重复所需的重复次数。"},{"id":"0267","name_zh":"卷腹（双手过头）","target":"腹部","media_id":"kjJ3VoQ","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双臂伸直至头顶上方。 收紧腹肌，将上半身抬离地面，向前向膝盖弯曲。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"0271","name_zh":"卷腹（在健身球上）","target":"腹部","media_id":"MCUhf1F","instructions_zh":"坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。 仰卧在球上，直到下背部得到支撑并且上半身与地板平行。 将双手放在脑后或放在胸前。 收紧腹肌，将上身抬向膝盖，躯干向前卷曲。 在动作的最高点暂停片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"0272","name_zh":"卷腹（在健身球上，手臂伸直）","target":"腹部","media_id":"Sn8wxAI","instructions_zh":"坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。 仰卧在球上，直到下背部得到支撑并且上半身与地板平行。 将双手放在脑后或交叉放在胸前。 收紧腹肌，将上半身抬离球，将肩膀向臀部弯曲。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"0274","name_zh":"仰卧卷腹","target":"腹部","media_id":"TFqbd8t","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，将肩膀抬离地面，向前向膝盖弯曲。 在顶部停顿片刻，然后慢慢将肩膀放回起始位置。 重复所需的重复次数。"},{"id":"3016","name_zh":"卷体","target":"腹部","media_id":"g2oKspu","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"3769","name_zh":"屈膝礼深蹲","target":"臀部","media_id":"gUjqdei","instructions_zh":"双脚分开与肩同宽站立。 右脚向斜后方跨出一步，跨过身体，交叉在左腿后面。 弯曲双膝，就像行屈膝礼一样，将身体降低到地面。 保持躯干直立，将体重放在前脚上。 推动前脚返回起始位置。 在另一侧重复，用左脚斜向后方跨过身体。"},{"id":"2331","name_zh":"椭圆机","target":"有氧","media_id":"XSCHmiI","instructions_zh":"调整座椅高度并将自己放在自行车交叉训练机上。 将脚放在踏板上并抓住车把。 开始以平稳且受控的动作踩踏。 保持稳定的步伐并根据需要增加阻力。 继续踩踏您的有氧运动所需的持续时间。"},{"id":"0276","name_zh":"死虫式","target":"腹部","media_id":"iny3m5y","instructions_zh":"平躺，双臂伸向天花板。 弯曲膝盖，将双腿抬离地面，使臀部和膝盖形成 90 度角。 接合你的核心和下背部，将你的下背部压入地面。 慢慢地将右臂和左腿放低至地面，保持它们伸直并悬停在地板上方。 暂停片刻，然后回到起始位置。 用左臂和右腿重复该动作。 继续交替进行所需的重复次数。"},{"id":"0277","name_zh":"下斜卷腹","target":"腹部","media_id":"9Ap7miY","instructions_zh":"躺在倾斜的长凳上，双脚固定，膝盖弯曲成 90 度角。 将双手放在脑后或放在胸前。 收紧腹肌，将上半身抬向膝盖，卷曲躯干。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"0279","name_zh":"下斜俯卧撑","target":"胸","media_id":"i5cEhka","instructions_zh":"将双手放在地面上，距离略宽于肩宽，双脚放在稳定的表面上。 保持身体从头到脚呈一条直线，锻炼核心肌肉。 弯曲肘部，使胸部靠近地面，使胸部靠近地面。 推动手掌以伸展手臂并返回到起始位置。 重复所需的重复次数。"},{"id":"0282","name_zh":"下斜仰卧起坐","target":"腹部","media_id":"QLL2gdc","instructions_zh":"躺在倾斜的长凳上，双脚固定，膝盖弯曲。 将双手放在脑后或放在胸前。 收紧腹肌，将上半身抬离长凳，向前向膝盖弯曲。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"1274","name_zh":"深度俯卧撑","target":"胸","media_id":"vptOQ4N","instructions_zh":"从高平板支撑位置开始，双手分开略宽于肩宽，身体呈一条直线。 弯曲肘部，使胸部靠近地面，使胸部靠近地面。 推动手掌以伸展手臂并返回到起始位置。 重复所需的重复次数。"},{"id":"0283","name_zh":"钻石俯卧撑","target":"肱三头肌","media_id":"soIB2rj","instructions_zh":"从高位平板支撑开始，双手并拢，拇指和食指形成菱形。 让你的身体从头到脚保持一条直线，锻炼你的核心和臀部。 将胸部降低至双手形成的菱形，保持肘部靠近身体。 在底部暂停片刻，然后将自己推回到起始位置。 重复所需的重复次数。"},{"id":"0284","name_zh":"驴式提踵","target":"小腿","media_id":"u5ESqzH","instructions_zh":"将脚趾站立在升高的表面上，例如台阶或木块。 将双手放在稳定的支撑物上，例如墙壁或栏杆，以保持平衡。 尽可能高地抬高脚后跟，将身体重量转移到脚掌上。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1275","name_zh":"下落俯卧撑","target":"胸","media_id":"Q497lAE","instructions_zh":"从高平板支撑位置开始，双手分开略宽于肩宽。 将胸部压向地面，保持肘部靠近身体。 当你的胸部刚好高于地面时，迅速将膝盖放在地上。 伸展双臂，将自己推回到起始位置。 重复所需的重复次数。"},{"id":"0285","name_zh":"哑铃交替弯举","target":"肱二头肌","media_id":"BU15nH4","instructions_zh":"站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数，交替手臂。"},{"id":"2403","name_zh":"哑铃交替弯举（使用弯举板）","target":"肱二头肌","media_id":"CfKsRbG","instructions_zh":"站直，双脚分开与肩同宽，双手各握一个哑铃，手掌朝前。 将手臂冲击波放在上臂上，确保牢固贴合。 保持上臂静止，呼气并将一只哑铃向上弯向肩膀，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢将哑铃放回起始位置。 用另一只手臂重复该动作。 继续交替手臂进行所需的重复次数。"},{"id":"1646","name_zh":"哑铃交替锤式牧师椅弯举","target":"肱二头肌","media_id":"fy7Tgy4","instructions_zh":"坐在牧师凳上，双手各持一个哑铃，手掌面向躯干，双臂完全伸展。 保持上臂静止，在弯举哑铃时呼气，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复建议的重复次数。"},{"id":"1647","name_zh":"哑铃交替牧师椅弯举","target":"肱二头肌","media_id":"NlfIbzq","instructions_zh":"坐在牧师凳上，每只手各握一个哑铃，手掌朝上。 将上臂放在牧师凳的垫子上，让手臂完全伸展。 保持上臂静止，呼气并弯曲右手的哑铃，同时收缩二头肌。 继续弯举哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 暂停片刻，然后吸气，慢慢将哑铃放回起始位置。 用左臂重复该动作。 继续交替手臂进行所需的重复次数。"},{"id":"1648","name_zh":"哑铃交替坐姿锤式弯举","target":"肱二头肌","media_id":"6em2Dxj","instructions_zh":"坐在长凳上，双手各握一个哑铃，手掌朝向躯干，手臂向下伸展。 保持背部挺直，肘部靠近躯干。 呼气，将右手的哑铃向肩膀弯曲，保持上臂静止。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 暂停片刻，然后吸气，慢慢将哑铃放回起始位置。 用左臂重复该动作。 继续交替手臂进行所需的重复次数。"},{"id":"0286","name_zh":"哑铃交替侧推举","target":"肩","media_id":"izMnLqz","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高。 将一个哑铃推过头顶，同时将另一个哑铃保持在与肩同高的位置。 将按下的哑铃放回肩部高度，同时将另一个哑铃压过头顶。 继续交替进行所需的重复次数。"},{"id":"1649","name_zh":"哑铃交替弯举（单腿抬起置于健身球上）","target":"肱二头肌","media_id":"Zwiw7XR","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。 将健身球放在身后，并将一只脚放在上面，保持平衡。 双臂完全伸展，肘部靠近身体两侧，将一只哑铃向肩膀弯曲，同时保持上臂静止。 将哑铃放回起始位置，然后用另一只手臂重复该动作。 继续交替手臂进行所需的重复次数。"},{"id":"1650","name_zh":"哑铃交替坐姿弯举（在健身球上）","target":"肱二头肌","media_id":"J74XlNf","instructions_zh":"坐在健身球上，双脚平放在地上，背部挺直。 每只手握住一个哑铃，手掌朝前，双臂完全伸展。 保持上臂静止，呼气并弯举一只哑铃，同时旋转前臂，直到手掌面向肩膀。 吸气，慢慢将哑铃放回起始位置。 用另一只手臂重复弯举动作。 继续交替卷发达到所需的重复次数。"},{"id":"2137","name_zh":"哑铃阿诺德推举","target":"肩","media_id":"Xy4jlWA","instructions_zh":"坐在有背部支撑的长凳上，双手各握一个哑铃，与肩同高，手掌朝向身体，肘部弯曲。 向上推哑铃，直到手臂完全伸展，手掌朝前。 抬起时旋转手腕，使手掌在动作的最高点朝前。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0287","name_zh":"哑铃阿诺德推举 v. 2","target":"肩","media_id":"eOrFCnx","instructions_zh":"坐在有背部支撑的长凳上，双手各握一个哑铃，与肩同高，手掌朝向身体，肘部弯曲。 向上推哑铃，直到手臂完全伸展，手掌朝前。 抬起时旋转手腕，使手掌在动作的最高点朝前。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0288","name_zh":"哑铃环绕上拉","target":"胸","media_id":"vi8EhoE","instructions_zh":"平躺在长凳上，头放在一端，双脚牢牢踩在地上。 双手握住哑铃，将手臂伸直至胸部上方。 保持手臂伸直，以弧线动作慢慢将哑铃降低到脑后。 在底部停顿片刻，然后将哑铃举回到起始位置。 重复所需的重复次数。"},{"id":"0289","name_zh":"哑铃平板卧推","target":"胸","media_id":"SpYC0Kp","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 双手各握一个哑铃，手掌朝前，双臂伸至胸部上方。 慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。 暂停片刻，然后将哑铃推回起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0290","name_zh":"哑铃坐姿推举","target":"肩","media_id":"3d7wHyd","instructions_zh":"坐在长凳上，每只手各拿一个哑铃，放在大腿上。 向后倾斜，将哑铃放在胸部两侧，手掌朝前。 向上推哑铃，直到手臂完全伸展。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0291","name_zh":"哑铃平凳深蹲","target":"臀部","media_id":"mnzcrIB","instructions_zh":"将哑铃放在长凳前的地面上。 背对长凳站立，双脚与肩同宽。 弯曲膝盖和臀部，将自己降低到长凳上，保持胸部挺直，背部挺直。 一旦你的臀部接触到长凳，就用脚后跟站起来，回到起始位置。 重复所需的重复次数。"},{"id":"0293","name_zh":"哑铃俯身划船","target":"上背部","media_id":"BJ0Hz5L","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个哑铃，手掌朝向身体。 臀部向前弯曲，保持背部挺直，核心肌群参与。 让你的手臂垂直垂向地板，肘部稍微弯曲。 将哑铃拉向胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1651","name_zh":"哑铃弯举弓步（保龄球式）","target":"肱二头肌","media_id":"1VpF8db","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。 右脚向前迈出一步，弯曲右膝，将身体降低至弓步位置。 当你向前弓步时，将哑铃向上弯向肩膀，保持肘部靠近身体。 在弓步底部，将躯干向右旋转，就像打保龄球一样。 反转动作，右脚向后退一步，回到起始位置，同时放下哑铃。 重复弓步和弯举动作，这次将躯干向左旋转。 继续交替进行所需的重复次数。"},{"id":"1652","name_zh":"哑铃弯举（在健身球上，单腿抬起）","target":"肱二头肌","media_id":"2NImIAG","instructions_zh":"坐在健身球上，双脚平放在地上，背部挺直。 每只手握住一个哑铃，手掌朝前，双臂完全伸展。 慢慢地将哑铃向肩膀弯曲，保持肘部靠近身体两侧。 在动作的最高点暂停片刻，然后慢慢将哑铃放回起始位置。 在进行二头肌弯举时，将一条腿抬离地面，并在整个练习过程中将其保持在空中。 重复所需的重复次数，然后换腿并重复。"},{"id":"1653","name_zh":"哑铃弯举（单腿站立）","target":"肱二头肌","media_id":"uSkDMYl","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。 将一条腿伸到身后，用脚趾保持平衡。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数，然后换腿并重复。"},{"id":"0294","name_zh":"哑铃弯举","target":"肱二头肌","media_id":"NbVPDMW","instructions_zh":"站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"2401","name_zh":"哑铃二头弯举（臂托板）","target":"肱二头肌","media_id":"nlJsbkW","instructions_zh":"站直，双手各持一个哑铃，手掌朝前。 保持肘部靠近躯干，上臂保持静止。 呼气并弯举哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1654","name_zh":"哑铃反握二头弯举","target":"肱二头肌","media_id":"nFc4FyV","instructions_zh":"站直，双手各握一个哑铃，手掌朝下，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1655","name_zh":"哑铃二头弯举深蹲","target":"肱二头肌","media_id":"niXESDw","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。 保持背部挺直，肘部靠近身体两侧，呼气并将哑铃向上弯向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气并慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1656","name_zh":"哑铃二头弯举（波速球V字坐姿）","target":"肱二头肌","media_id":"H1XAdpk","instructions_zh":"坐在博苏球上，双脚平放在地上，膝盖弯曲成 90 度角。 每只手握住一个哑铃，手掌朝前，双臂在身体两侧完全向下伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1201","name_zh":"哑铃波比跳","target":"有氧","media_id":"0JtKWum","instructions_zh":"从站立位置开始，双脚分开与肩同宽，每只手各拿一个哑铃。 将身体降低至蹲姿，将哑铃放在您面前的地面上。 将双脚踢回到俯卧撑位置，保持身体呈一条直线。 进行俯卧撑，弯曲肘部并将胸部降低到地面。 将脚向后跳向双手，以蹲姿着地。 爆发性地站起来，将哑铃从地上举起，放到肩膀上。 将哑铃举过头顶，充分伸展手臂。 将哑铃放回到肩膀上，然后重复整个序列，达到所需的重复次数。"},{"id":"0295","name_zh":"哑铃高翻","target":"臀部","media_id":"7Hg55JG","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，正握。 弯曲膝盖，降低臀部至下蹲位置，保持背部挺直，挺胸。 爆发性地伸展臀部和膝盖，通过脚后跟跳离地面。 当你跳跃时，耸肩并将哑铃拉向你的肩膀，保持它们靠近你的身体。 在与肩同高的位置抓住哑铃，肘部向前，手掌朝上。 通过反向运动将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1731","name_zh":"哑铃窄距卧推","target":"肱三头肌","media_id":"7jGOBF3","instructions_zh":"坐在平坦的长凳上，每只手各拿一个哑铃，放在大腿上。 用你的大腿帮助举起哑铃，一次举起一个哑铃，这样你就可以将它们保持在与肩同宽的位置。 一旦与肩同宽，向前旋转手腕，使手掌背向自己。这将是您的起始位置。 当你吸气时，慢慢地将哑铃降低到你的身边，直到它们与你的胸部齐平。 呼气时，用三头肌将哑铃举回到起始位置。确保只使用三头肌，不要使用前臂或二头肌来帮助举起哑铃。 在收缩位置第二次暂停后，重复该动作达到规定的重复次数。"},{"id":"0296","name_zh":"哑铃窄距卧推","target":"肱三头肌","media_id":"RxayqAZ","instructions_zh":"坐在平坦的长凳上，每只手各拿一个哑铃，放在大腿上。 用你的大腿帮助举起哑铃，一次举起一个哑铃，这样你就可以将它们保持在与肩同宽的位置。 一旦与肩同宽，向前旋转手腕，使手掌背向自己。这将是您的起始位置。 当你吸气时，慢慢地将哑铃降低到你的身边，直到它们与你的胸部齐平。 呼气时，用三头肌将哑铃举回到起始位置。 重复所需的重复次数。"},{"id":"0297","name_zh":"哑铃集中弯举","target":"肱二头肌","media_id":"gvsWLQw","instructions_zh":"坐在长凳上，双腿分开，一只手拿着哑铃，肘部放在大腿内侧。 完全伸展手臂并用反手握住哑铃。 保持上臂静止，呼气并将重量向上弯向肩膀，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"3635","name_zh":"哑铃对侧前弓步","target":"臀部","media_id":"ecl28tP","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 右脚向前迈出一步，保持背部挺直并启动核心。 弯曲双膝降低身体，直到右大腿与地面平行。 推动右脚跟回到起始位置。 左腿重复上述动作。 交替腿进行所需的重复次数。"},{"id":"0298","name_zh":"哑铃交叉锤式弯举","target":"肱二头肌","media_id":"Qyk5J3p","instructions_zh":"站直，双手各持一个哑铃，手掌朝向身体。 保持肘部靠近躯干，上臂保持静止。 呼气并弯举哑铃，同时收缩二头肌，将哑铃穿过身体拉向对侧的肩膀。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1657","name_zh":"哑铃交叉锤式弯举 v.2","target":"肱二头肌","media_id":"HDYiZcY","instructions_zh":"站直，双手各持一个哑铃，手掌朝向身体。 保持肘部靠近躯干，上臂保持静止。 呼气并弯举哑铃，同时收缩二头肌，使哑铃尽可能靠近另一侧的肩膀。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0299","name_zh":"哑铃古巴推举","target":"肩","media_id":"QfAKy1G","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝下。 保持核心收紧，肘部稍微弯曲，将哑铃向上举过头顶，直到手臂完全伸展。 旋转手腕，使手掌朝前。 慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。 重复所需的重复次数。"},{"id":"2136","name_zh":"哑铃古巴推举 v.2","target":"肩","media_id":"BqgCRif","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝下。 保持核心收紧，背部挺直，将哑铃垂直推过头顶，直到手臂完全伸展。 旋转手腕，使手掌朝前。 将哑铃放回至肩膀高度，将手腕旋转回起始位置。 重复所需的重复次数。"},{"id":"0300","name_zh":"哑铃硬拉","target":"臀部","media_id":"nUwVh7b","instructions_zh":"双脚分开与肩同宽站立，脚趾指向前方。 双手各握一个哑铃，手掌朝向身体，手臂向下伸展。 弯曲臀部和膝盖，将哑铃向地面降低，同时保持背部挺直。 脚跟用力，伸展臀部和膝盖，将哑铃举回起始位置。 重复所需的重复次数。"},{"id":"0301","name_zh":"哑铃下斜卧推","target":"胸","media_id":"DwhEmmE","instructions_zh":"躺在倾斜的长凳上，双脚固定，头部低于臀部。 双手各握一个哑铃，双臂伸直至胸部上方，手掌朝前。 慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。 将哑铃推回起始位置，充分伸展手臂。 重复所需的重复次数。"},{"id":"0302","name_zh":"哑铃下斜飞鸟","target":"胸","media_id":"xXm4nYq","instructions_zh":"躺在倾斜的长凳上，双脚固定，头部低于臀部。 双手各握一个哑铃，手掌相对，双臂伸至胸部上方。 将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。 暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。 重复所需的重复次数。"},{"id":"0303","name_zh":"哑铃下斜锤式推举","target":"胸","media_id":"1qrWgZ2","instructions_zh":"躺在倾斜的长凳上，双脚固定，头部低于臀部。 双手各握一个哑铃，手掌相对，双臂伸至胸部上方。 将哑铃降低到胸部两侧，保持肘部稍微弯曲。 将哑铃推回到起始位置，充分伸展手臂。 重复所需的重复次数。"},{"id":"1276","name_zh":"哑铃下斜单臂飞鸟","target":"胸","media_id":"NL6YBwN","instructions_zh":"躺在斜凳上，一只手拿着哑铃，将其放在大腿上。 用大腿帮助举起哑铃，将其举至与肩同宽，手掌朝向躯干。 旋转手腕，使手掌朝前。 吸气时，将哑铃慢慢降低到一侧，直到感觉到胸部有拉伸感。 呼气并使用胸部肌肉将哑铃拉回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1617","name_zh":"哑铃下斜单臂锤式推举","target":"肱三头肌","media_id":"SHUMp5H","instructions_zh":"躺在下斜长凳上，一只手握住哑铃，放在胸前。 将手臂伸直向上，保持肘部稍微弯曲。 将哑铃向肩膀方向降低，保持肘部靠近身体。 将哑铃推回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0305","name_zh":"哑铃下斜耸肩","target":"斜方肌","media_id":"cwsAI4G","instructions_zh":"设置一个 45 度角的下斜凳。 脸朝下躺在长凳上，胸部和腹部靠在长凳上。 每只手握住一个哑铃，双臂完全伸向地板。 保持手臂伸直，将肩膀尽可能高地抬向耳朵。 保持收缩一会儿，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0304","name_zh":"哑铃下斜耸肩 v.2","target":"斜方肌","media_id":"bRlbdjK","instructions_zh":"设置一个 45 度角的下斜凳。 脸朝下躺在长凳上，胸部和腹部靠在长凳上。 每只手握住一个哑铃，手掌相对，双臂完全伸展。 保持手臂伸直，尽可能高地抬高肩膀，同时将肩胛骨挤压在一起。 保持收缩短暂停顿，然后将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0306","name_zh":"哑铃下斜臂屈伸","target":"肱三头肌","media_id":"OTgkHwR","instructions_zh":"躺在斜凳上，头低于脚，双手各握一个哑铃，手掌相对。 充分伸展双臂，保持肘部靠近头部。 将哑铃慢慢降低到脑后，弯曲肘部。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数。"},{"id":"0307","name_zh":"哑铃下斜转体飞鸟","target":"胸","media_id":"reFHapa","instructions_zh":"躺在倾斜的长凳上，头部低于臀部。 双手各握一个哑铃，手掌相对，双臂伸直越过胸部。 将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。 当你降低哑铃时，扭转手腕，使手掌在动作底部朝前。 反转动作，将哑铃拉回到起始位置，在顶部挤压胸部肌肉。 重复所需的重复次数。"},{"id":"1437","name_zh":"哑铃指弯举","target":"前臂","media_id":"mtXengz","instructions_zh":"坐在长凳或椅子上，双脚平放在地上，背部挺直。 一只手握住哑铃，反手握住，将前臂放在大腿上，手掌朝上。 让哑铃向下滚动到指尖，然后弯曲手指将其卷起。 重复所需的重复次数，然后换另一只手。"},{"id":"0308","name_zh":"哑铃飞鸟","target":"胸","media_id":"yz9nUhF","instructions_zh":"平躺在长凳上，双手各握一个哑铃，手掌相对。 将手臂伸直越过胸部，肘部稍微弯曲。 保持肘部轻微弯曲，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。 暂停片刻，然后反转动作，将哑铃拉回到起始位置。 重复所需的重复次数。"},{"id":"1277","name_zh":"哑铃飞鸟（健身球）","target":"胸","media_id":"Lt3iWnf","instructions_zh":"坐在健身球上，每只手各握一个哑铃。 双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。 将双臂伸直至胸部上方，手掌相对。 稍微弯曲肘部，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。 暂停片刻，然后反向运动并挤压胸部肌肉，同时将​​哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1732","name_zh":"哑铃前弓步臂屈伸","target":"肱三头肌","media_id":"XalXcvM","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 右脚向前迈出一步，将身体降低至弓步位置。 保持背部挺直，挺胸。 将手臂伸直过头顶，保持肘部靠近耳朵。 弯曲肘部，将哑铃降低到脑后。 暂停片刻，然后伸直手臂回到起始位置。 重复该动作达到所需的重复次数，然后换腿并重复。"},{"id":"0310","name_zh":"哑铃前平举","target":"肩","media_id":"3eGE2JC","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。 保持双臂伸直，呼气并将哑铃举至身前，直至与肩齐平。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0309","name_zh":"哑铃前平举 v.2","target":"肩","media_id":"Rr7S3yg","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。 保持背部挺直并启动核心肌群。 慢慢举起你面前的哑铃，手臂伸直，直到与肩齐平。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0311","name_zh":"哑铃满罐侧平举","target":"肩","media_id":"AQ0mC4Y","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 保持背部挺直并启动核心肌群。 将手臂向两侧举起，肘部保持轻微弯曲，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"1760","name_zh":"哑铃高脚杯深蹲","target":"股四头肌","media_id":"yn8yg1r","instructions_zh":"双脚分开与肩同宽站立，双手握住哑铃垂直放在胸前。 保持胸部挺直，核心收紧，通过向后推臀部并弯曲膝盖，将身体降低至蹲姿。 继续降低，直到大腿与地面平行，或者尽可能低。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0313","name_zh":"哑铃锤式弯举","target":"肱二头肌","media_id":"slDvUAU","instructions_zh":"站直，双手各持一个哑铃，手掌朝向躯干。 保持肘部靠近躯干，并旋转手掌，直到手掌朝前。 这将是您的起始位置。 现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 然后，吸气并慢慢开始将哑铃放回起始位置。 重复建议的重复次数。"},{"id":"1659","name_zh":"哑铃锤式弯举（健身球）","target":"肱二头肌","media_id":"fY68AyX","instructions_zh":"坐在健身球上，双脚平放在地上，背部挺直。 每只手握住一个哑铃，手掌朝向身体，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0312","name_zh":"哑铃锤式弯举 v.2","target":"肱二头肌","media_id":"2NpxjC1","instructions_zh":"站直，双手各持一个哑铃，手掌朝向躯干。 保持肘部靠近躯干，并旋转手掌，直到手掌朝前。 这将是您的起始位置。 现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 然后，吸气并慢慢开始将哑铃放回起始位置。 重复建议的重复次数。"},{"id":"2402","name_zh":"哑铃锤式弯举（臂托板）","target":"肱二头肌","media_id":"GNhAeJ0","instructions_zh":"站直，双手各持一个哑铃，手掌朝向躯干。 保持肘部靠近躯干，并旋转手掌，直到手掌朝前。 这将是您的起始位置。 现在，保持上臂不动，呼气并卷曲哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 然后，吸气并慢慢开始将哑铃放回起始位置。 重复建议的重复次数。"},{"id":"1664","name_zh":"哑铃高位弯举","target":"肱二头肌","media_id":"qAmNMJY","instructions_zh":"站直，双手各持一个哑铃，手掌朝前。 保持上臂静止，将哑铃尽可能高地卷起，同时收缩二头肌。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"3545","name_zh":"哑铃上斜交替推举","target":"胸","media_id":"TVdivgY","instructions_zh":"坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。 向后靠在长凳上，用大腿帮助将哑铃举至肩高，手掌朝前。 到达肩膀高度后，旋转手腕，使手掌朝前。 用胸部和肩膀将哑铃向上推，充分伸展手臂。 将哑铃放回起始位置，保持肘部稍微弯曲。 重复所需的重复次数，交替手臂。"},{"id":"0314","name_zh":"哑铃上斜卧推","target":"胸","media_id":"ns0SIbU","instructions_zh":"设置一个 45 度角的上斜凳。 坐在长凳上，双脚平放在地上，背部紧贴长凳。 双手各握一个哑铃，掌心向前，将哑铃举至肩高。 慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。 将哑铃推回起始位置，充分伸展手臂。 重复所需的重复次数。"},{"id":"0315","name_zh":"哑铃上斜二头弯举","target":"肱二头肌","media_id":"F3xgbjF","instructions_zh":"坐在上斜凳上，双手各握一个哑铃，手掌朝前，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0316","name_zh":"哑铃上斜牧师凳弯举","target":"胸","media_id":"B3Rxp6L","instructions_zh":"设置一个 45 度角的上斜凳。 坐在长凳上，背部靠在垫子上，双脚平放在地面上。 双手各握一个哑铃，正手握握，手掌朝前。 首先，双臂完全伸展，垂直于地面。 慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。 在底部暂停片刻，然后将哑铃推回到起始位置。 重复所需的重复次数。"},{"id":"0318","name_zh":"哑铃上斜弯举","target":"肱二头肌","media_id":"ae9UoXQ","instructions_zh":"将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心向前。 将上臂放在上斜凳上，让肘部下垂，充分伸展手臂。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0317","name_zh":"哑铃上斜弯举 V2","target":"肱二头肌","media_id":"RaflbWD","instructions_zh":"坐在上斜凳上，双手各握一个哑铃，手掌朝前，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0319","name_zh":"哑铃上斜飞鸟","target":"胸","media_id":"ESOd5Pl","instructions_zh":"将上斜凳设置为 45 度角。 坐在长凳上，双手各握一个哑铃，手掌相对。 仰卧在长凳上，将哑铃推至起始位置，位于胸部正上方。 将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。 暂停片刻，然后挤压胸部肌肉，将哑铃拉回起始位置。 重复所需的重复次数。"},{"id":"1278","name_zh":"哑铃上斜健身球飞鸟","target":"胸","media_id":"HYe1ZqR","instructions_zh":"设置一个 45 度角的上斜凳。 坐在健身球上，向前滚动，直到上背部靠在倾斜的长凳上。 双手各握一个哑铃，手掌相对，双臂伸至胸部上方。 将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。 暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。 重复所需的重复次数。"},{"id":"0320","name_zh":"哑铃上斜锤式弯举","target":"肱二头肌","media_id":"ByX0WxV","instructions_zh":"坐在上斜凳上，每只手各握一个哑铃，手掌朝向躯干，手臂完全伸展。 背部靠在长凳上，双脚平放在地板上。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0321","name_zh":"哑铃上斜锤式推举","target":"胸","media_id":"PG1kcIb","instructions_zh":"将上斜凳设置成 45 度角，坐在上面，双手各握一个哑铃，放在大腿上。 仰卧在长凳上，将哑铃置于与肩同高的位置，手掌相对。 将哑铃向上推离身体，直到手臂完全伸展。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1618","name_zh":"哑铃上斜健身球锤式推举","target":"肱三头肌","media_id":"wkgnGfb","instructions_zh":"坐在健身球上，双手各握一个哑铃，手掌相对。 双脚向前走，身体沿着球滚动，直到头部、颈部和上背部得到球的支撑。 将哑铃保持在与肩同高的位置，肘部弯曲并指向两侧。 将哑铃向上并稍微向内推，保持手掌相对。 充分伸展双臂，在动作的最高点挤压三头肌。 慢慢地将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0322","name_zh":"哑铃上斜内侧二头弯举","target":"肱二头肌","media_id":"LCtQPn8","instructions_zh":"坐在上斜凳上，双手各握一个哑铃，手掌相对。 将上臂放在长凳上，让肘部下垂，手掌朝前。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1279","name_zh":"哑铃上斜单臂飞鸟","target":"胸","media_id":"Gw2HFvW","instructions_zh":"将倾斜凳调整至 30-45 度角。 坐在长凳上，一只手拿着哑铃，将其放在大腿上。 向后躺在长凳上，双脚平放在地面上。 握住哑铃，手臂伸直越过胸部。 将哑铃以宽弧线向一侧放低，保持肘部轻微弯曲。 当手臂与地面平行时暂停，然后反向运动，使哑铃回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1280","name_zh":"哑铃上斜单臂健身球飞鸟","target":"胸","media_id":"LLNh6q5","instructions_zh":"坐在健身球上，一只手拿着哑铃。 双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。 握住哑铃，手臂伸直越过胸部，手掌朝内。 慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。 当手臂与地面平行时暂停片刻。 启动胸部肌肉，将哑铃拉回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1619","name_zh":"哑铃上斜单臂锤式推举","target":"肱三头肌","media_id":"LL1UiTX","instructions_zh":"坐在上斜凳上，一只手拿着哑铃，放在大腿上。 向后靠在长凳上，用大腿帮助将哑铃举至肩膀高度。 旋转手腕，使手掌朝内，朝向身体。 将哑铃向上推离身体，完全伸展手臂。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1620","name_zh":"哑铃上斜单臂健身球锤式推举","target":"肱三头肌","media_id":"jDnrkar","instructions_zh":"坐在健身球上，一只手拿着哑铃。 双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。 握住哑铃，手掌朝内，肘部弯曲成 90 度角。 将哑铃向上推向天花板，伸直手臂。 将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0323","name_zh":"哑铃上斜单臂侧平举","target":"肩","media_id":"aTNKZiC","instructions_zh":"坐在上斜凳上，一只手拿着哑铃，将其放在大腿上。 身体前倾，将上臂靠在大腿内侧。 将哑铃举到一侧，保持手臂稍微弯曲，手掌朝下。 继续抬起，直到手臂与地板平行。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"1281","name_zh":"哑铃上斜单臂推举","target":"胸","media_id":"rDAiRf9","instructions_zh":"坐在上斜凳上，一只手拿着哑铃，放在大腿上。 仰卧在长凳上，将哑铃置于与肩同高的位置，手掌朝前。 将哑铃向上并稍微向内推，充分伸展手臂。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"1282","name_zh":"哑铃上斜单臂健身球推举","target":"胸","media_id":"Bg5JKSH","instructions_zh":"坐在健身球上，一只手拿着哑铃，双脚平放在地上。 慢慢地向前移动你的脚，滚动球，直到你的头、脖子和上背部得到球的支撑。 将哑铃握在与肩同高的位置，手掌朝前。 向上推哑铃，直到手臂完全伸展。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0324","name_zh":"哑铃上斜对握推举","target":"胸","media_id":"OVLmUuL","instructions_zh":"设置一个 45 度角的上斜凳。 坐在长凳上，双手各握一个哑铃，手掌相对。 将双脚牢牢踩在地面上，并保持背部挺直靠在长凳上。 从与肩同高的哑铃开始，肘部弯曲，手掌相对。 将哑铃向上推离身体，充分伸展手臂。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1283","name_zh":"哑铃上斜健身球推举","target":"胸","media_id":"bfiHMpI","instructions_zh":"坐在健身球上，每只手各握一个哑铃，手掌朝前。 双脚慢慢向前移动，身体沿着球滚动，直到头部、颈部和上背部得到球的支撑。 将哑铃保持在与肩同高的位置，肘部弯曲并指向两侧。 向上推哑铃，充分伸展手臂。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0325","name_zh":"哑铃上斜前平举","target":"肩","media_id":"nxW6BkN","instructions_zh":"坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。 向后靠在长凳上，将哑铃举至肩高，手掌朝前。 背部靠在长凳上，呼气并将哑铃举过头顶，充分伸展双臂。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回肩部高度。 重复所需的重复次数。"},{"id":"0326","name_zh":"哑铃上斜反向飞鸟","target":"肩","media_id":"vYk8lqw","instructions_zh":"设置一个 45 度角的上斜凳。 坐在长凳上，胸部靠在靠背上，双手各握一个哑铃。 双臂伸直向下，手掌相对。 保持肘部轻微弯曲，将手臂向两侧抬起，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0327","name_zh":"哑铃上斜划船","target":"上背部","media_id":"7vG5o25","instructions_zh":"设置一个 45 度角的上斜凳。 双手各握一个哑铃，坐在长凳上，胸部靠在斜坡上。 充分伸展双臂，让哑铃从肩膀上垂直垂下。 将哑铃拉向胸部，将肩胛骨挤压在一起。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0328","name_zh":"哑铃上斜肩部抬高","target":"前锯肌","media_id":"6e2DcYX","instructions_zh":"将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心朝下。 将哑铃放在大腿上，然后靠在长凳上。 用大腿帮助将哑铃举至肩膀高度，然后旋转手腕，使手掌朝前。 呼气，慢慢将哑铃举过头顶，保持肘部轻微弯曲。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回肩部高度。 重复所需的重复次数。"},{"id":"0329","name_zh":"哑铃上斜耸肩","target":"斜方肌","media_id":"JymLInS","instructions_zh":"将上斜凳设置为 45 度角，坐在上面，双手各握一个哑铃。 将双脚平放在地面上，让双臂笔直下垂，手掌朝向身体。 保持手臂伸直，耸肩，尽可能高地靠近耳朵。 保持收缩一会儿，然后慢慢将肩膀放回起始位置。 重复所需的重复次数。"},{"id":"3542","name_zh":"哑铃上斜T形飞鸟","target":"肩","media_id":"jgbvVJ0","instructions_zh":"将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心向内。 向前倾斜，让手臂笔直向下垂，垂直于地板。 保持手臂伸直，将它们向两侧举起，直到与地板平行，与身体形成“T”形。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0330","name_zh":"哑铃上斜臂屈伸","target":"肱三头肌","media_id":"OVIKwsd","instructions_zh":"坐在上斜凳上，双手各握一个哑铃，掌心向内。 将手臂完全伸过头顶，保持肘部靠近头部。 弯曲肘部，将哑铃降低到头后，保持上臂静止。 暂停片刻，然后伸展双臂将哑铃举回起始位置。 重复所需的重复次数。"},{"id":"0331","name_zh":"哑铃上斜旋转飞鸟","target":"胸","media_id":"1PLE8e9","instructions_zh":"将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心相对。 仰卧在长凳上，将哑铃推至起始位置，位于胸部正上方，双臂伸展。 将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。 放下哑铃时，旋转手腕，使手掌在动作底部朝前。 反转动作，将哑铃拉回起始位置，在顶部将胸部肌肉挤压在一起。 重复所需的重复次数。"},{"id":"1733","name_zh":"哑铃上斜双臂臂屈伸","target":"肱三头肌","media_id":"U7D9Fx3","instructions_zh":"坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。 慢慢地躺在长凳上，保持哑铃靠近胸部。 完全躺下后，将手臂伸向天花板，保持肘部稍微弯曲。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"3541","name_zh":"哑铃上斜Y形飞鸟","target":"上背部","media_id":"PbzNu7c","instructions_zh":"将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心向内。 稍微向前倾，让手臂伸直垂下，肘部保持轻微弯曲。 将手臂向两侧抬起并呈 Y 形，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0332","name_zh":"哑铃十字架","target":"肩","media_id":"cALkHHX","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。 将双臂向两侧举起，直至与地面平行，与身体形成T字形。 暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0333","name_zh":"哑铃俯身臂屈伸","target":"肱三头肌","media_id":"W6PxUkg","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将上臂靠近身体两侧，肘部弯曲成 90 度角。 将手臂向后伸直，在动作的最高点挤压三头肌。 暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1734","name_zh":"哑铃健身球臂屈伸","target":"肱三头肌","media_id":"cAvTaSg","instructions_zh":"坐在健身球上，双脚平放在地上，背部挺直。 双手各握一个哑铃，掌心向内，手臂弯曲成 90 度角。 将手臂向后伸直，在动作的最高点挤压三头肌。 暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1660","name_zh":"哑铃跪姿健身球二头弯举","target":"肱二头肌","media_id":"2JCuFTU","instructions_zh":"跪在地板上，面前放一个健身球。 将肘部放在健身球上，双手各握一个哑铃，手掌朝上。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0334","name_zh":"哑铃侧平举","target":"肩","media_id":"DsgkuIt","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 保持背部挺直并启动核心肌群。 将手臂向两侧抬起，直到与地板平行，保持肘部稍微弯曲。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0335","name_zh":"哑铃侧平举至前平举","target":"肩","media_id":"xMjBKwn","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 保持背部挺直并启动核心肌群。 将手臂向两侧举起，直到与地面平行，保持肘部稍微弯曲。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 接下来，将手臂举到身前，直到它们与地面平行，再次保持肘部稍微弯曲。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0336","name_zh":"哑铃箭步蹲","target":"臀部","media_id":"RRWFUcw","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 右脚向前迈出一步，将身体降低至弓步位置。 降低身体时保持背部挺直、挺胸。 推动右脚跟回到起始位置。 左腿重复上述动作。 交替腿进行所需的重复次数。"},{"id":"1658","name_zh":"哑铃箭步蹲二头弯举","target":"肱二头肌","media_id":"Mz6lLcW","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。 右脚向前迈出一步，将身体降低至弓步位置。你的右膝应该弯曲成 90 度角，左膝应该悬停在地面上方。 当你向前弓步时，同时将哑铃向肩膀弯曲，保持肘部靠近身体。 在弓步底部停顿片刻，然后通过右脚跟推动回到起始位置，将哑铃放回身体两侧。 在另一侧重复弓步和二头肌弯举，左脚向前迈出。 继续交替进行所需的重复次数。"},{"id":"0337","name_zh":"哑铃仰卧臂屈伸（过脸式）","target":"肱三头肌","media_id":"L2V5Nan","instructions_zh":"平躺在长凳上，双脚平放在地上，头放在长凳的末端。 双手握住哑铃，双臂伸直至胸部上方，手掌相对。 保持上臂静止，将哑铃在头后呈弧形缓慢降低，直到前臂与地面平行。 暂停片刻，然后收缩三头肌，将哑铃带回起始位置。 重复所需的重复次数。"},{"id":"1729","name_zh":"哑铃仰卧交替臂屈伸","target":"肱三头肌","media_id":"NfP83rA","instructions_zh":"平躺在长凳上，双手各握一个哑铃，手掌相对。 将手臂伸直越过胸部，保持肘部轻微弯曲。 将一个哑铃朝头部方向放下，肘部弯曲，同时保持另一只手臂伸展。 在底部停顿片刻，然后将哑铃举回到起始位置。 用另一只手臂重复上述动作，交替进行所需的重复次数。"},{"id":"0338","name_zh":"哑铃仰卧肘推","target":"肱三头肌","media_id":"eOCOwIR","instructions_zh":"平躺在长凳上，双手各握一个哑铃，手掌相对，双臂伸直越过胸部。 弯曲肘部，将哑铃向肩膀方向降低，保持上臂静止。 在底部暂停片刻，然后伸展肘部将哑铃推回到起始位置。 重复所需的重复次数。"},{"id":"0863","name_zh":"哑铃仰卧肩外旋","target":"肩","media_id":"bmBf7LN","instructions_zh":"侧躺在平坦的长凳上，上臂靠在身体两侧，肘部弯曲 90 度。 手中握住哑铃，手掌朝下。 保持上臂靠在身体两侧，尽可能缓慢地向上旋转前臂。 在顶部暂停片刻，然后慢慢将前臂放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"0339","name_zh":"哑铃仰卧腿弯举","target":"大腿后侧","media_id":"FkBIE6a","instructions_zh":"平躺，双腿伸直，将哑铃放在下腹部。 弯曲膝盖，将哑铃拉向臀部，保持双脚平放在地面上。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0340","name_zh":"哑铃仰卧锤式卧推","target":"胸","media_id":"7gdLIXa","instructions_zh":"平躺在长凳上，双手各握一个哑铃，手掌相对，双臂伸直向上。 将哑铃放低至胸部两侧，保持肘部呈 90 度角。 将哑铃推回到起始位置，充分伸展手臂。 重复所需的重复次数。"},{"id":"2470","name_zh":"哑铃俯卧地面后束飞鸟","target":"肩","media_id":"Ion0XWz","instructions_zh":"脸朝下躺在地板上，双手各握一个哑铃，手掌相对。 将手臂伸直在身前，保持肘部轻微弯曲。 调动肩部肌肉，将手臂向上并向两侧抬起，将肩胛骨挤压在一起。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0341","name_zh":"哑铃仰卧单臂后束飞鸟","target":"肩","media_id":"gSw59a4","instructions_zh":"脸朝下躺在平坦的长凳上，一只手握住哑铃，手掌朝内。 将手臂笔直向下伸向地板，保持靠近身体。 向上和向后举起手臂，将肩胛骨挤压向脊柱。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0343","name_zh":"哑铃仰卧单臂推举","target":"胸","media_id":"zGSIWQi","instructions_zh":"平躺在长凳上，一只手拿着哑铃，双脚平放在地上。 将哑铃举至肩部水平，手掌朝前。 向上推哑铃，直到手臂完全伸展。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0342","name_zh":"哑铃仰卧单臂推举v.2","target":"胸","media_id":"K3dIO25","instructions_zh":"平躺在长凳上，背部支撑，双脚平放在地面上。 一只手握住哑铃，手掌朝向脚部。 将手臂伸向天花板，保持肘部稍微弯曲。 慢慢地将哑铃向胸部方向降低，保持肘部靠近身体。 在底部暂停片刻，然后将哑铃推回到起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0344","name_zh":"哑铃仰卧单臂正握臂屈伸","target":"肱三头肌","media_id":"wyaqzOS","instructions_zh":"平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。 一只手握住哑铃，手掌朝下，将手臂伸直至肩膀上方。 保持上臂静止，弯曲肘部，慢慢将哑铃降低到脑后。 在底部停顿片刻，然后将手臂伸回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0345","name_zh":"哑铃仰卧单臂反向飞鸟","target":"肩","media_id":"KwFGiEP","instructions_zh":"脸朝下躺在平坦的长凳上，一只手拿着哑铃，垂向地板。 保持手臂伸直，将哑铃举到一侧，远离身体。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0346","name_zh":"哑铃仰卧单臂反握臂屈伸","target":"肱三头肌","media_id":"zZlORz6","instructions_zh":"平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。 一只手握住哑铃，反握，将手臂伸直至肩膀上方。 保持上臂静止，弯曲肘部，慢慢将哑铃降低到脑后。 在底部停顿片刻，然后将手臂伸回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0347","name_zh":"哑铃仰卧旋前","target":"前臂","media_id":"mym4hJo","instructions_zh":"平躺在长凳上，胸部朝下，双臂伸直向下，每只手各握一个哑铃。 旋转手掌，使手掌朝上。 保持上臂静止，呼气并弯曲哑铃，同时将手掌旋转至面朝下。 吸气并慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"2705","name_zh":"哑铃地面仰卧旋前","target":"前臂","media_id":"7RWNjiB","instructions_zh":"平躺在地板上，脸朝下，双臂伸直在身前，每只手各握一个哑铃。 旋转手掌，使其朝下朝向地板。 保持手臂伸直，收缩前臂将哑铃提离地板。 继续举起，直到前臂完全收缩并且哑铃与肩部齐平。 保持一会儿，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1284","name_zh":"哑铃健身球仰卧上拉","target":"胸","media_id":"iK59oEA","instructions_zh":"坐在健身球上，向前滚动，直到上背部靠在球上。 双手握住哑铃，将手臂伸直至胸部上方。 慢慢地将哑铃放到脑后，同时保持手臂伸直。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数。"},{"id":"1328","name_zh":"哑铃仰卧后束划船","target":"上背部","media_id":"XUUD0Fs","instructions_zh":"脸朝下躺在平坦的长凳上，每只手各握一个哑铃，手掌朝内。 将手臂伸直向下伸向地板，肘部保持轻微弯曲。 调动背部肌肉，将哑铃举向胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0348","name_zh":"哑铃仰卧反向飞鸟","target":"肩","media_id":"53Ttlck","instructions_zh":"脸朝下躺在平坦的长凳上，双手各握一个哑铃，手掌相对。 将手臂伸直向下伸向地板，肘部保持轻微弯曲。 调动肩部肌肉，将手臂向两侧抬起，直到与地板平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"1735","name_zh":"哑铃仰卧单臂臂屈伸","target":"肱三头肌","media_id":"6MfS53i","instructions_zh":"平躺在长凳上，一只手拿着哑铃，手臂完全伸展到胸部上方。 以受控的方式将哑铃降低到前额，保持上臂静止。 在动作底部短暂暂停，然后将手臂伸展回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0349","name_zh":"哑铃仰卧旋后","target":"前臂","media_id":"M2Pm3zj","instructions_zh":"平躺在长凳上，双脚平放在地上。 每只手握住一个哑铃，手掌朝上，双臂完全伸展。 保持上臂不动，收缩前臂，将哑铃向肩膀方向卷曲。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"2706","name_zh":"哑铃地面仰卧旋后","target":"前臂","media_id":"rEhi2o5","instructions_zh":"仰卧在地板上，双腿伸直，双臂放在身体两侧，每只手各握一个哑铃。 将手掌旋转至向上，保持肘部靠近身体两侧。 慢慢地将哑铃向肩膀弯曲，挤压前臂。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1661","name_zh":"哑铃仰卧二头弯举","target":"肱二头肌","media_id":"XVzF3iZ","instructions_zh":"平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。 每只手握住一个哑铃，手掌朝上，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0350","name_zh":"哑铃仰卧弯举","target":"肱二头肌","media_id":"KUaZst7","instructions_zh":"平躺在长凳上，双手各握一个哑铃，手掌朝上，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0351","name_zh":"哑铃仰卧臂屈伸","target":"肱三头肌","media_id":"mpKZGWz","instructions_zh":"平躺在长凳上，双手各握一个哑铃，手掌相对。 将手臂伸直越过胸部，保持肘部靠近身体。 将哑铃向前额方向降低，弯曲肘部。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"1662","name_zh":"哑铃仰卧宽距弯举","target":"肱二头肌","media_id":"qm9veZw","instructions_zh":"平躺在长凳上，双手各握一个哑铃，手掌朝上，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0352","name_zh":"哑铃对握卧推","target":"肱三头肌","media_id":"pP8wP2P","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 每只手握一个哑铃，中立握法（手掌相对），双臂伸直越过胸部。 慢慢地将哑铃降低到胸部，保持肘部靠近身体。 在底部停顿片刻，然后将哑铃推回起始位置，完全伸展手臂。 重复所需的重复次数。"},{"id":"1285","name_zh":"哑铃单臂平板飞鸟","target":"胸","media_id":"o5Jsk92","instructions_zh":"坐在平坦的长凳上，一只手拿着哑铃，将其放在大腿上方。 向后躺在长凳上，将哑铃压在大腿上。 用空着的那只手帮助将哑铃举至起始位置。 将哑铃握在肩膀正上方，手臂伸展，手掌朝内。 将哑铃以宽弧线向一侧放低，保持肘部轻微弯曲。 当手臂与地面平行时暂停，然后反向运动并将哑铃带回起始位置。 重复所需的重复次数，然后换臂重复。"},{"id":"0292","name_zh":"哑铃单臂俯身划船","target":"上背部","media_id":"C0MA9bC","instructions_zh":"双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。 稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。 让哑铃垂直垂向地板，手臂完全伸展。 将哑铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"1286","name_zh":"哑铃单臂健身球飞鸟","target":"胸","media_id":"Bpkf41o","instructions_zh":"坐在健身球上，一只手拿着哑铃，双脚平放在地上。 双脚向前走，滚动球，直到你的上背部受到球的支撑，并且你的头、脖子和肩膀离开球。 将手臂伸直，将哑铃举至胸部上方，手掌朝内。 慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。 当手臂与地面平行时暂停片刻。 启动胸部肌肉，将哑铃拉回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0353","name_zh":"哑铃单臂集中弯举（健身球上）","target":"肱二头肌","media_id":"k5IpyHg","instructions_zh":"坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。 一只手握住哑铃，手掌朝上，手臂向下伸向地板。 将肘部放在大腿内侧、膝盖上方。 保持上臂静止，呼气并将哑铃向上弯向肩膀，同时收缩二头肌。 在动作的最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂重复。"},{"id":"1287","name_zh":"哑铃单臂下斜卧推","target":"胸","media_id":"REGM1dE","instructions_zh":"躺在下斜长凳上，一只手握住哑铃，放在胸前。 将双脚平放在地面上，并将背部压在长凳上。 伸展手臂，将哑铃推向天花板，充分伸展肘部。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"1288","name_zh":"健身球单臂哑铃飞鸟","target":"胸","media_id":"Am02iPd","instructions_zh":"坐在健身球上，一只手拿着哑铃，双脚平放在地上。 双脚向前走，身体向下滚动，直到上背部靠在健身球上。 将手臂伸直，将哑铃举至胸部上方，手掌朝内。 慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。 暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1736","name_zh":"健身球单臂哑铃法式臂屈伸","target":"肱三头肌","media_id":"ziFKQXP","instructions_zh":"坐在健身球上，双脚平放在地上，背部挺直。 一只手握住哑铃，手掌朝上，肘部弯曲成 90 度角。 将手臂伸向天花板，保持肘部不动。 慢慢地将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1663","name_zh":"哑铃单臂锤式牧师凳弯举","target":"肱二头肌","media_id":"4dF3maG","instructions_zh":"坐在牧师凳上，一只手拿着哑铃，上臂放在垫子上。 以中立握法握住哑铃（手掌朝向身体）。 保持上臂静止，呼气并将哑铃向上弯向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1621","name_zh":"健身球单臂哑铃锤式推举","target":"肱三头肌","media_id":"VYmYxK5","instructions_zh":"坐在健身球上，双脚平放在地上，背部挺直。 一只手握住哑铃，掌心向内，肘部弯曲成 90 度角。 将另一只手放在臀部上以保持稳定。 向上推哑铃，充分伸展手臂。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1289","name_zh":"哑铃单臂上斜卧推","target":"胸","media_id":"PDaMuyV","instructions_zh":"将上斜凳调整至 45 度角。 坐在长凳上，背部靠在垫子上，双脚平放在地面上。 一只手握住哑铃，正手握住，将其放在肩膀上。 将哑铃向上推离身体，完全伸展手臂。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0354","name_zh":"哑铃单臂俯身臂屈伸","target":"肱三头肌","media_id":"bQy2Eni","instructions_zh":"双脚分开与肩同宽站立，右手握住哑铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将右肘举至身体一侧，保持弯曲 90 度角。 将右臂向后伸直，在动作的最高点挤压三头肌。 慢慢地将哑铃放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"0355","name_zh":"哑铃单臂侧平举","target":"肩","media_id":"n5cWCsI","instructions_zh":"双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。 在整个练习过程中保持背部挺直，核心肌群参与其中。 将哑铃举至一侧，保持手臂伸直，手掌朝下。 继续抬起，直到手臂与地面平行。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0356","name_zh":"有支撑哑铃单臂侧平举","target":"肩","media_id":"Yg7MJAT","instructions_zh":"双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。 将另一只手放在稳定的表面（例如长凳或墙壁）上以获得支撑。 保持背部挺直并启动核心肌群。 将哑铃向一侧举起，保持手臂伸直，手掌朝下。 继续抬起，直到手臂与地面平行。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"1290","name_zh":"健身球单臂哑铃肩推","target":"胸","media_id":"QZFv5ui","instructions_zh":"坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。 一只手握住哑铃，将其置于与肩同高的位置，肘部弯曲，手掌朝前。 慢慢向上推哑铃，直到手臂完全伸展，同时保持核心收紧并在健身球上保持平衡。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"1665","name_zh":"哑铃单臂俯身弯举","target":"肱二头肌","media_id":"JWjujiY","instructions_zh":"脸朝下躺在平坦的长凳上，一只手握住哑铃，掌心朝下。 完全伸展你的手臂，让它垂直垂向地板。 保持上臂静止，通过收缩二头肌将哑铃向上卷曲至肩膀。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1666","name_zh":"哑铃单臂俯身锤式弯举","target":"肱二头肌","media_id":"LIGZSTA","instructions_zh":"面朝下躺在平坦的长凳上，一只手拿着哑铃，手掌面向身体，手臂完全伸展。 保持上臂静止，将哑铃向肩膀弯曲，收缩二头肌。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1291","name_zh":"健身球单臂哑铃仰卧臂屈伸","target":"胸","media_id":"bQHPBU3","instructions_zh":"坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。 用一只手握住哑铃，将手臂伸直至胸部上方。 慢慢地将哑铃放到脑后，同时保持手臂伸直。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0358","name_zh":"哑铃单臂反握腕弯举","target":"前臂","media_id":"BwSNDGt","instructions_zh":"坐在长凳或椅子上，双脚平放在地面上。 一只手握住哑铃，正手握住，手掌朝下。 将前臂放在大腿上，手腕悬在边缘。 弯曲手腕，慢慢地将哑铃降低到地面。 在底部停顿片刻，然后慢慢地将手腕向上卷向身体。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0359","name_zh":"哑铃单臂反向飞鸟（有支撑）","target":"肩","media_id":"e25F58f","instructions_zh":"坐在长凳上，双脚平放在地上，背部挺直。 一只手握住哑铃，手掌朝内。 身体前倾，将空着的手放在长凳上以获得支撑。 保持手臂稍微弯曲并将其向侧面抬起，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1622","name_zh":"哑铃单臂反握推举","target":"胸","media_id":"Ze7MoIb","instructions_zh":"坐在平坦的长凳上，一只手拿着哑铃，手掌朝向身体。 将双脚平放在地面上，并保持背部挺直。 将哑铃举至肩膀高度，保持肘部靠近身体。 向上推哑铃，直到手臂完全伸展。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"1414","name_zh":"哑铃单臂反握牧师凳弯举","target":"肱二头肌","media_id":"bWxq4op","instructions_zh":"坐在牧师凳上，胸部靠在垫子上，手臂伸出长凳边缘，反握哑铃。 慢慢降低哑铃，直到手臂完全伸展。 将哑铃向后弯向肩膀，保持上臂静止。 在动作的最高点挤压二头肌，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1667","name_zh":"哑铃单臂反握蜘蛛弯举","target":"肱二头肌","media_id":"VdLZ3nB","instructions_zh":"站直，一只手握住哑铃，手掌朝下，手臂完全伸展。 保持上臂静止，弯曲肘部，将哑铃向肩膀方向卷曲。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1668","name_zh":"健身球坐姿单臂哑铃弯举","target":"肱二头肌","media_id":"s999Hdo","instructions_zh":"坐在健身球上，双脚平放在地上，背部挺直。 一只手握住哑铃，手掌朝上，手臂完全伸展。 保持上臂静止，通过收缩二头肌将哑铃向肩膀弯曲。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1669","name_zh":"哑铃单臂坐姿锤式弯举","target":"肱二头肌","media_id":"jK2hZ6n","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 一只手握住哑铃，保持中立握姿（手掌相对）。 将肘部放在大腿内侧、膝盖上方。 保持上臂静止，呼气并将哑铃向上弯向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1415","name_zh":"哑铃单臂坐姿中立腕弯举","target":"前臂","media_id":"YtaCTYl","instructions_zh":"坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝上。 将前臂放在大腿上，让手腕悬在边缘。 保持前臂静止，尽可能向上弯曲手腕。 在顶部暂停片刻，然后慢慢将手腕放回起始位置。 重复所需的重复次数，然后换另一只手。"},{"id":"0361","name_zh":"哑铃单臂肩推","target":"肩","media_id":"84RyJf8","instructions_zh":"双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。 向上推哑铃，直到手臂完全伸过头顶。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0360","name_zh":"哑铃单臂肩推 v. 2","target":"肩","media_id":"1TkiAFK","instructions_zh":"双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。 启动核心肌群，将哑铃垂直推过头顶，充分伸展手臂。 在顶部停顿片刻，然后慢慢将哑铃放回肩部水平。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"3888","name_zh":"哑铃单臂抓举","target":"臀部","media_id":"6pTkI99","instructions_zh":"双脚分开与肩同宽站立，一只手握住哑铃，正握。 稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。 将哑铃向地面放低，使其靠近身体。 爆发性伸展臀部、膝盖和脚踝，将哑铃沿直线向上推。 当哑铃到达肩膀高度时，快速旋转你的手并将其击打过头顶，充分伸展你的手臂。 将哑铃举过头顶，膝盖和臀部稍微弯曲。 以受控的方式将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"1670","name_zh":"哑铃单臂站姿弯举","target":"肱二头肌","media_id":"ffQsyBj","instructions_zh":"站直，一手握哑铃，手掌朝前，手臂完全伸展。 保持上臂静止，呼气并向上弯曲重量，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1671","name_zh":"哑铃单臂站姿锤式弯举","target":"肱二头肌","media_id":"2sQGZ5b","instructions_zh":"站直，双手各持一个哑铃，手掌朝向躯干。 保持肘部靠近躯干，上臂保持静止。 呼气并弯举哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0362","name_zh":"哑铃单臂颈后臂屈伸（凳上）","target":"肱三头肌","media_id":"nAuHPcD","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 一手握住哑铃，另一只手放在长凳上以获得支撑。 将哑铃举过头顶，保持上臂靠近头部，肘部向前。 弯曲肘部，将哑铃降低到头后，保持上臂静止。 将手臂向后伸展至起始位置，完全伸直肘部。 重复所需的重复次数，然后换臂。"},{"id":"0363","name_zh":"哑铃单臂直立划船","target":"肩","media_id":"6cKQC5E","instructions_zh":"双脚分开与肩同宽站立，一只手握住哑铃，正握。 让哑铃悬挂在大腿前面，与手臂保持一定距离，手掌朝向身体。 保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0364","name_zh":"哑铃单臂腕弯举","target":"前臂","media_id":"q8aHNoF","instructions_zh":"坐在长凳或椅子上，双脚平放在地面上。 一只手握住哑铃，反握，将前臂放在大腿上。 让你的手腕伸展，让哑铃向你的手指方向滚动。 慢慢地向后弯曲手腕，将哑铃拉向前臂。 重复所需的重复次数，然后换另一只手。"},{"id":"1672","name_zh":"哑铃单臂佐特曼牧师凳弯举","target":"肱二头肌","media_id":"sxY5Biu","instructions_zh":"坐在牧师弯举凳上，单手握哑铃，反握。 将上臂放在牧师凳垫上，让手臂完全伸展。 将哑铃向上弯向肩膀，保持上臂静止。 在卷曲的顶部，旋转手腕，使手掌朝上。 慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1292","name_zh":"健身球单腿哑铃飞鸟","target":"胸","media_id":"pH2x2jj","instructions_zh":"坐在健身球上，双手各握一个哑铃，手掌相对。 将一只脚放在地面上，并将另一条腿伸直到您面前。 稍微向前倾，将手臂向两侧伸出，保持肘部轻微弯曲。 慢慢地将哑铃向两侧放低，感觉胸部有拉伸感。 在底部暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。 重复所需的重复次数，然后换腿并重复。"},{"id":"0365","name_zh":"凳上哑铃中立腕弯举","target":"肱二头肌","media_id":"BKa8dmT","instructions_zh":"坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。 将前臂放在长凳上，让手腕悬在长凳边缘。 保持上臂静止，呼气并将哑铃向上弯向肩膀。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0366","name_zh":"凳上单臂哑铃中立腕弯举","target":"肱二头肌","media_id":"IvV6C9M","instructions_zh":"坐在长凳上，一只手拿着哑铃，手臂伸过长凳，手掌朝上。 保持上臂静止，将哑铃向肩膀弯曲，使手腕保持在中立位置。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1441","name_zh":"凳上单臂哑铃反握腕弯举","target":"前臂","media_id":"4Jc36XM","instructions_zh":"坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝下。 将前臂放在长凳上，手腕悬在长凳边缘。 慢慢向上弯曲手腕，将哑铃拉向前臂。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0367","name_zh":"哑铃搁凳单臂腕弯举","target":"前臂","media_id":"KI1DjNN","instructions_zh":"坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝下。 将前臂放在长凳上，手腕悬在长凳边缘。 慢慢向上弯曲手腕，将哑铃拉向前臂。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0368","name_zh":"哑铃搁凳反握腕弯举","target":"前臂","media_id":"3tAXPQ6","instructions_zh":"坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝下。 将前臂放在长凳上，让手腕悬在长凳边缘。 慢慢向上弯曲手腕，将哑铃拉向身体。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0369","name_zh":"哑铃搁凳腕弯举","target":"前臂","media_id":"D1xYJAU","instructions_zh":"坐在长凳上，前臂放在长凳上，手掌朝上，每只手各握一个哑铃。 让手腕悬在长凳边缘。 慢慢向上弯曲手腕，在动作的最高点挤压前臂。 暂停片刻，然后慢慢将手腕放回起始位置。 重复所需的重复次数。"},{"id":"1329","name_zh":"哑铃转腕俯身划船","target":"上背部","media_id":"wt6rwjk","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，正握。 臀部向前弯曲，保持背部挺直，膝盖稍微弯曲。 让你的手臂笔直下垂，手掌朝向身体。 收紧核心肌群，将哑铃拉向胸部，保持肘部靠近身体。 当你向上拉哑铃时，旋转手掌，使其背向身体。 在动作的最高点将肩胛骨挤压在一起。 慢慢地将哑铃放回起始位置，将手掌旋转回起始位置。 重复所需的重复次数。"},{"id":"1623","name_zh":"哑铃对握上斜卧推","target":"肱三头肌","media_id":"8eqjhOl","instructions_zh":"设置一个 45 度角的上斜凳。 坐在长凳上，背部靠在靠背上，双脚平放在地上。 双手各握一个哑铃，正手握握，手掌朝内。 将手臂伸直至胸部上方，保持肘部轻微弯曲。 将哑铃慢慢向肩膀方向降低，保持肘部靠近身体。 在底部暂停片刻，然后将哑铃推回到起始位置。 重复所需的重复次数。"},{"id":"0370","name_zh":"哑铃牧师凳锤式弯举","target":"肱二头肌","media_id":"F1KxjBa","instructions_zh":"站直，双手各持一个哑铃，手掌朝向躯干。 保持肘部靠近躯干，并旋转手掌，直到手掌朝前。 这将是您的起始位置。 现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 然后，吸气并慢慢开始将哑铃放回起始位置。 重复建议的重复次数。"},{"id":"0371","name_zh":"哑铃跳跃深蹲","target":"臀部","media_id":"S4pwGlc","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。 弯曲膝盖并将臀部向后推，将身体降低至蹲姿。 当你到达深蹲底部时，向上爆发，跳离地面。 在空中时，快速改变双脚的位置，落地时另一只脚向前。 立即将身体放回蹲姿，然后重复跳跃，再次换脚。 每次跳跃时继续交替双脚的位置，达到所需的重复次数。"},{"id":"0372","name_zh":"哑铃牧师凳弯举","target":"肱二头肌","media_id":"jivWf8n","instructions_zh":"坐在牧师弯举凳上，上臂放在垫子上，胸部靠在垫子上。 每只手握住一个哑铃，手掌朝上，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1673","name_zh":"哑铃健身球牧师凳弯举","target":"肱二头肌","media_id":"hwygydB","instructions_zh":"坐在健身球上，双脚平放在地上，背部挺直。 一只手握住哑铃，反握，将肘部放在健身球上。 保持上臂静止，呼气并将哑铃向上弯向肩膀。 在最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1293","name_zh":"哑铃健身球卧推","target":"胸","media_id":"O8o7q4d","instructions_zh":"坐在健身球上，双脚平放在地上，双手各握哑铃，放在大腿上。 慢慢地向前移动双脚，滚动健身球，直到下背部受到球的支撑并且膝盖呈 90 度角。 将哑铃举至肩高，手掌朝前。 向上推哑铃，直到手臂完全伸展。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0373","name_zh":"哑铃正握臂屈伸","target":"肱三头肌","media_id":"bpJL2Qs","instructions_zh":"坐在长凳或椅子上，背部挺直，双脚平放在地面上。 双手握住哑铃，掌心朝下，双臂伸直举过头顶。 保持上臂靠近头部，肘部向前，弯曲肘部，慢慢将哑铃降低到脑后。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"0374","name_zh":"哑铃俯卧上斜弯举","target":"肱二头肌","media_id":"mwpPcr1","instructions_zh":"将长凳调整至 45 度倾斜。 脸朝下躺在长凳上，胸部和腹部靠在长凳上。 每只手握住一个哑铃，手掌朝下，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1674","name_zh":"哑铃俯卧上斜锤式弯举","target":"肱二头肌","media_id":"cWemPG8","instructions_zh":"将长凳调整至 45 度倾斜。 脸朝下躺在长凳上，双手各握一个哑铃，手掌相对。 让你的手臂垂直垂向地板，保持肘部稍微弯曲。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0375","name_zh":"哑铃上拉","target":"胸","media_id":"9XjtHvS","instructions_zh":"平躺在长凳上，头放在一端，双脚放在地板上。 双手握住哑铃，将手臂伸直至胸部上方。 保持肘部轻微弯曲，慢慢地将哑铃放到脑后，直到感觉胸部和肩膀有拉伸感。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数。"},{"id":"1294","name_zh":"哑铃健身球上拉加髋伸展","target":"胸","media_id":"lI7easp","instructions_zh":"坐在健身球上，双脚平放在地面上，哑铃放在大腿上。 慢慢地向前移动你的脚，将健身球沿着你的背部滚动，直到你的头部、颈部和上背部得到球的支撑。 双手握住哑铃，将手臂伸直至胸部上方，肘部保持轻微弯曲。 将哑铃放在脑后，保持手臂伸直并保持控制。 暂停片刻，然后将哑铃举回到起始位置。 在保持双臂伸展的同时，将臀部抬离地面，挤压臀肌并启动核心肌群。 将臀部放低至起始位置。 重复所需的重复次数。"},{"id":"1295","name_zh":"哑铃健身球上拉","target":"胸","media_id":"FSD6PGL","instructions_zh":"坐在健身球上，双手握住哑铃，置于胸前，双臂伸展。 慢慢地将哑铃放到脑后，同时保持手臂伸直。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数。"},{"id":"1700","name_zh":"哑铃借力推举","target":"肩","media_id":"FS63wTN","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高。 稍微弯曲膝盖，身体下沉，然后爆发性伸展双腿，将哑铃压过头顶。 在动作的最高点锁定手臂，然后将哑铃放回肩部水平。 重复所需的重复次数。"},{"id":"0376","name_zh":"哑铃前平举","target":"肩","media_id":"c9MnDRp","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 保持背部挺直并启动核心肌群。 将手臂向两侧抬起，直到与地板平行，保持肘部稍微弯曲。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"2292","name_zh":"哑铃后束飞鸟","target":"肩","media_id":"mu5Guxt","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0377","name_zh":"哑铃后束划船","target":"肩","media_id":"EKXOMEh","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 每只手握住一个哑铃，手掌朝向身体。 腰部向前弯曲，保持背部挺直，核心肌群参与。 将手臂伸直向下伸向地板，肘部稍微弯曲。 将哑铃向两侧举起，将肩胛骨挤压在一起。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0378","name_zh":"哑铃反向飞鸟","target":"肩","media_id":"8DiFDVA","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将双臂笔直向下伸向地面，手掌相对。 保持肘部轻微弯曲，将手臂向两侧抬起，并将肩胛骨挤压在一起。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0380","name_zh":"哑铃后束侧平举","target":"肩","media_id":"v1qBec9","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心参与。 将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0379","name_zh":"哑铃后束侧平举（支撑头部）","target":"肩","media_id":"UzkLrem","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将手臂向两侧举起，肘部保持轻微弯曲，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0381","name_zh":"哑铃后弓步","target":"臀部","media_id":"SSsBDwB","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 右脚向后退一步，将身体降低至弓步位置。 弯曲左膝并降低身体，直到左大腿与地面平行。 暂停片刻，然后推动左脚跟回到起始位置。 在另一侧重复，左脚向后退一步。"},{"id":"0382","name_zh":"哑铃反握弯举","target":"肱二头肌","media_id":"e4ojVhP","instructions_zh":"站直，双手各握一个哑铃，手掌朝下，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1624","name_zh":"哑铃反握卧推","target":"胸","media_id":"UIbGx6H","instructions_zh":"平躺在长凳上，双脚平放在地上，膝盖弯曲。 双手各握一个哑铃，正手握住，手掌朝向脚部。 将手臂伸直向上伸向天花板，保持肘部轻微弯曲。 慢慢地将哑铃降低到胸部，让肘部向两侧张开。 在底部暂停片刻，然后将哑铃推回到起始位置。 重复所需的重复次数。"},{"id":"0383","name_zh":"哑铃反向飞鸟","target":"肩","media_id":"EAs3xL9","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将双臂伸直在身前，手掌相对。 保持肘部轻微弯曲，将手臂向两侧抬起，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"1330","name_zh":"哑铃反握上斜单臂划船","target":"上背部","media_id":"ZIViNh1","instructions_zh":"设置一个 45 度角的上斜凳。 将哑铃放在长凳旁边的地板上。 面对长凳站立，双脚分开与肩同宽。 弯曲腰部，将左膝和左手放在长凳上以获得支撑。 用右手反握（手掌朝下）拿起哑铃。 保持背部挺直，核心肌群参与。 将哑铃向上拉向胸部，保持肘部靠近身体。 在动作的最高点挤压背部肌肉。 以受控的方式将哑铃放回起始位置。 重复所需的重复次数。 换边并用左臂重复练习。"},{"id":"1331","name_zh":"哑铃反握上斜双臂划船","target":"上背部","media_id":"9pQSkH8","instructions_zh":"设置一个 45 度角的上斜凳。 坐在长凳上，胸部靠在靠背上，双脚平放在地上。 双手各握一个哑铃，反握。 身体前倾，双臂伸直下垂，完全伸展。 将哑铃拉向胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"2327","name_zh":"哑铃反握划船（女）","target":"上背部","media_id":"Nh3mvOO","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 双手各握一个哑铃，正手握握，手掌朝向身体。 腰部向前弯曲，保持背部挺直，核心肌群参与。 让你的手臂伸直垂下，完全伸展，肘部稍微弯曲。 将哑铃拉向胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0384","name_zh":"哑铃反握牧师凳弯举","target":"肱二头肌","media_id":"O8Aq69u","instructions_zh":"坐在牧师凳上，上臂放在垫子上，胸部靠在支撑物上。 每只手握住一个哑铃，反握，手掌朝上。 保持上臂静止，呼气并弯曲哑铃，同时收缩二头肌。 继续弯举哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1675","name_zh":"哑铃反握蜘蛛弯举","target":"肱二头肌","media_id":"6sMAmNv","instructions_zh":"站直，双手各握一个哑铃，手掌朝向身体，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0385","name_zh":"哑铃反握腕弯举","target":"前臂","media_id":"BLCvwr2","instructions_zh":"坐在长凳或椅子上，双脚平放在地面上。 双手各握一个哑铃，正手握握，手掌朝下。 将前臂放在大腿上，让手腕悬在边缘。 慢慢向上弯曲手腕，将哑铃拉向身体。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1459","name_zh":"哑铃罗马尼亚硬拉","target":"臀部","media_id":"rR0LJzx","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，正握。 保持背部挺直，核心收紧，以臀部为铰链，将哑铃向地面降低，让膝盖稍微弯曲。 降低哑铃，直到感觉到腿筋拉伸，然后推动脚后跟并收紧臀肌，回到起始位置。 重复所需的重复次数。"},{"id":"0386","name_zh":"哑铃旋转反向飞鸟","target":"肩","media_id":"prbWx1D","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，掌心向内。 稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。 将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。 旋转手臂，使手掌朝下。 慢慢地将手臂放回起始位置。 重复所需的重复次数。"},{"id":"2397","name_zh":"哑铃斯科特推举","target":"肩","media_id":"5vfAI0I","instructions_zh":"坐在长凳上，双手各握一个哑铃，手掌朝前。 将哑铃举至肩部高度，肘部弯曲，手掌朝前。 向上推哑铃，直到手臂完全伸展。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0387","name_zh":"哑铃坐姿交替前平举","target":"肩","media_id":"gH5fRsC","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 每只手握住一个哑铃，手掌朝向身体，手臂向下伸展到身体两侧。 保持双臂伸直，将一只哑铃举至身前，直至其与地面平行。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 用另一只手臂重复上述步骤。 双臂交替进行所需的重复次数。"},{"id":"1676","name_zh":"哑铃坐姿交替锤式弯举（在健身球上）","target":"肱二头肌","media_id":"QLRmNeT","instructions_zh":"坐在健身球上，双脚平放在地上，背部挺直。 每只手握住一个哑铃，手掌朝向身体，双臂完全伸展。 保持上臂静止，呼气并将一只哑铃向上弯向肩膀，同时保持手掌朝向身体。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢将哑铃放回起始位置。 用另一只手臂重复该动作。 继续交替手臂进行所需的重复次数。"},{"id":"0388","name_zh":"哑铃坐姿交替推举","target":"肩","media_id":"QT5Q0nK","instructions_zh":"坐在长凳上，双手各握一个哑铃，手掌朝前。 将哑铃举至肩部高度，肘部弯曲，手掌朝前。 将一只哑铃举过头顶，完全伸展手臂。 将哑铃放回至肩膀高度。 用另一只手臂重复上述步骤。 继续交替手臂进行所需的重复次数。"},{"id":"3546","name_zh":"哑铃坐姿交替肩部推举","target":"肩","media_id":"q7qkONO","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 双手各握一个哑铃，掌心向内，将哑铃举至肩高。 将一个哑铃举过头顶，同时将另一个哑铃保持在与肩同高的位置。 将举起的哑铃放回肩高，同时将另一个哑铃推过头顶。 继续交替手臂进行所需的重复次数。"},{"id":"0389","name_zh":"哑铃坐姿凳上臂屈伸","target":"肱三头肌","media_id":"JhYSVwT","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 双手握住哑铃，将手臂伸直至头顶上方。 慢慢地将哑铃放到脑后，保持肘部靠近耳朵。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数。"},{"id":"2317","name_zh":"哑铃坐姿屈臂侧平举","target":"肩","media_id":"JzQbv7J","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 双手各握一个哑铃，手掌朝向身体，手臂弯曲成 90 度角。 保持肘部弯曲，将手臂向两侧抬起，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"1730","name_zh":"哑铃坐姿俯身交替臂屈伸","target":"肱三头肌","media_id":"x0lwvfq","instructions_zh":"坐在长凳上，双手各握一个哑铃，手掌朝内。 腰部向前弯曲，保持背部挺直并与地面平行。 将一只手臂向后伸直，保持靠近身体，直到手臂完全伸展。 暂停片刻，然后慢慢将哑铃放回起始位置。 用另一只手臂重复上述步骤。 继续交替手臂进行所需的重复次数。"},{"id":"1737","name_zh":"哑铃坐姿俯身三头肌伸展","target":"肱三头肌","media_id":"4ievMJ9","instructions_zh":"坐在长凳上，双脚平放在地上，每只手各握一个哑铃。 腰部向前弯曲，保持背部挺直，头部抬起。 将手臂向后伸直，保持肘部靠近头部。 暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1677","name_zh":"哑铃坐姿弯举","target":"肱二头肌","media_id":"xiA6lRr","instructions_zh":"坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。 保持背部挺直，肘部靠近躯干。 呼气并将哑铃向上弯向肩膀，收缩二头肌。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0390","name_zh":"哑铃坐姿弯举（在健身球上）","target":"肱二头肌","media_id":"WgJnBH5","instructions_zh":"坐在稳定球上，双脚平放在地面上，背部挺直。 每只手握住一个哑铃，手掌朝前，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"3547","name_zh":"哑铃坐姿弯举转肩部推举","target":"肱二头肌","media_id":"OeL23VY","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 每只手握住一个哑铃，手掌朝前，双臂完全伸展。 保持肘部靠近身体两侧，将哑铃向上弯向肩膀。 前臂垂直后，旋转手腕，使手掌朝前。 将哑铃推过头顶，直到手臂完全伸展。 通过反向运动将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1379","name_zh":"哑铃坐姿提踵","target":"小腿","media_id":"r29jP7S","instructions_zh":"坐在长凳或椅子上，双脚平放在地面上，并将哑铃放在大腿上。 将脚掌放在升高的表面（例如台阶或木块）上，脚跟悬在边缘外。 握住哑铃以保持稳定。 尽可能高地抬高脚后跟，将身体重量转移到脚掌上。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0391","name_zh":"哑铃坐姿弯举","target":"肱二头肌","media_id":"TiaZTxx","instructions_zh":"坐在长凳上，双脚平放在地面上，每只手各握一个哑铃，手掌朝前。 保持背部挺直，肘部靠近躯干。 呼气并将哑铃向上弯向肩膀，收缩二头肌。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0392","name_zh":"哑铃坐姿前平举","target":"肩","media_id":"Ys97II0","instructions_zh":"坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。 保持背部挺直，核心参与。 将哑铃举到身前，手掌朝下，直到与肩同高。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1678","name_zh":"哑铃坐姿锤式弯举","target":"肱二头肌","media_id":"IGtBdNT","instructions_zh":"坐在长凳上，双手各握一个哑铃，手掌朝向躯干，手臂伸直向下。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0393","name_zh":"哑铃坐姿内侧弯举","target":"肱二头肌","media_id":"KXyoEtA","instructions_zh":"坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。 将上臂放在大腿上，让哑铃垂下。 保持上臂不动，通过收缩二头肌将哑铃向肩膀方向卷曲。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0394","name_zh":"哑铃坐姿臂屈伸","target":"肱三头肌","media_id":"en550rk","instructions_zh":"坐在长凳上，双脚平放在地上，每只手各握一个哑铃。 稍微弯曲膝盖，从臀部向前倾斜，保持背部挺直。 将上臂靠近身体两侧，并保持肘部弯曲成 90 度角。 将手臂向后伸直，在动作的最高点挤压三头肌。 暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0396","name_zh":"哑铃坐姿侧平举","target":"肩","media_id":"hxyTtWj","instructions_zh":"坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。 保持背部挺直，核心参与。 将哑铃举至身体两侧，肘部稍微弯曲，直到手臂与地面平行。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0395","name_zh":"哑铃坐姿侧平举（v2）","target":"肩","media_id":"hrrS0Ed","instructions_zh":"坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。 保持背部挺直，核心参与。 将哑铃举至身体两侧，肘部稍微弯曲，直到手臂与地面平行。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0397","name_zh":"哑铃坐姿中立腕弯举","target":"肱二头肌","media_id":"uJmK7Z1","instructions_zh":"坐在长凳上，双脚平放在地上，双手各握一个哑铃，手掌相对。 将前臂放在大腿上，让哑铃垂下。 保持手腕处于中立位置，将哑铃向上弯向肩膀。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1679","name_zh":"哑铃坐姿单臂弯举（健身球上抬腿）","target":"肱二头肌","media_id":"84sESNy","instructions_zh":"坐在健身球上，双脚平放在地上，背部挺直。 一只手握住哑铃，手掌朝上，手臂完全伸展。 将另一只手放在臀部上以保持稳定。 慢慢地将哑铃向肩膀弯曲，保持上臂静止。 在动作的最高点暂停片刻，挤压你的二头肌。 慢慢地将哑铃放回起始位置。 重复所需的重复次数。 交换手臂并重复练习。"},{"id":"0398","name_zh":"哑铃坐姿单臂臂屈伸","target":"肱三头肌","media_id":"VQ3sNCn","instructions_zh":"坐在长凳上，双脚平放在地上，一手握住哑铃。 将躯干的腰部向前弯曲，保持背部挺直并与地面平行。 将手臂向后伸直，保持肘部靠近身体。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0399","name_zh":"哑铃坐姿单臂旋转","target":"前臂","media_id":"7f2jsqP","instructions_zh":"坐在长凳上，背部挺直，一只手握住哑铃，将其放在大腿上。 将哑铃举至肩膀高度，保持肘部靠近身体。 向外旋转前臂，远离身体，同时保持上臂静止。 在顶部停顿片刻，然后慢慢旋转前臂回到起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0400","name_zh":"哑铃坐姿单腿提踵","target":"小腿","media_id":"Ia7tumC","instructions_zh":"坐在长凳或椅子上，双脚平放在地面上，将哑铃放在右大腿上。 将左腿伸直到身前，保持脚部弯曲。 将右脚掌放在升高的表面上，例如台阶或配重板。 使用小腿肌肉，尽可能高地抬高右脚跟。 在顶部暂停片刻，然后慢慢将脚跟放回起始位置。 重复所需的重复次数，然后换腿。"},{"id":"1380","name_zh":"哑铃坐姿单腿提踵-锤式握法","target":"小腿","media_id":"FxhcxUW","instructions_zh":"坐在长凳或椅子上，双脚平放在地面上，并将哑铃放在大腿上。 将一只脚放在凸起的表面上，例如台阶或木块，脚跟悬在边缘之外。 用锤式握法握住哑铃，这意味着您的手掌相对，手指缠绕在手柄上。 保持核心收紧，背部挺直，通过脚掌推动，将脚后跟慢慢抬高，尽可能高。 在顶部暂停片刻，然后慢慢将脚跟放回起始位置。 重复所需的重复次数，然后换另一条腿。"},{"id":"1381","name_zh":"哑铃坐姿单腿提踵-掌心向上","target":"小腿","media_id":"VW88JNd","instructions_zh":"坐在长凳或椅子上，背部挺直，双脚平放在地面上。 一只手握住哑铃，将其放在大腿上方，掌心朝上。 将一条腿抬离地面并将其延伸到您面前，保持膝盖稍微弯曲。 通过脚掌推动，尽可能高地抬起脚后跟。 在顶部停顿片刻，然后慢慢降低脚跟。 重复所需的重复次数，然后换腿并重复。"},{"id":"0401","name_zh":"哑铃坐姿掌心向上腕弯举","target":"前臂","media_id":"2dImyQ8","instructions_zh":"坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。 将前臂放在大腿上，让手腕悬在边缘。 慢慢向上弯曲手腕，在动作的最高点挤压前臂。 暂停片刻，然后将手腕放回起始位置。 重复所需的重复次数。"},{"id":"0402","name_zh":"哑铃坐姿牧师凳弯举","target":"肱二头肌","media_id":"7D5bgLT","instructions_zh":"坐在牧师弯举凳上，双脚平放在地板上。 一只手握住哑铃，反手握住，将上臂靠在讲道垫上。 保持上臂静止，呼气并将哑铃向上弯向肩膀。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0403","name_zh":"哑铃坐姿反握集中弯举","target":"肱二头肌","media_id":"lyKCLmK","instructions_zh":"坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝上。 将肘部放在大腿内侧、膝盖上方。 保持上臂静止，呼气并将哑铃向肩膀弯曲。 在顶部暂停片刻，挤压你的二头肌。 吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1738","name_zh":"哑铃坐姿反握单臂过头三头肌伸展","target":"肱三头肌","media_id":"5fKX7wi","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 反手握住哑铃，将手臂伸直至头顶。 弯曲肘部，将哑铃降低到头后，保持上臂静止。 暂停片刻，然后将手臂伸回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0405","name_zh":"哑铃坐姿肩部推举","target":"肩","media_id":"znQUdHY","instructions_zh":"坐在长凳上，每只手各拿一个哑铃，放在大腿上。 将哑铃举至肩高，手掌朝前。 向上推哑铃，直到手臂完全伸过头顶。 在顶部停顿片刻，然后慢慢将哑铃放回肩部高度。 重复所需的重复次数。"},{"id":"0404","name_zh":"哑铃坐姿肩部推举（对握）","target":"肩","media_id":"f1jf47L","instructions_zh":"坐在长凳上，双手各握一个哑铃，掌心向内。 将哑铃举至肩高，肘部弯曲，手掌朝前。 向上推哑铃，直到手臂完全伸过头顶。 在顶部停顿片刻，然后慢慢将哑铃放回肩部高度。 重复所需的重复次数。"},{"id":"2188","name_zh":"哑铃坐姿三头肌伸展","target":"肱三头肌","media_id":"kont8Ut","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 双手握住哑铃，双臂伸直举过头顶。 弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。 暂停片刻，然后伸直手臂，回到起始位置。 重复所需的重复次数。"},{"id":"0406","name_zh":"哑铃耸肩","target":"斜方肌","media_id":"NJzBsGJ","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 保持手臂伸直，让哑铃垂在身体两侧。 尽可能高地抬高肩膀，就像试图用肩膀触碰耳朵一样。 保持收缩一秒钟，然后慢慢将肩膀放回起始位置。 重复所需的重复次数。"},{"id":"0407","name_zh":"哑铃体侧屈","target":"腹部","media_id":"IpONWYv","instructions_zh":"站直，双脚分开与肩同宽，一手握住哑铃，让它垂在身侧。 保持背部挺直，核心肌群参与，慢慢地将腰部向哑铃的另一侧侧弯，在舒适的范围内尽可能降低重量。 暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数，然后换边重复。"},{"id":"0408","name_zh":"侧卧哑铃单臂侧平举","target":"肩","media_id":"fTlkJop","instructions_zh":"侧躺，双腿伸直，用手臂支撑头部。 用你的上手握住哑铃，手掌朝下。 保持手臂伸直，将哑铃举至肩膀高度。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"3664","name_zh":"哑铃侧平板后飞鸟","target":"上背部","media_id":"X6ytgYZ","instructions_zh":"首先侧躺，双腿伸展并叠放在一起。 将前臂放在肩膀正下方的地面上，保持肘部弯曲成 90 度角。 用你的上手握住哑铃，手臂垂直向下伸向地面。 收紧核心并将臀部抬离地面，从头部到脚后跟形成一条直线。 在保持侧平板支撑位置的同时，将哑铃向天花板方向举起，将肩胛骨挤压在一起。 将哑铃放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"3548","name_zh":"哑铃单臂过头行走","target":"肩","media_id":"mWBtgmb","instructions_zh":"站直，双脚分开与肩同宽，一手握住哑铃。 将哑铃举过头顶，充分伸展手臂。 向前行走时，启动核心肌群并保持背部挺直，将哑铃举过头顶。 继续步行所需的距离或时间。 交换双手并重复练习。"},{"id":"0409","name_zh":"哑铃单腿提踵","target":"小腿","media_id":"1kB3Wmk","instructions_zh":"站在台阶或平台的边缘，脚后跟悬垂，脚趾放在台阶上。 一手握住哑铃，另一只手放在墙壁或栏杆上以获得支撑。 尽可能高地抬高脚跟，将身体抬起到脚趾上。 在顶部停顿片刻，然后慢慢将脚跟放回到台阶下方。 重复所需的重复次数，然后换另一条腿。"},{"id":"1757","name_zh":"哑铃单腿硬拉","target":"臀部","media_id":"gKozT8X","instructions_zh":"双脚分开与臀部同宽站立，右手握住哑铃。 将体重转移到左腿上，并将右脚稍微抬离地面。 保持背部挺直，臀部向前转动，将哑铃放低至地面。 同时，将右腿伸直在身后，保持左膝轻微弯曲。 降低哑铃，直到躯干和右腿与地面平行。 暂停片刻，然后收紧臀肌和腿筋，回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"2805","name_zh":"哑铃单腿硬拉（踏板支撑）","target":"臀部","media_id":"daBmy1Y","instructions_zh":"双脚分开与臀部同宽站立，右手握住哑铃。 将左脚放在身后的台阶或高架表面上。 保持背部挺直，核心收紧，髋部向前转动，将哑铃放低至地面。 当你放下哑铃时，同时将左腿抬起到身后，从头到脚跟保持一条直线。 降低哑铃，直到感觉到右腿筋拉伸，然后回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0410","name_zh":"哑铃单腿分腿蹲","target":"股四头肌","media_id":"qx4fgX7","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 一只脚向前迈出一步，调整双脚的位置，使前脚平放在地面上，后脚抬高在长凳或台阶上。 弯曲前膝盖和臀部，降低身体，保持后膝盖稍微弯曲，后脚跟离开地面。 继续降低，直到大腿前部与地面平行，然后通过前脚跟推回到起始位置。 重复所需的重复次数，然后换腿并重复。"},{"id":"0411","name_zh":"哑铃单腿蹲","target":"臀部","media_id":"H6ybluc","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 向前伸展一条腿，并在整个练习过程中保持其离开地面。 弯曲站立的腿并降低身体，就像坐回椅子上一样。 保持挺胸、背部挺直。 在底部停顿片刻，然后用脚跟推动回到起始位置。 重复所需的重复次数，然后换腿。"},{"id":"0413","name_zh":"哑铃深蹲","target":"臀部","media_id":"HsvHqgf","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。 保持胸部挺直，核心收紧，弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。 继续降低，直到大腿与地面平行，或者尽可能低。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"3560","name_zh":"站姿交替哑铃锤式弯举推举","target":"肱二头肌","media_id":"LeaZOIz","instructions_zh":"站直，双手各持一个哑铃，手掌朝向身体。 保持肘部靠近躯干，背部挺直。 呼气，将右手的哑铃向肩膀弯曲，保持上臂静止。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 吸气，慢慢将哑铃放回起始位置。 用左手重复卷发动作。 左手完成弯举后，呼气，将右手的哑铃压过头顶。 完全伸展手臂并在顶部保持片刻。 吸气，慢慢将哑铃放回起始位置。 用左手重复按压。 继续交替进行弯举和推举，达到所需的重复次数。"},{"id":"0414","name_zh":"站姿交替哑铃推举","target":"肩","media_id":"bBi35y3","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝前。 将一只哑铃举过头顶，完全伸展手臂。 将哑铃放低至肩部水平。 用另一只手臂重复上述步骤。 继续交替手臂进行所需的重复次数。"},{"id":"0415","name_zh":"站姿交替哑铃前平举","target":"肩","media_id":"SxHteRW","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 保持背部挺直，核心肌群参与。 将一个哑铃举到一侧，保持手臂伸直，手掌朝下。 继续抬起，直到手臂与地面平行。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 用另一只手臂重复上述步骤。 双臂交替进行所需的重复次数。"},{"id":"1739","name_zh":"站姿交替哑铃俯身臂屈伸","target":"肱三头肌","media_id":"Gi2BXfK","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 双臂向后伸直，保持肘部靠近身体。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 用另一只手臂重复上述动作，每次重复时交替进行。"},{"id":"2143","name_zh":"站姿哑铃绕肩","target":"肩","media_id":"RSOsp5d","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 将手臂伸直至两侧，与肩同高，手掌朝下。 保持手臂伸直，慢慢地以圆周运动旋转手臂，将哑铃放在身体前面，然后举过头顶。 继续圆周运动，将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1740","name_zh":"站姿俯身单臂哑铃臂屈伸","target":"肱三头肌","media_id":"CJwa0vD","instructions_zh":"双脚分开与肩同宽站立，一只手握住哑铃。 腰部向前弯曲，保持背部挺直并与地面平行。 将手臂向后伸直，保持肘部靠近身体。 慢慢地将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1741","name_zh":"站姿俯身双臂哑铃臂屈伸","target":"肱三头肌","media_id":"3T12T87","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。 双臂向后伸直，保持肘部靠近身体。 慢慢地将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0416","name_zh":"站姿哑铃弯举","target":"肱二头肌","media_id":"3s4NnTh","instructions_zh":"站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0417","name_zh":"站姿哑铃提踵","target":"小腿","media_id":"dPmaUaU","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 用小腿将脚跟抬离地面，尽可能高。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0418","name_zh":"站姿哑铃集中弯举","target":"肱二头肌","media_id":"7inpWch","instructions_zh":"双脚分开与肩同宽站立，一手握住哑铃，手臂完全伸展，手掌朝内。 将另一只手放在大腿上以获得支撑。 保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0419","name_zh":"站姿哑铃前平举过头","target":"肩","media_id":"laVRfDf","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，正握。 保持双臂伸直，将哑铃举至身前，举过头顶。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"2321","name_zh":"站姿哑铃内弯举（v.2）","target":"肱二头肌","media_id":"vKilzz3","instructions_zh":"站直，双手各持一个哑铃，手掌朝向躯干。 保持肘部靠近躯干，并旋转手掌，直到手掌朝前。 保持上臂不动，弯曲哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气时慢慢开始将哑铃放回起始位置。 重复建议的重复次数。"},{"id":"0420","name_zh":"站姿哑铃俯身臂屈伸","target":"肱三头肌","media_id":"UmpPAAe","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将手臂向后伸直，在动作的最高点挤压三头肌。 暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0421","name_zh":"站姿单臂哑铃集中弯举","target":"肱二头肌","media_id":"8fgqP5a","instructions_zh":"站直，双脚分开与肩同宽，一手握住哑铃，掌心朝上。 将空着的手放在大腿上以获得支撑。 保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0422","name_zh":"站姿单臂哑铃弯举（靠上斜凳）","target":"肱二头肌","media_id":"BIb1tGo","instructions_zh":"双脚分开与肩同宽站立，一手握住哑铃，手掌朝前。 将另一只手放在倾斜的长凳上以获得支撑。 保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。 在最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1680","name_zh":"站姿单臂哑铃弯举（靠上斜凳）","target":"肱二头肌","media_id":"EmlJR2y","instructions_zh":"双脚分开与肩同宽站立，一只手握住哑铃。 将另一只手放在倾斜的长凳上以获得支撑。 保持上臂静止，通过收缩二头肌将哑铃向肩膀弯曲。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"0423","name_zh":"站姿单臂哑铃臂屈伸","target":"肱三头肌","media_id":"BCUR88E","instructions_zh":"双脚分开与肩同宽站立，一只手握住哑铃。 将哑铃举过头顶，充分伸展手臂。 保持上臂靠近头部并垂直于地面。 慢慢地将哑铃放到脑后，弯曲肘部。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数。"},{"id":"0424","name_zh":"站姿单臂哑铃对握推举","target":"肩","media_id":"ocYc6Db","instructions_zh":"双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝内。 启动你的核心并保持背部挺直。 向上推哑铃，直到手臂完全伸展。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0425","name_zh":"站姿单臂哑铃反握弯举","target":"肱二头肌","media_id":"DU5Kkj2","instructions_zh":"站直，双脚分开与肩同宽，一只手握住哑铃，正握。 保持手臂完全伸展并靠近身体，手掌朝下。 慢慢地将哑铃向上弯向肩膀，保持上臂静止。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0426","name_zh":"站姿哑铃推举","target":"肩","media_id":"A6wtbuL","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝前。 向上推哑铃，直到手臂完全伸过头顶。 在顶部停顿片刻，然后慢慢将哑铃放回至肩部水平。 重复所需的重复次数。"},{"id":"0427","name_zh":"站姿哑铃对握推举","target":"肩","media_id":"UilDHSs","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝内。 保持核心收紧，背部挺直，向上推哑铃，直到手臂完全伸过头顶。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0428","name_zh":"站姿哑铃牧师凳弯举","target":"肱二头肌","media_id":"hq2hyDH","instructions_zh":"站直，双脚分开与肩同宽，每只手各握一个哑铃，手掌朝前。 将上臂后部靠在牧师凳或上斜凳上，肘部稍微弯曲。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0429","name_zh":"站姿哑铃反握弯举","target":"肱二头肌","media_id":"0IgNjSM","instructions_zh":"站直，双脚分开与肩同宽，双手各握一个哑铃，手掌朝向身体。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0430","name_zh":"站姿哑铃臂屈伸","target":"肱三头肌","media_id":"PdmaD0N","instructions_zh":"双脚分开与肩同宽站立，一只手握住哑铃。 将哑铃举过头顶，保持手臂伸直。 弯曲肘部，将哑铃放到脑后，保持上臂静止。 将手臂向后伸展至起始位置。 重复所需的重复次数。"},{"id":"2293","name_zh":"站姿佐特曼牧师凳弯举","target":"肱二头肌","media_id":"P2nRiUa","instructions_zh":"站直，双手各持一个哑铃，手掌朝前。 将上臂靠在牧师凳上，并保持肘部稍微弯曲。 将哑铃向上弯向肩膀，同时保持上臂静止。 在动作的最高点，旋转手腕，使手掌朝下。 慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。 重复所需的重复次数。"},{"id":"1684","name_zh":"哑铃单腿平衡上步二头弯举","target":"肱二头肌","media_id":"76vfTdU","instructions_zh":"站在台阶或平台前，每只手各握一个哑铃，手掌朝向身体。 将右脚放在台阶上，确保整个脚与表面接触。 启动核心并推动右脚跟，将身体抬起到台阶上，将左膝抬向胸部。 在动作的最高点，弯曲肘部并将哑铃拉向肩膀，进行二头肌弯举。 将哑铃放回原处，同时将左脚放回地面。 在另一侧重复该动作，左脚向上并弯举哑铃。 继续交替进行所需的重复次数。"},{"id":"0431","name_zh":"哑铃上步","target":"臀部","media_id":"aXtJhlg","instructions_zh":"站在长凳或台阶前，每只手各握一个哑铃，手掌朝向身体。 将右脚放在长凳或台阶上，确保整个脚与表面接触。 推动右脚跟，将身体抬起到长凳或台阶上，伸直右腿。 将左脚放在长凳或台阶上，完全直立。 左脚向后退一步，然后是右脚，回到起始位置。 重复所需的重复次数，然后换腿。"},{"id":"2796","name_zh":"哑铃上步箭步蹲","target":"股四头肌","media_id":"gFyFj9z","instructions_zh":"站在台阶或平台前，每只手各持一个哑铃，手掌朝向身体两侧。 将右脚放在台阶上，确保整个脚都踩在台阶上。 推动右脚跟，将身体抬起到台阶上，同时将左脚抬起。 双脚踩在台阶上后，将左脚放回起始位置，并将右脚保持在台阶上。 重复该动作，每次交替使用哪只脚。 继续进行所需的重复次数。"},{"id":"2812","name_zh":"哑铃上步分腿蹲","target":"股四头肌","media_id":"QjE2DcA","instructions_zh":"站在长凳或台阶前，每只手各握一个哑铃，手掌朝向身体。 将右脚放在长凳或台阶上，确保整个脚与表面接触。 走到长凳上或用右脚踩上，用脚跟推动身体抬起。 当你向上迈步时，同时将左膝抬向胸部。 在动作的最高点暂停，然后慢慢将左脚放回地面，同时将右脚放在长凳或台阶上。 将左脚放在长凳或台阶上，重复该动作。 继续交替左右脚，达到所需的重复次数。"},{"id":"0432","name_zh":"哑铃直腿硬拉","target":"臀部","media_id":"5eLRITT","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，正握。 保持背部挺直，核心收紧，铰接臀部并将哑铃向地面降低，让膝盖稍微弯曲。 降低哑铃，直到感觉到腿筋拉伸，然后挤压臀肌并通过脚后跟推回到起始位置。 重复所需的重复次数。"},{"id":"0433","name_zh":"哑铃直臂上拉","target":"胸","media_id":"i8BdLTK","instructions_zh":"平躺在长凳上，头朝一端，双脚牢牢踩在地上。 双手握住哑铃，将手臂伸直至胸部上方。 保持手臂伸直，以弧线动作慢慢将哑铃降低到脑后。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数。"},{"id":"0434","name_zh":"哑铃直腿硬拉","target":"臀部","media_id":"oom75KC","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，正握。 保持背部挺直，核心收紧，以臀部为铰链，将哑铃向地面降低，让躯干向前倾斜。 继续降低哑铃，直到感觉到腿筋拉伸，保持膝盖稍微弯曲。 在底部暂停片刻，然后启动臀肌和腿筋，将躯干抬回到起始位置。 重复所需的重复次数。"},{"id":"2808","name_zh":"哑铃相扑拉","target":"臀部","media_id":"BmrwWzo","instructions_zh":"站立，双脚分开比肩宽，脚趾朝外。 双手握住哑铃置于身体前方，双臂伸展。 弯曲膝盖，将臀部放低至下蹲位置，保持背部挺直。 将哑铃放在两腿之间，保持手臂伸直。 通过脚后跟发力，向前伸展臀部，将哑铃向上拉至身体前方。 在动作的最高点挤压臀部，然后将哑铃放回双腿之间。 重复所需的重复次数。"},{"id":"2803","name_zh":"哑铃支撑深蹲","target":"股四头肌","media_id":"r5DgrW9","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。 保持挺胸，核心收紧，弯曲膝盖并向后推臀部，慢慢降低身体。 继续降低，直到大腿与地面平行，或者尽可能低。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0436","name_zh":"哑铃泰特推举","target":"肱三头肌","media_id":"s5PdDyY","instructions_zh":"坐在平坦的长凳上，双手各握一个哑铃，手掌相对。 将哑铃举至肩膀高度，然后旋转手腕，使手掌背向自己。 向上推哑铃，直到手臂完全伸展，然后将其放回至肩膀高度。 将手腕旋转回起始位置，然后重复所需的重复次数。"},{"id":"1742","name_zh":"哑铃鹳式站姿三头肌后摆","target":"肱三头肌","media_id":"wOLmCXc","instructions_zh":"双脚分开与肩同宽站立，右手握住哑铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将右肘举至身体一侧，保持弯曲 90 度角。 将右臂向后伸直，挤压三头肌。 暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"1743","name_zh":"哑铃转体卧推","target":"肱三头肌","media_id":"z6TAHoT","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 双手各握一个哑铃，正手握握，手掌背向自己。 将手臂伸直越过胸部，保持肘部轻微弯曲。 将哑铃向胸部方向降低，保持肘部靠近身体。 放下哑铃时，扭转手腕，使手掌在动作底部面向自己。 在底部暂停片刻，然后通过将哑铃推回到起始位置来反转动作。 当你向上推哑铃时，将手腕扭转回起始位置，手掌背向自己。 重复所需的重复次数。"},{"id":"0437","name_zh":"哑铃直立划船","target":"肩","media_id":"ainizkb","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，正握。 让哑铃悬挂在大腿前面，双臂完全伸展。 保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"1765","name_zh":"哑铃直立划船（背面视角）","target":"肩","media_id":"Iptlv6x","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，正握。 让哑铃悬挂在大腿前面，双臂完全伸展，手掌面向身体。 保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。 继续举起哑铃，直到哑铃与肩同高，肘部指向两侧。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0864","name_zh":"哑铃直立肩外旋","target":"肩","media_id":"x306lCW","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 将手臂向两侧抬起，直到与地面平行，保持肘部稍微弯曲。 向外旋转手臂，将哑铃举向头部，同时保持肘部处于同一位置。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"5201","name_zh":"哑铃服务员二头弯举","target":"肱二头肌","media_id":"KOpzGBL","instructions_zh":"站直，双手各持一个哑铃，手掌朝前。 保持上臂靠近身体，肘部内收。 慢慢地将哑铃向上弯向肩膀，保持手腕伸直。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0438","name_zh":"哑铃W推举","target":"肩","media_id":"vmwLyCg","instructions_zh":"坐在长凳上，双手各握一个哑铃，手掌朝前。 将哑铃举至肩高，肘部弯曲，手掌朝前。 向上推哑铃，直到手臂完全伸过头顶。 将哑铃放低至肩部高度。 重复所需的重复次数。"},{"id":"0439","name_zh":"哑铃佐特曼弯举","target":"肱二头肌","media_id":"kXaIn5A","instructions_zh":"站直，双手各持一个哑铃，手掌朝向身体。 保持肘部靠近躯干，并旋转手掌以面向前方。 将哑铃举至肩膀处，同时保持上臂静止。 在动作的最高点，旋转手腕，使手掌背向身体。 慢慢地将哑铃放回起始位置，将手掌旋转回面向身体。 重复所需的重复次数。"},{"id":"2294","name_zh":"哑铃佐特曼牧师凳弯举","target":"肱二头肌","media_id":"y5U5B9Y","instructions_zh":"坐在牧师凳上，双手各持一个哑铃，手掌朝上，肘部放在垫子上。 将哑铃向上弯向肩膀，保持上臂静止，手掌朝上。 在弯举的顶部，旋转手腕，使手掌朝下。 慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。 重复所需的重复次数。"},{"id":"2189","name_zh":"哑铃坐姿三头肌伸展","target":"肱三头肌","media_id":"FQXdXzY","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 双手握住哑铃，正握，将其举过头顶。 弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。 伸展双臂，将哑铃举回到起始位置。 重复所需的重复次数。"},{"id":"1167","name_zh":"动态胸部拉伸（男）","target":"胸","media_id":"3uj0Ozg","instructions_zh":"站直，双脚分开与肩同宽。 将双臂伸直至两侧，与地面平行。 慢慢地将双臂向前伸，交叉在身体前面。 感受胸部肌肉的伸展。 保持拉伸 10-30 秒。 返回起始位置并重复所需的重复次数。"},{"id":"3287","name_zh":"肘撑臂屈伸","target":"肱三头肌","media_id":"LkoAWAE","instructions_zh":"坐在长凳或椅子的边缘，双手抓住臀部旁边的边缘。 将臀部向前滑离长凳，伸直双腿，保持脚后跟着地。 弯曲肘部，将身体放低至地面，保持背部靠近长凳。 在底部停顿片刻，然后双手用力伸直手臂，将身体抬回到起始位置。 重复所需的重复次数。"},{"id":"1772","name_zh":"抬肘反向俯卧撑","target":"上背部","media_id":"wbUYILZ","instructions_zh":"首先，脸朝下躺在地上，双腿伸展，双手直接放在肩膀下方。 收紧核心并用手掌按压，将上半身抬离地面，保持肘部靠近身体两侧。 在顶部暂停片刻，挤压上背部肌肉。 慢慢地将身体放回起始位置。 重复所需的重复次数。"},{"id":"0443","name_zh":"肘触膝","target":"腹部","media_id":"jvp6DiD","instructions_zh":"首先平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，将上半身抬离地面，将右肘靠近左膝盖。 同时，将左膝移向右肘，形成扭转动作。 在顶部停顿片刻，然后慢慢降低上半身并将双腿伸展回到起始位置。 重复该动作，这次将左肘移向右膝，将右膝移向左肘。 继续交替进行所需的重复次数。"},{"id":"3292","name_zh":"电梯","target":"上背部","media_id":"zYmNaoY","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 将双手放在臀部或交叉放在胸前。 保持背部挺直，腰部慢慢向前弯曲，将上半身向地面降低。 在底部停顿片刻，然后慢慢抬起上半身回到起始位置。 重复所需的重复次数。"},{"id":"1332","name_zh":"健身球交替抬臂","target":"背阔肌","media_id":"EyLrNC2","instructions_zh":"坐在稳定球上，双脚平放在地面上，背部挺直。 双手各握一个哑铃，手掌朝内，双臂在身体两侧向下伸展。 启动你的核心，慢慢地将一只手臂向肩膀抬起，保持肘部稍微弯曲。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 用另一只手臂重复该动作。 继续交替手臂进行所需的重复次数。"},{"id":"1333","name_zh":"健身球手臂前伸背伸展","target":"脊柱","media_id":"PERjVm8","instructions_zh":"将稳定球放在地上，面朝下躺在上面，臀部放在球上，双脚靠在墙上以保持稳定。 将双臂伸直在身前，手掌朝下。 启动你的核心，慢慢地将上半身抬离球，保持背部挺直，颈部与脊柱成一直线。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"1334","name_zh":"健身球手抱头背伸展","target":"脊柱","media_id":"o1HGDSq","instructions_zh":"将稳定球放在地上，面朝下躺在上面，臀部放在球上。 将脚靠在墙壁或其他稳定的表面上以获得支撑。 双臂交叉于脑后，双手触碰后脑勺。 启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到臀部形成一条直线。 在动作的最高点暂停片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"1335","name_zh":"健身球膝盖离地背伸展","target":"脊柱","media_id":"WME869U","instructions_zh":"将稳定球放在地上，面朝下躺在上面，臀部放在球上，双脚靠在墙上以保持稳定。 将双手放在脑后或交叉在胸前。 启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"1336","name_zh":"健身球背伸转体","target":"脊柱","media_id":"WVD66ff","instructions_zh":"首先，面朝下躺在稳定球上，臀部放在球上，双脚牢牢踩在地面上。 将双手放在脑后或交叉放在胸前。 启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。 在顶部停顿片刻，然后慢慢将躯干旋转到一侧，保持臀部和腿部稳定。 返回中心并重复旋转到另一侧。 将上半身放低至起始位置，然后重复所需的重复次数。"},{"id":"1744","name_zh":"健身球臂屈伸","target":"肱三头肌","media_id":"kprile3","instructions_zh":"坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。 将双手放在臀部旁边的球上，手指指向前方。 启动你的三头肌并用力推动你的身体，将你的身体抬离球，伸直你的手臂。 弯曲肘部，将身体放低，使其靠近身体两侧。 重复所需的重复次数。"},{"id":"1559","name_zh":"健身球髋屈肌拉伸","target":"臀部","media_id":"2LQkNPW","instructions_zh":"将稳定球放在地上并跪在其前面。 将右脚放在稳定球上，膝盖弯曲成 90 度角。 将左腿伸到身后，保持伸直。 身体前倾，将臀部推向稳定球，直到感觉到右髋屈肌有拉伸感。 保持拉伸 20-30 秒，然后换边重复。"},{"id":"1338","name_zh":"健身球抱球","target":"脊柱","media_id":"d7z1Y7V","instructions_zh":"坐在稳定球上，双脚平放在地面上，背部挺直。 用双手握住稳定球，将其抱在靠近胸部的位置。 启动你的核心肌肉，慢慢向后倾斜，保持背部挺直，双脚踩在地上。 继续向后倾斜，直到感觉到背部肌肉伸展。 保持该姿势几秒钟，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"1339","name_zh":"健身球背阔肌拉伸","target":"背阔肌","media_id":"sM84pE4","instructions_zh":"坐在稳定球上，双脚平放在地面上，背部挺直。 一只手握住哑铃，然后将手臂伸直至头顶。 慢慢地向另一侧倾斜，感受背阔肌的拉伸。 保持伸展动作 20-30 秒，然后回到起始位置。 在另一侧重复。"},{"id":"1341","name_zh":"健身球下背拉伸（金字塔）","target":"背阔肌","media_id":"yU7w7CA","instructions_zh":"坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。 慢慢地向前移动你的脚，将球沿着你的背部滚动，直到你的下背部靠在球上。 将双手放在脑后或交叉放在胸前。 启动你的核心，慢慢地将你的上半身降低到地面，让你的下背部伸展到球上方。 保持伸展几秒钟，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"1342","name_zh":"健身球侧卧背阔肌拉伸","target":"背阔肌","media_id":"rTbyBYV","instructions_zh":"侧躺，双腿伸展，头部由稳定球支撑。 将上臂放在球上以保持稳定性。 将上臂举过头顶，让躯干稍微旋转。 感受身体一侧背阔肌的拉伸。 保持拉伸 20-30 秒，然后换边重复。"},{"id":"1382","name_zh":"健身球靠墙提踵","target":"小腿","media_id":"xo6sENf","instructions_zh":"背靠墙站立，将健身球放在下背部和墙壁之间。 双脚分开与肩同宽，脚趾指向前方。 每只手握住一个哑铃，双臂伸向身体两侧。 将脚跟抬离地面，将身体重量转移到脚掌上。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"3241","name_zh":"健身球靠墙提踵（脚踝夹网球）","target":"小腿","media_id":"FY3UdNT","instructions_zh":"面向墙壁站立，双脚分开与肩同宽。 在墙壁和下背部之间放置一个健身球。 每只手握住一个哑铃，双臂伸向身体两侧。 将网球放在脚踝之间。 将脚后跟抬离地面，将身体抬起到脚趾上。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"3240","name_zh":"健身球靠墙提踵（膝盖夹网球）","target":"小腿","media_id":"j74M6Zn","instructions_zh":"背靠墙站立，将健身球放在下背部和墙壁之间。 将双脚分开与肩同宽，并稍微位于您的前方。 每只手握住一个哑铃，双臂伸向身体两侧。 将网球放在膝盖之间。 将脚后跟抬离地面，将身体抬起到脚趾上。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1416","name_zh":"健身球单腿俯身转体","target":"臀部","media_id":"M72BExt","instructions_zh":"面朝下躺在稳定球上，臀部放在球上，双腿伸直在身后。 将双手放在身前的地面上以获得支撑。 调动你的臀肌和核心肌肉来稳定你的身体。 慢慢地将一条腿抬离地面，保持笔直并与地板平行。 向外旋转腿部，远离身体，同时保持臀部和上半身稳定。 旋转结束时暂停片刻，然后慢慢地将腿放回起始位置。 用另一条腿重复旋转。 继续交替双腿达到所需的重复次数。"},{"id":"1417","name_zh":"健身球单腿斜踢腿弯举","target":"臀部","media_id":"GOJKFfO","instructions_zh":"首先仰卧，双腿伸展，脚跟放在稳定球上。 将手臂放在身体两侧以保持稳定。 调动臀肌和核心肌肉，将臀部抬离地面，从肩膀到脚后跟形成一条直线。 弯曲右膝并将其靠近胸部，保持左腿伸展，脚部弯曲。 将右腿斜踢过身体，完全伸展并拉动腿筋。 慢慢地将右腿返回到起始位置，保持控制和稳定性。 用左腿重复该动作，交替进行所需的重复次数。"},{"id":"1296","name_zh":"健身球派克俯卧撑","target":"胸","media_id":"sVvXT5J","instructions_zh":"从俯卧撑位置开始，双手放在地板上，小腿放在稳定球上。 收紧核心肌群，将臀部抬向天花板，将球滚向双手。 保持双腿伸直，身体呈屈体姿势，形成倒V字形。 弯曲肘部，将上半身降低到地板上，保持头部与双手在一条直线上。 用手推动并伸展双臂以返回到起始位置。 重复所需的重复次数。"},{"id":"1343","name_zh":"健身球俯卧抬腿","target":"脊柱","media_id":"lCKm4Rs","instructions_zh":"面朝下躺在垫子上，双腿伸展，脚趾放在稳定球上。 将双手放在地上，与肩同宽，锻炼核心肌肉。 保持双腿伸直，慢慢将它们抬离地面，用下背部和臀部将它们尽可能抬高。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"1560","name_zh":"健身球坐姿腘绳肌拉伸","target":"大腿后侧","media_id":"yRYyfdA","instructions_zh":"坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。 慢慢地向前滚动球，双脚向外走，直到上背部靠在球上，双腿在身前伸直。 将双手放在臀部上以获得支撑。 启动你的核心，慢慢地将上半身降低到地面，保持背部挺直，胸部抬起。 当您感觉到腿筋拉伸时停止，并保持该姿势 20-30 秒。 通过推动脚后跟并使用腿筋将自己拉回来，慢慢回到起始位置。 重复所需的重复次数。"},{"id":"1745","name_zh":"健身球坐姿肱三头肌拉伸","target":"肱三头肌","media_id":"7ePTw4B","instructions_zh":"坐在稳定球上，双脚平放在地面上，背部挺直。 一只手握住哑铃，将手臂伸直至头顶上方。 弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。 保持伸展几秒钟，然后回到起始位置。 用另一只手臂重复上述步骤。"},{"id":"1746","name_zh":"健身球仰卧肱三头肌伸展","target":"肱三头肌","media_id":"Gm2Uv1z","instructions_zh":"坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。 双手握住哑铃，双臂伸直向天花板方向伸展。 慢慢地将哑铃放到脑后，保持肘部靠近耳朵。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数。"},{"id":"1747","name_zh":"健身球EZ杠法式推举","target":"肱三头肌","media_id":"CFN9P8G","instructions_zh":"坐在健身球上，正手握住 EZ 杠铃。 向上伸展双臂，保持肘部靠近头部。 弯曲肘部，慢慢将杠铃降低到脑后。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"3010","name_zh":"EZ杠仰卧屈臂上拉","target":"背阔肌","media_id":"nDK1HJ0","instructions_zh":"平躺在长凳上，头放在一端，双脚放在地板上。 旋前握住 EZ 杠铃（手掌背向您），双手与肩同宽。 将手臂伸直至胸部上方，保持肘部轻微弯曲。 以弧线动作将杠铃降低到头后，保持肘部轻微弯曲。 暂停片刻，然后通过反向弧线运动将杠铃返回到起始位置。 重复所需的重复次数。"},{"id":"1748","name_zh":"EZ杠仰卧窄握颈后肱三头肌伸展","target":"肱三头肌","media_id":"6CKUx7o","instructions_zh":"平躺在长凳上，双脚平放在地上，头放在长凳的末端。 紧紧握住 ez 杠铃，手掌朝上，将手臂伸直至胸部上方。 保持上臂静止，弯曲肘部，慢慢将杠铃降低到脑后。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"1344","name_zh":"EZ杠反握俯身划船","target":"上背部","media_id":"G8dXpNG","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 反手握住 ez 杠铃，手掌朝上，双手与肩同宽。 臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。 将 ez 杠铃拉向下胸部，将肩胛骨挤压在一起。 在顶部暂停片刻，然后慢慢将 ez 杠铃放回起始位置。 重复所需的重复次数。"},{"id":"1682","name_zh":"EZ杠坐姿窄握集中弯举","target":"肱二头肌","media_id":"Dsfz0Id","instructions_zh":"坐在长凳上，双脚平放在地面上，反手握住 EZ 杠铃。 将肘部放在大腿内侧、膝盖上方。 将杠铃向上弯向肩膀，同时保持上臂静止。 在动作的最高点挤压二头肌，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"1749","name_zh":"EZ杠站姿法式推举","target":"肱三头肌","media_id":"1cTf2Ux","instructions_zh":"双脚分开与肩同宽站立，正手握住杠铃。 将杠铃举过头顶，充分伸展双臂。 保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"0445","name_zh":"EZ杠铃反重力推举","target":"肩","media_id":"fprd84i","instructions_zh":"首先，双脚分开与肩同宽站立，并用正手握住杠铃。 将杠铃举至肩膀高度，保持肘部稍微弯曲，手掌朝前。 将杠铃推过头顶，充分伸展双臂。 将杠铃降低回肩部高度，然后重复所需的重复次数。"},{"id":"1627","name_zh":"EZ杠铃窄握牧师凳弯举","target":"肱二头肌","media_id":"hacCyUv","instructions_zh":"坐在牧师弯举凳上，将上臂放在垫子上，反手握住 ez 杠铃。 将三头肌放在垫子上，充分伸展手臂，保持背部挺直。 慢慢地将杠铃向肩膀弯曲，收缩二头肌。 在顶部暂停片刻，挤压你的二头肌。 将杠铃放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"0446","name_zh":"EZ杠铃窄握弯举","target":"肱二头肌","media_id":"V4ryaZa","instructions_zh":"站直，双脚分开与肩同宽，反手握住杠铃，双手分开与肩同宽。 在整个运动过程中，保持肘部靠近躯干，上臂保持静止。 将杠铃向上弯向肩膀，收缩二头肌。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0447","name_zh":"EZ杠铃弯举","target":"肱二头肌","media_id":"6TG6x2w","instructions_zh":"站直，双脚分开与肩同宽，反手握住 ez 杠铃，手掌朝上。 在整个运动过程中，保持肘部靠近躯干，上臂保持静止。 当你将杠铃向肩膀方向卷曲时呼气，收缩二头肌。 在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0448","name_zh":"EZ杠铃下斜窄握面部推举","target":"肱三头肌","media_id":"DgZQ11d","instructions_zh":"躺在倾斜的长凳上，头低于脚。 紧紧抓住 ez 杠铃，手掌相对。 将手臂伸直至胸部上方，保持肘部靠近身体。 弯曲肘部，将杠铃降低到前额。 暂停片刻，然后将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"2186","name_zh":"EZ杠铃下斜肱三头肌伸展","target":"肱三头肌","media_id":"CQHoDm0","instructions_zh":"躺在倾斜的长凳上，头低于脚，双脚固定。 正手握住 ez 杠铃，双手与肩同宽。 充分伸展双臂，保持肘部靠近头部。 将杠铃慢慢降低到前额，弯曲肘部。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"0449","name_zh":"EZ杠铃上斜肱三头肌伸展","target":"肱三头肌","media_id":"KyLtiLT","instructions_zh":"设置一个 45 度角的上斜凳。 坐在长凳上，背部靠在垫子上，正手握住 ez 杠铃。 将手臂完全伸过头顶，保持肘部靠近头部。 弯曲肘部，将杠铃降低到头后，保持上臂静止。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"0450","name_zh":"EZ杠铃JM卧推","target":"肱三头肌","media_id":"hnOYgH3","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 正手握住杠铃，握距略宽于肩宽。 将杠铃降低到胸部，保持肘部靠近身体。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0451","name_zh":"EZ杠铃反握弯举","target":"肱二头肌","media_id":"Y5X65IB","instructions_zh":"站直，双脚分开与肩同宽，反手握住 ez 杠铃。 在整个练习过程中，保持肘部靠近躯干，上臂保持静止。 通过收缩二头肌将杠铃向上卷曲，同时呼气。 继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气时慢慢开始将杠铃拉回起始位置。 重复所需的重复次数。"},{"id":"0452","name_zh":"EZ杠铃反握牧师凳弯举","target":"肱二头肌","media_id":"vBNyir7","instructions_zh":"坐在牧师凳上，胸部靠在垫子上，双脚平放在地板上。 反手抓住 ez 杠铃，双手与肩同宽。 将上臂放在垫子上，让前臂下垂。 保持上臂静止，呼气并将杠铃向上弯向肩膀。 在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"1458","name_zh":"EZ杠铃坐姿弯举","target":"肱二头肌","media_id":"jtFKbt5","instructions_zh":"坐在长凳上，双脚平放在地上，背部挺直。 反手握住 ez 杠铃，手掌朝上，双手与肩同宽。 将上臂放在大腿上，让 ez 杠铃垂在您面前。 保持上臂静止，呼气并将杠铃向上卷曲至肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气并缓慢地将 ez 杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0453","name_zh":"EZ杠铃坐姿肱三头肌伸展","target":"肱三头肌","media_id":"iaapw0g","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 正手握住 ez 杠铃，双手与肩同宽。 将杠铃举过头顶，充分伸展双臂。 保持上臂静止，弯曲肘部将杠铃降低到脑后。 暂停片刻，然后伸展双臂将杠铃举回起始位置。 重复所需的重复次数。"},{"id":"0454","name_zh":"EZ杠铃蜘蛛弯举","target":"肱二头肌","media_id":"Ye5Qxb0","instructions_zh":"双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。 将上臂放在牧师凳或稳定球上，让肘部下垂。 保持上臂静止，呼气并将杠铃向上弯向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气并慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"1628","name_zh":"EZ杠铃蜘蛛弯举","target":"肱二头肌","media_id":"2kattbR","instructions_zh":"双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。 将上臂放在牧师凳或稳定球上，让肘部下垂。 保持上臂静止，呼气并将杠铃向上弯向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气并慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"2404","name_zh":"EZ杠肱二头肌弯举（使用臂托板）","target":"肱二头肌","media_id":"tJ5nYqo","instructions_zh":"站直，双脚分开与肩同宽，反手握住 ez 杠铃，手掌朝上。 将上臂靠在手臂冲击波上，在整个练习过程中保持静止。 保持肘部靠近身体，呼气并将杠铃向上弯向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气，慢慢将杠铃放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"2432","name_zh":"EZ杠窄握卧推","target":"肱三头肌","media_id":"da4cXST","instructions_zh":"平躺在长凳上，双脚平放在地上，背部紧贴长凳。 紧握杠铃，双手与肩同宽，掌心向前。 将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。 慢慢地将杠铃降低到胸部，保持肘部靠近身体。 当杠铃触及胸部时暂停片刻。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"2741","name_zh":"EZ杠铃站姿宽握肱二头肌弯举","target":"肱二头肌","media_id":"OVTZ65k","instructions_zh":"站直，双脚分开与肩同宽，反手握住杠铃，双手分开比肩宽。 在整个运动过程中，保持肘部靠近躯干，上臂保持静止。 收缩二头肌，将杠铃向上弯向肩膀。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"2133","name_zh":"农夫行走","target":"股四头肌","media_id":"qPEzJjA","instructions_zh":"站直，双手各握一个哑铃，手掌朝向身体两侧。 保持背部挺直，肩膀向后。 向前迈出小步，控制住，保持直立姿势。 继续步行所需的距离或时间。 最后，停止行走并小心地将哑铃降低到身体两侧。"},{"id":"0455","name_zh":"手指弯举","target":"前臂","media_id":"awG04cF","instructions_zh":"坐在长凳上，双脚平放在地面上，反手握住杠铃，手掌朝上。 将前臂放在大腿上，让手腕悬在边缘。 慢慢地将手指向手掌弯曲，紧紧挤压杠铃。 保持收缩一会儿，然后慢慢松开手指回到起始位置。 重复所需的重复次数。"},{"id":"3303","name_zh":"人体旗帜","target":"腹部","media_id":"pQ0Mx1Z","instructions_zh":"首先，双手握住一根垂直杆，手掌相对，双臂完全伸展。 启动你的核心并将双腿抬离地面，保持伸直。 利用核心和上半身的力量，抬起双腿，直到它们与地面平行。 尽可能长时间地保持这个姿势，保持身体线条笔直。 慢慢地将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0456","name_zh":"屈腿仰卧起坐（屈膝）","target":"腹部","media_id":"AR0ig3o","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 同时，将双腿抬离地面，弯曲膝盖并将其拉向胸部。 在顶部停顿片刻，然后慢慢降低上半身和双腿回到起始位置。 重复所需的重复次数。"},{"id":"0457","name_zh":"屈腿仰卧起坐（直臂）","target":"腹部","media_id":"KZn52RC","instructions_zh":"平躺，双腿伸直，双臂伸直至头顶上方。 收紧腹肌，将上半身抬离地面，同时将双腿抬向胸部。 抬起上半身和腿部时，将双手伸向脚趾。 在顶部停顿片刻，然后慢慢降低上半身和双腿回到起始位置。 重复所需的重复次数。"},{"id":"0458","name_zh":"地板飞鸟（杠铃）","target":"胸","media_id":"neonEDL","instructions_zh":"仰卧在地板上，膝盖弯曲，双脚平放在地面上。 正手握住杠铃，双臂伸直越过胸部。 慢慢地将杠铃向两侧放低，保持肘部轻微弯曲。 降低杠铃，直到手臂与地板平行，感觉胸部有拉伸感。 暂停片刻，然后挤压胸部肌肉，使杠铃回到起始位置。 重复所需的重复次数。"},{"id":"0459","name_zh":"仰卧交替抬腿","target":"臀部","media_id":"UVo2Qs2","instructions_zh":"平躺，双腿伸展，双手放在身体两侧。 收紧核心肌群并将双腿抬离地面约 6 英寸。 保持双腿伸直，交替将一条腿抬得比另一条腿稍高。 继续这个颤动动作达到所需的重复次数。"},{"id":"1472","name_zh":"向前跳","target":"股四头肌","media_id":"uZKq7lo","instructions_zh":"双脚分开与肩同宽站立。 弯曲膝盖并将身体降低至蹲姿。 向后摆动手臂以获得动力。 爆发性地向前跳跃，伸展臀部、膝盖和脚踝。 脚掌轻轻落地，然后立即进入下一个跳跃。 重复所需的重复次数。"},{"id":"3470","name_zh":"向前弓步（男）","target":"臀部","media_id":"kMzUs9Y","instructions_zh":"站立，双脚分开与臀部同宽，双手放在臀部。 右脚向前迈出一大步，将身体降低到弓步位置。 将右膝盖弯曲约 90 度，保持膝盖与脚踝对齐。 用右脚推出并返回到起始位置。 用左腿重复上述动作，交替进行所需的重复次数。"},{"id":"3194","name_zh":"弗兰肯斯坦深蹲","target":"臀部","media_id":"bdWcbaU","instructions_zh":"双脚分开与肩同宽站立，双臂伸直将杠铃举在身体前方。 保持背部挺直，弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。 继续降低，直到大腿与地面平行，或者尽可能低。 暂停片刻，然后用力推动脚后跟，回到起始位置。 重复所需的重复次数。"},{"id":"2429","name_zh":"蛙式卷腹","target":"腹部","media_id":"FFRP97T","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，将上半身抬离地面，向前卷曲直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"3301","name_zh":"蛙式俄挺","target":"腹部","media_id":"rQhGcin","instructions_zh":"从俯卧撑位置开始，双手与肩同宽，双脚并拢。 弯曲肘部，将身体放低至地面，保持背部挺直。 当你降低身体时，将双脚抬离地面，并将膝盖靠近胸部。 保持这个姿势几秒钟，然后向后伸展双腿，并将自己推回到起始位置。 重复所需的重复次数。"},{"id":"3296","name_zh":"前水平","target":"腹部","media_id":"PkCN2lv","instructions_zh":"首先，用正手握法悬挂在引体向上杆上，双手与肩同宽。 启动你的核心并将肩胛骨向下拉和向后拉。 弯曲膝盖并将其向胸部靠拢。 同时，抬起双腿并将其伸直在您面前，保持身体与地面平行。 尽可能长时间地保持此位置，以达到完全前杆位置。 要释放，请慢慢降低双腿并返回到起始位置。 重复所需的重复次数。"},{"id":"3295","name_zh":"前水平重复","target":"上背部","media_id":"hbY9wqG","instructions_zh":"正手握住引体向上杆，手掌背向自己。 启动你的核心并将肩胛骨向下拉和向后拉。 保持身体挺直，抬起双腿直至与地面平行。 尽可能长时间地保持这个姿势，目标是 10-20 秒。 慢慢地将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0464","name_zh":"平板支撑转体","target":"腹部","media_id":"CosupLu","instructions_zh":"从高平板支撑位置开始，双手直接放在肩膀下方，身体从头到脚成一条直线。 调动你的核心和臀部以保持稳定的位置。 将躯干向右旋转，抬起右臂并向天花板延伸。 扭转时保持臀部和腿部稳定。 保持片刻，然后回到起始位置。 在左侧重复扭转。 继续交替进行所需的重复次数。"},{"id":"3315","name_zh":"全马耳他十字","target":"腹部","media_id":"YRaCa5Y","instructions_zh":"首先站立，双脚分开与肩同宽，双臂伸直至两侧。 慢慢向前倾斜，保持手臂伸直，直到上半身与地面平行。 启动你的核心并保持这个姿势几秒钟。 通过双脚推动并站起来，回到起始位置。 重复所需的重复次数。"},{"id":"3299","name_zh":"全俄挺","target":"腹部","media_id":"YZ4961r","instructions_zh":"从俯卧撑位置开始，双手与肩同宽，手指指向前方。 启动你的核心并缓慢地将你的重心向前移动，将你的脚抬离地面。 继续向前移动体重，直到身体与地面平行，并用双手保持平衡。 尽可能长时间地保持这个姿势，保持身体线条笔直。 慢慢地将双脚放回地面，然后回到起始位置。 重复所需的重复次数。"},{"id":"3327","name_zh":"全俄挺俯卧撑","target":"胸","media_id":"gw9PqGk","instructions_zh":"从俯卧撑位置开始，双手分开略宽于肩宽。 收紧核心肌群，将身体放低至地面，保持肘部靠近身体两侧。 当你降低身体高度时，身体向前倾斜，双脚离开地面，用双手保持平衡。 继续降低身体，直到胸部略高于地面。 用手推动并伸展双臂，将身体抬回到起始位置。 在整个运动过程中，从头部到脚后跟保持一条直线。 重复所需的重复次数。"},{"id":"0466","name_zh":"吉龙达胸骨引体","target":"背阔肌","media_id":"IL0JUxR","instructions_zh":"面向高杠站立，双脚分开与肩同宽。 向上伸手，正手握住杠铃，握距略宽于肩宽。 悬挂在杠上，双臂完全伸展，身体伸直。 用你的背阔肌和二头肌将你的胸部拉向杠铃杆，以胸骨为主导。 在最高点暂停片刻，然后慢慢降低回到起始位置。 重复所需的重复次数。"},{"id":"3561","name_zh":"臀桥行军","target":"臀部","media_id":"GibBPPg","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 收紧臀部并将臀部抬离地面，从膝盖到肩膀形成一条直线。 在保持臀部抬起的同时，将一只脚抬离地面，并将膝盖靠近胸部。 将脚放回地面，然后用另一条腿重复该动作。 继续交替双腿进行行进动作，同时保持桥式姿势。 重复所需的重复次数。"},{"id":"3523","name_zh":"双脚凳上臀桥（男）","target":"臀部","media_id":"aWedzZX","instructions_zh":"坐在长凳边缘，背靠着长凳，双脚平放在地上。 将双手放在臀部旁边的长凳上以获得支撑。 收紧臀肌和腿筋，然后将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。 在顶部暂停片刻，然后慢慢将臀部放回起始位置。 重复所需的重复次数。"},{"id":"3193","name_zh":"臀腿举","target":"大腿后侧","media_id":"Vvwjz6N","instructions_zh":"调整臀肌提升机以适合您的身体。 将自己面朝下放在机器上，固定脚踝。 将双手放在胸前或交叉在胸前。 调动腿筋和臀肌，将上半身抬向天花板。 继续抬起，直到身体从头部到脚后跟成一条直线。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"0467","name_zh":"大猩猩引体","target":"腹部","media_id":"bmwlYvD","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 正手握住引体向上杆，握距略宽于肩宽。 悬挂在杠上，双臂完全伸展，手掌背向自己。 收紧核心肌群，将身体拉向杠铃杆，将下巴置于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"0469","name_zh":"腹股沟卷腹","target":"腹部","media_id":"mWppALS","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，将双腿抬离地面，将膝盖靠近胸部。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"1383","name_zh":"哈克机提踵","target":"小腿","media_id":"2ORFMoR","instructions_zh":"将雪橇机调整至舒适的重量。 站在雪橇机上，脚趾放在平台上，脚后跟悬空。 握住手柄以保持稳定性。 通过推动脚掌将脚后跟尽可能抬高。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1384","name_zh":"哈克机单腿提踵","target":"小腿","media_id":"AxFoqAD","instructions_zh":"将雪橇机调整到合适的重量。 一脚站在雪橇机上，另一只脚离开地面。 握住手柄以保持稳定性。 尽可能高地抬高脚跟，用脚掌抬起身体。 在顶部暂停片刻，然后慢慢将脚跟放回起始位置。 重复所需的重复次数。 换腿并重复练习。"},{"id":"3221","name_zh":"半屈膝（男）","target":"有氧","media_id":"ia6kIIl","instructions_zh":"双脚分开与肩同宽站立。 弯曲膝盖并降低身体，就像坐回椅子上一样。 保持挺胸，将体重放在脚后跟上。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"3202","name_zh":"半仰卧起坐（男）","target":"腹部","media_id":"iQ241UP","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"1511","name_zh":"腘绳肌拉伸","target":"大腿后侧","media_id":"99rWm7w","instructions_zh":"双脚分开与肩同宽站立。 右脚向前迈出一步，将重心转移到右腿上。 保持背部挺直，臀部慢慢向前弯曲，双手伸向右脚。 保持伸展动作 20-30 秒，然后回到起始位置。 在另一侧重复。"},{"id":"2139","name_zh":"手臂自行车","target":"胸","media_id":"pAIWRGu","instructions_zh":"将座椅高度和车把位置调整至舒适的水平。 坐在测力计上，背部挺直，双脚放在踏板上。 双手抓住手柄，并将手臂呈 90 度角。 开始用手踩踏板，以受控的动作推拉手柄。 继续踩踏所需的持续时间或重复次数。"},{"id":"3218","name_zh":"双手交握圆周触脚尖（男）","target":"臀部","media_id":"B5xca8s","instructions_zh":"双脚分开与肩同宽站立，双手合十放在胸前。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将双手向脚趾方向以打圈的方式降低，尽量伸得尽可能远，但不要用力。 在底部停顿片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"3215","name_zh":"双手反握圆周触脚尖（男）","target":"臀部","media_id":"yq3GAJX","instructions_zh":"双脚分开与肩同宽站立，双臂向两侧伸展。 腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。 双手向下伸，并在腿后将它们握在一起。 慢慢地将双手举过头顶，做圆周运动，保持双腿伸直。 继续圆周运动，直到双手触及脚趾。 反转动作并将双手放回起始位置。 重复所需的重复次数。"},{"id":"3302","name_zh":"倒立","target":"肱三头肌","media_id":"XooAdhl","instructions_zh":"找到一个有足够空间的空地来进行倒立。 将双手放在地上，与肩同宽，手指指向前方。 将双腿向上踢向墙壁，用核心和肩膀保持平衡。 处于倒立位置后，用三头肌来支撑体重。 只要能保持平衡，就保持倒立。 下降时，慢慢将双腿放回地面。 重复所需的重复次数。"},{"id":"0471","name_zh":"倒立俯卧撑","target":"肱三头肌","media_id":"rQxwMxO","instructions_zh":"找到一堵墙，背对墙，站在几英尺远的地方。 将双手放在地面上，与肩同宽，然后将脚踢到墙上，形成倒立姿势。 弯曲肘部，将头低向地面，保持身体呈一条直线。 用手推动并伸展双臂以返回到起始位置。 重复所需的重复次数。"},{"id":"1764","name_zh":"悬垂举腿提髋","target":"腹部","media_id":"VEcJRo2","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。 弯曲臀部和膝盖，收紧核心并抬起双腿，直到大腿与地面平行。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0472","name_zh":"悬垂举腿","target":"腹部","media_id":"I3tsCnC","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。 启动你的核心并将双腿抬起到你面前，保持伸直。 继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"1761","name_zh":"悬垂侧提膝","target":"腹部","media_id":"BaE7O6U","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。 收紧核心并将膝盖抬向胸部，同时将躯干扭转到一侧。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 在另一侧重复上述步骤，向相反方向扭转躯干。 继续交替进行所需的重复次数。"},{"id":"0473","name_zh":"悬垂屈体抬腿","target":"腹部","media_id":"nuBF9MO","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。 收紧核心肌群，将双腿向杠铃方向抬起，保持伸直。 继续抬起身体，直到身体形成“V”形，双腿与地面平行。 保持该姿势片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0474","name_zh":"悬垂直腿抬髋","target":"腹部","media_id":"pj0X0tF","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。 启动你的核心并将双腿抬起到你面前，直到它们与地面平行。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0475","name_zh":"悬垂直腿举腿","target":"腹部","media_id":"4Ml7QFO","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。 启动你的核心并将双腿抬起到你面前，保持伸直。 继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0476","name_zh":"悬垂直腿转体抬髋","target":"腹部","media_id":"Q6bvyen","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，双腿伸直。 启动你的核心并将双腿抬向胸部，保持伸直。 一旦双腿与地面平行，将臀部向一侧扭转，将双腿移向一侧。 暂停片刻，然后回到起始位置。 重复这个动作，但这次将臀部扭向另一侧。 继续交替进行所需的重复次数。"},{"id":"3636","name_zh":"靠墙高抬腿","target":"有氧","media_id":"ealLwvX","instructions_zh":"面向墙壁站立，双脚分开与臀部同宽。 将双手放在墙上以获得支撑。 启动你的核心并将右膝抬向胸部，同时将左脚保持在地面上。 快速换腿，将左膝抬向胸部，然后将右脚放低。 继续交替双腿进行跑步动作，将膝盖尽可能抬高。 在整个练习过程中保持快节奏并保持上半身稳定。 重复所需的持续时间或重复次数。"},{"id":"0484","name_zh":"屈膝抬髋","target":"腹部","media_id":"196HJGw","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在身体两侧，掌心朝下。 收紧核心肌群和臀肌，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。 在顶部暂停片刻，然后慢慢将臀部放回起始位置。 重复所需的重复次数。"},{"id":"1418","name_zh":"抱膝触胸","target":"臀部","media_id":"znP9SIh","instructions_zh":"首先站立，双脚分开与肩同宽。 弯曲膝盖并将身体降低至蹲姿。 当你蹲下时，将膝盖抬向胸部，并用手臂抱住它们。 保持这个姿势一会儿，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"3234","name_zh":"高位哑铃飞鸟","target":"胸","media_id":"P9ZRyLT","instructions_zh":"平躺在长凳上，双手各握一个哑铃，手掌相对。 将手臂伸直越过胸部，肘部稍微弯曲。 保持肘部轻微弯曲，以宽弧线将哑铃向两侧放低，直到感觉到胸部有拉伸感。 暂停片刻，然后反转动作，将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0489","name_zh":"山羊挺身","target":"脊柱","media_id":"zhMwOwE","instructions_zh":"调整过度伸展凳，使大腿上部放在垫子上并且双脚固定。 双臂交叉放在胸前或将双手放在脑后。 将上半身压向地面，同时保持背部挺直。 在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。 重复所需的重复次数。"},{"id":"0488","name_zh":"凳上挺身","target":"脊柱","media_id":"zkgRrbK","instructions_zh":"调整过度伸展凳，使臀部舒适地放在垫子上，并且双脚固定。 双臂交叉放在胸前或将双手放在脑后。 慢慢地将上半身降低到地面，同时保持背部挺直。 在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。 重复所需的重复次数。"},{"id":"3289","name_zh":"不可能臂屈伸","target":"肱三头肌","media_id":"05Cf2v8","instructions_zh":"将自己定位在两个双杠之间，双臂完全伸展，身体悬浮在空中。 弯曲膝盖并交叉脚踝。 弯曲肘部降低身体，直到上臂与地面平行。 暂停片刻，然后伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"1471","name_zh":"毛毛虫爬","target":"腹部","media_id":"ZgsNQ6d","instructions_zh":"从站立位置开始，双脚分开与臀部同宽。 腰部向前弯曲，双手放在身前的地面上。 双手向前移动，直到处于高位平板支撑位置，身体从头到脚成一条直线。 暂停片刻，然后将双手移回双脚，尽可能保持双腿伸直。 一旦你的手到达你的脚，站回起始位置。 重复所需的重复次数。"},{"id":"3698","name_zh":"毛毛虫爬V2","target":"腹部","media_id":"TV87DNB","instructions_zh":"从站立位置开始，双脚分开与臀部同宽。 腰部向前弯曲，双手放在身前的地面上。 双手向前移动，直到处于高位平板支撑位置，身体从头到脚成一条直线。 保持双腿伸直，将脚移向双手，将臀部抬向天花板。 继续向前移动双手，重复该动作达到所需的重复次数。"},{"id":"0490","name_zh":"上斜窄距俯卧撑","target":"肱三头肌","media_id":"1YB40kg","instructions_zh":"将双手放在较高的表面上，例如长凳或台阶上，双手之间的距离略宽于肩宽。 将双腿伸到身后，放在脚掌上，身体从头到脚跟形成一条直线。 弯曲肘部，使肘部靠近身体两侧，将胸部降低到升高的表面。 在底部暂停片刻，然后伸直手臂将自己推回起始位置。 重复所需的重复次数。"},{"id":"0491","name_zh":"上斜直腿抬髋","target":"腹部","media_id":"eVxAzgz","instructions_zh":"躺在倾斜的长凳上，背部平放在长凳上，双腿伸直在身前。 将双手放在长凳两侧以获得支撑。 收紧腹肌，将双腿抬离长凳，尽可能抬高双腿，同时保持伸直。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0492","name_zh":"上斜俯卧撑跳深","target":"胸","media_id":"CB8WET1","instructions_zh":"找到一个较高的表面，例如长凳或台阶，并将双手与肩同宽放在边缘。 双脚向后退一步，保持身体从头到脚跟呈一条直线。 将胸部向水面边缘降低，弯曲肘部并保持身体对齐。 推动手掌以伸展手臂并返回到起始位置。 从水面边缘跳下，膝盖稍微弯曲，轻轻落地。 重复俯卧撑和深度跳跃达到所需的重复次数。"},{"id":"0493","name_zh":"上斜俯卧撑","target":"胸","media_id":"B1EVP9F","instructions_zh":"将双手放在较高的表面上，例如长凳或台阶上，双手之间的距离略宽于肩宽。 将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。 弯曲肘部，将胸部向升高的表面降低，保持身体呈一条直线。 在底部暂停片刻，然后伸直手臂将自己推回起始位置。 重复所需的重复次数。"},{"id":"3785","name_zh":"上斜俯卧撑（垫箱）","target":"胸","media_id":"F7vjXqT","instructions_zh":"将双手放在盒子或高架表面的边缘，距离略宽于肩宽。 将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。 弯曲肘部，将胸部向箱子方向降低，保持身体呈一条直线。 在底部暂停片刻，然后伸直手臂将自己推回起始位置。 重复所需的重复次数。"},{"id":"0494","name_zh":"上斜反握俯卧撑","target":"胸","media_id":"XaaRnRn","instructions_zh":"将双手放在长凳或高架表面的边缘，距离略宽于肩宽。 将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。 弯曲肘部，将胸部向长凳方向降低，使其靠近身体两侧。 在底部暂停片刻，然后伸展双臂将自己推回起始位置。 重复所需的重复次数。"},{"id":"3011","name_zh":"上斜肩胛俯卧撑","target":"前锯肌","media_id":"GdMa1ET","instructions_zh":"设置一个 45 度角的上斜凳。 将双手放在长凳上，距离略比肩宽。 将双脚放在地面上，距离与臀部同宽。 将胸部向长凳方向降低，保持肘部内收。 当你降低时，缩回肩胛骨，将肩胛骨挤压在一起。 推动手掌以伸展手臂并返回到起始位置。 重复所需的重复次数。"},{"id":"0495","name_zh":"上斜转体仰卧起坐","target":"腹部","media_id":"9ZGZuOD","instructions_zh":"设置一个 45 度角的上斜凳。 躺在长凳上，双脚固定在脚垫下。 将双手放在脑后或放在胸前。 收紧腹肌，将上半身抬离长凳，向前卷曲。 当你蜷缩起来时，将你的躯干扭转到一侧，将你的肘部拉向另一侧的膝盖。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复这个动作，这次将你的躯干扭转到另一侧。 继续交替进行所需的重复次数。"},{"id":"1564","name_zh":"中级髋屈肌和股四头肌拉伸","target":"股四头肌","media_id":"tFGKm99","instructions_zh":"站直，双脚分开与肩同宽。 抓住一个稳定的物体作为支撑。 弯曲右膝，将右脚移向臀部，用右手抓住绳子。 慢慢地将右脚拉向臀部，感受右股四头肌的拉伸。 保持拉伸 20-30 秒。 松开拉伸并在左侧重复。"},{"id":"0496","name_zh":"反向腿弯举（凳支撑）","target":"大腿后侧","media_id":"ms7tjSG","instructions_zh":"脸朝下躺在长凳上，臀部位于边缘，双腿伸直在身后。 抓住长凳以获得支撑。 保持上半身不动，弯曲膝盖并将双腿向臀部弯曲。 在顶部停顿片刻，然后慢慢将双腿伸展回起始位置。 重复所需的重复次数。"},{"id":"2400","name_zh":"反向腿弯举（引体向上绳索机）","target":"大腿后侧","media_id":"0rHfvy9","instructions_zh":"调整缆绳机，使踝带处于最低设置。 面朝下躺在长凳上，双腿伸展，脚踝带固定在脚上。 握住长凳的把手以保持稳定。 弯曲膝盖，将双腿向臀部弯曲，挤压腿筋。 在动作的最高点暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0499","name_zh":"反向划船","target":"上背部","media_id":"bZGHsAZ","instructions_zh":"在腰部高度设置一个杠铃或使用悬挂训练器。 面向杠铃或悬吊训练器站立，双脚分开与肩同宽。 正手握住杠铃或手柄，握距略宽于肩宽。 向后倾斜，保持身体挺直，脚后跟着地。 将胸部拉向杠铃或手柄，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢降低回到起始位置。 重复所需的重复次数。"},{"id":"2300","name_zh":"屈膝反向划船","target":"上背部","media_id":"VPPtusI","instructions_zh":"在腰部高度设置一根横杆，然后躺在其下方。 正手握住杠铃，握距略宽于肩宽。 调整身体位置，使脚后跟着地，身体伸直。 将肩胛骨挤压在一起，将胸部向上拉向杠铃。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"2298","name_zh":"凳上反向划船","target":"上背部","media_id":"Mxa7Cr8","instructions_zh":"设置一张长凳，其高度应让您的身体可以自由地悬挂在其下方。 面朝上躺在地上，头朝向长凳。 向上伸手，正手握住长凳，握距略宽于肩宽。 调整身体位置，使脚后跟着地，手臂完全伸展。 当你将胸部拉向长凳时，启动你的核心并将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢降低身体回到起始位置。 重复所需的重复次数。"},{"id":"0497","name_zh":"反向划船V2","target":"上背部","media_id":"uX3sUBz","instructions_zh":"在史密斯机上在腰部高度设置一根杠铃或使用悬挂训练器。 面向杠铃或悬吊训练器站立，用正手握法抓住它，双手与肩同宽。 双脚向前走，向后倾斜，直到身体呈轻微角度。 保持身体挺直，将胸部向上拉向杠铃或手柄，将肩胛骨挤压在一起。 在最高点暂停片刻，然后慢慢降低回到起始位置。 重复所需的重复次数。"},{"id":"0498","name_zh":"吊索反向划船","target":"上背部","media_id":"jdiExfW","instructions_zh":"在胸部高度设置悬挂训练器或带子。 面向锚点站立，并用正手握住手柄。 双脚向前走，向后倾斜，直到身体呈一定角度。 保持身体挺直并启动核心。 将胸部拉向手柄，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢降低回到起始位置。 重复所需的重复次数。"},{"id":"1419","name_zh":"铁十字拉伸","target":"臀部","media_id":"pZwUsKB","instructions_zh":"平躺，双臂向两侧伸展。 将双腿抬向天花板，保持伸直。 慢慢地将双腿降低到一侧，旨在用脚接触地板。 保持伸展几秒钟，然后将双腿恢复到起始位置。 在另一侧重复拉伸。 继续交替进行所需的重复次数。"},{"id":"1297","name_zh":"等长胸挤压","target":"胸","media_id":"HbSG1Pw","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 将双臂伸直在身前，与地面平行，手掌相对。 尽可能用力挤压胸部肌肉，同时保持手臂伸直。 保持这个姿势几秒钟，专注于收缩胸部肌肉。 释放挤压并放松胸部肌肉。 重复所需的重复次数。"},{"id":"0500","name_zh":"等长雨刷器","target":"胸","media_id":"11wrviz","instructions_zh":"首先平躺在垫子或长凳上。 将手臂伸直至两侧，与身体垂直。 启动你的核心并将双腿抬离地面，保持它们并拢并伸直。 慢慢地将双腿向一侧降低，目标是用脚接触地面，同时保持控制。 暂停片刻，然后用核心力量将双腿抬回到起始位置。 重复该动作，这次将双腿降低到另一侧。 继续交替进行所需的重复次数。"},{"id":"0501","name_zh":"开合波比跳","target":"有氧","media_id":"mr7pkqP","instructions_zh":"从站立位置开始，双脚分开与肩同宽。 将身体降低至蹲姿，将双手放在身前的地面上。 双脚向后踢，以俯卧撑姿势落地。 进行俯卧撑，将胸部降低到地面，然后再向上推。 双脚向前跳，以蹲姿落地。 爆发性地跳起，将双臂举过头顶。 轻轻落地并立即回到蹲姿，开始下一次重复。"},{"id":"3224","name_zh":"开合跳（男）","target":"有氧","media_id":"1g5bPpA","instructions_zh":"双脚并拢站立，双臂放在身体两侧。 跳起来，分开双脚，将手臂举过头顶。 当你落地时，迅速跳回起始位置。 重复所需的重复次数。"},{"id":"0507","name_zh":"折刀仰卧起坐","target":"腹部","media_id":"mbkgB44","instructions_zh":"平躺，双腿伸展，双臂举过头顶。 启动你的核心，同时抬起双腿和上半身，将双手伸向脚趾。 在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。 重复所需的重复次数。"},{"id":"0508","name_zh":"詹达仰卧起坐","target":"腹部","media_id":"1GPHRyK","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"2612","name_zh":"跳绳","target":"有氧","media_id":"e1e76I2","instructions_zh":"双手握住跳绳的手柄，掌心向内。 站立，双脚分开与肩同宽，膝盖稍微弯曲。 将绳子甩过头顶，当绳子靠近你的脚时跳过它。 轻轻地用脚掌着地，当绳子再次绕回时重复跳跃。 继续跳跃所需的持续时间或重复次数。"},{"id":"0514","name_zh":"深蹲跳","target":"臀部","media_id":"LIlE5Tn","instructions_zh":"双脚分开与肩同宽站立。 弯曲膝盖并将臀部向后推，将身体降低至蹲姿。 爆发性地跳离地面，伸展臀部、膝盖和脚踝。 在半空中时，快速将手臂向前伸以保持平衡。 脚掌轻轻落地，然后立即进入下一个重复动作。 重复所需的重复次数。"},{"id":"0513","name_zh":"深蹲跳 版本2","target":"臀部","media_id":"TDYiji6","instructions_zh":"双脚分开与肩同宽站立。 弯曲膝盖并将臀部向后推，将身体降低至蹲姿。 爆发力跳跃，充分伸展臀部和膝盖。 脚掌轻轻着地，然后立即将身体放回蹲姿。 重复所需的重复次数。"},{"id":"0517","name_zh":"壶铃高级风车","target":"腹部","media_id":"Kal9cQQ","instructions_zh":"站立，双脚分开比肩宽，脚趾稍微向外。 右手握住壶铃，手臂伸过头顶，手掌朝前。 将左脚稍微向右旋转，并将重量转移到左腿上。 弯曲左膝并铰接在臀部，将躯干向左侧降低。 保持右臂伸过头顶，眼睛盯着壶铃。 当你降低躯干时，让右腿伸直，右脚稍微转动。 降低躯干，直到感觉到左腿筋拉伸并且右臂指向地面。 暂停片刻，然后启动核心并推动左脚跟返回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0518","name_zh":"壶铃交替悬垂翻","target":"前臂","media_id":"I4tibZG","instructions_zh":"双脚分开与肩同宽站立，双手各握一个壶铃，正手握住。 稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。 让壶铃悬挂在身体前方，双臂完全伸展。 以一种流畅的动作，爆发性地伸展臀部，耸肩，并将壶铃拉向肩膀。 当壶铃到达肩膀高度时，旋转手腕并将壶铃抓住在架子位置，手掌朝内，壶铃放在前臂外侧。 将壶铃放回起始位置，然后用另一只手臂重复该动作。 继续交替手臂进行所需的重复次数。"},{"id":"0520","name_zh":"壶铃交替推举","target":"肩","media_id":"5KLbZWx","instructions_zh":"双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。 将一只壶铃按过头顶，完全伸展手臂。 将壶铃降低至肩膀高度。 用另一只手臂重复上述步骤。 继续交替手臂进行所需的重复次数。"},{"id":"0519","name_zh":"壶铃交替地板推举","target":"胸","media_id":"7w6i0vE","instructions_zh":"首先仰卧在地板上，膝盖弯曲，双脚平放在地面上。 每只手握住一个壶铃，手掌朝向脚部，手臂伸直向天花板。 将一个壶铃向肩膀方向降低，同时保持另一个壶铃向上伸直。 将降低的壶铃按回到起始位置，同时将另一个壶铃向肩膀方向降低。 继续用每个壶铃交替进行推举动作，达到所需的重复次数。"},{"id":"0521","name_zh":"壶铃交替叛徒划船","target":"上背部","media_id":"b9kqlBy","instructions_zh":"从高平板支撑位置开始，双手握住壶铃，双脚分开与臀部同宽。 收紧核心肌群，保持身体从头到脚跟呈一条直线。 将一个壶铃向上拉向胸部，保持肘部靠近身体。 将壶铃放回起始位置，然后用另一只手臂重复该动作。 继续交替手臂进行所需的重复次数。"},{"id":"0522","name_zh":"壶铃交替划船","target":"上背部","media_id":"Ca76jUE","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个壶铃，手掌朝向身体。 臀部向前弯曲，保持背部挺直，核心肌群参与。 将一个壶铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。 将壶铃放回起始位置，然后用另一只手臂重复该动作。 继续交替手臂进行所需的重复次数。"},{"id":"0523","name_zh":"壶铃阿诺德推举","target":"肩","media_id":"UM8mgyG","instructions_zh":"双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高，手掌朝向自己。 启动你的核心并将壶铃压过头顶，在伸展手臂时旋转手掌以面向前方。 在动作的最高点暂停，然后慢慢将壶铃放回起始位置。 重复所需的重复次数。"},{"id":"0524","name_zh":"壶铃屈体推举","target":"腹部","media_id":"kjE55n5","instructions_zh":"双脚分开与肩同宽站立，右手握住壶铃。 稍微弯曲膝盖，用右臂将壶铃压过头顶，保持肘部锁定。 将躯干向左旋转，将重量转移到左脚上。 弯曲左膝，将躯干压向地面，保持右臂伸过头顶。 当你下降时，眼睛盯着壶铃，胸部抬起。 左手接触地面后，将左脚推入并伸直左腿，推动臀部向前。 当你向前推动臀部时，用你的核心和右臂将壶铃推回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0525","name_zh":"壶铃底朝上悬垂翻","target":"肱二头肌","media_id":"4KJEpzb","instructions_zh":"双脚分开与肩同宽站立，一只手握住壶铃，正手握住。 稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。 让壶铃垂在双腿之间，手臂完全伸展。 以一种流畅的动作，爆发性地伸展你的臀部和膝盖，同时将壶铃拉向你的肩膀。 当壶铃到达肩膀高度时，旋转手腕，使壶铃底部朝上。 在与肩同高的位置抓住壶铃，肘部弯曲，手掌朝上。 通过反向运动将壶铃降低回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0526","name_zh":"壶铃双交替悬垂翻","target":"肱二头肌","media_id":"a4F9Oyc","instructions_zh":"双脚分开与肩同宽站立，双手各握一个壶铃，正手握住。 稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。 让壶铃垂直悬挂在身体前方。 以一种流畅的动作，爆发性地伸展臀部和膝盖，同时耸肩。 当壶铃上升时，将其拉向肩膀，保持肘部高且向两侧伸展。 在与肩同高的位置抓住壶铃，手掌朝内，肘部向前。 将壶铃放回起始位置，然后重复所需的重复次数。"},{"id":"0527","name_zh":"壶铃双挺举","target":"肩","media_id":"tznL2Ad","instructions_zh":"双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。 稍微弯曲膝盖并启动核心。 将壶铃压过头顶，充分伸展手臂。 弯曲膝盖并快速半蹲。 爆发性地伸展臀部和膝盖，将壶铃举过头顶。 锁定双臂，将壶铃举过头顶，膝盖稍微弯曲。 站直并回到起始位置。 重复所需的重复次数。"},{"id":"0528","name_zh":"壶铃双借力推举","target":"肩","media_id":"I4KkPdl","instructions_zh":"首先，双脚分开与肩同宽，每只手握住一个壶铃，与肩同高。 稍微弯曲膝盖并启动核心。 通过爆发性伸展臀部、膝盖和脚踝来开始运动，将壶铃举过头顶。 当壶铃到达顶部时，将它们完全压过头顶，锁定手臂。 弯曲肘部并将壶铃放回至肩膀高度，将壶铃放回起始位置。 重复所需的重复次数。"},{"id":"0529","name_zh":"壶铃双抓举","target":"肩","media_id":"M74kdvm","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个壶铃，放在大腿前面，与手臂保持一定距离。 稍微弯曲膝盖，臀部向前转动，保持背部平坦，挺胸。 以一种爆发力动作，伸展臀部、膝盖和脚踝，同时将壶铃拉向肩膀。 当壶铃达到肩膀水平时，旋转手腕并将壶铃击过头顶，充分伸展手臂。 将壶铃放回起始位置，然后重复所需的重复次数。"},{"id":"0530","name_zh":"壶铃双风车","target":"腹部","media_id":"OaE7CpD","instructions_zh":"双脚分开与肩同宽站立，右手握住壶铃。 将右臂伸过头顶，眼睛盯着壶铃。 左脚向左旋转 45 度，右脚向右旋转 90 度。 腰部向左弯曲，保持右臂伸过头顶。 将壶铃向地面降低，伸向左脚。 暂停片刻，然后启动核心并推动右脚返回起始位置。 重复所需的重复次数，然后换边。"},{"id":"0531","name_zh":"壶铃单臂地板全程推举","target":"胸","media_id":"rseLfH3","instructions_zh":"首先仰卧在地板上，膝盖弯曲，双脚平放在地面上。 一只手握住壶铃，手掌朝向脚部。 将手臂伸直向上伸向天花板，保持肘部锁定且手腕伸直。 慢慢地将壶铃放回起始位置，在整个运动过程中保持控制。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0532","name_zh":"壶铃8字环绕","target":"腹部","media_id":"L4ay0PW","instructions_zh":"双脚分开与肩同宽站立，一只手握住壶铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将壶铃放在双腿之间，当壶铃到达双腿后部时交换双手。 当壶铃向前移动时，将其传递到两腿之间的另一只手。 继续以 8 字形动作将壶铃传递到双腿之间。 在整个练习过程中保持稳定的节奏并调动核心力量。 重复所需的重复次数。"},{"id":"0533","name_zh":"壶铃前蹲","target":"臀部","media_id":"DB0n8AG","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微向外。 双手将壶铃放在胸前，靠近身体。 收紧核心并保持挺胸，同时降低臀部和向后倾斜，就像坐在椅子上一样。 降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。 通过脚跟发力站起来，在顶部挤压臀部。 重复所需的重复次数。"},{"id":"0534","name_zh":"壶铃高脚杯深蹲","target":"臀部","media_id":"ZA8b5hc","instructions_zh":"双脚分开与肩同宽站立，双手握住壶铃靠近胸部。 保持胸部挺直，核心收紧，弯曲膝盖和臀部，将身体降低至蹲姿。 继续降低，直到大腿与地面平行，或者尽可能低。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0535","name_zh":"壶铃悬垂翻","target":"大腿后侧","media_id":"LHWF7us","instructions_zh":"双脚分开与肩同宽站立，将壶铃放在大腿前面。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将壶铃放低至地面，使其在双腿之间摆动。 快速伸展臀部和膝盖，利用动量将壶铃摆动到肩膀高度。 当壶铃达到肩膀高度时，旋转手腕，将壶铃置于架子位置，肘部内收，壶铃靠在前臂上。 将壶铃放回双腿之间的起始位置，然后重复所需的重复次数。"},{"id":"0536","name_zh":"壶铃弓步穿越","target":"臀部","media_id":"WKMQzCD","instructions_zh":"双脚分开与肩同宽站立，双手握住壶铃放在胸前。 右脚向前迈出一步，将身体降低至弓步位置。 当你向前弓步时，将壶铃传递到右大腿下方，然后将其转移到左手。 用右脚蹬地回到起始位置，同时将壶铃传回右手。 在另一侧重复弓步，将壶铃传递到左大腿下方。 继续交替弓步并在双手之间传递壶铃，达到所需的重复次数。"},{"id":"0537","name_zh":"壶铃单臂翻挺举","target":"肩","media_id":"vzAxBtt","instructions_zh":"双脚分开与肩同宽站立，一只手握住壶铃，正手握住。 稍微弯曲膝盖并以臀部为铰链，将壶铃放在两腿之间。 爆发性地伸展你的臀部、膝盖和脚踝，利用动量将壶铃摆动到肩膀的高度。 当壶铃到达肩膀高度时，旋转手腕并向上挥拳，将手臂锁定在头顶上方。 将壶铃放回起始位置，然后重复所需的重复次数。"},{"id":"1298","name_zh":"壶铃单臂地板推举","target":"胸","media_id":"rg59QCH","instructions_zh":"仰卧在地板上，膝盖弯曲，双脚平放在地面上。 一只手握住壶铃，手掌朝向脚部，手臂笔直向上伸向天花板。 弯曲肘部，慢慢将壶铃降低到胸部，保持上臂靠近身体。 当壶铃位于胸部正上方时暂停片刻，然后通过伸展肘部将壶铃推回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0538","name_zh":"壶铃单臂挺举","target":"肩","media_id":"S37C94C","instructions_zh":"双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。 稍微弯曲膝盖并启动核心。 将壶铃沿直线压过头顶，充分伸展手臂。 当你将壶铃举过头顶时，同时弯曲膝盖并快速伸直以产生动力。 当壶铃到达最高点时，弯曲膝盖和臀部，快速落到壶铃下方。 膝盖和臀部稍微弯曲，抓住壶铃，手臂完全伸过头顶。 站直，充分伸展膝盖和臀部，并将壶铃稳定在头顶上。 弯曲膝盖和臀部，将壶铃放回起始位置，然后重复所需的重复次数。"},{"id":"0539","name_zh":"壶铃单臂侧向推举","target":"肩","media_id":"yCvYdi7","instructions_zh":"双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。 启动你的核心并保持背部挺直。 将壶铃压过头顶，充分伸展手臂。 在顶部暂停片刻，然后慢慢将壶铃放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"0540","name_zh":"壶铃单臂借力推举","target":"肩","media_id":"osdXT3K","instructions_zh":"双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。 稍微弯曲膝盖并启动核心。 伸展手臂并完全伸展双腿，将壶铃压过头顶。 弯曲膝盖并将壶铃放回肩膀，将壶铃放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"0541","name_zh":"壶铃单臂划船","target":"上背部","media_id":"g9AsZ8P","instructions_zh":"双脚分开与肩同宽站立，一只手握住壶铃，正手握住。 稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。 将壶铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。 在顶部暂停片刻，然后慢慢将壶铃放回起始位置。 重复所需的重复次数，然后换边并用另一只手臂重复。"},{"id":"0542","name_zh":"壶铃单臂抓举","target":"肩","media_id":"aXcUyKb","instructions_zh":"双脚分开与肩同宽站立，一只手将壶铃放在两腿之间。 稍微弯曲膝盖并铰接臀部，将壶铃降低到地面。 爆发性地伸展你的臀部和膝盖，利用动量将壶铃向上摆动到你的肩膀上。 当壶铃到达肩膀高度时，旋转你的手并将其直接击打到头顶，完全伸展你的手臂。 将壶铃放回到双腿之间，然后重复所需的重复次数。"},{"id":"0543","name_zh":"壶铃海盗式腿部练习","target":"肩","media_id":"kuXhl0o","instructions_zh":"双脚分开与肩同宽站立，一只手握住壶铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将壶铃举至肩膀高度，保持肘部靠近身体。 将手臂完全伸过头顶，伸直肘部。 将壶铃降低至肩膀高度，然后返回起始位置。 重复所需的重复次数，然后换边。"},{"id":"0544","name_zh":"壶铃手枪深蹲","target":"臀部","media_id":"5bpPTHv","instructions_zh":"双脚分开与肩同宽站立，双手握住壶铃放在胸前。 将左脚抬离地面并向前伸展，保持与地面平行。 慢慢地将身体降低到蹲姿，保持右脚平放在地面上，左腿伸展。 在深蹲底部暂停片刻，然后推动右脚跟返回到起始位置。 重复所需的重复次数，然后换腿。"},{"id":"0545","name_zh":"壶铃爆发俯卧撑","target":"胸","media_id":"ktf3nvW","instructions_zh":"从高平板支撑位置开始，双手放在壶铃上，距离与肩同宽。 将胸部压向地面，保持肘部靠近身体。 爆发性地推动你的手，将你的手从壶铃上抬起并完全伸展你的手臂。 轻轻地回到壶铃上，并立即降低胸部以进行下一次重复。 重复所需的重复次数。"},{"id":"0546","name_zh":"壶铃坐姿推举","target":"肩","media_id":"BkxB8LW","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 每只手握住一个壶铃，与肩同高，手掌朝前。 将壶铃压过头顶，充分伸展手臂。 将壶铃降低至肩膀高度。 重复所需的重复次数。"},{"id":"1438","name_zh":"壶铃坐姿双臂军事推举","target":"肩","media_id":"ZEkjZDi","instructions_zh":"坐在长凳上，背部挺直，双脚平放在地上。 每只手握住一个壶铃，与肩同高，手掌朝前。 完全伸展双臂，将壶铃压过头顶。 在顶部暂停片刻，然后慢慢将壶铃放回肩部水平。 重复所需的重复次数。"},{"id":"0547","name_zh":"壶铃交替推举","target":"肩","media_id":"UDm6cGl","instructions_zh":"双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。 将一个壶铃压过头顶，同时将另一个壶铃保持在肩膀高度。 将按下的壶铃降低至肩膀高度，同时将另一个壶铃压过头顶。 继续交替按压动作，形成跷跷板状的运动。 重复所需的重复次数。"},{"id":"0548","name_zh":"壶铃相扑高拉","target":"斜方肌","media_id":"8ARQ9Hw","instructions_zh":"站立，双脚分开比肩宽，脚趾朝外。 双手握住壶铃放在身体前方，手臂向下伸展。 弯曲膝盖，降低臀部至下蹲位置，保持背部挺直。 脚后跟发力，爆发性伸展臀部和膝盖，将壶铃拉向下巴。 当你向上拉壶铃时，保持肘部高且宽，并将肩胛骨挤压在一起。 将壶铃放回起始位置，然后重复所需的重复次数。"},{"id":"0549","name_zh":"壶铃摇摆","target":"臀部","media_id":"UHJlbu3","instructions_zh":"双脚分开与肩同宽站立，脚趾稍微向外。 双手握住壶铃放在身体前方，双臂伸展。 稍微弯曲膝盖并铰接臀部，将臀部向后推。 将壶铃在两腿之间向后摆动，保持手臂伸直并保持背部平坦。 利用臀部产生的动量，向前推动臀部并将壶铃摆动到肩膀高度。 让壶铃在双腿之间向下摆动，然后重复该动作达到所需的重复次数。"},{"id":"0550","name_zh":"壶铃火箭推","target":"肩","media_id":"yWxMvB5","instructions_zh":"首先，双脚分开与肩同宽站立，双手将壶铃放在胸前，手掌相对。 弯曲膝盖并将臀部向后推，保持挺胸、背部挺直，进入蹲姿。 当你到达深蹲底部时，爆发性地通过脚后跟站起来，同时将壶铃压过头顶。 在动作的最高点锁定你的手臂，完全伸展你的肘部。 通过反转动作，弯曲肘部并将重量放回胸部，将壶铃放回起始位置。 重复所需的重复次数。"},{"id":"0551","name_zh":"壶铃土耳其起立（深蹲式）","target":"臀部","media_id":"Ha7SZ3y","instructions_zh":"首先仰卧，双腿伸展，右手握住壶铃，手臂完全伸展到肩膀上方。 弯曲右膝，将右脚平放在地面上，保持左腿伸展。 压右脚，将臀部抬离地面，进入桥位。 将左腿滑到身体下方，弯曲左膝并将左脚平放在地面上。 将躯干向左旋转，将左手放在地面上以获得支撑。 压右脚和左手，将躯干抬离地面，形成跪姿。 从跪姿站起来，保持壶铃伸过头顶。 反向运动以返回到起始位置。 从左手的壶铃开始，在另一侧重复练习。"},{"id":"0552","name_zh":"壶铃双臂翻举","target":"肩","media_id":"7Ba7bQ2","instructions_zh":"双脚分开与肩同宽站立，双手握住壶铃放在大腿前，手掌朝向自己。 稍微弯曲膝盖并铰接臀部，将壶铃降低到地面。 爆发性伸展臀部和膝盖，利用动量将壶铃拉向肩膀。 当壶铃达到肩膀高度时，旋转手腕，将壶铃放在架子上，肘部内收，壶铃放在前臂背面。 将壶铃放回起始位置，然后重复所需的重复次数。"},{"id":"0553","name_zh":"壶铃双臂军事推举","target":"肩","media_id":"blBXysN","instructions_zh":"双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高，手掌朝前。 启动你的核心并将壶铃压过头顶，充分伸展你的手臂。 在顶部暂停片刻，然后慢慢将壶铃放回起始位置。 重复所需的重复次数。"},{"id":"1345","name_zh":"壶铃双臂划船","target":"上背部","media_id":"wf24o8S","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个壶铃，手掌朝向身体。 臀部向前弯曲，保持背部挺直，核心肌群参与。 将壶铃拉向胸部，将肩胛骨挤压在一起。 在顶部暂停片刻，然后慢慢将壶铃放回起始位置。 重复所需的重复次数。"},{"id":"0554","name_zh":"壶铃风车","target":"腹部","media_id":"9Tkqa9O","instructions_zh":"双脚分开与肩同宽站立，右手握住壶铃举过头顶。 将左脚向外旋转约 45 度，并保持右脚指向前方。 将你的躯干向左侧弯曲，保持右臂伸过头顶，眼睛盯着壶铃。 尽可能降低躯干，同时保持右臂伸直，左臂向一侧伸展。 暂停片刻，然后通过推动右脚并接合斜肌返回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0555","name_zh":"踢腿卷腹","target":"大腿后侧","media_id":"v7p5bYl","instructions_zh":"坐在长凳或椅子的边缘，双脚平放在地上，膝盖弯曲成 90 度角。 稍微向后倾斜，将双手放在长凳或椅子的边缘以获得支撑。 启动腿筋，将脚抬离地面，并将双腿伸直到身前。 在顶部停顿片刻，然后慢慢弯曲膝盖，将脚放回身体。 重复所需的重复次数。"},{"id":"0558","name_zh":"借力双力臂","target":"背阔肌","media_id":"pM07UxU","instructions_zh":"首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。 启动你的核心并使用摆动动作来产生动力。 当你向前挥杆时，将胸部拉向杠铃，用背阔肌和二头肌开始动作。 继续向上运动，直到胸部到达杠铃，然后向下推杠铃并伸展手臂，过渡到双臂屈伸姿势。 弯曲手臂并控制下降，将自己放回到起始位置。 重复所需的重复次数。"},{"id":"3640","name_zh":"触膝卷腹","target":"腹部","media_id":"dTg95eZ","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，将肩胛骨抬离地面，并将右手伸向左膝盖。 返回起始位置并重复，这次将左手伸向右膝盖。 继续交替进行所需的重复次数。"},{"id":"1420","name_zh":"跪姿跳蹲","target":"臀部","media_id":"UgDm3oy","instructions_zh":"首先跪在地上，双脚分开与臀部同宽，脚趾向前。 将杠铃放在上背部，将其放在肩膀上。 启动你的核心和臀部，然后爆发性地跳到空中，伸展你的臀部和膝盖。 跳跃时，用脚趾推动并充分伸展脚踝、膝盖和臀部。 轻轻地回到地面，弯曲膝盖以吸收冲击力。 立即进入下一个重复，重复跳蹲动作。"},{"id":"1346","name_zh":"跪姿背阔肌拉伸","target":"背阔肌","media_id":"f38OEuO","instructions_zh":"跪在地上，膝盖分开与臀部同宽，脚趾向后。 将双臂伸过头顶，手指交叉。 保持背部挺直，慢慢向右侧倾斜，感受左侧背阔肌的拉伸。 保持伸展动作 20-30 秒，然后回到起始位置。 在左侧重复该拉伸动作，向左侧倾斜，感受右侧背阔肌的拉伸。 继续交替进行所需的重复次数。"},{"id":"3239","name_zh":"跪姿平板触肩（男）","target":"腹部","media_id":"h1ezqSu","instructions_zh":"从跪姿开始，双手放在地上，与肩同宽。 将双腿伸到身后，用脚趾支撑，将身体抬起成平板支撑姿势。 保持核心参与并保持臀部稳定，将一只手抬离地面并拍打另一侧的肩膀。 将手放回地面并用另一只手重复此操作。 继续交替进行所需的重复次数。"},{"id":"3211","name_zh":"跪姿俯卧撑（男）","target":"胸","media_id":"ZOuKWir","instructions_zh":"首先跪在地上，双手与肩同宽，手指指向前方。 将双腿伸到身后，放在脚掌上，使身体从头到脚跟形成一条直线。 弯曲肘部，保持核心靠近身体两侧，将身体压向地面。 继续降低，直到胸部刚好高于地面，然后伸直手臂，将其推回起始位置。 重复所需的重复次数。"},{"id":"3288","name_zh":"韩式臂屈伸","target":"胸","media_id":"rWoBmi5","instructions_zh":"将自己定位在两个双杠之间，双臂伸展并支撑体重。 弯曲肘部降低身体，直到上臂与地面平行。 暂停片刻，然后伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"3418","name_zh":"L字引体向上","target":"背阔肌","media_id":"d1GgzTU","instructions_zh":"正手握住引体向上杆，握距略宽于肩宽。 双臂完全伸展，身体伸直。 收紧背阔肌和二头肌，将身体拉向杠铃杆，保持肘部靠近身体。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"3419","name_zh":"地面L字支撑","target":"腹部","media_id":"UpWmA5E","instructions_zh":"坐在地板上，双腿伸到身前。 将双手放在臀部旁边的地板上，手指指向前方。 启动你的核心并将双腿抬离地面，保持伸直。 尝试使双腿与地面平行，与身体形成“L”形。 尽可能长时间地保持这个姿势。 慢慢地将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0562","name_zh":"地雷杠180度旋转","target":"腹部","media_id":"QYysSLV","instructions_zh":"双脚分开与肩同宽站立，双手握住杠铃于胸前。 稍微弯曲膝盖并将躯干向右旋转，将杠铃向下朝右臀部摆动。 当你到达动作的底部时，快速反向运动并向左旋转你的躯干，向上摆动杠铃并穿过你的身体朝向左肩。 继续这个扭转动作，两侧交替，达到所需的重复次数。"},{"id":"3237","name_zh":"地雷杠侧平举","target":"肩","media_id":"eXMFHww","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 正手握住杠铃，将其放在肩膀前面。 保持核心收紧并保持背部挺直，将杠铃向上举起并远离身体，将其提升至肩膀高度。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"3300","name_zh":"前倾俄挺","target":"腹部","media_id":"LYJodFS","instructions_zh":"从俯卧撑位置开始，双手分开与肩同宽，身体伸直。 启动你的核心，慢慢地将你的重心向前移动，让你的肩膀越过你的手。 向前倾时，保持肘部稍微弯曲，身体伸直。 保持这个姿势几秒钟，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"2271","name_zh":"左勾拳（拳击）","target":"肩","media_id":"hoXt6wv","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 左手举起以保护脸部，右手握住下巴。 旋转臀部并以左脚为轴心，同时以出拳动作向前伸展左臂。 扭转你的躯干并调动你的核心肌肉以产生出拳的力量。 将手臂拉回到起始位置，然后重复所需的重复次数。"},{"id":"0570","name_zh":"平板凳屈腿收腹","target":"腹部","media_id":"OyoZ3Pu","instructions_zh":"坐在平坦的长凳上，双腿在身前伸直。 将双手放在臀部旁边的长凳上以获得支撑。 收紧腹肌，将双腿抬离地面，使膝盖靠近胸部。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"1576","name_zh":"抬腿腘绳肌拉伸","target":"大腿后侧","media_id":"sU5BrfP","instructions_zh":"平躺，双腿伸展。 弯曲一侧膝盖，将其靠近胸部，握住大腿或小腿。 尽可能伸直腿，同时保持腿抬高。 保持拉伸 20-30 秒。 换另一条腿重复上述步骤。"},{"id":"2287","name_zh":"杠杆交替腿举","target":"股四头肌","media_id":"V07qpXy","instructions_zh":"将杠杆机的座椅和脚踏平台调整到您想要的位置。 坐在机器上，背部靠在靠背上，双脚放在脚踏板上。 将手放在机器的手柄或侧面以保持稳定性。 将一只脚推到脚平台上，伸展腿直到几乎完全伸直。 暂停片刻，然后慢慢弯曲腿，回到起始位置。 换另一条腿重复上述步骤。 继续交替双腿达到所需的重复次数。"},{"id":"0571","name_zh":"杠杆交替窄握坐姿划船","target":"上背部","media_id":"w2oRpuH","instructions_zh":"调整座椅高度和踏板位置以确保正确对齐。 坐在机器上，背部挺直，双脚平放在踏板上。 紧紧握住手柄，手掌相对。 在整个练习过程中保持挺胸、肩膀向后。 将一个手柄拉向您的躯干，同时保持另一个手柄静止。 在动作结束时将肩胛骨挤压在一起。 慢慢地将手柄返回到起始位置，并在另一侧重复此操作。 继续交替进行所需的重复次数。"},{"id":"0572","name_zh":"杠杆辅助引体向上","target":"背阔肌","media_id":"MaMuGH6","instructions_zh":"将杠杆机调整至您想要的阻力水平。 站在脚踏板上，正手握住手柄，握距略宽于肩宽。 双臂完全伸展，保持身体挺直。 收紧背部肌肉，将身体拉向手柄，以胸部为主导。 继续拉，直到下巴位于手柄上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"0573","name_zh":"杠杆背部伸展","target":"脊柱","media_id":"rUXfn3R","instructions_zh":"调整机器以适合您的身体尺寸和运动范围。 坐在机器上，背部靠在垫子上，双脚固定。 将手放在手柄或握杆上。 启动你的核心并慢慢向前倾斜，让你的背部稍微弯曲。 在底部位置暂停片刻，感觉下背部有拉伸感。 使用背部肌肉，慢慢将躯干抬回到起始位置。 重复所需的重复次数。"},{"id":"0574","name_zh":"杠杆俯身划船","target":"上背部","media_id":"X3cqyXz","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 正手握住杠铃，双手分开略宽于肩宽。 臀部向前弯曲，保持背部挺直，挺胸。 将杠铃拉向下胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"3200","name_zh":"杠杆V杠俯身划船","target":"上背部","media_id":"LuBEORI","instructions_zh":"调整座椅高度并将自己面向机器。 正手握住 V 形杆，保持背部挺直，膝盖稍微弯曲。 将 V 形杆拉向腹部，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢释放重量回到起始位置。 重复所需的重复次数。"},{"id":"0575","name_zh":"杠杆二头弯举","target":"肱二头肌","media_id":"q6y3OhV","instructions_zh":"调整座椅高度并将自己放在机器上，背部靠在垫子上。 反手握住手柄，手掌朝上，肘部靠近身体两侧。 呼气并向上弯曲手柄，收缩二头肌。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气，慢慢将手柄放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"2289","name_zh":"杠杆小腿推举","target":"小腿","media_id":"7B4F5nZ","instructions_zh":"调整杠杆机的座椅，使肩膀与杠杆垫对齐。 将脚趾放在杠杆垫上，脚跟悬在边缘上。 抓住手柄或侧面支撑以保持稳定性。 伸展脚踝，收缩小腿肌肉，将杠杆垫向下推。 在动作的底部停顿片刻。 让脚后跟重新抬起，慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0577","name_zh":"杠杆胸推","target":"胸","media_id":"T0yTjgW","instructions_zh":"调整座椅高度，将自己放在机器上，背部平放在垫子上。 正手握住手柄，肘部呈 90 度角。 向前推动手柄，直到手臂完全伸展，运动过程中呼气。 动作结束时短暂暂停，然后慢慢回到起始位置，同时吸气。 重复所需的重复次数。"},{"id":"0576","name_zh":"杠杆胸推","target":"胸","media_id":"DOoWcnA","instructions_zh":"调整座椅高度，将自己放在机器上，背部平放在垫子上。 正手握住手柄，肘部呈 90 度角。 向前推动手柄，直到手臂完全伸展，运动过程中呼气。 动作结束时短暂暂停，然后慢慢回到起始位置，同时吸气。 重复所需的重复次数。"},{"id":"0578","name_zh":"器械硬拉","target":"臀部","media_id":"GUT8I22","instructions_zh":"将座椅高度和脚踏板调整到您想要的位置。 坐在机器上，背部靠在垫子上，双脚平放在脚踏板上。 抓住把手或座椅侧面以保持稳定性。 收紧臀肌和腿筋，并通过脚后跟推动举重。 保持背部挺直，避免圆肩。 在动作的最高点完全伸展臀部，挤压臀部。 以受控的方式降低重量，保持臀肌和腿筋的张力。 重复所需的重复次数。"},{"id":"1300","name_zh":"器械下斜胸推","target":"胸","media_id":"vsVoPHt","instructions_zh":"将杠杆机的座椅高度和靠背调整到舒适的位置。 坐在机器上，背部靠在靠背上，双脚平放在地板上。 正手握住手柄，双手之间的距离略大于肩宽。 向前推动手柄并使其远离身体，直到双臂完全伸展。 慢慢地将手柄放回胸部，保持肘部稍微弯曲。 在底部暂停片刻，然后将手柄推回起始位置。 重复所需的重复次数。"},{"id":"1253","name_zh":"器械驴式提踵","target":"小腿","media_id":"C9LuR4A","instructions_zh":"将杠杆机调节至适合您身体的高度。 面向机器定位，脚趾放在脚踏平台上，脚后跟悬在边缘。 将手放在手柄或支撑杆上以保持稳定性。 用脚掌收紧小腿并尽可能高地抬起脚后跟。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0579","name_zh":"器械前下拉","target":"背阔肌","media_id":"7F1DVzn","instructions_zh":"调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。 正手握住手柄，握距略宽于肩宽。 坐直，胸部抬起，肩膀向后，保持下背部轻微的拱形。 收紧背阔肌，将手柄向下拉向胸部，将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"0580","name_zh":"器械无握把耸肩","target":"斜方肌","media_id":"f91FwXG","instructions_zh":"调整座椅高度并将自己放在杠杆机上。 手掌朝内，抓住手柄，双臂完全伸展。 保持背部挺直，呼气并尽可能抬高肩膀。 保持收缩一会儿，然后吸气并慢慢将肩膀放回起始位置。 重复所需的重复次数。"},{"id":"1439","name_zh":"器械无握把耸肩 v. 2","target":"斜方肌","media_id":"cbuFJrn","instructions_zh":"调整座椅高度并将自己放在机器上，背部靠在垫子上。 正手握住手柄或杆，保持手臂伸直。 保持背部挺直，将肩膀尽可能高地抬向耳朵。 保持收缩一会儿，然后慢慢将肩膀放回起始位置。 重复所需的重复次数。"},{"id":"2288","name_zh":"器械双手握力器","target":"前臂","media_id":"mKwcrHn","instructions_zh":"调整座椅高度并握住杠杆机的手柄。 保持背部挺直，双脚平放在地面上。 呼气并挤压手柄，收缩前臂。 保持收缩一秒钟，然后慢慢释放并返回到起始位置。 重复所需的重复次数。"},{"id":"1615","name_zh":"器械锤式握法牧师凳弯举","target":"肱二头肌","media_id":"OAguZoG","instructions_zh":"调整座椅高度并将自己放在杠杆机上。 将你的上臂放在讲道垫上，确保你的胸部压在上面。 用锤子握把抓住手柄（手掌相对）。 保持上臂静止，呼气并将手柄卷向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气并慢慢将手柄放回起始位置。 重复所需的重复次数。"},{"id":"0581","name_zh":"器械高位划船","target":"上背部","media_id":"nZZZy9m","instructions_zh":"将座椅高度和脚踏板调整至舒适的位置。 坐在机器上，胸部靠在垫子上，双脚平放在脚踏平台上。 正手握住手柄，握距略宽于肩宽。 保持背部挺直并启动核心肌群。 将手柄拉向身体，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"2286","name_zh":"器械髋后伸 v. 2","target":"臀部","media_id":"OPqShYN","instructions_zh":"调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。 将脚放在脚踏板上并握住手柄以保持稳定。 启动臀肌和腿筋，然后推动脚踏板以伸展臀部并向后抬起双腿。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"2611","name_zh":"器械水平单腿推举","target":"臀部","media_id":"9KU9TYF","instructions_zh":"调整机器座椅，使双脚放在踏板上时膝盖呈 90 度角。 坐在机器上，背部靠在靠背上，双脚与肩同宽放在踏板上。 将手放在机器的手柄或侧面以保持稳定性。 伸展腿，使背部紧靠靠背，将踏板推离身体。 在完全伸展位置暂停片刻，然后慢慢弯曲腿回到起始位置。 重复所需的重复次数，然后换腿。"},{"id":"1299","name_zh":"器械上斜胸推","target":"胸","media_id":"jHAnWmT","instructions_zh":"将杠杆机的座椅和靠背调整到舒适的位置。 坐在机器上，背部靠在靠背上，双脚平放在地板上。 正手握住手柄，双手之间的距离略大于肩宽。 向前推动手柄并使其远离身体，直到双臂完全伸展。 暂停片刻，然后慢慢弯曲肘部，将手柄放回到胸部。 重复所需的重复次数。"},{"id":"1479","name_zh":"器械上斜胸推 v. 2","target":"胸","media_id":"o17Jfkt","instructions_zh":"将杠杆机上的座椅高度和靠背角度调整到舒适的位置。 坐在机器上，背部靠在靠背上，双脚平放在地板上。 正手握住手柄，双手之间的距离略大于肩宽。 向前推动手柄并远离身体，直到手臂完全伸展，但不要锁定肘部。 在完全伸展的位置暂停片刻，然后慢慢弯曲肘部并将手柄放回胸部。 重复所需的重复次数。"},{"id":"0582","name_zh":"器械跪姿腿弯举","target":"大腿后侧","media_id":"nnmCTLN","instructions_zh":"调整机器以适合您的身体并选择所需的重量。 面朝下跪在机器上，膝盖放在垫子上，双脚固定在脚垫下。 抓住机器的手柄或侧面以保持稳定性。 保持上半身静止，呼气，弯曲膝盖，将双腿向臀肌方向卷起。 在动作的最高点暂停片刻，挤压你的腿筋。 吸气，慢慢将双腿放回起始位置，充分伸展膝盖。 重复所需的重复次数。"},{"id":"0583","name_zh":"器械跪姿扭转","target":"腹部","media_id":"sZOR9EV","instructions_zh":"调整座椅高度，将自己放在机器上，膝盖放在垫子上，上半身朝前。 抓住机器的手柄或侧面以保持稳定性。 保持核心参与，将躯干尽可能舒适地向一侧扭转。 暂停片刻，然后慢慢回到起始位置。 向另一侧重复扭转。 继续交替进行所需的重复次数。"},{"id":"0584","name_zh":"器械侧平举","target":"肩","media_id":"dRTfGZT","instructions_zh":"调整座椅高度并将自己放在机器上，背部靠在垫子上。 正手握住手柄并保持手臂伸直。 呼气并将手臂向两侧抬起，直到与地板平行。 在顶部停顿片刻，然后吸气，慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0585","name_zh":"器械腿屈伸","target":"股四头肌","media_id":"my33uHU","instructions_zh":"调整机器的座椅高度和靠背以适合您的身体。 坐在机器上，背部靠在靠背上，双脚放在脚垫上。 抓住手柄或侧杆以保持稳定性。 伸直膝盖，举起重物，向前伸展双腿。 在顶部暂停片刻，然后慢慢将重量放回起始位置。 重复所需的重复次数。"},{"id":"0586","name_zh":"器械俯卧腿弯举","target":"大腿后侧","media_id":"17lJ1kr","instructions_zh":"调整机器以适合您的身体并选择所需的重量。 面朝下躺在机器上，双腿伸直，脚跟靠在带衬垫的杠杆上。 抓住机器的手柄或侧面以保持稳定性。 保持上半身静止，呼气并尽可能向上弯曲双腿，但不要将臀部抬离垫子。 挤压腿筋时，保持收缩位置短暂停顿。 吸气并缓慢地将控制杆降低回起始位置。 重复所需的重复次数。"},{"id":"3195","name_zh":"器械俯卧双腿单腿弯举","target":"大腿后侧","media_id":"UXpKJoq","instructions_zh":"调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。 将双腿放在脚踝上方的杠杆垫上。 抓住机器两侧的手柄以提供支撑。 保持上半身不动，呼气并将双腿向上弯曲至臀部。 在顶部停顿片刻，然后吸气，慢慢降低双腿回到起始位置。 重复所需的重复次数。"},{"id":"0587","name_zh":"器械站姿推举","target":"肩","media_id":"CggQhII","instructions_zh":"调整座椅高度并将自己放在机器上，背部靠在靠背上。 正手握住手柄，双手之间的距离略大于肩宽。 向上推动手柄，直到手臂完全伸展，但不要锁住肘部。 在顶部暂停片刻，然后慢慢将手柄放回起始位置。 重复所需的重复次数。"},{"id":"0588","name_zh":"器械窄握坐姿划船","target":"上背部","media_id":"IGjKj1v","instructions_zh":"调整座椅高度和脚踏板以确保形状正确。 坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。 紧紧握住手柄，手掌相对。 保持背部挺直并稍微向前倾斜。 将手柄拉向躯干，将肩胛骨挤压在一起。 在动作的最高点停顿片刻。 慢慢松开手柄并返回到起始位置。 重复所需的重复次数。"},{"id":"0589","name_zh":"器械单臂俯身划船","target":"上背部","media_id":"Fhdtwf3","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲，正手握住杠铃。 臀部向前弯曲，保持背部挺直，头部抬起。 让杠铃悬挂在你面前，双臂完全伸展。 将杠铃拉向胸部，保持肘部靠近身体。 在动作的最高点将肩胛骨挤压在一起。 将杠铃降低回到起始位置。 重复所需的重复次数。"},{"id":"1356","name_zh":"器械单臂侧高位划船","target":"上背部","media_id":"OIFMAp1","instructions_zh":"调整座椅高度并将自己面向机器。 用一只手抓住手柄并保持背部挺直。 将手柄拉向身体，保持肘部靠近身体两侧。 在动作的最高点挤压背部肌肉。 慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"1347","name_zh":"器械单臂侧宽位下拉","target":"背阔肌","media_id":"tTuZSDT","instructions_zh":"调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。 正手握住手柄，完全伸展手臂，保持肘部轻微弯曲。 将手柄向下拉，穿过身体向对面的臀部方向拉，在动作底部挤压背阔肌。 慢慢地将手柄返回到起始位置，完全伸展手臂。 重复所需的重复次数，然后换边。"},{"id":"0590","name_zh":"器械单臂肩推","target":"肩","media_id":"2KGnL6M","instructions_zh":"调整座椅高度并将自己放在机器上，背部靠在垫子上。 用一只手抓住杠杆手柄，并将肘部置于 90 度角。 向上按下控制杆，直到手臂完全伸过头顶。 在顶部暂停片刻，然后慢慢将控制杆放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"0591","name_zh":"器械正握三头臂屈伸","target":"肱三头肌","media_id":"D5yqP2p","instructions_zh":"将机器调整到合适的高度并将身体固定到位。 正手握住手柄，调整身体位置，使手臂完全伸展。 弯曲肘部降低身体，保持上臂靠近身体两侧。 继续降低，直到上臂与地板平行。 暂停片刻，然后伸展肘部将自己推回起始位置。 重复所需的重复次数。"},{"id":"0592","name_zh":"器械牧师凳弯举","target":"肱二头肌","media_id":"b6hQYMb","instructions_zh":"调整座椅高度并将自己放在杠杆机上。 将上臂放在垫子上，并用反手握住手柄。 保持背部挺直，并将肘部放在垫子上。 呼气并将前臂向上臂弯曲，收缩二头肌。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气并慢慢将手柄放回起始位置。 重复所需的重复次数。"},{"id":"1614","name_zh":"器械牧师凳弯举 v. 2","target":"肱二头肌","media_id":"ye84CTU","instructions_zh":"调整座椅高度，将自己放在机器上，上臂放在垫子上，胸部靠在支撑物上。 反手握住手柄，握距略宽于肩宽。 保持上臂静止，呼气，同时将手柄向肩膀卷曲，收缩二头肌。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气，慢慢将手柄放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"2285","name_zh":"器械臂拉过","target":"背阔肌","media_id":"4U7iLb5","instructions_zh":"将杠杆机的座椅和手柄调整到舒适的位置。 坐在机器上，背部靠在垫子上，并用正手握住手柄。 保持手臂稍微弯曲，核心肌群参与。 慢慢地将手柄拉向胸部，挤压背阔肌。 在收缩高峰时暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"2736","name_zh":"器械反握高位下拉","target":"背阔肌","media_id":"ky8FLU8","instructions_zh":"调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。 正手握住手柄，握距略宽于肩宽。 坐直，挺胸，肩膀向后，保持下背部轻微的拱形。 将手柄向下拉向胸部，用肘部引导并将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"1616","name_zh":"器械反握牧师凳弯举","target":"肱二头肌","media_id":"kj3hy6W","instructions_zh":"调整座椅高度并将自己放在杠杆机上。 反手握住手柄，手掌朝上。 将上臂放在牧师垫上，确保肘部完全伸展。 保持上臂静止，呼气并将手柄卷向肩膀。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气，慢慢将手柄放回起始位置，充分伸展肘部。 重复所需的重复次数。"},{"id":"1348","name_zh":"器械反握直立划船","target":"上背部","media_id":"ZqNOWQ6","instructions_zh":"调整座椅高度和踏板位置以确保正确对齐。 坐在机器上，胸部靠在垫子上，双脚平放在踏板上。 反手握住手柄，手掌朝上。 保持背部挺直并启动核心肌群。 将手柄拉向胸部，将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。 重复所需的重复次数。"},{"id":"0593","name_zh":"器械反向背伸展","target":"臀部","media_id":"Krmb3cB","instructions_zh":"调整杠杆机以适合您的身体并将双脚固定在脚垫中。 面朝下躺在机器上，上半身悬在机器边缘，臀部放在垫子上。 双臂交叉放在胸前或放在脑后。 用臀部和腿筋将双腿向上抬起，直到它们与地面平行。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"1349","name_zh":"器械反握T杠划船","target":"上背部","media_id":"BgljGjd","instructions_zh":"调整杠杆机上的座椅高度和踏板位置。 坐在机器上，胸部靠在垫子上，双脚平放在踏板上。 正手握住手柄，握距略宽于肩宽。 保持背部挺直并启动核心肌群。 将手柄拉向胸部，将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。 重复所需的重复次数。"},{"id":"2315","name_zh":"器械旋转提踵","target":"小腿","media_id":"MrgP9L6","instructions_zh":"调整座椅高度，使膝盖稍微弯曲，双脚平放在踏板上。 将脚趾放在踏板上，脚跟悬在踏板边缘。 抓住机器的手柄或侧面以保持稳定性。 用脚掌推动，尽可能高地抬高脚后跟。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"2335","name_zh":"杠杆坐姿小腿推举","target":"小腿","media_id":"Ie9UGty","instructions_zh":"调整机器的座椅，使您的肩膀与杠杆垫对齐。 将脚趾放在平台的下部，并将膝盖放在杠杆垫下方。 抓住座椅两侧的把手以保持稳定性。 伸展脚踝，将杠杆垫压下，尽可能高地抬起脚后跟。 在动作的最高点暂停片刻，然后慢慢降低脚跟回到起始位置。 重复所需的重复次数。"},{"id":"0594","name_zh":"杠杆坐姿提踵","target":"小腿","media_id":"bOOdeyc","instructions_zh":"调整座椅高度，使膝盖稍微弯曲，双脚平放在踏板上。 将脚趾放在踏板上，脚跟悬在踏板边缘。 抓住把手或座椅侧面以保持稳定性。 推动脚掌，将脚后跟尽可能抬高。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1452","name_zh":"杠杆坐姿卷腹","target":"腹部","media_id":"Wgaz7pm","instructions_zh":"坐在杠杆机上，背部靠在垫子上，双脚平放在地板上。 抓住手柄或将手放在侧垫上以获得支撑。 收紧腹肌并慢慢向后倾斜，让垫子随着您一起移动。 一旦你的上半身呈 45 度角，收缩腹肌并向前卷腹，使胸部靠近膝盖。 在顶部停顿片刻，然后慢慢松开并返回到起始位置。 重复所需的重复次数。"},{"id":"0595","name_zh":"杠杆坐姿卷腹（带胸垫）","target":"腹部","media_id":"ZnJHhMk","instructions_zh":"根据您的舒适度调整座椅高度和胸垫位置。 坐在机器上，背部靠在胸垫上，双脚平放在地板上。 抓住手柄或侧杆以保持稳定性。 收紧腹肌并慢慢向后倾斜，让胸垫随着您一起移动。 在最大收缩时暂停片刻，感受腹肌的紧张感。 收缩腹肌并将自己拉回来，慢慢回到起始位置。 重复所需的重复次数。"},{"id":"3760","name_zh":"杠杆坐姿卷腹 v.2","target":"腹部","media_id":"eXFXCY0","instructions_zh":"坐在杠杆机上，背部靠在垫子上，双脚固定在脚垫下。 将手放在把手上或座椅两侧以获得支撑。 收紧腹肌，慢慢向前挺胸，使胸部靠近膝盖。 在动作的最高点暂停片刻，挤压腹肌。 慢慢回到起始位置，让背部稍微弯曲。 重复所需的重复次数。"},{"id":"1451","name_zh":"杠杆坐姿臂屈伸","target":"肱三头肌","media_id":"BRImeP8","instructions_zh":"调整座椅高度，使双脚平放在地面上，膝盖呈 90 度角。 手掌朝下，抓住杠杆机的手柄，双臂完全伸展。 弯曲肘部，慢慢降低身体，直到上臂与地面平行。 暂停片刻，然后伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"0596","name_zh":"杠杆坐姿夹胸","target":"胸","media_id":"v3xmPAR","instructions_zh":"调整座椅高度并将自己放在机器上，背部靠在垫子上。 旋前抓住手柄，并保持肘部稍微弯曲。 呼气并将手柄向前推，将它们放在胸前。 暂停片刻，挤压胸部肌肉。 吸气并慢慢回到起始位置，让胸部肌肉伸展。 重复所需的重复次数。"},{"id":"3759","name_zh":"杠杆坐姿早安式","target":"臀部","media_id":"XsCcxCC","instructions_zh":"调整座椅高度，使臀部略高于膝盖。 坐在机器上，背部靠在垫子上，双脚平放在脚踏板上。 抓住把手或座椅侧面以保持稳定性。 保持背部挺直，从臀部开始慢慢向前倾斜，直到上半身与地面平行。 暂停片刻，然后通过推动臀肌和腿筋慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0597","name_zh":"杠杆坐姿髋外展","target":"外展肌","media_id":"CHpahtl","instructions_zh":"调整座椅高度，使膝盖成 90 度角。 坐在机器上，背部靠在靠背上，双脚放在脚踏板上。 将手放在侧手柄上以保持稳定性。 启动外展肌并慢慢将双腿分开，远离身体中线。 动作结束时暂停片刻，然后慢慢将双腿放回到起始位置。 重复所需的重复次数。"},{"id":"0598","name_zh":"杠杆坐姿髋内收","target":"内收肌","media_id":"oHsrypV","instructions_zh":"调整座椅高度并将自己放在机器上，背部靠在靠背上。 将脚放在脚踏板上并抓住手柄以保持稳定。 收紧内收肌，慢慢将双腿并拢，挤压大腿内侧。 在收缩高峰时暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0599","name_zh":"杠杆坐姿腿弯举","target":"大腿后侧","media_id":"Zg3XY7P","instructions_zh":"调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。 将小腿放在带衬垫的杠杆下方，就在脚踝上方。 抓住机器两侧的手柄以提供支撑。 保持大腿不动，呼气并尽可能向上弯曲双腿。 挤压腿筋时，保持收缩位置短暂停顿。 吸气并缓慢地将控制杆降低回起始位置。 重复所需的重复次数。"},{"id":"0600","name_zh":"杠杆坐姿抬腿卷腹","target":"腹部","media_id":"PQ2AtC3","instructions_zh":"坐在杠杆机上，背部靠在靠背上，双脚放在脚踏板上。 抓住手柄或侧杆以保持稳定性。 收紧腹肌，慢慢地将双腿抬向胸部，同时向前卷曲躯干。 在顶部停顿片刻，然后慢慢降低双腿和躯干回到起始位置。 重复所需的重复次数。"},{"id":"0602","name_zh":"杠杆坐姿反向飞鸟","target":"肩","media_id":"myfUsKf","instructions_zh":"调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。 正手握住手柄，并保持手臂稍微弯曲。 呼气并将肩胛骨挤压在一起，同时向后和向外拉动手柄，使其远离身体。 在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0601","name_zh":"杠杆坐姿反向飞鸟（平行握）","target":"肩","media_id":"xiHiJcA","instructions_zh":"调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。 平行握住手柄，手掌相对，并保持手臂稍微弯曲。 呼气并将肩胛骨挤压在一起，同时向后和向外拉动手柄，使其远离身体。 在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。 重复所需的重复次数。"},{"id":"1350","name_zh":"杠杆坐姿划船","target":"上背部","media_id":"7I6LNUG","instructions_zh":"将座椅高度和脚踏板调整到舒适的位置。 坐在机器上，胸部靠在垫子上，双脚放在脚踏板上。 正手握住手柄，距离与肩同宽。 保持背部挺直，核心肌群参与。 将手柄拉向身体，将肩胛骨挤压在一起。 在动作的最高点停顿片刻。 慢慢松开手柄并返回到起始位置。 重复所需的重复次数。"},{"id":"1385","name_zh":"杠杆坐姿深蹲提踵（腿举机）","target":"小腿","media_id":"IeDEXTe","instructions_zh":"调整压腿机的座椅，使双脚放在踏板上时膝盖稍微弯曲。 坐在机器上，背部靠在靠背上，双脚平放在踏板上，与肩同宽。 将脚趾和脚掌放在踏板上，使脚后跟远离边缘。 松开安全手柄，并通过伸展膝盖将踏板推离您。 一旦膝盖完全伸展，弯曲小腿，慢慢降低脚后跟。 在底部停顿片刻，然后通过伸展小腿将踏板向后推。 重复所需的重复次数。"},{"id":"0603","name_zh":"杠杆坐姿肩推","target":"肩","media_id":"67n3r98","instructions_zh":"调整座椅高度并将自己放在机器上，背部靠在靠背上。 正手握住手柄，并将双手置于肩部水平。 向上推动手柄，直到手臂完全伸展，但不要锁住肘部。 在顶部暂停片刻，然后慢慢将手柄放回起始位置。 重复所需的重复次数。"},{"id":"0869","name_zh":"杠杆坐姿肩推 v.2","target":"肩","media_id":"vqsbmL0","instructions_zh":"将杠杆机的座椅高度和靠背调整到舒适的位置。 坐在机器上，背部靠在靠背上，双脚平放在地板上。 正手握住机器的手柄，握距略宽于肩宽。 向上和向前推动手柄，直到手臂完全伸展，但未锁定。 在顶部暂停片刻，然后慢慢将手柄放回起始位置。 重复所需的重复次数。"},{"id":"2318","name_zh":"杠杆坐姿肩推 v.3","target":"肩","media_id":"dNFYIU1","instructions_zh":"将杠杆机的座椅高度和靠背调整到舒适的位置。 坐在机器上，背部靠在靠背上，双脚平放在地板上。 正手握住机器的手柄，握距略宽于肩宽。 向上和向前推动手柄，直到手臂完全伸展，但未锁定。 在顶部暂停片刻，然后慢慢将手柄放回起始位置。 重复所需的重复次数。"},{"id":"0604","name_zh":"杠杆耸肩","target":"斜方肌","media_id":"ZZKbeMw","instructions_zh":"调整座椅高度，将自己放在杠杆机上，背部靠在垫子上。 正手握住手柄并保持手臂伸直。 保持背部挺直，将肩膀尽可能高地抬向耳朵。 保持收缩一会儿，然后慢慢将肩膀放回起始位置。 重复所需的重复次数。"},{"id":"0605","name_zh":"杠杆站姿提踵","target":"小腿","media_id":"ykUOVze","instructions_zh":"将机器调整到您的高度，双脚分开与肩同宽站立。 将肩膀放在护垫下方，并握住手柄以保持稳定。 伸展脚踝，将脚后跟尽可能抬高。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"3758","name_zh":"杠杆站姿胸推","target":"胸","media_id":"WbNq5Xu","instructions_zh":"调整座椅高度并将自己放在机器上，双脚平放在地面上。 正手握住手柄，并将双手置于胸部水平。 向前推动手柄，直到手臂完全伸展，保持肘部稍微弯曲。 暂停片刻，然后慢慢地将手柄拉回到胸部，在整个动作过程中保持控制。 重复所需的重复次数。"},{"id":"0606","name_zh":"杠杆T杠划船","target":"上背部","media_id":"aaXr7ld","instructions_zh":"调整座椅高度和踏板位置以确保正确对齐。 坐在机器上，胸部靠在垫子上，双脚平放在踏板上。 正手握住手柄，握距略宽于肩宽。 保持背部挺直并启动核心肌群。 将手柄拉向躯干，将肩胛骨挤压在一起。 在收缩峰值时暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"1351","name_zh":"杠杆T杠反握划船","target":"上背部","media_id":"FVM1AUZ","instructions_zh":"调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。 正手握住手柄，握距略宽于肩宽。 保持背部挺直并启动核心肌群。 将手柄拉向胸部，将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。 重复所需的重复次数。"},{"id":"0607","name_zh":"杠杆臂屈伸","target":"肱三头肌","media_id":"Ser9eQp","instructions_zh":"调整座椅高度并将自己放在机器上，背部靠在垫子上。 正手握住手柄，并将手臂完全伸展到身前。 保持上臂不动，弯曲肘部，慢慢将手柄向前额降低。 在底部暂停片刻，然后伸展双臂将手柄推回起始位置。 重复所需的重复次数。"},{"id":"1313","name_zh":"杠杆单侧划船","target":"上背部","media_id":"oROuvrX","instructions_zh":"调整座椅高度并将自己面向机器。 正手握住手柄并保持背部挺直。 将手柄拉向身体，将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。 重复所需的重复次数。"},{"id":"0609","name_zh":"伦敦桥","target":"上背部","media_id":"bLyQokI","instructions_zh":"将绳子连接到高锚点。 背对锚点站立，双脚与肩同宽。 正手握住绳子，手掌朝下。 稍微向前倾，保持背部挺直，核心参与。 将绳子拉向身体，将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数。"},{"id":"3013","name_zh":"地板低位臀桥","target":"臀部","media_id":"u0cNiij","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将手臂放在身体两侧，手掌朝下。 启动臀肌和核心肌群，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。 在顶部暂停片刻，挤压臀部。 慢慢地将臀部放回起始位置。 重复所需的重复次数。"},{"id":"1352","name_zh":"下背卷曲","target":"脊柱","media_id":"ANbbry2","instructions_zh":"平躺，双腿伸直，双臂放在身体两侧。 收紧臀肌和腿筋，慢慢将上半身抬离地面，向上弯曲背部。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"3582","name_zh":"弓步跳","target":"臀部","media_id":"PM1PZjg","instructions_zh":"首先站立，双脚分开与肩同宽。 右脚向前迈出一步，将身体降低至弓步位置。 右脚蹬地，跳到空中，在空中改变脚的位置。 左脚向前轻柔落地，并立即将身体降低至弓步位置。 继续在弓步和跳跃之间交替进行所需的重复次数。"},{"id":"1688","name_zh":"弓步转体","target":"腹部","media_id":"K9VL0Jq","instructions_zh":"首先站立，双脚分开与肩同宽。 右脚向前迈出一步，将身体降低至弓步位置。 当你弓步时，将你的躯干向右扭转，将你的左肘拉向你的右膝盖。 暂停片刻，然后回到起始位置。 在另一侧重复，左脚向前迈出，并将躯干向左扭转。 继续交替进行所需的重复次数。"},{"id":"0613","name_zh":"侧卧股四头肌拉伸","target":"股四头肌","media_id":"BWnJR72","instructions_zh":"侧躺，双腿伸直。 弯曲上面的那条腿，用手抓住脚踝或脚。 轻轻地将脚踝或脚拉向臀部，直到感觉到股四头肌有拉伸感。 保持拉伸 20-30 秒。 松开拉伸并在另一侧重复。"},{"id":"2312","name_zh":"仰卧肘触膝","target":"腹部","media_id":"AQIhRjM","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，将上半身抬离地面，将右肘靠近左膝盖。 同时，将右腿伸直并抬离地面。 暂停片刻，然后回到起始位置。 重复该动作，这次将左肘移向右膝盖并伸展左腿。 继续交替进行所需的重复次数。"},{"id":"0620","name_zh":"平板凳仰卧举腿","target":"腹部","media_id":"WhuFnR7","instructions_zh":"平躺在平坦的长凳上，背部紧贴长凳。 将双手放在臀部下方以获得支撑。 保持双腿伸直并拢，然后将它们抬向天花板。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0865","name_zh":"仰卧抬腿抬髋","target":"腹部","media_id":"9IxJdtC","instructions_zh":"平躺，双腿伸展，双臂放在身体两侧。 将双手放在臀部下方以获得支撑。 启动你的核心并将双腿抬离地面，将它们抬向天花板。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"1301","name_zh":"器械内胸推","target":"胸","media_id":"wDN97Ca","instructions_zh":"调整座椅高度，将自己放在机器上，背部平放在垫子上。 正手握住手柄，肘部呈 90 度角。 向前推动手柄，直到手臂完全伸展，运动过程中呼气。 动作结束时暂停片刻，然后慢慢回到起始位置，同时吸气。 重复所需的重复次数。"},{"id":"0624","name_zh":"靠墙坐姿踏步","target":"臀部","media_id":"sVQCCeG","instructions_zh":"背靠墙站立，双脚分开与臀部同宽。 慢慢地将背部滑下墙壁，直到膝盖弯曲成 90 度角。 将右脚抬离地面，并将膝盖靠近胸部。 将右脚放低，将左脚抬离地面，将膝盖靠近胸部。 继续交替抬起右脚和左脚，达到所需的重复次数。"},{"id":"1353","name_zh":"药球接球过头抛","target":"背阔肌","media_id":"PsVS1QP","instructions_zh":"双脚分开与肩同宽站立，双手握住健身球，与胸部齐平。 稍微弯曲膝盖并启动核心。 将身体降低至蹲姿，保持背部挺直、挺胸。 爆发性伸展臀部和腿部，同时将药球扔过头顶。 在动作的最高点释放球并在下降的过程中接住它。 将身体放回蹲姿，然后重复所需的重复次数。"},{"id":"1302","name_zh":"药球胸前传球","target":"胸","media_id":"aDoFKrE","instructions_zh":"双脚分开与肩同宽站立，将健身球保持在胸部水平。 向前伸展双臂，用力将药球推离胸部。 当你释放球时，用你的手臂和躯干将球从后脚转移到前脚。 当球从墙壁或伙伴身上反弹时接住球，并立即重复该动作。 继续进行所需的重复次数。"},{"id":"1303","name_zh":"三点支撑药球胸前推","target":"胸","media_id":"dCJnuVq","instructions_zh":"以三点姿势开始，一只手放在健身球上，另一只手放在地上。 伸展双腿并将身体摆成一条直线。 将胸部压向地面，同时保持背部挺直。 将药球推离身体，完全伸展手臂。 返回起始位置并重复所需的重复次数。"},{"id":"1304","name_zh":"药球胸前多次推","target":"胸","media_id":"7aolH9D","instructions_zh":"双脚分开与肩同宽站立，将药球举至胸部水平。 向前伸展双臂，将药球推离胸部。 暂停片刻，然后慢慢地将健身球放回胸前。 重复所需的重复次数。"},{"id":"1305","name_zh":"药球胸前单次推","target":"胸","media_id":"jeHtrlO","instructions_zh":"双脚分开与肩同宽站立，将健身球保持在胸部水平。 向前伸展双臂，将药球推离胸部。 暂停片刻，然后慢慢地将健身球放回胸前。 重复所需的重复次数。"},{"id":"1312","name_zh":"药球胸前推接跑","target":"胸","media_id":"pX9Elbe","instructions_zh":"双脚分开与肩同宽站立，将药球举至胸部水平。 右脚向前迈出一步，同时向前推动药球，充分伸展双臂。 当你向前推动球时，松开它并让它向前滚动。 快速向前跑，在球落地之前接住球。 接住球后，将其放回胸前，左脚向前重复该动作。 继续交替双腿并重复练习达到所需的重复次数。"},{"id":"1701","name_zh":"药球窄距俯卧撑","target":"肱三头肌","media_id":"8K7m2SS","instructions_zh":"从高平板支撑位置开始，双手放在健身球上，距离与肩同宽。 弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。 推回起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"1354","name_zh":"药球过顶砸","target":"上背部","media_id":"oHg8eop","instructions_zh":"双脚分开与肩同宽站立，双手握住药球举过头顶。 启动你的核心并保持背部挺直。 稍微弯曲膝盖，用力将药球摔到你面前的地面上。 当你击球时，用你的整个身体来产生力量，包括你的肩膀和核心。 接住球的弹跳并重复所需的重复次数。"},{"id":"1750","name_zh":"仰卧药球胸前抛","target":"肱三头肌","media_id":"Al3tP0D","instructions_zh":"平躺在长凳上，膝盖弯曲，双脚平放在地上。 双手握住药球，将手臂伸直至胸部上方。 将健身球降低到胸部，保持肘部靠近身体。 爆发性地将药球向上推，充分伸展双臂并将球扔得尽可能高。 接住药球并重复所需的重复次数。"},{"id":"0627","name_zh":"正反握引体向上","target":"背阔肌","media_id":"T8UpLkb","instructions_zh":"反握（手掌朝向自己）抓住引体向上杆，双手之间的距离略大于肩宽。 悬挂在杠上，双臂完全伸展，双脚离开地面。 调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后有控制地慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"3217","name_zh":"改良印度俯卧撑（男）","target":"胸","media_id":"epOSYUZ","instructions_zh":"从俯卧撑位置开始，双手分开略宽于肩宽，双脚分开与臀部同宽。 将身体向地面降低，弯曲肘部并保持核心参与。 当你降低身体时，将你的重心向后转移，并将臀部向上抬向天花板，与你的身体形成一个倒V形。 继续降低身体，直到胸部刚好高于地面，然后反向运动，将臀部向下推，并伸展手臂回到起始位置。 重复所需的重复次数。"},{"id":"1421","name_zh":"改良俯卧撑至前臂","target":"前臂","media_id":"arvaszz","instructions_zh":"从俯卧撑位置开始，双手直接放在肩膀下方，身体呈一条直线。 弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。 一旦肘部成 90 度角，将前臂放低至地面，将肘部保持在肩膀正下方。 暂停片刻，然后用手掌推动前臂，使其回到起始位置。 重复所需的重复次数。"},{"id":"0628","name_zh":"怪兽行走","target":"臀部","media_id":"O95afRA","instructions_zh":"在脚踝周围放置一根阻力带。 双脚分开与肩同宽站立，稍微弯曲膝盖。 右脚向一侧迈出一步，保持阻力带的张力。 左脚跟随，向一侧迈步以返回起始位置。 重复所需的重复次数，然后换边。"},{"id":"0630","name_zh":"登山者","target":"有氧","media_id":"RJgzwny","instructions_zh":"从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。 启动你的核心并将你的右膝盖靠近你的胸部，然后快速切换并将你的左膝盖靠近你的胸部。 继续以跑步动作交替双腿，保持臀部较低，核心肌群参与。 在整个练习过程中保持稳定的节奏和均匀的呼吸。 重复所需的重复次数。"},{"id":"0631","name_zh":"双力臂","target":"背阔肌","media_id":"yJUHKTn","instructions_zh":"首先悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。 启动核心肌群，将身体拉向杠铃杆，以胸部为主导。 当你到达动作的最高点时，改变你的握力，使你的手掌朝向你。 继续将自己向上拉，直到胸部位于杠铃上方并且手臂完全弯曲。 通过慢慢降低自己回到起始位置来反转动作。 重复所需的重复次数。"},{"id":"1401","name_zh":"双力臂（垂直杆）","target":"背阔肌","media_id":"Af0EW2I","instructions_zh":"首先悬挂在垂直杆上，手掌背对自己，手臂完全伸展。 启动核心肌群，将身体拉向杠铃杆，以胸部为主导。 当你站起来时，稍微向后倾斜，并将肘部移向身体两侧。 继续拉，直到胸部到达杠铃并且肘部完全弯曲。 在最高点暂停片刻，然后慢慢降低回到起始位置。 重复所需的重复次数。"},{"id":"2328","name_zh":"窄距健身球俯卧撑","target":"肱三头肌","media_id":"4cWjYEN","instructions_zh":"将稳定球放在地面上，将自己置于俯卧撑位置，双手放在球上，距离略窄于肩宽。 调动你的核心力量，让你的身体从头到脚保持在一条直线上。 弯曲肘部，使胸部靠近球，使胸部靠近球。 在底部暂停片刻，然后伸直手臂将自己推回起始位置。 重复所需的重复次数。"},{"id":"1403","name_zh":"颈部侧拉伸","target":"肩胛提肌","media_id":"x2chWLO","instructions_zh":"站直或坐直，肩膀放松。 将头向一侧倾斜，将耳朵靠近肩膀。 保持拉伸 15-30 秒。 在另一侧重复。 每侧进行 2-4 组。"},{"id":"0634","name_zh":"离心卷腹","target":"腹部","media_id":"szIn2UK","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"1495","name_zh":"侧卷腹2","target":"腹部","media_id":"cJgSTmh","instructions_zh":"仰卧，膝盖弯曲，双脚平放在地上。 将双手放在脑后或交叉放在胸前。 收紧腹肌，将肩胛骨抬离地面，将躯干旋转到一侧。 暂停片刻，然后将肩胛骨放回起始位置。 在另一侧重复。 继续交替进行所需的重复次数。"},{"id":"0635","name_zh":"地板侧卷腹","target":"腹部","media_id":"QUDd8WS","instructions_zh":"仰卧，膝盖弯曲，双脚平放在地板上。 将双手放在脑后或交叉放在胸前。 收紧腹肌，将肩胛骨抬离地面，将躯干旋转到一侧。 暂停片刻，然后将肩胛骨放回到地板上。 在另一侧重复，每次重复时交替进行。"},{"id":"0636","name_zh":"杠铃锤式弯举","target":"肱二头肌","media_id":"o1ntciW","instructions_zh":"站直，双脚分开与肩同宽，正手握住奥林匹克杠铃。 让杠铃悬挂在大腿前面，手掌与身体保持一臂距离。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0637","name_zh":"杠铃臂屈伸","target":"肱三头肌","media_id":"wu5LXwz","instructions_zh":"首先，双脚分开与肩同宽站立，并用正手握住杠铃。 将杠铃举过头顶，充分伸展双臂。 保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。"},{"id":"1355","name_zh":"单臂靠墙","target":"背阔肌","media_id":"ZZTGMKh","instructions_zh":"面向墙壁站立，双脚分开与肩同宽。 将一只手臂伸直到身前，将手掌靠在墙上。 启动你的核心，身体向前倾斜，保持手臂伸直，背部平坦。 用手掌慢慢推向墙壁，激活背阔肌。 保持该姿势几秒钟，然后松开并用另一只手臂重复该动作。"},{"id":"0638","name_zh":"单臂引体向上","target":"背阔肌","media_id":"HjdqmZa","instructions_zh":"面向引体向上杆站立，双脚分开与肩同宽。 抬起手，用反握方式抓住杠铃，一只手握住杠铃，另一只手握住手腕以提供支撑。 悬挂在杠上，手臂完全伸展，保持身体伸直，核心肌群参与。 弯曲肘部并挤压背部肌肉，将自己拉向杠铃。 继续拉，直到下巴高于杠铃，然后慢慢降低回到起始位置。 重复所需的重复次数，然后换臂重复。"},{"id":"0639","name_zh":"单臂臂屈伸","target":"肱三头肌","media_id":"FAoIFMw","instructions_zh":"背对长凳或椅子站立，双脚分开与肩同宽。 将一只手放在身后的长凳或椅子上，手指指向您的身体。 将双腿向前方伸展，脚跟保持在地面上。 弯曲肘部，将身体放低至地面，使背部靠近长凳或椅子。 在底部停顿片刻，然后用手掌推直手臂，回到起始位置。 重复所需的重复次数，然后换边并用另一只手臂重复。"},{"id":"0640","name_zh":"单臂药球砸地","target":"腹部","media_id":"jCrtE9b","instructions_zh":"双脚分开与肩同宽站立，一只手将健身球放在腰前。 稍微弯曲膝盖并启动核心。 将健身球举过头顶，充分伸展手臂。 用力将药球摔到地上，用你的核心和肩膀产生力量。 抓住弹起的实心球，然后重复所需的重复次数。"},{"id":"1773","name_zh":"单臂毛巾划船","target":"上背部","media_id":"bKWbrTA","instructions_zh":"双脚分开与肩同宽站立，膝盖微曲，单手握住毛巾。 腰部向前弯曲，保持背部挺直，核心肌群参与。 完全伸展手臂，让毛巾挂在您面前。 将毛巾拉向胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将毛巾放回起始位置。 重复所需的重复次数，然后换臂。"},{"id":"1386","name_zh":"单腿驴提踵","target":"小腿","media_id":"A2upspL","instructions_zh":"双脚分开与肩同宽站立，脚趾指向前方。 将双手放在稳定的表面上以获得支撑，例如墙壁或酒吧。 将一条腿抬离地面，保持膝盖稍微弯曲。 使用小腿肌肉，尽可能高地抬高脚跟。 在顶部停顿片刻，然后慢慢降低脚跟。 重复所需的重复次数，然后换腿。"},{"id":"1387","name_zh":"单腿地板提踵","target":"小腿","media_id":"0jp9Rlz","instructions_zh":"双脚分开与臀部同宽站立，双手放在墙壁或坚固的物体上以保持平衡。 将一只脚抬离地面并用另一只脚保持平衡。 慢慢地将脚跟抬离地面，将身体抬起到脚掌上。 在顶部暂停片刻，然后慢慢将脚跟放回起始位置。 重复所需的重复次数，然后换腿并重复。"},{"id":"1476","name_zh":"单腿深蹲","target":"臀部","media_id":"C31LMnP","instructions_zh":"双脚分开与肩同宽站立。 向前伸出一条腿，使其离开地面。 弯曲站立的腿并降低身体，就像坐回椅子上一样。 保持挺胸、背部挺直。 推动脚后跟返回到起始位置。 换另一条腿重复上述步骤。"},{"id":"0641","name_zh":"奥蒂斯起坐","target":"腹部","media_id":"UVL20oz","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"0642","name_zh":"俯卧撑侧踢腿","target":"臀部","media_id":"jNU1gFQ","instructions_zh":"从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。 弯曲肘部，将身体降低到地面，保持背部挺直，核心参与。 当你向后推时，将一条腿踢向一侧，完全伸展并启动臀部。 将腿恢复到起始位置并重复俯卧撑，每次重复时交替腿。 继续交替踢腿和俯卧撑，达到所需的重复次数。"},{"id":"0643","name_zh":"过头肱三头肌拉伸","target":"肱三头肌","media_id":"Z5YStHW","instructions_zh":"站立或坐直，双脚分开与肩同宽。 将一只手臂伸过头顶，弯曲肘部，使手伸向对面的肩胛骨。 用另一只手轻轻地将伸出的手臂的肘部拉向头部的另一侧，感受三头肌的拉伸。 保持拉伸 15-30 秒，然后放松。 在另一侧重复。"},{"id":"3147","name_zh":"骨盆卷动","target":"腹部","media_id":"NKJ8o6x","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在身体两侧。 收紧腹肌，向上倾斜骨盆，将下背部压入地面。 保持这个姿势几秒钟，专注于收缩腹肌。 释放倾斜并返回到起始位置。 重复所需的重复次数。"},{"id":"1422","name_zh":"骨盆卷动至臀桥","target":"臀部","media_id":"D9qe7CM","instructions_zh":"仰卧，膝盖弯曲，双脚平放在地上。 将手臂放在身体两侧，手掌朝下。 调动你的臀肌和核心肌肉。 向上倾斜骨盆，将臀部抬离地面。 保持桥位置几秒钟。 慢慢地将臀部放回起始位置。 重复所需的重复次数。"},{"id":"1388","name_zh":"腓骨肌拉伸","target":"小腿","media_id":"XhfS1DZ","instructions_zh":"坐在地上，双腿在身前伸展。 将绳子绕在脚掌上，并用手握住绳子的末端。 轻轻地将绳子拉向自己，弯曲脚并伸展小腿肌肉。 保持拉伸 15-30 秒。 释放绳子上的张力，然后在另一条腿上重复拉伸。 重复所需的重复次数。"},{"id":"3662","name_zh":"屈体到眼镜蛇俯卧撑","target":"臀部","media_id":"XPUDTt7","instructions_zh":"从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。 收紧核心肌群，将臀部抬向天花板，与身体形成倒V字形。 弯曲肘部，使上半身靠近地面，使上半身靠近地面。 当你下降时，将你的重心向前移动，并通过伸直手臂并抬起胸部来过渡到眼镜蛇姿势。 通过弯曲肘部并将胸部放回到地面来扭转运动。 双手用力推回到倒V字形。 通过将臀部放回地面继续运动，回到起始俯卧撑位置。 重复所需的重复次数。"},{"id":"1306","name_zh":"爆发力俯卧撑","target":"胸","media_id":"Snj1wSv","instructions_zh":"从高平板支撑位置开始，双手分开略宽于肩宽。 弯曲肘部，将胸部压向地面，保持身体呈一条直线。 爆发性地推离地面，利用胸部肌肉将上半身推离地面。 双手回到起始位置，轻轻落地。 重复所需的重复次数。"},{"id":"1687","name_zh":"后撤步过头伸展","target":"腹部","media_id":"ErqK3UL","instructions_zh":"站立，双脚分开与臀部同宽，双臂放在身体两侧。 右脚向后退一步，用脚掌着地。 弯曲左膝并将身体降低至弓步位置。 当你降低弓步时，同时将手臂举过头顶。 在弓步底部暂停片刻，然后通过推动左脚跟并将右脚向前拉回到起始位置。 在另一侧重复该动作，左脚向后退一步并弯曲右膝盖。 继续交替进行所需的重复次数。"},{"id":"1389","name_zh":"胫骨后肌拉伸","target":"小腿","media_id":"DEEqoI2","instructions_zh":"坐在地上，双腿在身前伸展。 将绳子绕在脚掌上，并用手握住绳子的末端。 轻轻地将绳子拉向自己，弯曲脚并伸展小腿肌肉。 保持拉伸 20-30 秒。 释放绳子上的张力并放松脚。 在另一条腿上重复该拉伸动作。"},{"id":"3119","name_zh":"坐便式深蹲","target":"腹部","media_id":"75Bgtjy","instructions_zh":"双脚分开与肩同宽站立，脚趾稍微向外。 弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。 在整个动作过程中保持挺胸、背部挺直。 降低自己，直到大腿与地面平行或尽可能低。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"3132","name_zh":"支撑坐便式深蹲","target":"臀部","media_id":"b63ZzGe","instructions_zh":"双脚分开与肩同宽站立，脚趾稍微向外。 抓住稳定的支撑物，例如椅子或墙壁，以保持平衡。 弯曲膝盖并将臀部向后推，将身体降低至蹲姿。 在整个动作过程中保持挺胸、背部挺直。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0648","name_zh":"力量翻","target":"大腿后侧","media_id":"SiWCcTN","instructions_zh":"首先将杠铃放在你面前的地面上，双脚分开与肩同宽。 弯腰，正手握住杠铃，握距略宽于肩宽。 将杠铃提离地面时，保持背部挺直，挺胸，伸展臀部和膝盖。 当杠铃到达大腿中部时，爆发性地将其向上拉，耸肩并将肘部拉高并向两侧拉。 当杠铃到达最高点时，迅速下降到其下方，旋转肘部，以前蹲姿势将杠铃接在肩膀上。 握住杠铃站起来，充分伸展臀部和膝盖。 将杠铃放回起始位置，在整个运动过程中保持对重量的控制。 重复所需的重复次数。"},{"id":"3665","name_zh":"前伸平板支撑","target":"腹部","media_id":"hCjGsRQ","instructions_zh":"从高平板支撑位置开始，双手直接放在肩膀下方，身体从头到脚成一条直线。 启动你的核心并挤压你的臀肌以保持稳定的位置。 将身体放低到前臂上，一次一只手臂，从头到脚保持一条直线。 保持这个姿势所需的时间，保持核心肌群和臀肌的参与。 要返回到起始位置，请推动前臂并将身体抬回到高位平板支撑位置。 重复所需的重复次数。"},{"id":"3203","name_zh":"囚徒半仰卧起坐（男）","target":"腹部","media_id":"mgejmGP","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"1707","name_zh":"健身球上俯卧扭转","target":"腹部","media_id":"1IG6gVF","instructions_zh":"首先，面朝下躺在稳定球上，双脚分开与肩同宽，脚趾接触地面。 将双手放在脑后或交叉放在胸前。 启动核心肌肉，慢慢将上半身抬离球，保持背部挺直。 将躯干旋转到一侧，使肩膀靠近臀部。在整个运动过程中保持臀部和腿部稳定。 暂停片刻，然后回到起始位置。 重复旋转到另一侧。 继续交替进行所需的重复次数。"},{"id":"0651","name_zh":"对握引体向上","target":"背阔肌","media_id":"0V2YQjW","instructions_zh":"用中立握法（手掌相对）悬挂在引体向上杆上，双臂完全伸展。 启动你的核心并将肩胛骨挤压在一起。 弯曲肘部并将肘部向下推向臀部，将身体向上拉向杠铃。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后有控制地慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"0650","name_zh":"健身球收腿","target":"腹部","media_id":"UQr48Oi","instructions_zh":"首先坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。 将双手放在稳定球的两侧以获得支撑。 收紧腹肌，慢慢向前滚动臀部，使膝盖靠近胸部。 在动作的最高点停顿片刻，然后慢慢将双腿伸展回起始位置。 重复所需的重复次数。"},{"id":"0652","name_zh":"引体向上","target":"背阔肌","media_id":"lBDjFxJ","instructions_zh":"悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。 启动你的核心并将肩胛骨挤压在一起。 弯曲肘部并将胸部拉向杠铃杆，将身体向上拉向杠铃杆。 在动作的最高点暂停，然后慢慢降低身体回到起始位置。 重复所需的重复次数。"},{"id":"1689","name_zh":"自重推拉","target":"胸","media_id":"wXvUZC8","instructions_zh":"从俯卧撑位置开始，双手分开略宽于肩宽，身体呈一条直线。 弯曲肘部，将胸部压向地面，保持身体伸直。 推动手掌以伸展手臂并返回到起始位置。 从俯卧撑位置开始，弯曲肘部，将胸部拉向地面，保持身体伸直。 推动手掌以伸展手臂并返回到起始位置。 重复所需的重复次数。"},{"id":"3638","name_zh":"俯撑起跑","target":"有氧","media_id":"PrQbjvB","instructions_zh":"从俯卧撑位置开始，双手分开与肩同宽，身体呈一条直线。 弯曲肘部，将胸部压向地面，保持身体伸直。 用手推动以伸展手臂并返回到起始位置。 快速将一个膝盖靠近胸部，然后快速切换并将另一只膝盖靠近胸部。 继续尽可能快地交替膝盖，同时保持良好的姿势。 继续所需的持续时间或重复次数。"},{"id":"1307","name_zh":"波速球俯卧撑","target":"胸","media_id":"wVompEp","instructions_zh":"将博苏球平放在地上，平面朝上。 将自己置于俯卧撑位置，双手放在博苏球的外边缘。 弯曲肘部，调动核心力量，将身体向博苏球方向降低。 伸展双臂，将自己推回到起始位置。 重复所需的重复次数。"},{"id":"0662","name_zh":"俯卧撑","target":"胸","media_id":"I4hDWkc","instructions_zh":"从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。 弯曲肘部，调动核心力量，将身体压向地面，保持身体呈一条直线。 当你的胸部刚好高于地面时，暂停片刻，然后伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"0653","name_zh":"波速球俯卧撑","target":"胸","media_id":"2kr2lWy","instructions_zh":"将博苏球平放在地上，平面朝上。 将自己置于俯卧撑位置，双手放在博苏球的外边缘。 弯曲肘部，调动核心力量，将身体向博苏球方向降低。 伸展双臂，将自己推回到起始位置。 重复所需的重复次数。"},{"id":"0655","name_zh":"健身球俯卧撑","target":"胸","media_id":"Y4BRNQF","instructions_zh":"将稳定球放在地上，面朝下，双手放在球上，与肩同宽。 将双腿伸直在身后，用脚趾保持平衡。 弯曲肘部，调动核心力量，将胸部向球方向降低，保持身体呈一条直线。 在底部暂停片刻，然后伸直手臂将自己推回起始位置。 重复所需的重复次数。"},{"id":"0656","name_zh":"健身球俯卧撑","target":"胸","media_id":"tgryw5Y","instructions_zh":"将稳定球放在地上，面朝下，双手放在球上，与肩同宽。 将双腿伸直在身后，用脚趾保持平衡。 弯曲肘部，调动核心力量，将胸部向球方向降低，保持身体呈一条直线。 在底部暂停片刻，然后伸直手臂将自己推回起始位置。 重复所需的重复次数。"},{"id":"0659","name_zh":"墙壁俯卧撑","target":"胸","media_id":"LEH9jxP","instructions_zh":"面向墙壁站立，距离大约一臂距离。 将双手放在墙上，与肩同高，距离略宽于肩宽。 后退几英尺，保持身体挺直，双脚分开与臀部同宽。 弯曲肘部，将胸部向墙壁降低，保持身体呈一条直线。 推回起始位置，伸直手臂。 重复所需的重复次数。"},{"id":"0658","name_zh":"墙壁俯卧撑 v. 2","target":"胸","media_id":"NCmbLCw","instructions_zh":"面向墙壁站立，距离大约一臂距离。 将双手放在墙上，与肩同高，距离略宽于肩宽。 双脚向后退一步，保持与臀部同宽。 收紧核心肌群，保持身体从头到脚跟呈一条直线。 弯曲肘部，将胸部向墙壁降低，保持身体挺直。 暂停片刻，然后将自己推回到起始位置。 重复所需的重复次数。"},{"id":"0660","name_zh":"哑铃上窄距俯卧撑","target":"肱三头肌","media_id":"KZXAtKQ","instructions_zh":"从俯卧撑位置开始，双手并拢，直接放在肩膀下方。 每只手握住一个哑铃，将其放在地上。 弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。 推动手掌以伸展手臂并返回到起始位置。 重复所需的重复次数。"},{"id":"0661","name_zh":"俯卧撑内侧踢腿","target":"臀部","media_id":"0br45wL","instructions_zh":"从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。 弯曲肘部，将身体降低到地面，保持背部挺直，核心肌群参与。 当你向后推时，将一条腿抬离地面并将其踢向一侧，保持伸直。 将腿放下并重复俯卧撑，然后换另一条腿。 每次重复俯卧撑时继续交替踢腿。"},{"id":"0663","name_zh":"药球俯卧撑","target":"胸","media_id":"W8KAlkI","instructions_zh":"从高平板支撑位置开始，双手放在健身球上，距离与肩同宽。 弯曲肘部，保持背部挺直，调动核心力量，将身体降低至地面。 推动手掌以伸展手臂并返回到起始位置。 重复所需的重复次数。"},{"id":"1467","name_zh":"前臂俯卧撑","target":"肱三头肌","media_id":"4Jt8QsQ","instructions_zh":"从平板支撑位置开始，前臂放在地面上，肘部位于肩膀正下方。 调动你的核心力量，让你的身体从头到脚保持在一条直线上。 弯曲肘部，使胸部靠近地面，使胸部靠近地面。 在底部暂停片刻，然后将自己推回到起始位置。 重复所需的重复次数。"},{"id":"3145","name_zh":"俯卧撑+","target":"胸","media_id":"pvBMLHA","instructions_zh":"从高位平板支撑开始，双手分开略宽于肩宽，身体从头到脚跟呈一条直线。 弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。 一旦你的胸部刚好高于地面，用力推动你的手臂，伸展你的手臂并抬起你的上半身。 在动作的最高点，将上背部推向天花板，从而伸展肩胛骨。 暂停片刻，然后通过缩回肩胛骨并将身体放回起始位置来反转动作。 重复所需的重复次数。"},{"id":"0664","name_zh":"俯卧撑转侧平板支撑","target":"腹部","media_id":"KhHJ338","instructions_zh":"从俯卧撑位置开始，双手分开与肩同宽，身体呈一条直线。 弯曲肘部，将身体降低到地面，保持核心参与。 推回到起始位置。 将体重转移到左手上，然后将身体向右旋转，将右臂举向天花板。 保持侧板姿势几秒钟，然后返回到起始位置。 在另一侧重复俯卧撑和侧板支撑。 继续交替进行所需的重复次数。"},{"id":"3533","name_zh":"股四头肌拉伸","target":"股四头肌","media_id":"6YUfHPL","instructions_zh":"双脚分开与肩同宽站立。 弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。 保持挺胸、背部挺直。 降低身体直到大腿与地面平行。 推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"3201","name_zh":"四分之一仰卧起坐","target":"腹部","media_id":"enxnJcM","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"3552","name_zh":"快速碎步 v. 2","target":"股四头肌","media_id":"mweqJin","instructions_zh":"双脚分开与肩同宽站立，双臂放在身体两侧。 首先快速上下移动双脚，就像原地跑步一样。 保持动作快速而轻盈，重点放在脚掌上。 继续所需的持续时间或重复次数。"},{"id":"0666","name_zh":"单臂抬起俯卧撑","target":"胸","media_id":"13TpY4H","instructions_zh":"从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。 将一只手臂伸直至一侧，与地面平行。 弯曲肘部，将身体降低到地面，保持背部挺直，核心参与。 推回起始位置，使用胸部肌肉抬起身体。 另一只手臂伸出，重复上述动作。"},{"id":"0668","name_zh":"下斜后桥","target":"臀部","media_id":"UpAlold","instructions_zh":"仰卧，双脚平放在地上，膝盖弯曲。 将手臂放在身体两侧，手掌朝下。 收紧臀肌和腿筋，将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。 保持这个姿势几秒钟，然后慢慢地将臀部放回起始位置。 重复所需的重复次数。"},{"id":"0669","name_zh":"三角肌后束拉伸","target":"肩","media_id":"xifhB5W","instructions_zh":"站直，双脚分开与肩同宽。 将右臂伸过胸部，将左手放在右肘上。 轻轻地将右臂拉向左肩，感受右肩的拉伸。 保持拉伸 15-30 秒，然后放松。 在另一侧重复。"},{"id":"0670","name_zh":"颈后引体向上","target":"背阔肌","media_id":"CbFSYC1","instructions_zh":"正手握住引体向上杆，握距略宽于肩宽。 悬挂在杠上，双臂完全伸展，身体伸直。 收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"1582","name_zh":"仰卧手抓大脚趾式（用绳）","target":"大腿后侧","media_id":"K5xgdvI","instructions_zh":"仰卧，双腿伸展，双臂放在身体两侧。 将绳子绕在右脚掌上，并用手握住绳子的末端。 慢慢地将右腿抬向胸部，保持膝盖伸直，脚弯曲。 保持伸展几秒钟，然后慢慢将腿放回起始位置。 左腿重复上述动作。 继续交替双腿达到所需的重复次数。"},{"id":"3236","name_zh":"弹力带跪姿臀推（女）","target":"臀部","media_id":"Pjbc0Kt","instructions_zh":"首先跪在地上，膝盖分开与臀部同宽，双脚弯曲。 将阻力带缠绕在大腿上，就在膝盖上方。 将双手放在臀部或向前伸展以保持平衡。 调动你的臀肌和核心肌肉。 当你将膝盖抬离地面时，向前推动臀部并挤压臀部，伸展臀部直到大腿与地面平行。 保持该姿势片刻，然后慢慢将膝盖放回起始位置。 重复所需的重复次数。"},{"id":"3007","name_zh":"弹力带腿屈伸","target":"股四头肌","media_id":"Y1MsI1l","instructions_zh":"将阻力带固定在坚固的锚点上，并将其固定在脚踝上。 面向锚点站立，双脚分开与肩同宽。 保持核心参与并保持上半身稳定，将腿伸直到身前。 在顶部暂停片刻，然后慢慢地将腿放回起始位置。 重复所需的重复次数，然后换腿。"},{"id":"3123","name_zh":"弹力带坐姿二头弯举","target":"肱二头肌","media_id":"XFc3vpY","instructions_zh":"坐在椅子或长凳上，背部挺直，双脚平放在地面上。 反手握住阻力带，手掌朝上，手臂向下伸展到身体两侧。 保持上臂静止，呼气并将阻力带向上卷向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气并慢慢降低阻力带回到起始位置。 重复所需的重复次数。"},{"id":"3124","name_zh":"弹力带坐姿胸部推举","target":"胸","media_id":"4x5Okof","instructions_zh":"坐在椅子或长凳上，背部挺直，双脚平放在地面上。 每只手握住阻力带手柄，手掌朝下，肘部弯曲成 90 度角。 向前伸展双臂，将阻力带推离胸部。 动作结束时暂停片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"3006","name_zh":"弹力带坐姿髋外展","target":"外展肌","media_id":"0xDpB4L","instructions_zh":"坐在椅子或长凳上，背部挺直，双脚平放在地面上。 将阻力带缠绕在大腿上，就在膝盖上方。 将双手放在椅子或长凳的两侧以获得支撑。 启动外展肌（大腿外侧肌肉），并克服弹力带的阻力，慢慢将膝盖分开。 动作结束时暂停片刻，然后慢慢将膝盖放回一起。 重复所需的重复次数。"},{"id":"3122","name_zh":"弹力带坐姿肩推","target":"肩","media_id":"S93zLTG","instructions_zh":"坐在椅子或长凳上，背部挺直，双脚平放在地面上。 双手握住阻力带，手掌朝前，将其拉至肩部水平。 将弹力带压过头顶，充分伸展双臂。 在顶部停顿片刻，然后慢慢将弹力带降低至肩部水平。 重复所需的重复次数。"},{"id":"3144","name_zh":"弹力带坐姿直背划船","target":"上背部","media_id":"Nu7jqFE","instructions_zh":"坐在地板上，双腿伸展，将阻力带绕在脚上。 双手握住阻力带的两端，手掌相对。 保持背部挺直，稍微向后倾斜，锻炼核心肌群。 将阻力带拉向胸部，将肩胛骨挤压在一起。 在最高点停顿片刻，然后慢慢释放张力，回到起始位置。 重复所需的重复次数。"},{"id":"0872","name_zh":"反向卷腹","target":"腹部","media_id":"nCU1Ekp","instructions_zh":"平躺，双臂沿着身体两侧伸展。 弯曲膝盖，将脚抬离地面，使大腿垂直于地板。 收缩腹肌，将臀部卷离地板，使膝盖靠近胸部。 在顶部暂停片刻，然后慢慢将臀部放回起始位置。 重复所需的重复次数。"},{"id":"0672","name_zh":"反向臂屈伸","target":"肱三头肌","media_id":"NZ5Qqkz","instructions_zh":"将自己定位在两个双杠之间，双臂完全伸展，身体伸直。 弯曲肘部降低身体，直到上臂与地面平行。 暂停片刻，然后伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"0673","name_zh":"反握器械高位下拉","target":"背阔肌","media_id":"ecpY0rH","instructions_zh":"调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。 反手握住手柄，握距略宽于肩宽。 坐直，挺胸，肩膀向后，保持下背部轻微的拱形。 将手柄向下拉向胸部，将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"0674","name_zh":"反握引体向上","target":"背阔肌","media_id":"YAk5dIw","instructions_zh":"双手分开与肩同宽，反握抓住引体向上杆。 悬挂在杠上，双臂完全伸展，身体伸直。 调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"0675","name_zh":"反向山羊挺身（瑜伽球）","target":"臀部","media_id":"vM5YS2g","instructions_zh":"面朝下躺在稳定球上，臀部放在球上，双腿伸直在身后。 将双手放在身前的地面上以保持稳定。 调动臀肌和腿筋，将双腿尽可能高地抬向天花板。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"1423","name_zh":"平板凳反向山羊挺身","target":"臀部","media_id":"OrETs32","instructions_zh":"脸朝下躺在平坦的长凳上，臀部位于边缘，双腿悬在长凳上。 抓住长凳以保持稳定。 保持双腿伸直，尽可能将它们抬向天花板。 在动作的最高点挤压臀部。 慢慢地将双腿放回起始位置。 重复所需的重复次数。"},{"id":"3663","name_zh":"反向平板支撑抬腿","target":"腹部","media_id":"tFToB7l","instructions_zh":"坐在地上，双腿向前伸展，双手放在身后的地面上，手指指向脚部。 双手用力，将臀部抬离地面，进入反向平板支撑位置。 启动你的核心并将一条腿抬离地面，将其笔直向上伸向天花板。 保持一会儿，然后将腿放下。 换另一条腿重复上述步骤。 继续交替双腿达到所需的重复次数。"},{"id":"0677","name_zh":"吊环臂屈伸","target":"肱三头肌","media_id":"ezTvXcr","instructions_zh":"首先，将手臂完全伸展，身体伸直，挂在吊环上。 弯曲肘部，降低身体，直到肩膀低于肘部。 伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"2571","name_zh":"摇摆蛙式拉伸","target":"臀部","media_id":"2Dk4xQV","instructions_zh":"首先跪在地上，膝盖分开与臀部同宽。 将双手放在身前的地面上以获得支撑。 慢慢向前倾，将重心转移到双手上，并将双腿伸到身后。 当你将臀部向后推向天花板时，保持背部挺直并收紧臀部。 保持这个姿势几秒钟，感受臀部的拉伸。 弯曲膝盖并降低臀部，慢慢回到起始位置。 重复所需的重复次数。"},{"id":"0678","name_zh":"洛奇引体下拉","target":"背阔肌","media_id":"cQ19bBP","instructions_zh":"站在引体向上杆前，双脚分开与肩同宽。 向上伸手，正手握住杠铃，握距略宽于肩宽。 悬挂在杠上，双臂完全伸展，身体伸直。 调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"2208","name_zh":"泡沫轴背部拉伸","target":"脊柱","media_id":"isofgzg","instructions_zh":"首先坐在地上，双腿在身前伸展。 将滚轮垂直于您的身体放置，位于臀部下方。 慢慢向后滚动你的身体，让滚轮向上移动你的背部。 继续滚动，直到滚轮到达您的上背部。 暂停片刻，然后慢慢滚回到起始位置。 重复所需的重复次数。"},{"id":"2204","name_zh":"泡沫轴锯式","target":"腹部","media_id":"XeMvLgE","instructions_zh":"从平板支撑位置开始，前臂放在滚轴上，身体呈一条直线。 启动你的核心并缓慢向前滚动滚轮，在保持控制的同时尽可能地伸展你的身体。 在最远点暂停片刻，然后慢慢地将滚轮滚回到起始位置。 重复所需的重复次数。"},{"id":"2205","name_zh":"泡沫轴髋部背阔肌拉伸","target":"臀部","media_id":"0L2KwtI","instructions_zh":"首先跪在地上，将滚轮放在臀部下方。 将双手放在滚轮上以获得支撑。 慢慢地向前滚动滚轮，伸展臀部并伸展臀部。 保持伸展几秒钟，然后滚回起始位置。 重复所需的重复次数。"},{"id":"2202","name_zh":"泡沫轴髋部拉伸","target":"臀部","media_id":"oMypNrz","instructions_zh":"首先坐在地上，双腿在身前伸展。 将滚轮放在臀部下方、膝盖上方。 向后倾斜，双手放在身后的地面上以获得支撑。 收紧臀部，慢慢向前滚动滚轮，弯曲膝盖并将其拉向胸部。 动作结束时暂停片刻，感受臀部的拉伸。 慢慢地将滚轮滚回起始位置，伸展双腿。 重复所需的重复次数。"},{"id":"2206","name_zh":"泡沫轴反向卷腹","target":"腹部","media_id":"SKXQAx3","instructions_zh":"平躺，双臂伸直过头顶，双腿伸直在身前。 将滚筒放在双脚之间，并用脚趾抓住它。 收紧腹肌，将双腿抬离地面，将膝盖向胸部弯曲，将滚轮向身体方向滚动。 在顶部停顿片刻，然后慢慢将双腿放回起始位置，将滚轮滚离身体。 重复所需的重复次数。"},{"id":"2203","name_zh":"泡沫轴坐姿肩部屈肌下压后缩拉伸","target":"胸","media_id":"8coXSYU","instructions_zh":"坐在平坦的表面上，双腿在身前伸展。 双手握住滚轮，掌心朝下，将其放在大腿上。 稍微向前倾，将滚轮滚离身体，将手臂伸直在身前。 暂停片刻，然后慢慢将滚轮向身体方向滚动，弯曲手臂，将滚轮拉回到大腿处。 重复所需的重复次数。"},{"id":"2209","name_zh":"泡沫轴坐姿单腿肩部屈肌下压后缩拉伸","target":"胸","media_id":"CjETvlw","instructions_zh":"坐在平坦的表面上，双腿在身前伸展。 双手握住滚轮，掌心朝下，将其放在大腿上。 稍微向后倾斜并锻炼核心肌肉。 将滚轮抬高至肩部高度，保持手臂伸直。 慢慢地将滚轮放回到大腿处。 重复所需的重复次数。"},{"id":"2207","name_zh":"泡沫轴侧背阔肌拉伸","target":"背阔肌","media_id":"c3Pfhti","instructions_zh":"双脚分开与肩同宽站立，双手握住滚轮放在身体前方。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 向前伸展双臂，将滚轮向脚部方向滚动，感受背阔肌的拉伸。 保持拉伸几秒钟，然后慢慢地将滚轮滚动回起始位置。 重复所需的重复次数。"},{"id":"0680","name_zh":"爬绳","target":"上背部","media_id":"yaAxcQr","instructions_zh":"面向绳子站立，双脚分开与肩同宽。 用双手抓住绳子，手掌朝向自己。 稍微弯曲膝盖并启动核心。 开始通过交替的双手动作将自己拉上绳子。 用双腿协助向上运动。 继续攀爬，直到到达所需的高度或绳索的顶部。 要下降，请在控制下降的同时反转双手的动作。 重复所需的重复次数。"},{"id":"0685","name_zh":"跑步","target":"有氧","media_id":"oLrKqDH","instructions_zh":"首先站直，双脚分开与臀部同宽。 启动你的核心并保持上半身放松。 开始原地慢跑，将膝盖抬向胸部，然后轻轻落在脚掌上。 保持稳定的步伐并继续慢跑所需的时间或距离。 记住在整个练习过程中深呼吸并保持良好的姿势。"},{"id":"0684","name_zh":"跑步（器械）","target":"有氧","media_id":"y5p0H8a","instructions_zh":"首先站直，双脚分开与臀部同宽。 启动你的核心并保持上半身放松。 开始原地慢跑，将膝盖抬向胸部，然后轻轻落在脚掌上。 保持稳定的步伐并继续慢跑所需的时间或距离。 记住在整个练习过程中深呼吸并保持良好的姿势。"},{"id":"1585","name_zh":"跑者拉伸","target":"大腿后侧","media_id":"0mB6wHO","instructions_zh":"双脚分开与臀部同宽站立。 右脚向前迈出一步，保持左脚踩地。 弯曲右膝，降低身体，保持左腿伸直。 将双手放在右大腿上以获得支撑。 保持拉伸 20-30 秒，然后换边重复。"},{"id":"0687","name_zh":"俄罗斯转体","target":"腹部","media_id":"XVDdcoj","instructions_zh":"坐在地上，膝盖弯曲，双脚平放在地板上。 稍微向后倾斜，同时保持背部挺直并且核心参与。 如果需要，双手合拢放在胸前或举重物。 将脚抬离地面，在坐骨上保持平衡。 将你的躯干向右扭转，将你的手或重量移向身体的右侧。 暂停片刻，然后将躯干向左扭转，将手或体重移向身体的左侧。 继续交替进行所需的重复次数。"},{"id":"3012","name_zh":"肩胛骨臂屈伸","target":"斜方肌","media_id":"7xeukSt","instructions_zh":"首先站立，双脚分开与肩同宽，双臂在身前伸展。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 弯曲肘部并缩回肩胛骨来降低身体，就像你试图在它们之间挤一支铅笔一样。 在底部停顿片刻，然后双手用力，伸展肘部，回到起始位置。 重复所需的重复次数。"},{"id":"3021","name_zh":"肩胛骨俯卧撑","target":"前锯肌","media_id":"jV65tKx","instructions_zh":"从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。 将胸部压向地面，保持肘部靠近身体。 当你下降时，将肩胛骨挤压在一起并将胸部向前推。 在底部停顿片刻，然后推回到起始位置。 重复所需的重复次数。"},{"id":"0688","name_zh":"肩胛引体向上","target":"斜方肌","media_id":"uTBt1HV","instructions_zh":"首先悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。 通过向下拉和向后拉动肩胛骨来缩回肩胛骨。 启动背部肌肉，将身体拉向杠铃杆，重点是将肩胛骨挤压在一起。 在动作的最高点停顿片刻，然后慢慢降低身体回到起始位置。 重复所需的重复次数。"},{"id":"3219","name_zh":"剪刀跳（男）","target":"有氧","media_id":"Eh2v5Iu","instructions_zh":"双脚分开与肩同宽站立。 跳离地面，同时将右腿交叉到左腿前面。 落地时，快速换腿，将左腿交叉在右腿前面。 继续交替双腿并尽可能快地跳跃。 重复所需的重复次数。"},{"id":"1390","name_zh":"坐姿小腿拉伸（男）","target":"小腿","media_id":"17bqEXD","instructions_zh":"坐在椅子或长凳的边缘，双脚平放在地面上。 将一只腿伸直在身前，脚跟保持在地面上。 稍微向前倾，感受小腿肌肉的拉伸。 保持拉伸 20-30 秒。 换腿并重复拉伸。"},{"id":"1424","name_zh":"坐姿臀部拉伸","target":"臀部","media_id":"DeDThfG","instructions_zh":"坐在地上，双腿在身前伸展。 弯曲右膝，将右脚踝交叉在左大腿上。 将右手放在身后的地面上以获得支撑。 用左手轻轻按下右膝盖以加深伸展。 保持拉伸 30 秒到 1 分钟。 换边并重复。"},{"id":"0689","name_zh":"坐姿抬腿","target":"腹部","media_id":"Hgs6Nl1","instructions_zh":"坐在平坦的长凳上，背部挺直，双脚平放在地面上。 将双手放在长凳两侧以获得支撑。 保持双腿伸直，慢慢将它们抬起到您面前，直到它们与地面平行。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0690","name_zh":"坐姿下背部拉伸","target":"背阔肌","media_id":"QFmz6ch","instructions_zh":"坐在椅子边缘，双脚平放在地面上。 将双手放在大腿上或椅子两侧以获得支撑。 从臀部开始慢慢向前倾斜，保持背部挺直。 感受下背部的拉伸并保持 20-30 秒。 慢慢回到起始位置并重复所需的重复次数。"},{"id":"2567","name_zh":"坐姿梨状肌拉伸","target":"臀部","media_id":"QY39eBr","instructions_zh":"坐在地上，双腿在身前伸展。 弯曲右膝，将右脚放在左膝外侧。 将左肘放在右膝外侧，轻轻地将躯干向右扭转。 保持拉伸 20-30 秒，然后换边重复。"},{"id":"0691","name_zh":"坐姿侧卷腹（靠墙）","target":"腹部","media_id":"Y9hNPcN","instructions_zh":"坐在地板上，背靠墙，双腿在身前伸展。 弯曲膝盖，将双脚平放在地板上，与臀部同宽。 将双手放在脑后，肘部朝外。 收紧腹肌并向一侧倾斜，将肘部靠近臀部。 暂停片刻，然后回到起始位置。 在另一侧重复。 继续交替进行所需的重复次数。"},{"id":"1587","name_zh":"坐姿广角式序列","target":"大腿后侧","media_id":"HIgYKAB","instructions_zh":"坐在地上，双腿大角度伸展。 弯曲你的脚并锻炼你的股四头肌。 将双手放在身后的地面上以获得支撑。 保持背部挺直，从臀部向前倾。 继续向前倾斜，直到感觉到腿筋被拉伸。 保持这个姿势几个呼吸。 慢慢释放拉伸并返回到起始位置。 重复所需的重复次数。"},{"id":"0697","name_zh":"自辅助反向腿弯举","target":"大腿后侧","media_id":"GwYwElT","instructions_zh":"平躺在垫子或长凳上，双腿伸展。 将双手放在身体两侧或臀部下方以获得支撑。 弯曲膝盖，将脚抬离地面，将大腿靠近胸部。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"1766","name_zh":"自辅助反向腿弯举","target":"大腿后侧","media_id":"ZSY3MsL","instructions_zh":"面朝下躺在腿弯举机上，双腿伸展，脚踝钩在带衬垫的杠杆下。 将双手放在机器的侧手柄上以获得支撑。 保持上半身静止，呼气并尽可能向上弯曲双腿。 挤压腿筋时，保持收缩位置短暂停顿。 吸气时慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0696","name_zh":"自辅助反向腿弯举（地面）","target":"大腿后侧","media_id":"E4PwJqI","instructions_zh":"平躺，双腿伸展，双臂放在身体两侧。 弯曲膝盖，将双脚平放在地面上，距离与臀部同宽。 将臀部抬离地面，锻炼臀肌和腿筋。 慢慢地将双腿向臀部弯曲，保持臀部抬起。 在顶部停顿片刻，然后慢慢将双腿伸展回起始位置。 将臀部放回地面。 重复所需的重复次数。"},{"id":"3222","name_zh":"半蹲跳（男）","target":"有氧","media_id":"6FMU51h","instructions_zh":"双脚分开与肩同宽站立。 弯曲膝盖并将身体降低至蹲姿。 爆发性跳跃，伸展臀部和膝盖，同时摆动手臂以获得动力。 脚掌轻轻落地，然后立即进入下一个重复动作。 重复所需的重复次数。"},{"id":"3656","name_zh":"小步跑","target":"有氧","media_id":"CcWEoWV","instructions_zh":"找一个空地或跑步机来进行锻炼。 站直，双脚分开与臀部同宽。 开始原地慢跑，抬起膝盖并挥动手臂。 几秒钟后，开始小步前进，保持快速的步伐。 继续小步跑所需的时间或距离。"},{"id":"1763","name_zh":"肩宽引体向上","target":"背阔肌","media_id":"YtgD7Xq","instructions_zh":"握距与肩同宽，抓住引体向上杆，手掌背向自己。 双臂完全伸展，自由悬挂。 启动背部肌肉，将身体向上拉向杠铃，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"3699","name_zh":"肩部触地","target":"腹部","media_id":"yRpV5TC","instructions_zh":"从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。 启动你的核心并将右手抬离地面，伸手拍打你的左肩。 将右手放回地面，然后用左手轻拍右肩，重复此操作。 继续交替轻拍肩膀，同时保持臀部和躯干稳定。 重复所需的重复次数。"},{"id":"0699","name_zh":"肩触俯卧撑","target":"胸","media_id":"qEse6fe","instructions_zh":"从高位平板支撑开始，双手分开略宽于肩宽，身体从头到脚跟呈一条直线。 弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。 当你向后推时，将右手抬离地面并轻拍左肩。 将右手放回地面并重复俯卧撑，这次抬起左手并拍打右肩。 每次重复俯卧撑时，继续交替拍肩。 在整个练习过程中保持核心稳定并避免臀部过度旋转。 重复所需的重复次数。"},{"id":"1774","name_zh":"侧桥髋外展","target":"外展肌","media_id":"WL4EmxJ","instructions_zh":"侧躺，双腿伸展并叠放在一起。 用前臂支撑自己，将肘部保持在肩膀正下方。 启动你的核心并将臀部抬离地面，从头到脚形成一条直线。 在保持核心肌群参与的同时，尽可能高地抬起上面的那条腿，但不要旋转臀部。 在顶部停顿片刻，然后将腿放下。 重复所需的重复次数，然后换边。"},{"id":"0705","name_zh":"侧桥2.0","target":"腹部","media_id":"RKjH6Lt","instructions_zh":"侧躺，双腿伸展并叠放在一起。 将前臂放在肩膀正下方的地面上，肘部弯曲成 90 度角。 启动你的核心并将臀部抬离地面，从头到脚形成一条直线。 保持此位置所需的时间。 将臀部放低至起始位置。 在另一侧重复。"},{"id":"0709","name_zh":"侧髋（双杠）","target":"腹部","media_id":"jTkSc6o","instructions_zh":"站在两根平行杠之间，双脚分开与肩同宽。 将双手放在横杆上，将身体抬离地面，用手臂支撑体重。 收紧腹肌，慢慢将双腿向一侧抬起，保持伸直。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0710","name_zh":"侧髋外展","target":"外展肌","media_id":"7WaDzyL","instructions_zh":"双脚分开与肩同宽站立，双手放在臀部。 将重心转移到一条腿上，并将另一条腿向一侧抬起，保持伸直。 在顶部暂停片刻，然后慢慢将腿放回起始位置。 在另一侧重复。 继续交替进行所需的重复次数。"},{"id":"1358","name_zh":"侧卧地面拉伸","target":"背阔肌","media_id":"jDOKRM5","instructions_zh":"侧躺，双腿伸直，下臂伸直过头顶。 弯曲上面的膝盖，将脚放在下面的腿前面的地面上。 将上臂伸过头顶，抓住稳定的东西，例如墙壁或一件家具。 慢慢地将下面的腿抬离地面，保持伸直，直到感觉到身体一侧有拉伸感。 保持拉伸 20-30 秒，然后慢慢将腿放下。 在另一侧重复。"},{"id":"3667","name_zh":"侧卧髋内收（男）","target":"内收肌","media_id":"c8f5cSY","instructions_zh":"侧躺，双腿伸直并叠放在一起。 将下臂放在头下方以获得支撑。 启动内收肌并尽可能高地抬起上面的腿，但不要旋转臀部或向后倾斜。 在顶部暂停片刻，然后慢慢将腿放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"1775","name_zh":"侧平板髋内收","target":"内收肌","media_id":"VO2qeJg","instructions_zh":"首先侧躺，双腿伸展并叠放在一起。 用前臂支撑自己，将肘部保持在肩膀正下方。 启动你的核心并将臀部抬离地面，从头到脚形成一条直线。 在保持侧平板支撑位置的同时，将上面的腿抬向天花板，保持笔直。 慢慢地将腿放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"0716","name_zh":"侧推颈部拉伸","target":"肩胛提肌","media_id":"oQRJYkC","instructions_zh":"站直或坐直，肩膀放松。 将头向右倾斜，将右耳靠近右肩。 将右手放在头部左侧，轻轻施加压力以增加拉伸。 保持拉伸 15-30 秒。 在另一侧重复，将头向左倾斜并用左手施加压力。 每侧重复拉伸 2-3 次。"},{"id":"0717","name_zh":"侧俯卧撑","target":"肱三头肌","media_id":"wpbD28t","instructions_zh":"首先侧躺，双腿伸展并叠放在一起。 将下面的手放在肩膀正下方的地面上，手指指向前方。 用下面的手将身体抬离地面，保持双腿伸直，核心肌群参与。 将上臂伸向天花板，形成从头部到脚后跟的直线。 有控制地降低身体回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0721","name_zh":"手腕侧向拉伸","target":"前臂","media_id":"UtmIqcI","instructions_zh":"双脚分开与肩同宽站立，双臂在身前伸展。 将右臂向侧面伸出，与地面平行，手掌朝下。 用左手抓住右手，轻轻地将其拉向身体，感觉右前臂有拉伸感。 保持拉伸 15-30 秒，然后放松。 在另一侧重复。"},{"id":"0720","name_zh":"左右移动下巴","target":"背阔肌","media_id":"isAAZWA","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 正手握住引体向上杆，双手之间的距离略大于肩宽。 悬挂在杠上，双臂完全伸展，身体放松。 弯曲肘部并将下巴朝向杠铃杆，将自己拉起，同时保持身体挺直。 一旦你的下巴高于杠铃，就将自己放低回到起始位置。 重复所需的重复次数。"},{"id":"3213","name_zh":"左右触脚尖（男）","target":"腹部","media_id":"WCAvOfC","instructions_zh":"双脚分开与肩同宽站立，双臂向两侧伸展。 腰部向右弯曲，将右手伸向右脚，同时保持左手向一侧延伸。 返回起始位置，然后腰部向左弯曲，将左手伸向左脚，同时保持右手向侧面延伸。 重复左右弯曲动作达到所需的重复次数。"},{"id":"0725","name_zh":"单臂俯卧撑","target":"胸","media_id":"MUic5zN","instructions_zh":"从俯卧撑位置开始，双手分开与肩同宽，一只手比另一只手稍宽。 弯曲肘部，保持背部挺直，调动核心力量，将身体降低至地面。 当你降低身体时，将你的重心转移到一侧，并将另一只手臂抬离地面，将其笔直延伸到一侧。 推动胸部和三头肌，将身体抬回到起始位置，同时将伸出的手臂放回地面。 重复该动作，每次重复时交替伸展手臂。"},{"id":"3645","name_zh":"单腿臀桥（另一腿伸直）","target":"臀部","media_id":"rmEukuS","instructions_zh":"仰卧，膝盖弯曲，双脚平放在地上。 将一条腿伸直在您面前。 收紧臀部并将臀部抬离地面，从膝盖到肩膀形成一条直线。 在顶部保持片刻，然后慢慢将臀部放回起始位置。 重复所需的重复次数，然后换腿。"},{"id":"0727","name_zh":"单腿提踵（踩哑铃）","target":"小腿","media_id":"fKZgDEO","instructions_zh":"双脚分开与臀部同宽站立，一只手握住哑铃。 将一只脚抬离地面并用另一只脚保持平衡。 使用小腿肌肉，慢慢地将脚跟抬高，尽可能高。 在顶部停顿片刻，然后慢慢降低脚跟。 重复所需的重复次数，然后换另一条腿。"},{"id":"0730","name_zh":"单腿滑盘","target":"大腿后侧","media_id":"LNE3wfo","instructions_zh":"首先将一只脚站在平台或滑板上。 稍微弯曲膝盖，将脚向后滑动到平台上，伸展腿。 在整个运动过程中保持核心参与并保持笔直姿势。 将脚滑回初始位置，慢慢返回起始位置。 重复该动作达到所需的重复次数，然后换腿。"},{"id":"1759","name_zh":"单腿深蹲（手枪式）（男）","target":"臀部","media_id":"nqs5HGV","instructions_zh":"双脚分开与肩同宽站立，双臂在身前伸展。 将右脚抬离地面并向前伸展。 弯曲左膝并将臀部向后推，慢慢降低身体。 降低身体时，保持挺胸、背部挺直。 降低直到左大腿与地面平行，或者尽可能降低到您能舒服的高度。 在底部停顿片刻，然后推动左脚跟回到起始位置。 重复所需的重复次数，然后换腿。"},{"id":"1489","name_zh":"西斯深蹲","target":"股四头肌","media_id":"xdYPUtE","instructions_zh":"双脚分开与肩同宽站立，脚趾稍微向外。 如果需要，请抓住一个稳定的物体以保持平衡。 弯曲膝盖并向后倾斜，慢慢降低身体，保持躯干直立。 继续降低，直到大腿与地面平行或尽可能舒适地下降。 暂停片刻，然后用力推动脚后跟，回到起始位置。 重复所需的重复次数。"},{"id":"0735","name_zh":"仰卧起坐（变式2）","target":"腹部","media_id":"Bn6TXyO","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"3679","name_zh":"双手抱胸仰卧起坐","target":"腹部","media_id":"6ZCiYWQ","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 双臂交叉于胸前。 收紧腹肌，将上半身抬离地面，靠近膝盖。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"3361","name_zh":"滑冰跳","target":"有氧","media_id":"zfNHMN9","instructions_zh":"双脚分开与肩同宽站立。 稍微弯曲膝盖，向右跳，右脚着地。 落地时，将左腿摆动到右腿后面，并用左脚趾敲击地面。 立即向左侧跳跃，左脚着地。 落地时，将右腿摆动到左腿后面，并用右脚趾敲击地面。 继续交替两侧，跳跃并用每条腿敲击地面。 重复所需的重复次数。"},{"id":"2142","name_zh":"滑雪机","target":"肱三头肌","media_id":"vpQaQkH","instructions_zh":"将座椅高度和脚踏板调整到舒适的位置。 正手握住手柄，手掌朝下。 坐直，双脚平放在脚踏板上。 将手臂伸直在身前，保持肘部稍微弯曲。 收紧三头肌并将手柄向下推向大腿。 在底部停顿片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"3671","name_zh":"滑雪步","target":"有氧","media_id":"5MRH8H2","instructions_zh":"双脚分开与肩同宽站立。 稍微弯曲膝盖并保持背部挺直。 跳到右侧，右脚着地，同时将左腿摆动到右腿后面。 立即向左侧跳，左脚着地，同时将右腿摆动到左腿后面。 继续从一侧到另一侧交替跳跃，模仿滑雪动作。 重复所需的重复次数。"},{"id":"3304","name_zh":"翻越","target":"上背部","media_id":"MSfvriJ","instructions_zh":"首先，将双臂完全伸展，身体放松地悬挂在杆上。 收紧核心并抬起双腿，使膝盖靠近胸部。 继续将双腿举过头顶，让身体穿过手臂。 一旦双腿完全伸过头顶，就开始将它们放回起始位置。 当你降低双腿时，让你的身体通过手臂向后移动，直到你再次完全伸展手臂悬挂。 重复所需的重复次数。"},{"id":"1425","name_zh":"45度倒蹬机单腿腿举","target":"臀部","media_id":"WWD6FzI","instructions_zh":"将雪橇机调整至 45 度角。 坐在雪橇机上，背部靠在垫子上，双脚放在踏板上。 将一只脚放在踏板上并伸展腿，将雪橇推离您。 慢慢弯曲膝盖，将雪橇放回起始位置。 换另一条腿重复上述步骤。 继续交替双腿达到所需的重复次数。"},{"id":"0738","name_zh":"45度倒蹬机提踵","target":"小腿","media_id":"qCNVnaU","instructions_zh":"将雪橇机调整至 45 度角。 将脚放在雪橇平台上，脚趾朝前。 伸展脚踝和小腿，将雪橇平台推离您。 在顶部暂停片刻，然后慢慢将雪橇平台放回起始位置。 重复所需的重复次数。"},{"id":"0739","name_zh":"45度倒蹬机腿举","target":"臀部","media_id":"10Z2DXU","instructions_zh":"将雪橇机的座椅和脚踏板调整到舒适的位置。 坐在雪橇机上，背部靠在靠背上，双脚与肩同宽放在踏板上。 握住座椅两侧的把手以保持稳定性。 伸展双腿，将脚踏板推离身体，脚后跟保持在脚踏板上。 继续推动，直到双腿几乎完全伸展，但不要锁住膝盖。 在动作的最高点暂停片刻，然后弯曲膝盖，慢慢地将踏板放回到身体的方向。 重复所需的重复次数。"},{"id":"1464","name_zh":"45度倒蹬机腿举（背部视角）","target":"臀部","media_id":"yn2lLSI","instructions_zh":"调整雪橇机的座椅，使膝盖成45度角。 坐在雪橇机上，背部靠在靠背上，双脚与肩同宽放在踏板上。 握住座椅两侧的把手以保持稳定性。 伸展双腿，将脚踏板推离身体，脚后跟保持在脚踏板上。 在完全伸展的位置暂停片刻。 慢慢弯曲膝盖，将踏板放回到身体的方向，控制动作。 重复所需的重复次数。"},{"id":"1463","name_zh":"45度倒蹬机腿举（侧面视角）","target":"臀部","media_id":"2Qh2J1e","instructions_zh":"调整雪橇机的座椅，使双脚放在踏板上时膝盖呈90度角。 坐在雪橇机上，背部平放在靠背上，双脚与肩同宽放在踏板上。 握住座椅两侧的把手以保持稳定性。 推动脚踏板以伸展双腿，将其完全伸直。 在顶部停顿片刻，然后慢慢弯曲膝盖，将踏板放回起始位置。 重复所需的重复次数。"},{"id":"0740","name_zh":"45度倒蹬机宽距腿举","target":"臀部","media_id":"tj41Nu6","instructions_zh":"将雪橇机调整至 45 度角。 坐在雪橇机上，背部靠在垫子上，双脚放在脚踏平台上。 双脚分开的距离比肩宽。 推动脚部平台以伸展双腿并伸直膝盖。 动作结束时暂停片刻，然后慢慢弯曲膝盖回到起始位置。 重复所需的重复次数。"},{"id":"1391","name_zh":"倒蹬机提踵","target":"小腿","media_id":"ykHcWme","instructions_zh":"调整压腿机的座椅，使双脚踩在雪橇上时膝盖稍微弯曲。 将双脚与肩同宽放在雪橇上，脚趾指向前方。 松开安全手柄，并通过伸展膝盖和脚踝将雪橇推离您。 在动作的最高点暂停片刻，然后弯曲膝盖和脚踝，慢慢将雪橇放回原处。 重复所需的重复次数。"},{"id":"0741","name_zh":"倒蹬机窄距哈克深蹲","target":"臀部","media_id":"gf3ZjB9","instructions_zh":"将雪橇机调整到舒适的重量，并将背部靠在垫子上。 将双脚分开与肩同宽放在平台上，脚趾稍微向外。 握住机器两侧的手柄以保持稳定性。 弯曲膝盖和臀部，调动核心力量，慢慢降低身体，保持背部挺直。 继续降低，直到大腿与地面平行或略低于地面。 在底部停顿片刻，然后用脚跟推动双腿并返回到起始位置。 重复所需的重复次数。"},{"id":"0742","name_zh":"倒蹬机前倾提踵","target":"小腿","media_id":"XDOiFns","instructions_zh":"将雪橇机调整到舒适的重量，然后将自己放在机器上，脚趾放在平台上，脚后跟悬空。 将手放在机器的手柄或侧面上以获得支撑。 收紧小腿，慢慢地尽可能高地抬起脚后跟，克服雪橇的阻力。 在动作的最高点暂停片刻，然后慢慢降低脚跟回到起始位置。 重复所需的重复次数。"},{"id":"0743","name_zh":"倒蹬机哈克深蹲","target":"臀部","media_id":"Qa55kX1","instructions_zh":"将雪橇机调整到适合您身高的舒适位置。 双脚与肩同宽站立在平台上，脚趾稍微向外。 握住手柄或杆以保持稳定性。 弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。 继续降低，直到大腿与地面平行或略低于地面。 暂停片刻，然后用脚后跟将身体抬回到起始位置。 重复所需的重复次数。"},{"id":"2334","name_zh":"倒蹬机仰卧提踵","target":"小腿","media_id":"g376LuL","instructions_zh":"将雪橇机调整至舒适的重量。 坐在雪橇机上，背部靠在垫子上，双脚放在平台上。 将脚趾和脚掌放在平台边缘，脚跟悬空。 伸展脚踝，将平台推离您，保持膝盖稍微弯曲。 继续用力，直到小腿完全收缩。 保持收缩一会儿，然后慢慢将平台放回起始位置。 重复所需的重复次数。"},{"id":"0744","name_zh":"倒蹬机仰卧深蹲","target":"臀部","media_id":"9n2149Z","instructions_zh":"将雪橇机调整至舒适的重量。 仰卧在雪橇机上，双脚放在踏板上。 双脚分开与肩同宽，并稍微向外倾斜。 握住雪橇机的手柄以保持稳定。 调动你的臀肌和核心肌肉。 脚后跟用力，双腿伸直，抬起雪橇。 弯曲膝盖和臀部，将雪橇放回原位。 重复所需的重复次数。"},{"id":"1392","name_zh":"倒蹬机单腿提踵","target":"小腿","media_id":"u0pLNgz","instructions_zh":"调整压腿机的座椅，使双脚踩在雪橇上时膝盖稍微弯曲。 坐在机器上，背部靠在靠背上，双脚放在雪橇上，与肩同宽。 将脚趾和脚掌放在雪橇上，保持脚跟离开。 伸展脚踝，保持膝盖稍微弯曲，将雪橇向前推。 在顶部停顿片刻，然后通过弯曲脚踝慢慢将雪橇放回原处。 重复所需的重复次数。"},{"id":"1496","name_zh":"大锤训练","target":"腹部","media_id":"REXmfVC","instructions_zh":"双脚分开与肩同宽站立，双手握住大锤。 启动你的核心并保持背部挺直。 使用核心和上半身的力量，将大锤向下挥向地面。 当你向下挥杆时，转动臀部并将力量传递到锤子上。 重复所需的重复次数。"},{"id":"0746","name_zh":"史密斯机后耸肩","target":"斜方肌","media_id":"MzNnwx9","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 正手握住杠铃，双手间距略宽于肩宽。 保持手臂伸直，让杠铃挂在大腿前面。 将肩膀向耳朵方向伸直，挤压斜方肌顶部。 保持一会儿，然后将肩膀放回起始位置。 重复所需的重复次数。"},{"id":"0747","name_zh":"史密斯机颈后推举","target":"肩","media_id":"Gpn4ADc","instructions_zh":"调整史密斯机的座椅高度，使杠铃与肩部齐平。 双脚分开与肩同宽站立，膝盖稍微弯曲。 正手握住杠铃，握距略宽于肩宽。 将杠铃从架子上抬起并向后退一步，保持稳定的姿势。 将杠铃降低到颈后，保持肘部向前。 将杠铃向上推过头顶，直到双臂完全伸展。 在顶部暂停片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0748","name_zh":"史密斯机卧推","target":"胸","media_id":"trqKQv2","instructions_zh":"将史密斯机杆的高度调整至胸部水平。 平躺在长凳上，双脚牢牢踩在地上。 正手握住杠铃，握距略宽于肩宽。 松开杠铃并将其向胸部降低，保持肘部内收。 当杠铃接触到你的胸部时暂停片刻。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0749","name_zh":"史密斯机屈膝早安式","target":"臀部","media_id":"1bQkKZK","instructions_zh":"首先站立，双脚分开与肩同宽，脚趾指向前方。 将杠铃放在上背部，放在斜方肌上。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 降低躯干直到与地面平行，感觉腿筋被拉伸。 启动臀肌和腿筋，将躯干抬回到起始位置。 重复所需的重复次数。"},{"id":"1359","name_zh":"史密斯机俯身划船","target":"上背部","media_id":"ZX9UZmj","instructions_zh":"将史密斯机设置为与臀部高度相同的杠铃。 面向杠铃站立，双脚分开与肩同宽。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 正手握住杠铃，双手距离略宽于肩宽。 将杠铃拉向下胸部，将肩胛骨挤压在一起。 在顶部暂停片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0750","name_zh":"史密斯机箱式深蹲","target":"股四头肌","media_id":"Gu2rNJd","instructions_zh":"将史密斯机杆的高度调整到舒适的位置。 站立，双脚分开与肩同宽，脚趾稍微向外。 将杠铃放在上背部，放在斜方肌上。 通过弯曲膝盖和臀部慢慢降低身体，收紧核心并保持挺胸。 继续降低，直到大腿与地面平行，或者尽可能低。 暂停片刻，然后用力推动脚后跟，回到起始位置。 重复所需的重复次数。"},{"id":"0751","name_zh":"史密斯机窄距卧推","target":"肱三头肌","media_id":"WcHl7ru","instructions_zh":"调整座椅高度，将自己放在长凳上，双脚平放在地面上。 紧紧握住杠铃，握距略窄于肩宽。 将杠铃向胸部降低，保持肘部靠近身体。 在底部停顿片刻，然后将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"0752","name_zh":"史密斯机硬拉","target":"臀部","media_id":"UfePqpx","instructions_zh":"将史密斯机设置为与臀部高度相同的杠铃。 双脚分开与肩同宽站立，脚趾稍微向外。 弯曲臀部和膝盖，保持背部挺直，挺胸，正手握住杠铃，握距略宽于肩宽。 伸展臀部和膝盖，调动核心力量并举起杠铃，保持杠铃靠近身体。 站直，充分伸展臀部和膝盖。 通过弯曲臀部和膝盖来降低杠铃，保持控制并保持背部挺直。 重复所需的重复次数。"},{"id":"0753","name_zh":"史密斯机下斜卧推","target":"胸","media_id":"ETZfAbZ","instructions_zh":"将下斜凳调整至所需角度。 躺在长凳上，双脚固定在脚垫下。 正手握住杠铃，握距略宽于肩宽。 松开杠铃，慢慢将其降低到胸部，保持肘部内收。 在底部停顿片刻，然后将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"0754","name_zh":"史密斯机下斜反握推举","target":"胸","media_id":"MY9P1WA","instructions_zh":"将史密斯机调整至下降位置。 躺在长凳上，双脚固定在脚垫下。 反握抓住杠铃，双手分开略宽于肩宽。 松开杠铃并将其向胸部降低，保持肘部内收。 在底部停顿片刻，然后将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"1433","name_zh":"史密斯机前蹲（高翻握法）","target":"臀部","media_id":"lFhb2Rw","instructions_zh":"将杠铃置于肩高的史密斯机上。 面向杠铃站立，双脚与肩同宽。 正手握住杠铃，握距略宽于肩宽。 后退一步，将杠铃放在前肩上，放在锁骨和三角肌上。 保持挺胸、背部挺直、核心收紧。 弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。 继续降低，直到大腿与地面平行或略低于地面。 暂停片刻，然后用力推动脚后跟，回到起始位置。 重复所需的重复次数。"},{"id":"3281","name_zh":"史密斯机全蹲","target":"臀部","media_id":"NNoHCEA","instructions_zh":"将杠铃置于肩高的史密斯机上。 站立，双脚分开与肩同宽，脚趾稍微向外。 走到杠铃下方，将其放在上背部上方，放在斜方肌上。 双手握住杠铃，距离略大于肩宽。 松开杠铃并后退一步，保持稳定的姿势。 保持胸部挺直，核心参与，通过将臀部向后推并弯曲膝盖来开始深蹲。 降低你的身体，直到你的大腿与地面平行，或者在你的灵活性允许的范围内尽可能低。 在底部停顿片刻，然后用脚后跟恢复到起始位置。 重复所需的重复次数。"},{"id":"0755","name_zh":"史密斯机哈克深蹲","target":"臀部","media_id":"ZuPXtCK","instructions_zh":"将史密斯机上的杠铃调整到适合您身体的高度。 双脚分开与肩同宽站立，脚趾稍微向外。 将自己置于杠铃下方，将其放在斜方肌上部和肩膀上。 正手握住杠铃，握距略宽于肩宽。 当你打开杠铃时，启动你的核心并保持挺胸。 后退一步，双脚分开的距离略大于肩宽。 弯曲膝盖，降低身体，保持挺胸、背部挺直。 继续下降，直到大腿与地面平行或略低于地面。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0756","name_zh":"史密斯机臀桥","target":"腹部","media_id":"CqhoytW","instructions_zh":"将自己放在史密斯机上，背部靠在垫子上，双脚分开与肩同宽。 将双手放在杠铃上，距离略宽于肩宽。 启动你的核心肌群和臀大肌，然后通过脚后跟将臀部抬离地面。 继续提升，直到身体从膝盖到肩膀形成一条直线。 在顶部保持片刻，然后慢慢将臀部放回起始位置。 重复所需的重复次数。"},{"id":"0757","name_zh":"史密斯机上斜卧推","target":"胸","media_id":"5v7KYld","instructions_zh":"将长凳调整至 30-45 度倾斜。 坐在长凳上，背部平放在垫子上，双脚牢牢踩在地上。 正手握住杠铃，握距略宽于肩宽。 松开杠铃，慢慢地将其降低到上胸部，保持肘部稍微内收。 在底部停顿片刻，然后将杠铃推回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"0758","name_zh":"史密斯上斜反握卧推","target":"胸","media_id":"78VqWQK","instructions_zh":"将史密斯机的座椅调整到舒适的倾斜角度。 坐在机器上，背部靠在垫子上，双脚平放在地面上。 正手握住杠铃，握距略宽于肩宽。 松开杠铃并将其缓慢降低至胸部，同时保持肘部内收。 当杠铃位于胸部正上方时，暂停片刻。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0759","name_zh":"史密斯上斜肩举","target":"前锯肌","media_id":"ayAHcEm","instructions_zh":"将史密斯机调整至倾斜位置。 面向机器站立，双脚分开与肩同宽。 正手握住杠铃，握距略宽于肩宽。 保持背部挺直，核心参与。 将杠铃举向天花板，用肘部引导。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0760","name_zh":"史密斯腿举","target":"臀部","media_id":"7zdxRTl","instructions_zh":"将史密斯机的座椅和脚踏板调整到舒适的位置。 坐在机器上，背部靠在靠背上，双脚与肩同宽放在踏板上。 抓住机器的手柄或侧面以保持稳定性。 伸展双腿，使背部紧靠靠背，将脚踏板推离您。 在完全伸展的位置暂停片刻。 慢慢弯曲膝盖，将脚踏板向您的方向放低，回到起始位置。 重复所需的重复次数。"},{"id":"1434","name_zh":"史密斯低杠深蹲","target":"臀部","media_id":"RGLscZM","instructions_zh":"将史密斯机与杠铃设置在一个高度，以便您可以将其舒适地放在上背部。 站立，双脚分开与肩同宽，脚趾稍微向外转动。 走到杠铃下方，将其放在上背部上方，将其放在斜方肌上。 双手握住杠铃，距离略大于肩宽。 伸直双腿并从架子上退后，将杠铃松开。 深呼吸并支撑你的核心。 通过向后推臀部并弯曲膝盖来开始深蹲。 降低身体，直到大腿与地面平行或稍低于地面。 在整个动作过程中保持挺胸、背部挺直。 通过脚后跟站起来，伸展臀部和膝盖。 重复所需的重复次数。"},{"id":"1683","name_zh":"史密斯机二头弯举","target":"肱二头肌","media_id":"zILLZ98","instructions_zh":"将史密斯机杆的高度调整到腰部水平。 面对史密斯机站立，双脚与肩同宽。 反手握住杠铃，双手间距略大于肩宽。 保持肘部靠近身体两侧，上臂保持静止。 呼气并将杠铃向上卷向肩膀，收缩二头肌。 在动作的最高点暂停片刻，挤压你的二头肌。 吸气并慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"1625","name_zh":"史密斯机下斜窄握卧推","target":"肱三头肌","media_id":"yB9SvIF","instructions_zh":"将史密斯机上的长凳调整至下降位置。 躺在长凳上，双脚牢牢踩在地上。 紧紧握住杠铃，握距略窄于肩宽。 松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。 当杠铃位于胸部正上方时，暂停片刻。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"1752","name_zh":"史密斯机上斜臂屈伸","target":"肱三头肌","media_id":"o8aOcrz","instructions_zh":"调整史密斯机的座椅，使杠铃处于肩部高度。 坐在长凳上，背部靠在垫子上，双脚平放在地上。 正手握住杠铃，握距略宽于肩宽。 充分伸展双臂，将杠铃从架子上提起，并将其保持在胸部正上方。 慢慢地将杠铃降低到前额，保持肘部靠近头部。 在底部暂停片刻，然后将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"1626","name_zh":"史密斯机反向下斜窄握卧推","target":"胸","media_id":"QyO6Uma","instructions_zh":"将史密斯机调整至下降位置。 躺在长凳上，双脚固定在脚垫下。 紧紧握住杠铃，握距略窄于肩宽。 松开杠铃，慢慢将其降低到胸部，保持肘部内收。 在底部停顿片刻，然后将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"0761","name_zh":"史密斯窄距划船","target":"上背部","media_id":"JGKowMS","instructions_zh":"调整座椅高度并将自己放在机器上，双脚平放在地板上。 正手握住手柄，握距略窄于肩宽。 当您将手柄拉向身体时，保持背部挺直，挺胸，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"1360","name_zh":"史密斯单臂划船","target":"上背部","media_id":"Q4DSJPC","instructions_zh":"将史密斯机杆的高度调整至腰部水平。 面对史密斯机站立，双脚与肩同宽。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 用一只手正手握住杠铃，手掌朝下。 保持肘部靠近身体，将杠铃拉向腰部，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。"},{"id":"1393","name_zh":"史密斯单腿地板提踵","target":"小腿","media_id":"9GXrTE6","instructions_zh":"将自己放在史密斯机杆下方的地板上，背对机器。 将脚掌放在凸起的表面上，例如举重板或杠铃块。 将史密斯机杆放在小腿上，就在脚踝上方。 用手握住横杆以保持稳定。 伸展脚踝，将脚后跟抬离地面，抬起身体。 在动作的最高点暂停，然后慢慢降低脚跟回到起始位置。 重复所需的重复次数。"},{"id":"0762","name_zh":"史密斯后束划船","target":"肩","media_id":"nFUwqG6","instructions_zh":"调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地面上。 正手握住手柄，握距略宽于肩宽。 将手柄拉向胸部，将肩胛骨挤压在一起，保持背部挺直，核心肌群参与。 在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。"},{"id":"0763","name_zh":"史密斯反向提踵","target":"小腿","media_id":"ywaNfuh","instructions_zh":"将史密斯机杆调整到略低于肩膀的高度。 面向杠铃站立，双脚分开与臀部同宽，脚趾向前。 将脚掌放在台阶或平台的边缘，脚后跟悬空。 握住杠铃以提供支撑，保持背部挺直，核心肌群参与。 尽可能高地抬高脚后跟，将身体重量转移到脚掌上。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1394","name_zh":"史密斯反向提踵","target":"小腿","media_id":"Lsqrgh4","instructions_zh":"将史密斯机杆调整到略低于肩膀的高度。 面向杠铃站立，双脚分开与臀部同宽，脚趾向前。 将脚掌放在台阶或平台的边缘，脚后跟悬空。 抓住横杆以获得支撑。 尽可能高地抬高脚跟，将身体抬起到脚趾上。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1361","name_zh":"史密斯反握俯身划船","target":"上背部","media_id":"aaxA3cm","instructions_zh":"将史密斯机设置为与臀部高度相同的杠铃。 面向杠铃站立，双脚分开与肩同宽。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 反手握住杠铃，双手与肩同宽。 将杠铃拉向下胸部，将肩胛骨挤压在一起。 在顶部暂停片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0764","name_zh":"史密斯反握卧推","target":"胸","media_id":"zK8Fu1W","instructions_zh":"将史密斯机杆的高度调整至胸部水平。 面向杠铃站立，双脚分开与肩同宽。 正手握住杠铃，双手距离略宽于肩宽。 退后一步，膝盖稍微弯曲。 在整个练习过程中保持挺胸并保持核心参与。 将杠铃向胸部方向降低，保持肘部内收。 在底部暂停片刻，然后将杠铃推回到起始位置。 重复所需的重复次数。"},{"id":"1395","name_zh":"史密斯坐姿单腿提踵","target":"小腿","media_id":"0S75mYG","instructions_zh":"坐在机器上，背部靠在垫子上，双脚放在脚踏板上。 将一条腿放在脚踏板上，另一条腿离开脚踏板。 使用小腿肌肉，尽可能高地抬高脚跟。 在顶部暂停片刻，然后慢慢将脚跟放回起始位置。 重复所需的重复次数，然后换腿并重复。"},{"id":"0765","name_zh":"史密斯坐姿肩推举","target":"肩","media_id":"xUwnBMT","instructions_zh":"调整座椅高度，使手柄与肩部齐平。 坐在机器上，背部靠在垫子上，双脚平放在地板上。 正手握住手柄，将其提离支撑物，充分伸展双臂。 将手柄降低至肩部水平，保持肘部稍微弯曲。 将手柄向上推过头顶，直到手臂完全伸展。 在顶部暂停片刻，然后慢慢将手柄放回至肩部水平。 重复所需的重复次数。"},{"id":"1426","name_zh":"史密斯坐姿腕弯举","target":"前臂","media_id":"B6dAO1t","instructions_zh":"坐在史密斯机前的长凳上，双脚平放在地面上。 反握抓住杠铃，双手与肩同宽。 将前臂放在大腿上，让手腕悬垂。 慢慢向上弯曲手腕，将杠铃拉向前臂。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0766","name_zh":"史密斯肩推举","target":"肩","media_id":"903mzG8","instructions_zh":"调整座椅高度，将自己放在史密斯机上，双脚分开与肩同宽。 正手握住杠铃，握距略宽于肩宽。 将杠铃从架子上提起，并将其置于与肩同高的位置，肘部弯曲，手掌朝前。 向上推杠铃，直到手臂完全伸过头顶。 在顶部暂停片刻，然后慢慢将杠铃放回至肩部水平。 重复所需的重复次数。"},{"id":"0767","name_zh":"史密斯耸肩","target":"斜方肌","media_id":"OUQ0ZyW","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 正手握住杠铃，双手间距略宽于肩宽。 保持双臂伸直，肩膀放松。 将肩膀向耳朵方向抬起，在顶部挤压斜方肌。 保持一会儿，然后慢慢将肩膀放回起始位置。 重复所需的重复次数。"},{"id":"0768","name_zh":"史密斯单腿分腿蹲","target":"股四头肌","media_id":"wWFspEi","instructions_zh":"站在史密斯机前，双脚分开与肩同宽。 将一只脚放在身后的长凳或台阶上，脚趾向前。 握住史密斯机杆以保持稳定性。 弯曲前膝盖，将身体降低到弓步位置，保持背部挺直。 在底部停顿片刻，然后推动前脚跟回到起始位置。 重复所需的重复次数，然后换腿。"},{"id":"0769","name_zh":"史密斯冲刺弓步","target":"臀部","media_id":"HsjbB1z","instructions_zh":"将杠铃置于臀部高度的史密斯机上。 背对机器站立，双脚与肩同宽。 右脚向后退一步，将其放在杠铃上，将脚尖放在杠上。 弯曲左膝，将身体降低到弓步位置，保持背部挺直。 推动左脚跟返回到起始位置。 在另一侧重复，左脚向后退一步。 继续交替进行所需的重复次数。"},{"id":"0770","name_zh":"史密斯深蹲","target":"臀部","media_id":"jFtipLl","instructions_zh":"将史密斯机和杠铃设置在适合深蹲的高度。 站立，双脚分开与肩同宽，脚趾稍微向外。 将自己置于杠铃下方，将其放在斜方肌上部和肩膀上。 宽握距握住杠铃，握距略宽于肩宽。 启动你的核心并打开杠铃，后退以清理架子。 保持胸部挺直，背部挺直，通过弯曲臀部和膝盖开始深蹲。 降低身体，直到大腿与地面平行或稍低于地面。 在底部停顿片刻，然后用脚后跟恢复到起始位置。 重复所需的重复次数。"},{"id":"0771","name_zh":"史密斯站立背后腕弯举","target":"前臂","media_id":"hfmQ0Tz","instructions_zh":"面对史密斯机站立，双脚与肩同宽。 正手握住杠铃，双手与肩同宽。 保持背部挺直，肘部靠近身体。 慢慢向上弯曲手腕，将杠铃拉向身体。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0772","name_zh":"史密斯站立颈后推举","target":"肩","media_id":"ht8xDrP","instructions_zh":"调整史密斯机的座椅高度，使杠铃与肩部齐平。 双脚分开与肩同宽站立，膝盖稍微弯曲。 正手握住杠铃，握距略宽于肩宽。 将杠铃从架子上抬起并向后退一步，保持稳定的姿势。 将杠铃放在脑后，放在斜方肌上部。 在整个练习过程中保持核心收紧并抬起胸部。 伸展双臂，完全伸直，将杠铃推过头顶。 在动作的最高点稍作停顿，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"0773","name_zh":"史密斯站立提踵","target":"小腿","media_id":"6MaEjVA","instructions_zh":"将史密斯机杆调整到一个高度，使您能够双脚平放在地面上且肩膀位于杆下方。 将自己置于杠铃下方，双脚分开与肩同宽，脚趾向前。 将双手放在横杆上以保持稳定。 收紧小腿，慢慢将脚跟抬离地面，将身体抬起到脚趾上。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0774","name_zh":"史密斯站立推举","target":"肩","media_id":"jjUPrze","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 正手握住杠铃，握距略宽于肩宽。 将杠铃从架子上提起，并将其降至与肩同高，手掌朝前。 向上推杠铃，直到手臂完全伸过头顶。 在顶部停顿片刻，然后慢慢将杠铃放回至肩部水平。 重复所需的重复次数。"},{"id":"3142","name_zh":"史密斯相扑深蹲","target":"臀部","media_id":"dzz6BiV","instructions_zh":"将杠铃置于臀部高度的史密斯机上。 站立，双脚分开比肩宽，脚趾朝外。 将自己置于杠铃下方，将其放在上背部和肩膀上。 当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。 放低身体，直到大腿与地面平行，或者尽可能低到您能舒服的高度。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1396","name_zh":"史密斯勾脚尖","target":"小腿","media_id":"Y4QlY8z","instructions_zh":"将史密斯机杆调整到一个高度，让您可以舒适地站立，双脚平放在地面上。 将自己置于杠铃下方，肩膀位于杠铃正下方，双脚分开与肩同宽。 将脚掌放在升高的平台或重量板上，脚后跟悬在边缘。 正手握住杠铃，握距略宽于肩宽。 在整个练习过程中启动你的核心并保持背部挺直。 慢慢地尽可能高地抬起脚后跟，将身体重量转移到脚掌上。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0775","name_zh":"史密斯直立划船","target":"肩","media_id":"1DN3iz4","instructions_zh":"双脚分开与肩同宽站立，面向史密斯机。 正手握住杠铃，双手间距略宽于肩宽。 保持背部挺直，核心肌群参与。 将杠铃拉向下巴，用肘部引导。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"1308","name_zh":"史密斯宽握卧推","target":"胸","media_id":"zoOvPcx","instructions_zh":"将史密斯机上的长凳调整到舒适的位置。 躺在长凳上，双脚平放在地上。 宽握距抓住杠铃，握距略宽于肩宽。 松开杠铃并将其慢慢降低到胸部，保持肘部向两侧伸出。 当杠铃触及胸部时暂停片刻。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"1309","name_zh":"史密斯宽握下斜卧推","target":"胸","media_id":"wi2H9QX","instructions_zh":"将下斜凳调整至所需角度。 躺在长凳上，双脚固定在脚垫下。 宽握距抓住杠铃，握距略宽于肩宽。 松开杠铃并将其慢慢降低到胸部，保持肘部朝外。 当杠铃触及胸部时暂停片刻。 将杠铃推回到起始位置，完全伸展双臂。 重复所需的重复次数。"},{"id":"0776","name_zh":"抓举提拉","target":"股四头肌","media_id":"dG5Smob","instructions_zh":"双脚分开与肩同宽站立，杠铃放在你面前的地面上。 弯曲膝盖并以臀部为铰链，降低至下蹲位置，用正手握住杠铃。 当你通过脚后跟将杠铃抬离地面时，保持背部挺直，挺胸，伸展臀部和膝盖。 当杠铃到达臀部水平时，爆发性地将其向上拉，耸肩并将肘部向两侧拉高。 当杠铃到达最高点时，迅速落到杠铃下方，将自己拉成深蹲位置。 双臂完全伸展，膝盖弯曲，将杠铃举过头顶。 伸展臀部和膝盖站起来，将杠铃保持在头顶上方。 通过反向运动将杠铃降低回起始位置。 重复所需的重复次数。"},{"id":"0777","name_zh":"施法者","target":"腹部","media_id":"p9cCe2r","instructions_zh":"双脚分开与肩同宽站立，一只手握住哑铃。 稍微弯曲膝盖，腰部向前转动，保持背部挺直。 将哑铃伸向另一只脚的手臂，同时旋转躯干。 返回起始位置并在另一侧重复。 继续交替进行所需的重复次数。"},{"id":"1362","name_zh":"斯芬克斯","target":"脊柱","media_id":"DIVyqrU","instructions_zh":"面朝下躺在地上，前臂平放在地板上，肘部直接位于肩膀下方。 收紧核心肌群，将胸部抬离地面，将前臂和脚趾保持在地板上。 保持这个姿势几秒钟，确保颈部保持在中立位置。 慢慢地将胸部放回起始位置。 重复所需的重复次数。"},{"id":"0778","name_zh":"蜘蛛爬俯卧撑","target":"臀部","media_id":"P9GFBME","instructions_zh":"从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。 将右膝靠近右肘，使其离开地面。 当您将右膝向后拉时，同时弯曲肘部将身体降低到地面。 推回起始位置，然后将左膝朝向左肘重复此动作。 继续交替进行所需的重复次数。"},{"id":"1363","name_zh":"脊柱拉伸","target":"脊柱","media_id":"JbC2iaV","instructions_zh":"坐在地上，双腿在身前伸展。 将双手放在身后的地面上，手指指向身体。 启动你的核心并慢慢向后倾斜，保持背部挺直。 继续向后倾斜，直到感觉到脊柱被拉伸。 保持伸展几秒钟，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"2329","name_zh":"脊柱扭转","target":"腹部","media_id":"2jl9K55","instructions_zh":"坐在地上，双腿在身前伸展。 弯曲膝盖，将双脚平放在地面上，距离与臀部同宽。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢向右扭转躯干，将右肘拉向左膝盖。 扭转结束时暂停片刻，然后慢慢回到起始位置。 向左侧重复扭转，将左肘拉向右膝盖。 继续交替进行所需的重复次数。"},{"id":"2368","name_zh":"箭步蹲","target":"股四头肌","media_id":"9E25EOx","instructions_zh":"双脚分开与肩同宽站立。 一只脚向前迈出一步，并将其放在另一只脚前面约两英尺处。 弯曲膝盖和臀部，降低身体，保持背部挺直。 继续降低，直到前大腿与地面平行，后膝盖悬停在地面上方。 暂停片刻，然后推动前脚跟回到起始位置。 重复所需的重复次数，然后换腿并重复。"},{"id":"0786","name_zh":"深蹲挺举","target":"股四头肌","media_id":"IMRsOCn","instructions_zh":"首先将杠铃放在肩膀上，双脚分开与肩同宽。 将身体降低至蹲姿，保持挺胸，膝盖位于脚趾上方。 当你到达深蹲底部时，爆发性地用腿发力，并将杠铃推过头顶。 当杠铃到达最高点时，迅速落入分体位置，一脚向前，一脚向后。 双臂完全伸展，后膝盖稍微接触地面，将杠铃举过头顶。 从分开的位置站起来，将双脚重新并拢。 将杠铃放回肩膀处，然后重复所需的重复次数。"},{"id":"1705","name_zh":"波速球深蹲","target":"股四头肌","media_id":"T2fA5Ir","instructions_zh":"将博苏球平放在地上。 双脚分开与肩同宽站立，将自己放在博苏球的顶部。 弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。 保持挺胸，将体重放在脚后跟上。 降低身体直到大腿与地面平行。 暂停片刻，然后用力推动脚后跟，回到起始位置。 重复所需的重复次数。"},{"id":"1685","name_zh":"深蹲上举","target":"股四头肌","media_id":"QChZi3x","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微外翻。 弯曲膝盖并将臀部向后推，将身体降低至蹲姿。 当你从深蹲中站起来时，将手臂伸过头顶，伸向天花板。 放下手臂并弯曲膝盖再次蹲下，回到起始位置。 重复所需的重复次数。"},{"id":"1686","name_zh":"深蹲上举转体","target":"股四头肌","media_id":"5BZHW9s","instructions_zh":"站立，双脚分开与肩同宽，脚趾稍微外翻。 弯曲膝盖并将臀部向后推，将身体降低至蹲姿。 当你从深蹲中站起来时，将手臂举过头顶并将躯干扭转到一侧。 返回起始位置并重复下蹲，这次将躯干扭转到另一侧。 每次深蹲重复时继续交替进行。"},{"id":"2297","name_zh":"瑞士球卷腹（全幅度，双手抱头）","target":"腹部","media_id":"Gn5FwYT","instructions_zh":"坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。 将双手放在脑后，肘部朝外。 收紧腹肌，慢慢向前弯曲上半身，使胸部靠近膝盖。 在顶部停顿片刻，然后慢慢降低上半身回到起始位置。 重复所需的重复次数。"},{"id":"3291","name_zh":"施塔尔德压","target":"肱三头肌","media_id":"zd4P4B2","instructions_zh":"首先站立，双脚分开与肩同宽，双臂伸过头顶。 稍微弯曲膝盖并启动核心。 将身体降低至蹲姿，同时保持手臂伸过头顶。 当你蹲下时，将手臂向下压向地面，锻炼三头肌。 在深蹲底部停顿片刻，然后用脚后跟站起来，同时将手臂举过头顶。 重复所需的重复次数。"},{"id":"3669","name_zh":"站姿弓步","target":"上背部","media_id":"JF8AkMX","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 将双臂伸直至前方，与肩同高，与地面平行。 将躯干向右旋转，保持双臂伸展，背部挺直。 旋转时，向前伸展右臂，向后伸展左臂，模仿拉弓弦的动作。 保持该姿势片刻，然后回到起始位置。 重复该动作，这次将躯干向左旋转，左臂向前伸展，右臂向后伸展。 继续交替进行所需的重复次数。"},{"id":"0788","name_zh":"站姿颈后推举","target":"肩","media_id":"xDh0lJr","instructions_zh":"双脚分开与肩同宽站立，用正手握法将杠铃握在颈后。 保持背部挺直，核心参与。 伸展手臂，充分伸展肘部，将杠铃推过头顶。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。"},{"id":"1490","name_zh":"站姿提踵（在楼梯上）","target":"小腿","media_id":"6HmFgmx","instructions_zh":"站在台阶或坚固平台的边缘，脚后跟悬垂，脚趾放在台阶上。 如果需要，抓住栏杆或墙壁以保持平衡。 慢慢地尽可能高地抬起脚后跟，将身体重量转移到脚掌上。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1397","name_zh":"站姿提踵","target":"小腿","media_id":"XIHEoCG","instructions_zh":"双脚分开与肩同宽站立，脚趾指向前方。 将脚后跟抬离地面，尽可能高，用脚趾站立。 保持该姿势片刻，然后慢慢降低脚跟回到起始位置。 重复所需的重复次数。"},{"id":"1398","name_zh":"站姿小腿拉伸","target":"小腿","media_id":"qOKcgVP","instructions_zh":"面朝墙壁或坚固物体站立，距离大约一臂远。 将手放在与肩同高的墙壁或物体上。 一只脚向后退一步，保持脚跟平放在地面上。 稍微弯曲前膝盖并向前倾斜，保持后腿伸直。 您应该感觉到小腿肌肉有拉伸感。 保持拉伸 20-30 秒。 在另一条腿上重复。"},{"id":"1599","name_zh":"站姿腘绳肌与小腿拉伸（弹力带）","target":"大腿后侧","media_id":"xTjr103","instructions_zh":"站直，双脚分开与肩同宽。 用双手握住带子并将其放在脚掌周围。 保持腿伸直，从臀部慢慢向前倾斜，保持背部挺直。 感受腿筋和小腿肌肉的拉伸。 保持拉伸 20-30 秒。 放松拉伸并用另一条腿重复。 重复所需的重复次数。"},{"id":"0794","name_zh":"站姿侧伸展","target":"背阔肌","media_id":"1jXLYEw","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 将双臂伸直至两侧，与地面平行。 慢慢将上半身向一侧倾斜，感觉侧面和背阔肌有拉伸感。 保持拉伸 15-30 秒。 返回起始位置并在另一侧重复。 重复所需的重复次数。"},{"id":"1364","name_zh":"站姿骨盆倾斜","target":"脊柱","media_id":"cuKYxhu","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 将双手放在臀部或垂在身体两侧。 调动核心肌肉并向前倾斜骨盆，将下背部推向身后的墙壁。 保持该位置几秒钟，然后松开并返回到起始位置。 重复所需的重复次数。"},{"id":"0795","name_zh":"站姿单腿弯举","target":"大腿后侧","media_id":"C5jncD2","instructions_zh":"站立，双脚分开与臀部同宽，双手放在臀部。 将体重转移到左腿上，将右脚抬离地面，弯曲膝盖。 慢慢地将右脚跟卷向臀部，挤压腿筋。 在顶部暂停片刻，然后慢慢将右脚放回起始位置。 重复所需的重复次数，然后换腿。"},{"id":"0796","name_zh":"站姿健腹轮前滚","target":"腹部","media_id":"KtRomty","instructions_zh":"首先，站直，双脚分开与肩同宽，滚轮位于您的前方。 弯腰，慢慢向前滚动轮子，保持背部挺直，核心肌群参与。 继续向前滚动，直到感觉到腹肌拉伸并且身体尽可能伸展。 暂停片刻，然后慢慢地将轮子向身体方向滚动，回到起始位置。 重复所需的重复次数。"},{"id":"3223","name_zh":"星跳（男）","target":"有氧","media_id":"HtfCpfi","instructions_zh":"双脚分开与肩同宽站立，双臂放在身体两侧。 稍微弯曲膝盖并爆发性地跳起来。 跳跃时，张开双腿，将手臂向两侧伸展，与身体形成星形。 膝盖轻轻弯曲，脚掌轻轻着地。 重复所需的重复次数。"},{"id":"2138","name_zh":"固定单车跑步 v.3","target":"有氧","media_id":"H1PESYI","instructions_zh":"调整座椅高度和位置以确保正确对齐。 将脚放在踏板上，并用带子（如果有）将其固定。 以舒适的速度开始踩踏板。 保持稳定的节奏并根据需要增加阻力。 调动核心肌肉以保持稳定性和正确的姿势。 继续踩踏板达到所需的锻炼时间。 逐渐减小阻力并减速，然后完全停止。 锻炼后伸展双腿并放松。"},{"id":"0798","name_zh":"固定单车行走","target":"有氧","media_id":"a8VDgLw","instructions_zh":"调整固定自行车上的座椅高度和位置，以确保正确对齐。 将脚放在踏板上，并用带子（如果有）将其固定。 以舒适的速度开始踩踏，保持背部挺直，核心参与。 保持稳定的节奏，并根据需要增加阻力水平。 继续踩踏您的有氧运动所需的持续时间。 通过逐渐降低步速和阻力水平来冷静下来。 锻炼后伸展腿部肌肉，以防止紧绷并促进恢复。"},{"id":"3314","name_zh":"分腿马耳他","target":"腹部","media_id":"HfqciZF","instructions_zh":"首先，悬挂在一对环上，双臂完全伸展，身体呈一条直线。 双腿分开，形成跨坐姿势。 启动你的核心并慢慢降低你的身体，直到你的手臂与地面平行。 保持这个姿势几秒钟，然后将自己推回到起始位置。 重复所需的重复次数。"},{"id":"3298","name_zh":"分腿俄式挺身","target":"腹部","media_id":"BL3GHeY","instructions_zh":"从俯卧撑位置开始，双手与肩同宽，双脚分开。 启动你的核心，慢慢地将你的重心向前移动，将你的肩膀放在你的手上。 弯曲肘部，将身体放低至地面，保持肘部靠近身体两侧。 在底部停顿片刻，然后双手用力伸直手臂，将身体抬回到起始位置。 重复所需的重复次数。"},{"id":"1427","name_zh":"直腿髋外展","target":"外展肌","media_id":"mQ1tBXn","instructions_zh":"侧躺，双腿伸直并叠放在一起。 将下臂放在头下方以获得支撑。 启动你的核心并尽可能高地抬起你的上腿，不要旋转你的臀部或向后倾斜。 在顶部暂停片刻，然后慢慢将腿放回起始位置。 重复所需的重复次数，然后换边。"},{"id":"0803","name_zh":"超人俯卧撑","target":"胸","media_id":"4GqRrAk","instructions_zh":"从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。 收紧核心，将身体降低到地面，保持肘部靠近身体两侧。 当你降低身体时，同时将右臂和左腿抬离地面，笔直向外伸展。 在顶部暂停片刻，然后放下手臂和腿，同时将自己推回起始位置。 重复该动作，这次抬起左臂和右腿。 继续交替进行所需的重复次数。"},{"id":"0805","name_zh":"悬垂腹肌前推","target":"腹部","media_id":"X3TCNEU","instructions_zh":"将悬挂训练器连接到高锚点并将带子调整至腰部高度。 背对锚点站立，并握住手柄，双臂向前伸展。 腰部向前倾，保持身体挺直，核心肌群参与。 尽可能降低身体，同时保持腹肌的控制和紧张。 在底部停顿片刻，然后慢慢抬起身体回到起始位置。 重复所需的重复次数。"},{"id":"0806","name_zh":"悬垂俯卧撑","target":"胸","media_id":"IaGQCrC","instructions_zh":"找到一个悬挂训练器并将其调整到合适的高度。 背对锚点站立，并用正手握住手柄。 双脚向前走，身体向前倾斜，直到悬架训练器支撑您的体重。 保持身体从头到脚跟伸直，核心部位收紧，胸部朝手柄方向降低。 推动你的胸部和手臂回到起始位置。 重复所需的重复次数。"},{"id":"0807","name_zh":"悬垂反向卷腹","target":"腹部","media_id":"R1WYG5D","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。 收紧核心肌群，将膝盖抬向胸部，将骨盆卷向胸腔。 在顶部暂停片刻，然后慢慢将膝盖放回起始位置。 重复所需的重复次数。"},{"id":"0808","name_zh":"悬垂划船","target":"上背部","media_id":"4OaumBr","instructions_zh":"将悬挂训练器设置在适当的高度。 面向锚点站立，双脚分开与肩同宽。 正手握住手柄，手掌相对。 向后倾斜，保持身体挺直，脚后跟着地。 将胸部拉向手柄，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢降低回到起始位置。 重复所需的重复次数。"},{"id":"0809","name_zh":"悬垂箭步蹲","target":"股四头肌","media_id":"QpXqiq8","instructions_zh":"背对悬吊训练器站立，双脚与肩同宽。 向前伸展一条腿，将脚背放在悬吊训练器的脚托中。 弯曲站立的腿，将身体降低到弓步位置，保持胸部向上，膝盖与脚趾对齐。 推动脚后跟返回到起始位置。 重复所需的重复次数，然后换腿。"},{"id":"3433","name_zh":"游泳打腿 v.2（男）","target":"臀部","media_id":"SP3hUez","instructions_zh":"脸朝下躺在垫子上，双臂伸过头顶。 启动核心肌群，同时将胸部和腿部抬离地面。 以扑动的动作上下踢腿，就像在游泳一样。 继续踢所需的重复次数。 将胸部和双腿放低至起始位置。"},{"id":"3318","name_zh":"360度摆荡","target":"有氧","media_id":"tnaj0mT","instructions_zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 将双臂伸直在身前，与地面平行。 启动你的核心并以圆周运动摆动你的手臂，同时旋转你的躯干。 继续圆周运动，摆动手臂并旋转躯干，达到所需的重复次数。 记住在整个练习过程中保持呼吸。"},{"id":"1753","name_zh":"三凳臂屈伸","target":"肱三头肌","media_id":"DQ0cqkT","instructions_zh":"坐在长凳上，双手抓住边缘，手指指向前方。 将臀部滑离长凳，用手支撑体重。 弯曲肘部并降低身体，直到上臂与地面平行。 将自己推回到起始位置。 重复所需的重复次数。"},{"id":"2459","name_zh":"翻轮胎","target":"臀部","media_id":"oZjMu1t","instructions_zh":"双脚分开与肩同宽站立，面向轮胎。 弯曲膝盖并以臀部为铰链，降低至蹲姿。 向下伸手，用双手抓住轮胎的底部边缘，手指朝向您。 调动你的臀部和腿部肌肉，并爆发性地推动你的腿，将轮胎抬离地面。 当轮胎翻转时，用上半身的力量引导轮胎并保持控制。 轮胎完全翻转后，迅速后退并重置姿势。 重复所需的重复次数。"},{"id":"0811","name_zh":"六角杠硬拉","target":"臀部","media_id":"jQGwmxN","instructions_zh":"双脚分开与肩同宽站立，将陷阱杆放在你面前的地面上。 弯曲臀部和膝盖，降低身体高度，并用正手握住陷阱杆的手柄。 当你开始通过伸展臀部和膝盖将陷阱杆抬离地面时，保持背部挺直，挺胸。 当你举起时，专注于通过脚后跟发力，并在运动的最高点挤压臀部。 弯曲臀部和膝盖，将陷阱杆放回地面，在整个运动过程中保持背部挺直。 重复所需的重复次数。"},{"id":"0814","name_zh":"臂屈伸","target":"肱三头肌","media_id":"X6C6i5Y","instructions_zh":"坐在长凳或椅子的边缘，双手抓住边缘，手指指向前方。 将臀部滑离长凳，用手支撑体重。 弯曲肘部，将身体放低至地面，保持背部靠近长凳。 在底部暂停片刻，然后将自己推回到起始位置。 重复所需的重复次数。"},{"id":"0812","name_zh":"凳上臂屈伸","target":"肱三头肌","media_id":"VuoerH0","instructions_zh":"坐在长凳边缘，双手抓住边缘，手指指向前方。 双脚向前走，将臀部滑离长凳，然后伸直手臂。 弯曲肘部，将身体放低至地面，保持背部靠近长凳。 推动手掌以伸直手臂并返回到起始位置。 重复所需的重复次数。"},{"id":"0813","name_zh":"双凳臂屈伸","target":"肱三头肌","media_id":"Wgbn9qo","instructions_zh":"坐在长凳上，双手抓住长凳边缘，手指指向前方。 将臀部滑离长凳，用手支撑体重。 弯曲肘部，将身体放低至地面，保持背部靠近长凳。 在底部暂停片刻，然后将自己推回到起始位置。 重复所需的重复次数。"},{"id":"0815","name_zh":"地板臂屈伸","target":"肱三头肌","media_id":"7aVz15j","instructions_zh":"坐在椅子或长凳的边缘，双手放在臀部旁边，手指指向前方。 将你的屁股从椅子前面滑下来，双腿伸到你面前。 伸直手臂，保持肘部稍微弯曲，以保持三头肌和肘关节的张力。 慢慢弯曲你的肘部，将你的身体向地板降低，直到你的肘部成大约 90 度角。 一旦到达动作的底部，向下压入椅子以伸直肘部，返回到起始位置。 重复所需的重复次数。"},{"id":"0816","name_zh":"三头肌下压","target":"肱三头肌","media_id":"fSrPP6B","instructions_zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 将双臂伸直在身前，与地面平行。 弯曲肘部，将身体放低至地面，保持上臂靠近身体两侧。 在底部暂停片刻，然后将自己推回到起始位置。 重复所需的重复次数。"},{"id":"0817","name_zh":"肱三头肌拉伸","target":"肱三头肌","media_id":"uOV3Itw","instructions_zh":"站立或坐直，背部挺直。 将一只手臂伸过头顶，肘部弯曲。 将另一只手放在弯曲的肘部上，然后轻轻地将其拉向头部。 保持拉伸 15-30 秒，感受三头肌的轻微拉伸。 松开拉伸并在另一只手臂上重复。"},{"id":"0871","name_zh":"屈腿卷腹","target":"腹部","media_id":"BMMolZ3","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，将肩胛骨抬离地面，将膝盖靠近胸部，同时将上半身卷向膝盖。 在顶部停顿片刻，然后慢慢降低肩胛骨并将双腿伸展回起始位置。 重复所需的重复次数。"},{"id":"0818","name_zh":"双把手对握高位下拉","target":"背阔肌","media_id":"rkg41Fb","instructions_zh":"调整座椅高度并将自己面向电缆机。 正手握住手柄，双手与肩同宽。 坐下来，将大腿放在大腿垫下方，保持双脚平放在地板上。 稍微向后倾斜，挺胸，保持脊柱中立。 将手柄向下拉至上胸部，将肩胛骨挤压在一起。 在动作的底部暂停片刻，感受背阔肌的收缩。 慢慢松开手柄并返回到起始位置。 重复所需的重复次数。"},{"id":"1466","name_zh":"扭转髋部上提","target":"臀部","media_id":"AX1kB0o","instructions_zh":"仰卧，膝盖弯曲，双脚平放在地上。 将双手放在身体两侧以获得支撑。 收紧臀部并将臀部抬离地面，从膝盖到肩膀形成一条直线。 在保持臀部抬起的同时，将下半身扭转到右侧，使膝盖靠近地面。 返回起始位置并向左侧重复扭转。 继续交替扭转所需的重复次数。"},{"id":"2802","name_zh":"扭转举腿","target":"腹部","media_id":"C0eCeEt","instructions_zh":"平躺，双腿伸展，双臂放在身体两侧。 将双手放在臀部下方以获得支撑。 收紧腹肌，将双腿抬离地面，保持伸直。 当你抬起双腿时，将臀部扭向一侧，将双腿拉向对面的肩膀。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复这个动作，这次将臀部扭到另一侧。 继续交替进行所需的重复次数。"},{"id":"2801","name_zh":"扭转举腿（女）","target":"腹部","media_id":"yT9tk17","instructions_zh":"平躺，双腿伸展，双臂放在身体两侧。 弯曲膝盖，将双腿抬离地面，将它们拉向胸部。 当你抬起双腿时，将臀部扭向一侧，将膝盖移向另一侧的肩膀。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复这个动作，这次将臀部扭到另一侧。 继续交替进行所需的重复次数。"},{"id":"3231","name_zh":"双脚触趾（男）","target":"脊柱","media_id":"p195zsJ","instructions_zh":"双脚分开与肩同宽站立，双臂向两侧伸展。 腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。 双手向下伸向脚趾，保持双腿伸直。 在底部停顿片刻，然后慢慢回到起始位置。 重复所需的重复次数。"},{"id":"1365","name_zh":"上背部拉伸","target":"上背部","media_id":"GSDioYu","instructions_zh":"站直，双脚分开与肩同宽。 将双臂伸直在身前，与地面平行。 手指交叉，手掌旋转远离身体。 慢慢地将手臂举过头顶，保持它们伸直并彼此平行。 当你举起手臂时，将肩胛骨挤压在一起。 保持拉伸 15-30 秒，然后松开并重复。"},{"id":"1366","name_zh":"上犬式","target":"脊柱","media_id":"01qpYSe","instructions_zh":"脸朝下躺在地板上，双腿伸到身后。 将双手放在下肋骨旁边的地板上，手指指向前方。 双手用力按在地板上，伸直手臂，将躯干和大腿抬离地面。 向后和向下转动肩膀，打开胸部，将目光转向天花板。 保持这个姿势几次呼吸，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"3420","name_zh":"地板V字支撑","target":"腹部","media_id":"ZuXu4Eq","instructions_zh":"坐在地板上，双腿伸到身前。 稍微向后倾斜，将双腿抬离地面，保持伸直。 同时，将上半身抬离地面，并将手臂伸向腿部。 保持这个姿势几秒钟，然后慢慢降低上半身和双腿回到起始位置。 重复所需的重复次数。"},{"id":"0826","name_zh":"双杠垂直举腿","target":"腹部","media_id":"ZNgOYQU","instructions_zh":"悬挂在双杠上，双臂完全伸展，身体伸直。 启动你的核心并将双腿抬起到你面前，保持伸直。 继续抬起，直到双腿与地面平行或稍高。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"2141","name_zh":"椭圆机走步","target":"有氧","media_id":"rjtuP6X","instructions_zh":"将椭圆机的阻力水平和倾斜度调整到您想要的设置。 踩上机器的踏板并轻轻握住手柄。 首先用脚向下压，然后将手柄拉向身体。 继续这个动作，交替推和拉，以模拟行走或跑步动作。 在整个练习过程中保持稳定的步伐并保持核心参与。 继续进行有氧运动所需的持续时间。 下车前逐渐降低机器的强度和速度。"},{"id":"3655","name_zh":"行进高抬腿弓步","target":"有氧","media_id":"J9zIWig","instructions_zh":"双脚分开与臀部同宽站立。 将右膝尽可能高地抬向胸部，同时用左腿保持平衡。 右脚向前迈出一步，身体降低成弓步姿势，双膝弯曲成 90 度角。 用右脚推出，并将左膝抬向胸部。 左脚向前迈出一步，将身体降低至弓步位置。 继续交替双腿并向前冲刺，保持核心参与并保持稳定的步伐。 重复所需的重复次数。"},{"id":"1460","name_zh":"弓步走","target":"臀部","media_id":"IZVHb27","instructions_zh":"双脚分开与肩同宽站立。 右腿向前迈出一步，将身体降低至弓步位置。 保持躯干直立，前膝与脚踝对齐。 右脚蹬地，左脚向前，左腿呈弓步姿势。 继续交替双腿向前行走，保持受控且稳定的步伐。 重复所需的重复次数。"},{"id":"3666","name_zh":"上坡行走","target":"有氧","media_id":"rjiM4L3","instructions_zh":"将跑步机的倾斜度调整到您想要的强度。 站在跑步机上，双脚分开与肩同宽。 开始以舒适的步伐行走，确保保持正确的姿势。 在整个练习过程中，调动核心肌肉并保持背部挺直。 继续在倾斜跑步机上行走，完成有氧运动所需的时间。 逐渐降低跑步机的坡度和速度，使其冷却后再停止。"},{"id":"2311","name_zh":"爬楼梯机","target":"有氧","media_id":"j9Q5crt","instructions_zh":"将步进机调整到舒适的水平。 走上机器，将双手放在扶手上以获得支撑。 开始行走时，将一只脚放在台阶上，然后将另一只脚放在台阶上，双腿交替。 保持直立姿势并锻炼核心肌肉。 继续步行所需的时间或距离。 当您对锻炼感到更加舒适时，逐渐增加强度或速度。 完成练习后记得冷静下来并伸展身体。"},{"id":"0830","name_zh":"负重凳上臂屈伸","target":"肱三头肌","media_id":"MU9HnE7","instructions_zh":"坐在长凳上，双手抓住边缘，手指指向前方。 将臀部滑离长凳，用手支撑体重。 弯曲肘部降低身体，直到上臂与地板平行。 伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"2987","name_zh":"负重窄握反手引体向上（双杠架）","target":"背阔肌","media_id":"Gk1r408","instructions_zh":"站在俯卧撑前面，用反握抓住双杠，双手与肩同宽。 悬挂在杠上，双臂完全伸展，双脚离开地面，身体伸直。 收紧背部肌肉，将身体拉向杠铃，保持肘部靠近身体两侧。 继续拉，直到下巴高于杠铃，然后暂停片刻。 慢慢地将身体放回起始位置，充分伸展双臂。 重复所需的重复次数。"},{"id":"3643","name_zh":"负重哥萨克深蹲（男）","target":"臀部","media_id":"GWoKnIm","instructions_zh":"站立时双脚分开比肩宽，脚趾稍微向外。 用双手将重物放在胸前。 将您的体重转移到一侧，并通过弯曲您转移一侧的膝盖来降低身体，同时保持另一条腿伸直。 尽可能降低身体高度，同时保持平衡并挺胸。 推动弯曲腿的脚跟以返回到起始位置。 在另一侧重复，双腿之间交替。"},{"id":"0832","name_zh":"负重卷腹","target":"腹部","media_id":"s8nrDXF","instructions_zh":"平躺，膝盖弯曲，双脚平放在地上。 将杠铃片或哑铃放在胸前。 收紧腹肌，将上半身抬离地面，向前卷曲，直到肩胛骨离开地面。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"3670","name_zh":"负重下斜仰卧起坐","target":"腹部","media_id":"EZeDVzO","instructions_zh":"平躺在倾斜的长凳上，双脚固定在脚垫下。 将双手放在脑后或放在胸前。 收紧腹肌，慢慢将上半身抬离长凳，向前卷曲，直到躯干垂直于地面。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"0833","name_zh":"负重驴式提踵","target":"小腿","media_id":"LmaFNZS","instructions_zh":"站在一个升高的平台上，脚趾放在边缘，脚后跟悬垂。 抓住一个稳定的物体作为支撑。 伸展脚踝，将脚后跟尽可能抬高。 在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"1310","name_zh":"负重下落俯卧撑","target":"胸","media_id":"PSlvNMs","instructions_zh":"从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。 将胸部压向地面，保持肘部靠近身体。 一旦你的胸部刚好高于地面，爆发性地把自己推起来，将双手抬离地面。 当你向上推时，快速将双手移至两侧并稍微向前，让你的身体向地面落下。 将双手置于更宽的位置，然后立即再次将胸部降低到地面。 重复俯卧撑动作，下降并用双手抓住自己在较窄的位置。 继续在更宽和更窄的手位置之间交替，以达到所需的重复次数。"},{"id":"2135","name_zh":"负重平板支撑","target":"腹部","media_id":"VBAWRPG","instructions_zh":"首先脸朝下躺在地板上。 将前臂放在地面上，肘部直接位于肩膀下方。 将双腿伸直在身后，脚趾着地。 启动你的核心并将你的身体抬离地面，用前臂和脚趾保持平衡。 保持身体从头部到脚跟呈一条直线。 保持此位置所需的时间。 将身体放低至起始位置。 重复所需的重复次数。"},{"id":"0834","name_zh":"负重前平举","target":"肩","media_id":"e4aFmFY","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。 保持双臂伸直，呼气并将哑铃举至身前，直至与肩齐平。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数。"},{"id":"0866","name_zh":"负重悬垂举腿提髋","target":"腹部","media_id":"QOA0FD0","instructions_zh":"悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。 启动你的核心并将双腿抬起到你面前，保持伸直。 继续抬起，直到双腿与地面平行或稍高。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。"},{"id":"0835","name_zh":"负重健身球背部伸展","target":"脊柱","media_id":"8urJS9b","instructions_zh":"将自己面朝下放在稳定球上，臀部放在球上，双脚靠在墙上以保持稳定。 将双手放在脑后或交叉放在胸前。 启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体形成一条直线。 在顶部停顿片刻，然后慢慢将上半身放回起始位置。 重复所需的重复次数。"},{"id":"3641","name_zh":"负重跪姿弓步摆臂","target":"肩","media_id":"7uFJuXp","instructions_zh":"从跪姿开始，膝盖分开与臀部同宽，背部挺直。 每只手各握一个重物，双臂在身前笔直向下伸展。 启动你的核心肌群，将重物向上举过头顶，保持手臂伸直。 将重量放回起始位置，然后重复所需的重复次数。"},{"id":"3644","name_zh":"负重箭步蹲（摆臂）","target":"臀部","media_id":"5WiFcYk","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个重物。 右脚向前迈出一步，将身体降低至弓步位置。 当你向前冲时，向前和向上摆动重物，保持手臂伸直。 用右脚推出并返回到起始位置，将重物向下摆动。 用左脚重复上述动作，并继续交替双腿，完成所需的重复次数。"},{"id":"3286","name_zh":"负重双力臂","target":"背阔肌","media_id":"JsOV1SU","instructions_zh":"首先悬挂在引体向上杆上，手掌背向自己，双手之间的距离略大于肩宽。 启动核心肌群，将身体拉向杠铃杆，以胸部为主导。 当你到达动作的最高点时，改变你的握力，使你的手掌朝向你。 继续拉起自己，直到胸部到达杠铃，然后暂停片刻。 慢慢地将自己放回到起始位置，在整个运动过程中保持控制。 重复所需的重复次数。"},{"id":"3312","name_zh":"负重双力臂（单杠）","target":"背阔肌","media_id":"MCkqdKE","instructions_zh":"首先悬挂在引体向上杆上，手掌背向自己，双手之间的距离略大于肩宽。 启动你的核心并将肩胛骨向下拉和向后拉。 弯曲肘部，将胸部拉向杠铃杆，保持身体挺直。 当你的胸部到达杠铃时，用手向下推并将肘部向后推，将身体提升到杠铃上方。 在动作的最高点暂停，然后慢慢降低回到起始位置。 重复所需的重复次数。"},{"id":"3290","name_zh":"负重单臂引体向上","target":"背阔肌","media_id":"fXfqg1E","instructions_zh":"正手握住引体向上杆，握距略宽于肩宽。 悬挂在杠上，手臂完全伸展，身体伸直。 弯曲肘部并挤压背部肌肉，调动核心力量，将身体拉向杠铃杆。 继续拉，直到下巴位于杠铃上方。 有控制地降低身体回到起始位置。 重复所需的重复次数。"},{"id":"0840","name_zh":"负重过头卷腹（健身球）","target":"腹部","media_id":"xmM75XG","instructions_zh":"坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。 双手握住杠铃片或哑铃，并将手臂伸过头顶。 收紧腹肌，慢慢向前弯曲躯干，使胸部靠近膝盖。 在顶部暂停片刻，然后慢慢将躯干放回起始位置。 重复所需的重复次数。"},{"id":"0841","name_zh":"负重引体向上","target":"背阔肌","media_id":"HMzLjXx","instructions_zh":"正手握住引体向上杆，握距略宽于肩宽。 悬挂在杠上，双臂完全伸展，身体伸直。 收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"0844","name_zh":"负重手臂绕环","target":"肩","media_id":"VLYXo8S","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将手臂向两侧举起，肘部保持轻微弯曲。 继续举起手臂，直到它们与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。"},{"id":"0846","name_zh":"负重俄罗斯转体","target":"腹部","media_id":"fZFZ704","instructions_zh":"坐在地上，膝盖弯曲，双脚平放在地板上。 双手握住重物球或健身球放在胸前。 稍微向后倾斜，保持背部挺直，核心肌群参与。 慢慢地将你的躯干向右扭转，将重物或药球拉向右侧的地板。 暂停片刻，然后将躯干向左扭转，将重物或健身球拉向左侧的地板。 继续交替进行所需的重复次数。"},{"id":"0845","name_zh":"负重俄罗斯转体（抬腿）","target":"腹部","media_id":"WU9BLIs","instructions_zh":"坐在地上，膝盖弯曲，双脚离开地面，保持双腿并拢。 用双手将重物放在胸前，保持肘部稍微弯曲。 稍微向后倾斜以锻炼核心肌肉。 将躯干向右扭转，将重量移向右侧地面。 暂停片刻，然后将躯干向左扭转，将重量转移到左侧地面。 继续交替进行所需的重复次数。"},{"id":"2371","name_zh":"负重俄罗斯转体 V2","target":"腹部","media_id":"YIUAtYf","instructions_zh":"坐在地上，膝盖弯曲，双脚平放在地板上。 用双手将重物放在胸前。 稍微向后倾斜以锻炼核心肌肉。 将躯干向右扭转，将重量移至身体右侧。 暂停片刻，然后将躯干向左扭转，将重量移向身体的左侧。 继续交替进行所需的重复次数。"},{"id":"0847","name_zh":"负重坐姿二头弯举（健身球）","target":"肱二头肌","media_id":"b4b6afT","instructions_zh":"坐在稳定球上，双脚平放在地面上，背部挺直。 反手握住健身球，手掌朝上，让手臂垂在身体两侧。 保持上臂静止，呼气并将药球向上卷向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气并缓慢地将健身球放回起始位置。 重复所需的重复次数。"},{"id":"0849","name_zh":"负重坐姿转体（健身球）","target":"腹部","media_id":"s34Y4LR","instructions_zh":"坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。 双手靠近胸部握住杠铃片或哑铃。 启动你的核心并慢慢地将你的躯干旋转到一侧，保持臀部稳定。 旋转结束时暂停片刻，然后慢慢回到起始位置。 重复旋转到另一侧。 继续交替进行所需的重复次数。"},{"id":"0850","name_zh":"负重体侧屈（健身球）","target":"腹部","media_id":"6bOA1Oi","instructions_zh":"坐在稳定球上，双脚分开与肩同宽，平放在地面上。 一只手握住重物，另一只手放在臀部上。 启动你的核心，慢慢向受重侧侧弯，保持背部挺直。 在底部停顿片刻，然后慢慢回到起始位置。 重复所需的重复次数，然后换边。"},{"id":"0851","name_zh":"负重西斯深蹲","target":"股四头肌","media_id":"0lQnxMZ","instructions_zh":"双脚分开与肩同宽站立，脚趾稍微向外。 用双手将重物放在胸前，或将杠铃放在上背部。 保持挺胸，核心收紧，弯曲膝盖和臀部，慢慢降低身体。 继续降低，直到大腿与地面平行或尽可能低。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。"},{"id":"0852","name_zh":"负重深蹲","target":"臀部","media_id":"JZuApnB","instructions_zh":"双脚分开与肩同宽站立，脚趾稍微向外。 将重物放在胸前或肩膀上。 收紧核心并保持挺胸，同时降低臀部和向后倾斜，就像坐在椅子上一样。 降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。 推动脚后跟站起来，在顶部挤压臀部。 重复所需的重复次数。"},{"id":"0853","name_zh":"负重站姿弯举","target":"肱二头肌","media_id":"M5Y7GPg","instructions_zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。 保持肘部靠近躯干，并在将哑铃弯举至肩部水平时呼气。 在顶部暂停片刻，然后吸气，慢慢将重量放回起始位置。 重复所需的重复次数。"},{"id":"0854","name_zh":"负重站姿手挤压","target":"前臂","media_id":"bjqbauy","instructions_zh":"双脚分开与肩同宽站立，每只手各握一个重物。 将双臂伸直在身前，手掌相对。 尽可能用力将双手握在一起，用力接触前臂。 按住挤压几秒钟，然后松开。 重复所需的重复次数。"},{"id":"3313","name_zh":"负重直杆臂屈伸","target":"胸","media_id":"Ff18ItA","instructions_zh":"将自己置于双杠之间，双臂完全伸展，身体伸直。 弯曲肘部降低身体，直到上臂与地面平行。 暂停片刻，然后伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"3642","name_zh":"负重箭步蹲拉伸","target":"臀部","media_id":"13VW2VO","instructions_zh":"双脚分开与肩同宽站立。 右脚向前迈出一步，保持背部挺直。 弯曲膝盖降低身体，直到右大腿与地面平行。 推动右脚跟回到起始位置。 左腿重复上述动作。 继续交替双腿达到所需的重复次数。"},{"id":"0856","name_zh":"负重斯文德推胸","target":"胸","media_id":"I1OBLnn","instructions_zh":"双脚分开与肩同宽站立，双手将杠铃片放在胸前。 保持肘部稍微弯曲，手掌相对。 将配重板直接压在您面前，完全伸展双臂。 动作结束时暂停片刻，然后慢慢将配重板放回起始位置。 重复所需的重复次数。"},{"id":"1754","name_zh":"负重三凳臂屈伸","target":"肱三头肌","media_id":"gtO1ErP","instructions_zh":"坐在长凳边缘，双手抓住边缘，手指指向前方。 双脚向前走，将臀部滑离长凳，并用手臂支撑体重。 弯曲肘部降低身体，使背部靠近长凳。 在底部暂停片刻，然后将自己推回到起始位置。 重复所需的重复次数。"},{"id":"1755","name_zh":"负重三头臂屈伸","target":"肱三头肌","media_id":"bZq4bwK","instructions_zh":"坐在长凳或椅子的边缘，双手抓住臀部旁边的边缘。 将你的屁股从长凳前面滑下来，双腿在你面前伸展。 保持背部靠近长凳，肘部稍微弯曲。 弯曲肘部降低身体，直到上臂与地板平行。 伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"1767","name_zh":"负重高位双杠三头臂屈伸","target":"肱三头肌","media_id":"K1vlode","instructions_zh":"将自己定位在两个双杠之间，双手握住杠，双臂完全伸展。 弯曲肘部并降低身体，直到上臂与地面平行。 暂停片刻，然后用手掌推直手臂并返回到起始位置。 重复所需的重复次数。"},{"id":"0857","name_zh":"健腹轮滚动","target":"腹部","media_id":"NAgVB3t","instructions_zh":"跪在地板上，将滚轮放在您面前。 将双手放在滚轮的手柄上，并将手臂伸直至前方。 调动你的核心肌肉，慢慢向前滚动轮子，保持背部挺直，腹肌紧张。 继续向前滚动，直到身体完全伸展并且手臂举过头顶。 暂停片刻，然后慢慢地将轮子向膝盖方向滚动，保持控制并保持腹肌接合。 重复所需的重复次数。"},{"id":"3637","name_zh":"健腹轮跑","target":"有氧","media_id":"km2Ljzj","instructions_zh":"从平板支撑位置开始，双手放在方向盘上，身体伸直。 启动你的核心并通过伸展双臂开始向前滚动轮子。 继续滚动，直到身体完全伸展并且手臂举过头顶。 使用你的核心和手臂将轮子拉回你的身体，从而扭转运动。 重复所需的重复次数。"},{"id":"1429","name_zh":"宽握引体向上","target":"背阔肌","media_id":"Qqi7bko","instructions_zh":"悬挂在引体向上杆上，手掌背向自己，双手之间的距离比肩宽。 启动你的核心并将肩胛骨挤压在一起。 将身体向上拉向杠铃，直到下巴位于杠铃上方。 有控制地降低身体回到起始位置。 重复所需的重复次数。"},{"id":"1367","name_zh":"宽握后颈引体向上","target":"背阔肌","media_id":"OYFhXVD","instructions_zh":"正手宽握抓住引体向上杆，双手间距略宽于肩宽。 悬挂在杠上，双臂完全伸展，身体伸直。 调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。"},{"id":"1311","name_zh":"宽距俯卧撑","target":"胸","media_id":"JmMVpR3","instructions_zh":"从高平板支撑位置开始，双手分开比肩宽。 保持身体从头到脚呈一条直线。 弯曲肘部，将胸部压向地面，使其靠近身体两侧。 推动手掌以伸展手臂并返回到起始位置。 重复所需的重复次数。"},{"id":"2363","name_zh":"宽握高位双杠胸臂屈伸","target":"胸","media_id":"O2K9Vb5","instructions_zh":"将自己置于双杠上，双臂完全伸展，身体悬浮在空中。 稍微向前倾，弯曲肘部降低身体，直到胸部位于杠铃上方。 暂停片刻，然后伸直手臂，将自己推回起始位置。 重复所需的重复次数。"},{"id":"0858","name_zh":"冲刺跑","target":"腹部","media_id":"Qoujh3Q","instructions_zh":"找一个空地或跑道来进行练习。 首先站立，双脚分开与肩同宽。 开始尽可能快地跑步，挥动手臂并抬起膝盖。 继续冲刺特定的距离或时间。 休息并重复所需的重复次数。"},{"id":"1604","name_zh":"世界最伟大拉伸","target":"大腿后侧","media_id":"DFGXwZr","instructions_zh":"从弓步位置开始，右脚向前，左脚向后。 将双手放在右脚两侧的地面上。 将左膝降低到地面并伸展右腿，保持右脚平放在地面上。 向右旋转你的躯干，将你的右臂伸向天花板。 保持这个姿势几秒钟，然后回到起始位置。 换边并重复拉伸，左脚向前。"},{"id":"1428","name_zh":"手腕环绕","target":"前臂","media_id":"2zNKRUB","instructions_zh":"将双臂伸直在身前。 双手握拳。 以圆周运动旋转手腕，保持手臂静止。 继续手腕转圈达到所需的重复次数。"},{"id":"0859","name_zh":"手腕滚轮","target":"前臂","media_id":"bd5b860","instructions_zh":"将重物固定在绳子或杆的一端。 用双手握住绳子或杆的另一端，手掌朝下。 双脚分开与肩同宽站立，双臂完全伸展在身前。 弯曲手腕，慢慢地将重物向上滚动到手上。 在顶部暂停片刻，然后慢慢将重量放回起始位置。 重复所需的重复次数。"}]
